      "path": "lib/index.js",
      "content": "/**\n * dsh-short-video-studio — host half.\n *\n * MiniMax-Design 风格的短剧/动画画布工作室：\n *  - ComfyUI 生成引擎（图片 FLUX / 视频 MiniMax H3，默认 http://localhost:8188）\n *  - 画布持久存储 <workspace>/canvas/<sessionId>/project.json + 媒体文件\n *  - /dsh-short-video-studio 路由（画布 API + 媒体伺服 + studio 静态站）\n *  - Agent 工具：comfy_generate_image / comfy_generate_video / canvas_*\n *  - systemPrompt 段：流水线 + 工具契约 + 选项卡门控\n *  - pre-ask 自动送达：tools/pre-execute 钩子在 ask_user_question 前把画布\n *    未送达产物经 send_file 发到飞书（文本节点自动导出 .pdf）\n *\n * 本文件刻意零 @deepseek-ai/* 运行时 import：工具用原生 ToolDefinition\n * 注册（parameters 直接写 JSON Schema），服务全部走注入的 ctx\n * （webServer/tools/systemPrompt/workspaceRegistry），从而 link:/file: 安装\n * 都不受 peer 解析路径影响。\n */\n\nimport { randomBytes, randomUUID, createHash } from 'node:crypto'\nimport { createReadStream, existsSync, readFileSync, writeFileSync, cpSync, readdirSync, mkdirSync, statSync, rmSync } from 'node:fs'\nimport {\n  mkdir,\n  readFile,\n  readdir,\n  writeFile,\n  rename,\n  realpath,\n  stat,\n  unlink,\n  link,\n  copyFile,\n} from 'node:fs/promises'\nimport { resolve, basename, dirname, join, relative, sep, extname, isAbsolute } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { homedir } from 'node:os'\nimport { execFile } from 'node:child_process'\nimport { loadBuiltinManifests, buildGraphFromManifest, validateManifest, resolveAssets, CAPABILITIES, TIERS } from './manifest.js'\nimport { convertComfyExport, isRawComfyExport, isLegacyWorkflowFormat } from './convert.js'\nimport {\n  DEFAULT_RECHECK_MS, DEFAULT_SETTLE_MS, archiveSessionDir, diffArchived, dirStats,\n  normalizeArchiveRoot, probeArchiveRoot, readArchiveIndex, restoreSessionDir, updateArchiveIndex,\n} from './archive-move.js'\nimport {\n  loadLibrary, isAssetRef, canonicalAssetId, assetFilename, newAssetId, normalizeDisplayName, findAssetByLabel,\n  assetDisplayName, assetDisplayState,\n  resolveAssetImagePath, resolveAssetPath, registerAsset, removeAsset, renameAsset, slugifyName,\n  ASSET_TYPES, TYPE_KINDS, NODE_KINDS, assetKind, assetTypesForKind,\n} from './assets.js'\nimport { buildConcatGraph, detectFfmpeg, ffmpegConcat, ffmpegRetimeFps } from './concat.js'\nimport {\n  probeMp4, snapToAlign, planUpscale, planUpscaleChunks, chunkRanges, sliceUpscaleGraph,\n  PIXEL_FRAME_WARN,\n} from './upscale.js'\nimport { planRegenerate, normalizeRegenerateTargets, resolveRegenerateTarget, decideRegenerateHandoff } from './regenerate.js'\nimport { detectPdfTool, htmlToPdf } from './pdf.js'\nimport { markdownToHtml, escapeHtmlText, inlineFormat } from '../studio/markdown.js'\n\nexport const name = 'short-video-studio'\n\n/** 宿主服务依赖（fiber 等待这些服务先就绪）。 */\nexport const inject = ['webServer', 'tools', 'systemPrompt', 'workspaceRegistry']\n\n// ---------------------------------------------------------------------------\n// 配置（优先级：env > 配置文件 ~/.dsh/dsh-short-video-studio.json > 默认）\n// 配置文件示例见 README「配置」；也支持 DSH_SVS_CONFIG 指向其它路径。\n// ---------------------------------------------------------------------------\nfunction loadConfigFile() {\n  const path = process.env.DSH_SVS_CONFIG || join(homedir(), '.dsh', 'dsh-short-video-studio.json')\n  try {\n    if (existsSync(path)) return JSON.parse(readFileSync(path, 'utf8')) || {}\n  } catch { /* 忽略损坏的配置，回退默认 */ }\n  return {}\n}\nconst _cfg = loadConfigFile()\nconst _models = _cfg.models || {}\nconst env = (k, d) => (process.env[k] !== undefined && process.env[k] !== '' ? process.env[k] : d)\n\nconst COMFY_BASE_URL = env('DSH_SVS_COMFY_URL', _cfg.baseUrl || 'http://localhost:8188').replace(/\\/+$/, '')\nconst COMFY_API_KEY = env('DSH_SVS_COMFY_KEY', _cfg.apiKey || '')\nconst POLL_INTERVAL_MS = Number(env('DSH_SVS_POLL_MS', _cfg.pollMs || 2000))\nconst GENERATION_TIMEOUT_MS = Number(env('DSH_SVS_TIMEOUT_MS', _cfg.timeoutMs || 15 * 60 * 1000))\n\nconst ROUTE_ROOT = '/dsh-short-video-studio'\nconst CANVAS_DIR = 'canvas'\n\n// FLUX 2 本地模型（图片）\nconst FLUX_MODEL = env('DSH_SVS_FLUX_MODEL', _models.fluxUnet || 'flux2_dev_fp8mixed.safetensors')\nconst FLUX_CLIP = env('DSH_SVS_FLUX_CLIP', _models.fluxClip || 'mistral_3_small_flux2_bf16.safetensors')\nconst FLUX_CLIP_TYPE = 'flux2'\nconst FLUX_VAE = env('DSH_SVS_FLUX_VAE', _models.fluxVae || 'flux2-vae.safetensors')\n\n// MiniMax H3 本地模型（视频，音视频 AV）\nconst H3_MODEL = env('DSH_SVS_H3_MODEL', _models.h3Unet || 'minimax_h3_fl2va_pruned_int8_convrot.safetensors')\nconst H3_CLIP = env('DSH_SVS_H3_CLIP', _models.h3Clip || 'qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors')\nconst H3_CLIP_TYPE = 'minimax'\nconst H3_VAE = env('DSH_SVS_H3_VAE', _models.h3VideoVae || 'minimax_h3_video_vae_fp16.safetensors')\nconst H3_AUDIO_VAE = env('DSH_SVS_H3_AUDIO_VAE', _models.h3AudioVae || 'minimax_h3_audio_vae_fp32.safetensors')\nconst H3_MODEL_REF = env('DSH_SVS_H3_MODEL_REF', _models.h3RefUnet || 'minimax_h3_ref2va_pruned_int8_convrot.safetensors')\nconst H3_LORA_FAST = env('DSH_SVS_H3_LORA_FAST', _models.h3FastLora || 'minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors')\nconst H3_FPS = Number(env('DSH_SVS_H3_FPS', _models.h3Fps || 24))\n\n/** 配置持久化路径（与 loadConfigFile 一致）。 */\nconst CONFIG_PATH = process.env.DSH_SVS_CONFIG || join(homedir(), '.dsh', 'dsh-short-video-studio.json')\n\n/**\n * 运行时配置（每次调用重读 env + 配置文件，使设置即时生效）。\n * 优先级：env > 配置文件 ~/.dsh/dsh-short-video-studio.json > 默认。\n */\nfunction getCfg() {\n  const c = loadConfigFile()\n  const m = c.models || {}\n  return {\n    baseUrl: env('DSH_SVS_COMFY_URL', c.baseUrl || 'http://localhost:8188').replace(/\\/+$/, ''),\n    apiKey: env('DSH_SVS_COMFY_KEY', c.apiKey || ''),\n    // 本机 ffmpeg 路径（显式配置最稳；不配时先看 PATH 里的全局 ffmpeg，再向上层目录搜索 tools/ffmpeg）。\n    ffmpegPath: env('DSH_SVS_FFMPEG', c.ffmpegPath || ''),\n    pollMs: Number(env('DSH_SVS_POLL_MS', c.pollMs || 2000)),\n    timeoutMs: Number(env('DSH_SVS_TIMEOUT_MS', c.timeoutMs || 15 * 60 * 1000)),\n    // 画布的家：'tab' = 会话区视图标签页（默认，向后兼容现状）；'sidebar' = 右侧栏标签页。\n    // 白名单兜底：任何非法/缺失值都回落 'tab'。浏览器半在插件启动时读此值，**只注册一个家**，\n    // 因此两种配置下结构上都不可能出现两个 studio iframe 实例（见 docs/right-sidebar-canvas-research.md §13）。\n    canvasHome: c.canvasHome === 'sidebar' ? 'sidebar' : 'tab',\n    // 归档路径：会话归档时把 <工作区>/canvas/<sessionId> 搬到这个路径，取消归档再搬回。\n    // 留空 = 关闭（画布留在工作区，等同旧行为）。支持本地盘 / 外置盘 / NAS 挂载点；跨盘自动\n    // 退化为「拷贝 + 删源」。相对路径非法（不同工作区语义不清），由 normalizeArchiveRoot 置 null。\n    archiveRoot: env('DSH_SVS_ARCHIVE_ROOT', c.archiveRoot || ''),\n    models: {\n      fluxUnet: env('DSH_SVS_FLUX_MODEL', m.fluxUnet || 'flux2_dev_fp8mixed.safetensors'),\n      fluxClip: env('DSH_SVS_FLUX_CLIP', m.fluxClip || 'mistral_3_small_flux2_bf16.safetensors'),\n      fluxVae: env('DSH_SVS_FLUX_VAE', m.fluxVae || 'flux2-vae.safetensors'),\n      h3RefUnet: env('DSH_SVS_H3_MODEL_REF', m.h3RefUnet || 'minimax_h3_ref2va_pruned_int8_convrot.safetensors'),\n      // i2v（首/末帧串联）用 FL2VA 变体：官方 I2V/T2V 即这套权重，与 ref2va 是两套不同 base\n      h3FlUnet: env('DSH_SVS_H3_MODEL_FL', m.h3FlUnet || 'minimax_h3_fl2va_pruned_int8_convrot.safetensors'),\n      h3Clip: env('DSH_SVS_H3_CLIP', m.h3Clip || 'qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors'),\n      h3VideoVae: env('DSH_SVS_H3_VAE', m.h3VideoVae || 'minimax_h3_video_vae_fp16.safetensors'),\n      h3AudioVae: env('DSH_SVS_H3_AUDIO_VAE', m.h3AudioVae || 'minimax_h3_audio_vae_fp32.safetensors'),\n      h3FastLora: env('DSH_SVS_H3_LORA_FAST', m.h3FastLora || 'minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors'),\n      // fl2v 系 4 步 LoRA（544p 训练域，shift 12/3）—— 与 fl2va base 配对给 i2v 的 fast 档\n      h3FlFastLora: env('DSH_SVS_H3_LORA_FL_FAST', m.h3FlFastLora || 'minimax_h3_fl2v_lightx2v_turbo_4step_v0.1_comfy.safetensors'),\n      // ref2v 的 8 步 768p LoRA（balanced 档，shift 6/3 + euler）\n      h3BalancedLora: env('DSH_SVS_H3_LORA_BALANCED', m.h3BalancedLora || 'minimax_h3_ref2v_turbo_8step_v1.0_768p_comfyui_bf16.safetensors'),\n      // fl2v 的 8 步 768p LoRA（i2v 平衡档，shift 6/3 + euler）——必须与 544p 系（shift 12/3）区分\n      h3FlBalancedLora: env('DSH_SVS_H3_LORA_FL_BALANCED', m.h3FlBalancedLora || 'minimax_h3_fl2v_turbo_8step_v1.0_768p_comfyui_bf16.safetensors'),\n      // PDD（Parallel Decoding Distillation）权重：**必须放 models/pdd_acc/**（节点只从该目录取，\n      // 放 models/loras/ 会被 LoraLoader 系列看到但 PDD 节点取不到）。与 base 变体严格配对：\n      // ref2va UNET ↔ Ref2VA 权重，fl2va UNET ↔ FL2VA 权重（节点有指纹守卫，错配直接报错）。\n      h3PddRef2v: env('DSH_SVS_H3_PDD_REF2V', m.h3PddRef2v || 'minimax_h3_ref2va_pdd_acc_8step_comfyui.safetensors'),\n      h3PddFl2v: env('DSH_SVS_H3_PDD_FL2VA', m.h3PddFl2v || 'minimax_h3_fl2va_pdd_acc_8step_comfyui.safetensors'),\n      h3Fps: Number(env('DSH_SVS_H3_FPS', m.h3Fps || 24)),\n    },\n    assetOverrides: c.assetOverrides || {},\n    preferred: c.preferred || {},\n    // 档位选择：capability → tier → 实现 id（见 docs/tier-strategy-design.md）\n    tiers: c.tiers && typeof c.tiers === 'object' ? c.tiers : {},\n    // 用户自建策略：capability → [{ id, name, tiers:{tier→实现id} }]（策略由用户命名与组合）\n    strategies: c.strategies && typeof c.strategies === 'object' ? c.strategies : {},\n    // 当前选中的策略 id（仅用于 UI 点亮；真正生效的仍是上面的 tiers 快照）\n    strategyOf: c.strategyOf && typeof c.strategyOf === 'object' ? c.strategyOf : {},\n  }\n}\n\n/**\n * 未指定档位时的默认档（沿用旧行为：旧路径的默认是清单首个 mode，内置 ref2v 的\n * 首个 mode 即 quality）。解析结果里会带 resolution='tier-default' 与警告，不静默。\n */\nconst DEFAULT_TIER = 'quality'\n\nconst GUIDANCE_ORDER = 150\n\n// 未指定分组时的中性兜底名。分组词汇由 skill 自由定义，执行层不认识任何片型名词；\n// 展示顺序由画布 settings.groupOrder（skill 通过 canvas_set_state 声明）决定，未声明的按首次出现排。\nconst DEFAULT_GROUP = 'ungrouped'\n\n// ---------------------------------------------------------------------------\n// 小工具\n// ---------------------------------------------------------------------------\n\nconst text = (value) => [{ type: 'text', text: String(value) }]\n\nfunction HttpError(status, message) {\n  const e = new Error(message)\n  e.status = status\n  return e\n}\n\nfunction errorCode(error) {\n  if (!error || typeof error !== 'object') return ''\n  const code = Reflect.get(error, 'code')\n  return typeof code === 'string' ? code : ''\n}\n\nfunction sendJson(res, status, value) {\n  const body = JSON.stringify(value)\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(body),\n    'cache-control': 'no-store',\n  })\n  res.end(body)\n}\n\n/** 校验 workspace 内相对路径，防路径逃逸（借鉴 idesign / dsh-ssh）。 */\nfunction safeRelative(value, prefix = '') {\n  const normalized = String(value ?? '').replace(/\\\\/g, '/').replace(/^\\.\\//, '').replace(/\\/+$/, '')\n  if (!normalized || isAbsolute(normalized) || normalized.includes('\\0')) {\n    throw HttpError(400, 'invalid canvas path')\n  }\n  if (normalized.split('/').some((p) => !p || p === '.' || p === '..')) {\n    throw HttpError(400, 'invalid canvas path')\n  }\n  if (prefix) {\n    const root = prefix.replace(/\\/+$/, '')\n    if (normalized !== root && !normalized.startsWith(root + '/')) {\n      throw HttpError(403, 'path escapes canvas folder')\n    }\n  }\n  return normalized\n}\n\nfunction inside(root, target) {\n  const r = relative(root, target)\n  return r === '' || (!r.startsWith('..' + sep) && r !== '..' && !isAbsolute(r))\n}\n\nasync function requestJson(req, maxBytes = 8 * 1024 * 1024) {\n  const chunks = []\n  let size = 0\n  for await (const chunk of req) {\n    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)\n    size += buf.length\n    if (size > maxBytes) throw HttpError(413, 'request too large')\n    chunks.push(buf)\n  }\n  try {\n    const value = JSON.parse(Buffer.concat(chunks).toString('utf8'))\n    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('not object')\n    return value\n  } catch {\n    throw HttpError(400, 'invalid JSON body')\n  }\n}\n\nconst CONTENT_TYPES = {\n  '.css': 'text/css; charset=utf-8',\n  '.gif': 'image/gif',\n  '.html': 'text/html; charset=utf-8',\n  '.jpeg': 'image/jpeg',\n  '.jpg': 'image/jpeg',\n  '.js': 'text/javascript; charset=utf-8',\n  '.json': 'application/json; charset=utf-8',\n  '.png': 'image/png',\n  '.svg': 'image/svg+xml',\n  '.webp': 'image/webp',\n  '.mp4': 'video/mp4',\n  '.webm': 'video/webm',\n  '.mov': 'video/quicktime',\n  '.wav': 'audio/wav',\n  '.mp3': 'audio/mpeg',\n  '.m4a': 'audio/mp4',\n  '.flac': 'audio/flac',\n  '.ogg': 'audio/ogg',\n  '.mp4a': 'audio/mp4',\n  '.aac': 'audio/aac',\n  '.opus': 'audio/ogg',\n}\n\nconst contentType = (p) => CONTENT_TYPES[extname(p).toLowerCase()] || 'application/octet-stream'\n\n/** 计算一个媒体相对路径的交付信息：绝对路径 / 媒体类型 / 字节数（供 TUI/飞书渠道送达）。 */\nfunction mediaDelivery(root, media) {\n  if (!media) return { absPath: '', mediaType: '', bytes: 0 }\n  const absPath = join(root, ...String(media).split('/'))\n  let bytes = 0\n  try { bytes = statSync(absPath).size } catch { /* 文件缺失时保持 0 */ }\n  return { absPath, mediaType: contentType(absPath), bytes }\n}\n\n/** 字节数 → 人类可读（交付时对照 send_file 的单文件上限）。 */\nfunction humanSize(bytes) {\n  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B'\n  const units = ['B', 'KiB', 'MiB', 'GiB']\n  let value = bytes\n  let i = 0\n  while (value >= 1024 && i < units.length - 1) { value /= 1024; i++ }\n  return (i === 0 ? String(Math.round(value)) : value.toFixed(1)) + ' ' + units[i]\n}\n\n/** 生成类工具结果的统一交付信息文本：相对路径供 send_file，绝对路径供终端打开。 */\nfunction mediaResultDetail(value) {\n  const lines = [`相对路径(send_file 交付): ${value.media}`]\n  if (value.absPath) lines.push(`绝对路径(终端打开): ${value.absPath}`)\n  if (value.mediaType || value.bytes) lines.push(`媒体: ${value.mediaType || 'unknown'} · ${humanSize(value.bytes)}`)\n  return lines.join('\\n')\n}\n\n/**\n * 渲染结果的档位透明度说明：档位 → 实现 → 解析来源（+ 警告）。\n * 产品层必须能一眼看出\"这次实际用了哪个实现\"，否则又回到\"显示 fast 实际跑 20 步\"的失真。\n */\nfunction renderResolutionNote(value) {\n  if (!value || !value.ok) return ''\n  const bits = []\n  if (value.tier) bits.push(`档位 ${value.tier}`)\n  if (value.implementation) bits.push(`实现 ${value.implementation}`)\n  if (value.resolution) bits.push(`解析 ${value.resolution}`)\n  const warn = Array.isArray(value.warnings) && value.warnings.length ? `\\n注意：${value.warnings.join('；')}` : ''\n  return (bits.length ? `\\n${bits.join(' · ')}` : '') + warn\n}\n\n/** 视频提示词库结果说明：让调用方看到「这次真正用了哪一档提示词」。 */\nfunction promptBankNote(value) {\n  if (!value || !value.ok || !value.promptNodeId) return ''\n  const bits = [`提示词库 ${value.promptNodeId}`]\n  if (value.promptTier) bits.push(`用 ${value.promptTier} 档`)\n  if (value.promptFallback) bits.push(`（无本档段落，回退到 ${value.promptFallback}）`)\n  return `\\n${bits.join(' ')}`\n}\n\n// ---------------------------------------------------------------------------\n// ComfyUI 客户端\n// ---------------------------------------------------------------------------\n\nasync function comfyFetch(path, init) {\n  const cfg = getCfg()\n  const headers = { ...(init?.headers || {}) }\n  if (cfg.apiKey) headers.authorization = 'Bearer ' + cfg.apiKey\n  let res\n  try {\n    res = await fetch(cfg.baseUrl + path, { ...init, headers })\n  } catch (error) {\n    throw new Error('comfy-unreachable: ComfyUI 不可达（' + cfg.baseUrl + '）：' + (error?.message || String(error)))\n  }\n  return res\n}\n\n/** 提交工作流，返回 prompt_id。 */\nasync function comfySubmit(graph) {\n  const res = await comfyFetch('/prompt', {\n    method: 'POST',\n    headers: { 'content-type': 'application/json' },\n    body: JSON.stringify({ prompt: graph, client_id: 'dsh-short-video-studio-' + randomUUID() }),\n  })\n  const body = await res.json().catch(() => ({}))\n  if (!res.ok || !body?.prompt_id) {\n    let detail = ''\n    if (body?.node_errors && Object.keys(body.node_errors).length) detail = JSON.stringify(body.node_errors)\n    else if (body?.error) detail = typeof body.error === 'string' ? body.error : JSON.stringify(body.error)\n    else if (body?.message) detail = body.message\n    else detail = res.status + (typeof res.statusText === 'string' ? ' ' + res.statusText : '')\n    throw new Error('workflow-validation: ComfyUI 拒绝工作流：' + (detail || res.status))\n  }\n  return body.prompt_id\n}\n\n/** 轮询 /history/{id} 直到 completed/error，带超时与 signal。 */\nasync function comfyWait(promptId, signal) {\n  const deadline = Date.now() + GENERATION_TIMEOUT_MS\n  for (;;) {\n    if (signal?.aborted) throw new Error('generation cancelled')\n    if (Date.now() > deadline) throw new Error('timeout: ComfyUI 生成超时（>' + GENERATION_TIMEOUT_MS + 'ms）')\n    const res = await comfyFetch('/history/' + encodeURIComponent(promptId))\n    const body = await res.json().catch(() => ({}))\n    const entry = body?.[promptId]\n    if (entry) {\n      const status = entry.status\n      if (status?.completed) return entry\n      if (status?.status_str === 'error') {\n        const errs = []\n        for (const out of Object.values(entry.outputs || {})) {\n          for (const e of out?.node_errors || []) errs.push(e?.message || JSON.stringify(e))\n        }\n        throw new Error('generation-error: ' + (errs.join('; ') || 'ComfyUI 节点报错'))\n      }\n    }\n    await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS))\n  }\n}\n\n/** 从 history 抽取输出文件。 */\nfunction comfyOutputs(entry) {\n  const files = []\n  const seen = new Set()\n  for (const out of Object.values(entry?.outputs || {})) {\n    for (const kind of ['images', 'videos', 'gifs', 'audio']) {\n      for (const item of out?.[kind] || []) {\n        // LoadVideo/LoadImage 等**加载类节点**会把输入文件回显成 images/videos 条目（type=input）。\n        // 那不是产物：误收会把「上一镜」当成这一镜的结果存进画布（链式续接里尤其致命）。\n        if (item.type === 'input') continue\n        const key = (item.type || 'output') + '/' + (item.subfolder || '') + '/' + item.filename\n        if (seen.has(key)) continue\n        seen.add(key)\n        files.push({ filename: item.filename, subfolder: item.subfolder || '', type: item.type || 'output' })\n      }\n    }\n  }\n  return files\n}\n\n/** 下载产物为 Buffer。 */\nasync function comfyDownload(file) {\n  const params = new URLSearchParams({\n    filename: file.filename,\n    subfolder: file.subfolder,\n    type: file.type || 'output',\n  })\n  const res = await comfyFetch('/view?' + params.toString())\n  if (!res.ok) throw new Error('comfy-download-failed: ' + res.status + ' ' + file.filename)\n  return Buffer.from(await res.arrayBuffer())\n}\n\n/** 上传媒体文件（图片 / 音频 / 视频）到 ComfyUI input 目录，返回 {name, subfolder, type}。 */\nasync function comfyUploadMedia(buffer, filename) {\n  const form = new FormData()\n  form.append('image', new Blob([buffer]), filename)\n  form.append('overwrite', 'true')\n  const res = await comfyFetch('/upload/image', { method: 'POST', body: form })\n  const body = await res.json().catch(() => ({}))\n  if (!res.ok || !body?.name) {\n    throw new Error('comfy-upload-failed: ' + (body?.error || body?.message || res.status))\n  }\n  return body\n}\n\n/** 兼容旧调用名（/upload/image 同时接受图片与音频/视频，行为不变）。 */\nconst comfyUploadImage = comfyUploadMedia\n\n/** 参考音频上限（与 H3 官方 Ref2VA 规格一致：≤3 段、每段 2–15s、总 15s、单文件 15MB）。 */\nconst AUDIO_REF_MAX_COUNT = 3\nconst AUDIO_REF_MAX_BYTES = 15 * 1024 * 1024\nconst AUDIO_REF_MIN_SEC = 2\nconst AUDIO_REF_MAX_SEC = 15\nconst AUDIO_REF_TOTAL_SEC = 15\n\n/** 直接从 WAV 头读时长（不依赖 ffprobe；本机没装也能校验 2–15s，最常见的情况）。 */\nfunction probeWavDurationSec(buf) {\n  try {\n    if (buf.length < 44) return null\n    if (buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') return null\n    let off = 12\n    let byteRate = 0\n    while (off + 8 <= buf.length) {\n      const id = buf.toString('ascii', off, off + 4)\n      const size = buf.readUInt32LE(off + 4)\n      if (id === 'fmt ' && off + 20 <= buf.length) byteRate = buf.readUInt32LE(off + 16)\n      else if (id === 'data') {\n        if (byteRate > 0 && size > 0) return size / byteRate\n        return null\n      }\n      off += 8 + size + (size % 2)\n    }\n  } catch { /* 不是合法 WAV：交给上层判定 */ }\n  return null\n}\n\n/** 用 ffprobe 读时长（本机可能没有 ffprobe；失败返回 null，由调用方降级为警告）。 */\nfunction probeMediaDurationSec(absPath) {\n  return new Promise((resolvePromise) => {\n    execFile('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'default=nw=1:nk=1', absPath],\n      { timeout: 8000 }, (error, stdout) => {\n        if (error) return resolvePromise(null)\n        const v = Number(String(stdout || '').trim().split('\\n')[0])\n        resolvePromise(Number.isFinite(v) && v > 0 ? v : null)\n      })\n  })\n}\n\n// ---------------------------------------------------------------------------\n// 工作流模板（ComfyUI API 格式）\n// ---------------------------------------------------------------------------\n\n/**\n * FLUX 2 文生图工作流。\n * UNETLoader → ModelSamplingFlux → CLIPLoader → VAELoader →\n * CLIPTextEncode(通用，mistral flux2 CLIP) → FluxGuidance →\n * EmptyFlux2LatentImage → Flux2Scheduler →\n * RandomNoise + BasicGuider + KSamplerSelect → SamplerCustomAdvanced → VAEDecode → SaveImage\n */\nfunction buildFluxImageWorkflow({ prompt, width, height, seed, steps, guidance, filenamePrefix }) {\n  const models = getCfg().models\n  return {\n    '1': { class_type: 'UNETLoader', inputs: { unet_name: models.fluxUnet, weight_dtype: 'default' } },\n    '2': { class_type: 'CLIPLoader', inputs: { clip_name: models.fluxClip, type: FLUX_CLIP_TYPE } },\n    '3': { class_type: 'VAELoader', inputs: { vae_name: models.fluxVae } },\n    '4': { class_type: 'ModelSamplingFlux', inputs: { model: ['1', 0], max_shift: 1.15, base_shift: 0.5, width, height } },\n    '5': { class_type: 'CLIPTextEncode', inputs: { text: prompt, clip: ['2', 0] } },\n    '5b': { class_type: 'FluxGuidance', inputs: { conditioning: ['5', 0], guidance } },\n    '6': { class_type: 'EmptyFlux2LatentImage', inputs: { width, height, batch_size: 1 } },\n    '7': { class_type: 'Flux2Scheduler', inputs: { steps, width, height } },\n    '8': { class_type: 'RandomNoise', inputs: { noise_seed: seed } },\n    '9': { class_type: 'BasicGuider', inputs: { model: ['4', 0], conditioning: ['5b', 0] } },\n    '10': { class_type: 'KSamplerSelect', inputs: { sampler_name: 'euler' } },\n    '11': { class_type: 'SamplerCustomAdvanced', inputs: { noise: ['8', 0], guider: ['9', 0], sampler: ['10', 0], sigmas: ['7', 0], latent_image: ['6', 0] } },\n    '12': { class_type: 'VAEDecode', inputs: { samples: ['11', 0], vae: ['3', 0] } },\n    '13': { class_type: 'SaveImage', inputs: { images: ['12', 0], filename_prefix: filenamePrefix } },\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 分辨率计算：fast/quality 均按「每档固定长边 + 画布 aspectRatio」推导宽高，\n// 因此 fast 也支持 9:16 / 1:1 等任意比例（不再写死 832×480）。\n// ---------------------------------------------------------------------------\nconst VIDEO_MODE_LONG = { fast: 832, quality: 1344 }\nconst VIDEO_MODE_DEFAULT = { fast: { w: 832, h: 480 }, quality: { w: 1344, h: 768 } }\n/** 起链序号：会话级单调递增；起点随机（latent 槽位跨会话共享，随机起点避免两会话互踩）。 */\nfunction allocateChainIndex(project) {\n  if (!project.settings || typeof project.settings !== 'object') project.settings = {}\n  const s = project.settings\n  if (!Number.isInteger(s.chainNext) || s.chainNext < 1) s.chainNext = 1 + Math.floor(Math.random() * 9000)\n  return s.chainNext\n}\n\n/** 采样帧数取整到模型合法网格（清单声明 [步长, 偏移]，如 17k+5）：**向上**取整，不缩短交付。 */\nfunction snapLengthToGrid(len, grid) {\n  const n = Math.max(1, Math.round(Number(len) || 1))\n  if (!Array.isArray(grid) || grid.length !== 2) return n\n  const step = Math.max(1, Math.round(Number(grid[0]) || 1))\n  const offset = Math.max(1, Math.round(Number(grid[1]) || 1))\n  if (n <= offset) return offset\n  return offset + Math.ceil((n - offset) / step) * step\n}\n\nfunction snap32(n) { return Math.max(32, Math.round(n / 32) * 32) }\n/**\n * 计算单镜头视频实际宽高。\n * - 显式传入 width/height：直接采用（snap 到 32 倍数）；\n * - 否则按 aspectRatio（如 '16:9'/'9:16'/'1:1'）以「每档长边」推导；\n * - 都没给：回退每档默认（fast 832×480 / quality 1344×768）。\n */\nfunction computeVideoSize({ mode, width, height, aspectRatio }) {\n  const hasW = Number.isFinite(width) && width > 0\n  const hasH = Number.isFinite(height) && height > 0\n  if (hasW && hasH) return { w: snap32(width), h: snap32(height) }\n  const m = /^\\s*(\\d+)\\s*[:/x]\\s*(\\d+)\\s*$/.exec(String(aspectRatio || '').trim())\n  if (m) {\n    const rw = Number(m[1])\n    const rh = Number(m[2])\n    const long = VIDEO_MODE_LONG[mode] || VIDEO_MODE_LONG.quality\n    if (rw >= rh) return { w: long, h: snap32(long * rh / rw) }\n    return { w: snap32(long * rw / rh), h: long }\n  }\n  return VIDEO_MODE_DEFAULT[mode] || VIDEO_MODE_DEFAULT.quality\n}\n\n/**\n * MiniMax H3 音视频 + 参考绑定工作流（静音→有声，去参考→参考绑定）。\n * - 模式 quality：1344×768 / 20 步 / 无 LoRA；fast：4 步 / Lightning LoRA（调试）。\n * - 分辨率由调用方按画布 aspectRatio 传入 width/height（fast/quality 均支持任意比例）。\n * - refComfyNames 为已上传到 ComfyUI 的参考图文件名（角色/场景卡），经\n *   MiniMaxH3ReferenceToVideo 的 ref_images.ref_image_N（dotted）绑定身份/环境。\n * - 音频经 VAEDecodeAudio(audio_vae) → CreateVideo(audio) 合成，不再静音。\n */\nfunction buildH3VideoWorkflow({ prompt, width, height, length, seed, steps, filenamePrefix, mode = 'quality', refComfyNames = [] }) {\n  const fast = mode === 'fast'\n  const w = width\n  const h = height\n  const st = fast ? 4 : steps\n  const sampler = 'res_multistep'\n  const scheduler = 'simple'\n  const models = getCfg().models\n\n  const graph = {\n    '1': { class_type: 'UNETLoader', inputs: { unet_name: models.h3RefUnet, weight_dtype: 'default' } },\n    '3': { class_type: 'CLIPLoader', inputs: { clip_name: models.h3Clip, type: H3_CLIP_TYPE } },\n    '4': { class_type: 'VAELoader', inputs: { vae_name: models.h3VideoVae } },\n    '4a': { class_type: 'VAELoader', inputs: { vae_name: models.h3AudioVae } },\n  }\n\n  // 模型链路：fast 档插入 Lightning LoRA（4 步 turbo）\n  let modelRef = ['1', 0]\n  if (fast) {\n    graph['1a'] = { class_type: 'LoraLoaderModelOnly', inputs: { lora_name: models.h3FastLora, strength_model: 1.0, model: ['1', 0] } }\n    modelRef = ['1a', 0]\n  }\n  graph['2'] = { class_type: 'MiniMaxH3SigmaShift', inputs: { model: modelRef, shift_video: 12.0, shift_audio: 3.0 } }\n\n  const n5 = { clip: ['3', 0], vae: ['4', 0], audio_vae: ['4a', 0], prompt, width: w, height: h, length, ref_image_size: 'match' }\n  if (Array.isArray(refComfyNames) && refComfyNames.length) {\n    for (let i = 0; i < refComfyNames.length; i++) {\n      const nodeKey = String(200 + i)\n      graph[nodeKey] = { class_type: 'LoadImage', inputs: { image: refComfyNames[i] } }\n      n5['ref_images.ref_image_' + i] = [nodeKey, 0]\n    }\n  }\n  graph['5'] = { class_type: 'MiniMaxH3ReferenceToVideo', inputs: n5 }\n\n  graph['6'] = { class_type: 'RandomNoise', inputs: { noise_seed: seed } }\n  graph['7'] = { class_type: 'BasicGuider', inputs: { model: ['2', 0], conditioning: ['5', 0] } }\n  graph['8'] = { class_type: 'KSamplerSelect', inputs: { sampler_name: sampler } }\n  graph['9'] = { class_type: 'BasicScheduler', inputs: { model: ['2', 0], scheduler, steps: st, denoise: 1.0 } }\n  graph['10'] = { class_type: 'SamplerCustomAdvanced', inputs: { noise: ['6', 0], guider: ['7', 0], sampler: ['8', 0], sigmas: ['9', 0], latent_image: ['5', 1] } }\n  graph['11'] = { class_type: 'VAEDecode', inputs: { samples: ['10', 0], vae: ['4', 0] } }\n  graph['11a'] = { class_type: 'VAEDecodeAudio', inputs: { samples: ['10', 0], vae: ['4a', 0] } }\n  graph['12'] = { class_type: 'CreateVideo', inputs: { images: ['11', 0], audio: ['11a', 0], fps: H3_FPS } }\n  graph['13'] = { class_type: 'SaveVideo', inputs: { video: ['12', 0], filename_prefix: filenamePrefix, format: 'mp4', codec: 'h264' } }\n\n  return graph\n}\n\n/**\n * MiniMax H3 首/末帧串联 + 音频工作流（用于同场景续接镜，改善 Q5 过渡）。\n * - first_frame_node/last_frame_node：把上一镜末帧 / 本镜末帧作为首帧/末帧，实现连续性。\n * - 与 buildH3VideoWorkflow 不同，它用 MiniMaxH3ImageToVideo（无 ref_images，但 latent 仍可\n *   VAEDecodeAudio 取音频），身份/环境由首帧（真实帧）继承。\n */\nfunction buildH3ImageToVideoWorkflow({ prompt, width, height, length, seed, steps, filenamePrefix, mode = 'quality', firstFrameComfyName = null, lastFrameComfyName = null }) {\n  const fast = mode === 'fast'\n  const w = width\n  const h = height\n  const st = fast ? 4 : steps\n  const sampler = 'res_multistep'\n  const scheduler = 'simple'\n  const models = getCfg().models\n\n  const graph = {\n    '1': { class_type: 'UNETLoader', inputs: { unet_name: models.h3FlUnet, weight_dtype: 'default' } },\n    '3': { class_type: 'CLIPLoader', inputs: { clip_name: models.h3Clip, type: H3_CLIP_TYPE } },\n    '4': { class_type: 'VAELoader', inputs: { vae_name: models.h3VideoVae } },\n    '4a': { class_type: 'VAELoader', inputs: { vae_name: models.h3AudioVae } },\n  }\n  let modelRef = ['1', 0]\n  if (fast) {\n    graph['1a'] = { class_type: 'LoraLoaderModelOnly', inputs: { lora_name: models.h3FlFastLora, strength_model: 1.0, model: ['1', 0] } }\n    modelRef = ['1a', 0]\n  }\n  graph['2'] = { class_type: 'MiniMaxH3SigmaShift', inputs: { model: modelRef, shift_video: 12.0, shift_audio: 3.0 } }\n\n  const n5 = { clip: ['3', 0], vae: ['4', 0], prompt, width: w, height: h, length }\n  let nid = 200\n  if (firstFrameComfyName) {\n    graph[String(nid)] = { class_type: 'LoadImage', inputs: { image: firstFrameComfyName } }\n    graph[String(nid + 1)] = { class_type: 'ImageScale', inputs: { image: [String(nid), 0], upscale_method: 'lanczos', width: w, height: h, crop: 'disabled' } }\n    n5.first_frame = [String(nid + 1), 0]\n    nid += 2\n  }\n  if (lastFrameComfyName) {\n    graph[String(nid)] = { class_type: 'LoadImage', inputs: { image: lastFrameComfyName } }\n    graph[String(nid + 1)] = { class_type: 'ImageScale', inputs: { image: [String(nid), 0], upscale_method: 'lanczos', width: w, height: h, crop: 'disabled' } }\n    n5.last_frame = [String(nid + 1), 0]\n  }\n  graph['5'] = { class_type: 'MiniMaxH3ImageToVideo', inputs: n5 }\n\n  graph['6'] = { class_type: 'RandomNoise', inputs: { noise_seed: seed } }\n  graph['7'] = { class_type: 'BasicGuider', inputs: { model: ['2', 0], conditioning: ['5', 0] } }\n  graph['8'] = { class_type: 'KSamplerSelect', inputs: { sampler_name: sampler } }\n  graph['9'] = { class_type: 'BasicScheduler', inputs: { model: ['2', 0], scheduler, steps: st, denoise: 1.0 } }\n  graph['10'] = { class_type: 'SamplerCustomAdvanced', inputs: { noise: ['6', 0], guider: ['7', 0], sampler: ['8', 0], sigmas: ['9', 0], latent_image: ['5', 1] } }\n  graph['11'] = { class_type: 'VAEDecode', inputs: { samples: ['10', 0], vae: ['4', 0] } }\n  graph['11a'] = { class_type: 'VAEDecodeAudio', inputs: { samples: ['10', 0], vae: ['4a', 0] } }\n  graph['12'] = { class_type: 'CreateVideo', inputs: { images: ['11', 0], audio: ['11a', 0], fps: H3_FPS } }\n  graph['13'] = { class_type: 'SaveVideo', inputs: { video: ['12', 0], filename_prefix: filenamePrefix, format: 'mp4', codec: 'h264' } }\n\n  return graph\n}\n\n// ---------------------------------------------------------------------------\n// 画布存储\n// ---------------------------------------------------------------------------\n\nfunction projectDir(root, sessionId) {\n  return join(root, CANVAS_DIR, sessionId)\n}\nfunction projectFile(root, sessionId) {\n  return join(projectDir(root, sessionId), 'project.json')\n}\n\nfunction emptyProject(sessionId) {\n  return {\n    schemaVersion: 1,\n    sessionId,\n    settings: normalizeSettings({}),\n    approvals: {},\n    nodes: [],\n  }\n}\n\nasync function loadProject(root, sessionId) {\n  const file = projectFile(root, sessionId)\n  if (!existsSync(file)) return emptyProject(sessionId)\n  try {\n    const parsed = JSON.parse(await readFile(file, 'utf8'))\n    if (!parsed || typeof parsed !== 'object') return emptyProject(sessionId)\n    if (!Array.isArray(parsed.nodes)) parsed.nodes = []\n    if (!parsed.approvals || typeof parsed.approvals !== 'object') parsed.approvals = {}\n    parsed.settings = normalizeSettings(parsed.settings, { project: parsed, root })\n    return parsed\n  } catch {\n    return emptyProject(sessionId)\n  }\n}\n\n/** 原子写 project.json（临时文件 + rename），带 per-session 串行化。 */\nconst writeLocks = new Map()\nasync function saveProject(root, sessionId, project) {\n  const key = root + ':' + sessionId\n  const prev = writeLocks.get(key) || Promise.resolve()\n  let release\n  const tail = new Promise((r) => (release = r))\n  const queued = prev.then(() => tail, () => tail)\n  writeLocks.set(key, queued)\n  await prev.catch(() => {})\n  try {\n    const dir = projectDir(root, sessionId)\n    await mkdir(dir, { recursive: true })\n    const file = projectFile(root, sessionId)\n    const tmp = join(dir, '.project.' + randomUUID() + '.tmp')\n    await writeFile(tmp, JSON.stringify(project, null, 2), 'utf8')\n    await rename(tmp, file)\n  } finally {\n    release()\n    if (writeLocks.get(key) === queued) writeLocks.delete(key)\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 项目配置（settings v2）：STEP 0 参数的结构化真相源\n//\n// 真相源是 project.settings；画布上的「配置卡」只是它的投影（同一写入口\n// applyProjectConfig 原子更新）。所有生成/后处理门都读这一份。\n// ---------------------------------------------------------------------------\nconst FLOW_VALUES = ['story', 'series', 'brand', 'ecommerce', 'free']\nconst CONFIG_GROUP = '项目配置'\nconst CONFIG_CARD_TITLE = '项目配置（STEP 0）'\nconst CONFIG_CARD_PREFIX = 'cfg-'\nconst DELIVERY_VALUES = ['native', 'upscale1080', 'upscale2k', 'upscale4k', 'regen2k', 'fps48']\n// 门组（§10）：契约门（h3/几何/写保护）永远开；流程门按 flow 开。\n// 未知 flow → free（只开契约门）。新片型 = 在这里加一行，不改门实现。\n// approval = 创作批准门（角色卡/场景卡/镜头表/分镜/片段的人工确认凭据，\n// 见 makeApprovalGateListener）。story/series 必开；brand/ecommerce 暂不开\n// （品牌片的 6 列表与资产形态不同，仍走品牌事实表/硬确认卡）。\nconst GATE_PROFILES = {\n  free: ['h3'],\n  story: ['h3', 'plan', 'shot', 'config', 'approval'],\n  series: ['h3', 'plan', 'shot', 'production', 'config', 'approval'],\n  brand: ['h3', 'config', 'shot'],\n  ecommerce: ['h3', 'config', 'shot'],\n}\n\n/** 当前项目是否启用某个流程门（契约门不走这里）。 */\nfunction gateOn(settings, id) {\n  const flow = GATE_PROFILES[settings?.flow] ? settings.flow : 'free'\n  return GATE_PROFILES[flow].includes(id)\n}\nconst BREAKING_FIELDS = new Set([\n  'flow', 'aspectRatio', 'duration', 'audioMode', 'delivery',\n  'characterCardVariant', 'voicePlan', 'subtitles', 'language', 'style', 'bgmMode',\n])\nconst SETTINGS_DEFAULTS = {\n  aspectRatio: '16:9',\n  duration: '',\n  audioMode: 'silent',\n  reviewMode: 'per-shot',\n  shotGate: 'verdict',\n  mode: 'quality',\n  imageTier: 'balanced',\n  delivery: 'native',\n  characterCardVariant: 'single',\n  voicePlan: 'existing',\n  subtitles: 'none',\n  language: 'auto',\n  style: '',\n  bgmMode: 'none',\n}\n\nfunction pickEnum(value, allowed, fallback) {\n  return allowed.includes(value) ? value : fallback\n}\n\n/** 按结构推断片型：有系列状态 → series；有七列镜头表 → story；否则 free。 */\nfunction inferFlow(project, root) {\n  if (project?.settings?.series?.id) return 'series'\n  if (root && existsSync(join(root, 'series', 'production-state.json'))) return 'series'\n  const nodes = Array.isArray(project?.nodes) ? project.nodes : []\n  const hasPlan = nodes.some((n) => n?.kind === 'table' && typeof n.content === 'string' && parseShotTableContent(n.content))\n  // 老项目没有 flow 字段：已经有视频产物 = 走过故事/剧集拍摄，按 story 迁移（避免丢 shot 门）。\n  const hasVideo = nodes.some((n) => n?.kind === 'video')\n  return hasPlan || hasVideo ? 'story' : 'free'\n}\n\n/** 规范化 settings（缺省值 / 枚举 / 一致性）。不写盘，纯函数。 */\nfunction normalizeSettings(input, { project = null, root = '' } = {}) {\n  const src = input && typeof input === 'object' ? input : {}\n  const out = { ...SETTINGS_DEFAULTS, ...src }\n  out.aspectRatio = typeof out.aspectRatio === 'string' && out.aspectRatio.trim() ? out.aspectRatio.trim() : '16:9'\n  out.duration = typeof out.duration === 'string' ? out.duration : (out.duration == null ? '' : String(out.duration))\n  out.audioMode = pickEnum(out.audioMode, ['silent', 'dialogue-led', 'narration-led'], 'silent')\n  out.reviewMode = pickEnum(out.reviewMode, ['per-shot', 'batch'], 'per-shot')\n  out.shotGate = pickEnum(out.shotGate, ['off', 'frames', 'verdict'], 'verdict')\n  out.mode = pickEnum(out.mode, TIERS, 'quality')\n  out.imageTier = pickEnum(out.imageTier, TIERS, 'balanced')\n  out.delivery = pickEnum(out.delivery, DELIVERY_VALUES, 'native')\n  out.characterCardVariant = pickEnum(out.characterCardVariant, ['single', 'three'], 'single')\n  out.voicePlan = pickEnum(out.voicePlan, ['existing', 'audition', 'text-only'], 'existing')\n  out.subtitles = pickEnum(out.subtitles, ['none', 'burned-in'], 'none')\n  out.language = pickEnum(out.language, ['zh', 'en', 'auto'], 'auto')\n  out.style = typeof out.style === 'string' ? out.style.trim() : ''\n  out.bgmMode = pickEnum(out.bgmMode, ['none', 'in-model'], 'none')\n  // fast 档只能单视图：任何写入都收敛到 single，避免把非法组合落盘。\n  if (out.mode === 'fast' && out.characterCardVariant === 'three') out.characterCardVariant = 'single'\n  out.flow = FLOW_VALUES.includes(out.flow) ? out.flow : inferFlow(project, root)\n  out.groupOrder = Array.isArray(src.groupOrder)\n    ? src.groupOrder.filter((g) => typeof g === 'string' && g.trim()).map((g) => g.trim())\n    : (Array.isArray(out.groupOrder) ? out.groupOrder : undefined)\n  if (out.groupOrder && !out.groupOrder.includes(CONFIG_GROUP)) out.groupOrder = [CONFIG_GROUP, ...out.groupOrder]\n  out.rev = Number.isInteger(out.rev) && out.rev >= 0 ? out.rev : 0\n  out.breakingRev = Number.isInteger(out.breakingRev) && out.breakingRev >= 0 ? out.breakingRev : 0\n  out.configured = out.configured === true\n  out.meta = out.meta && typeof out.meta === 'object' ? out.meta : {}\n  out.series = out.series && typeof out.series === 'object' ? out.series : undefined\n  if (!out.series) delete out.series\n  return out\n}\n\nconst CONFIG_FIELD_ROWS = [\n  ['flow', '片型 flow'],\n  ['aspectRatio', '画幅'],\n  ['duration', '总时长'],\n  ['audioMode', '音频模式'],\n  ['mode', '视频档位'],\n  ['imageTier', '图片档位'],\n  ['delivery', '交付画质'],\n  ['characterCardVariant', '角色卡版本'],\n  ['voicePlan', '声线方案'],\n  ['subtitles', '字幕'],\n  ['language', '语言'],\n  ['style', '视觉风格'],\n  ['bgmMode', 'BGM 模式'],\n  ['reviewMode', '审查节奏'],\n  ['shotGate', '逐镜自检门'],\n]\n\nconst CONFIG_IMPACT_NOTES = {\n  flow: '门组与字段 schema 变化，需重走该片型 STEP 0',\n  aspectRatio: '已出卡片/分镜/片段比例不对',\n  duration: '镜头预算重算',\n  audioMode: '已出片段的对白/声线不匹配',\n  mode: '非破坏性（逐镜可覆盖）',\n  imageTier: '非破坏性（已有卡片仍有效）',\n  delivery: '交付路线变化',\n  characterCardVariant: '身份形态变化',\n  voicePlan: '声线锚点变化',\n  subtitles: '提示词与成片是否带字',\n  language: '台词/字幕语言变化',\n  style: '全部卡片/片段作废',\n  bgmMode: 'BGM 有无',\n  reviewMode: '只影响后续人工确认时机',\n  shotGate: '只影响后续自检门强度',\n}\n\nfunction configValueLabel(key, value) {\n  if (value === '' || value == null) return '（未设）'\n  return String(value)\n}\n\n/** 配置卡正文（由 settings 生成，不手改）。 */\nfunction renderConfigMarkdown(settings) {\n  const meta = settings.meta || {}\n  const sources = meta.sources || {}\n  const locked = new Set(Array.isArray(meta.locked) ? meta.locked : [])\n  const header = [\n    `## ${CONFIG_CARD_TITLE}`,\n    '',\n    `- 片型 flow：\\`${settings.flow}\\` · 配置版本 rev ${settings.rev} · 更新者 ${meta.updatedBy || 'default'}`,\n    `- 状态：${settings.configured ? '已配置' : '未配置'}${locked.size ? ' · 锁定字段：' + [...locked].join(' / ') : ''}`,\n    '',\n    '| 项 | 值 | 来源 | 改动影响 |',\n    '|---|---|---|---|',\n  ]\n  const rows = CONFIG_FIELD_ROWS.map(([key, label]) => {\n    const src = locked.has(key) ? '系列锁定' : (sources[key] || 'default')\n    return `| ${label} | ${configValueLabel(key, settings[key])} | ${src} | ${CONFIG_IMPACT_NOTES[key] || ''} |`\n  })\n  return [\n    ...header,\n    ...rows,\n    '',\n    '> 本卡由系统维护，直接改文本会被拒绝。改配置请在画布点「⚙ 配置」，或让 Agent 调用 canvas_set_state。',\n  ].join('\\n')\n}\n\nfunction configCardId(sessionId) {\n  return CONFIG_CARD_PREFIX + sessionId\n}\n\nfunction findConfigCard(project) {\n  return (project?.nodes || []).find((n) => n?.params?.configCard) || null\n}\n\nfunction upsertConfigCard(project, settings, sessionId) {\n  const id = configCardId(sessionId)\n  const content = renderConfigMarkdown(settings)\n  let node = (project.nodes || []).find((n) => n.id === id || n?.params?.configCard) || null\n  if (!node) {\n    const minOrder = project.nodes.reduce((m, n) => Math.min(m, Number(n.order) || 0), 0)\n    node = {\n      id,\n      kind: 'text',\n      title: CONFIG_CARD_TITLE,\n      content,\n      media: '',\n      group: CONFIG_GROUP,\n      params: {},\n      status: 'ready',\n      createdAt: Date.now(),\n      order: minOrder - 1,\n    }\n    project.nodes.push(node)\n  }\n  node.kind = 'text'\n  node.title = CONFIG_CARD_TITLE\n  node.content = content\n  node.media = ''\n  node.group = CONFIG_GROUP\n  node.status = 'ready'\n  node.params = {\n    ...(node.params || {}),\n    configCard: true,\n    configRev: settings.rev,\n    config: JSON.parse(JSON.stringify(settings)),\n  }\n  return node\n}\n\n/** 配置变更影响面（给 UI/工具返回一个可读的数字）。 */\nfunction computeConfigImpact(project, changed = []) {\n  const nodes = (project?.nodes || []).filter((n) => !n?.params?.configCard)\n  return {\n    changed: [...new Set(changed)],\n    images: nodes.filter((n) => n.kind === 'image').length,\n    videos: nodes.filter((n) => n.kind === 'video').length,\n    tables: nodes.filter((n) => n.kind === 'table').length,\n    total: nodes.length,\n  }\n}\n\nfunction configChangedFields(prev, next) {\n  const keys = new Set([...Object.keys(prev || {}), ...Object.keys(next || {})])\n  const out = []\n  for (const k of keys) {\n    if (k === 'meta' || k === 'rev' || k === 'breakingRev' || k === 'configured') continue\n    if (JSON.stringify(prev?.[k]) !== JSON.stringify(next?.[k])) out.push(k)\n  }\n  return out\n}\n\n/** 把配置卡导出成 PDF（送达链路读 node.file）；失败不影响配置保存。 */\nasync function exportConfigCard(root, sessionId, node) {\n  try {\n    const pdfTool = await detectPdfTool()\n    const out = await exportTextNode(root, sessionId, node.id, node.title, node.kind, node.group, node.content, pdfTool)\n    node.file = out.rel\n  } catch (error) {\n    console.warn('[dsh-short-video-studio] 配置卡导出失败（不影响保存）:', error?.message || error)\n  }\n}\n\n/**\n * 唯一配置写入口：校验 + 交叉规则 + rev/breakingRev + 配置卡同步 + 落盘。\n * - source: user | agent | package | migration\n * - expectedRev: 乐观并发；不一致抛 code=CONFIG_REV_CONFLICT（errors.settings 带最新配置）\n */\nasync function applyProjectConfig(root, sessionId, patch = {}, opts = {}) {\n  const source = ['user', 'agent', 'package', 'migration'].includes(opts.source) ? opts.source : 'agent'\n  const project = await loadProject(root, sessionId)\n  const prev = normalizeSettings(project.settings, { project, root })\n  if (opts.expectedRev !== undefined && opts.expectedRev !== null && Number(opts.expectedRev) !== prev.rev) {\n    const error = new Error(`配置已被更新（当前 rev ${prev.rev}，你看到的是 rev ${opts.expectedRev}）`)\n    error.code = 'CONFIG_REV_CONFLICT'\n    error.settings = prev\n    throw error\n  }\n  const cleanPatch = {}\n  for (const [k, v] of Object.entries(patch && typeof patch === 'object' ? patch : {})) {\n    if (k === 'sessionId' || k === 'workspaceId') continue\n    cleanPatch[k] = v\n  }\n  const merged = { ...prev, ...cleanPatch }\n  const next = normalizeSettings(merged, { project, root })\n  const warnings = []\n  if (cleanPatch.flow !== undefined && !FLOW_VALUES.includes(cleanPatch.flow)) {\n    warnings.push(`未知片型 flow=\"${cleanPatch.flow}\"，已按结构推断为 ${next.flow}（可用：${FLOW_VALUES.join(' / ')}）`)\n  }\n  if (next.mode === 'fast' && (cleanPatch.characterCardVariant === 'three' || prev.characterCardVariant === 'three')) {\n    warnings.push('生成档位是 fast：角色卡引用版本只能是 single，已自动改为单视图')\n  }\n  if (next.subtitles === 'burned-in' && next.mode !== 'quality') {\n    warnings.push('画面内字幕建议用 quality 档（fast/balanced 实测不稳）')\n  }\n  next.configured = true\n  if (!next.groupOrder) next.groupOrder = [CONFIG_GROUP]\n  const changed = configChangedFields(prev, next)\n  if (!prev.configured && next.configured) changed.push('configured')\n  if (changed.length) {\n    next.rev = prev.rev + 1\n    if (changed.some((f) => BREAKING_FIELDS.has(f))) next.breakingRev = next.rev\n    next.meta = {\n      ...(next.meta || {}),\n      updatedAt: new Date().toISOString(),\n      updatedBy: source,\n      sources: {\n        ...(next.meta?.sources || {}),\n        ...Object.fromEntries(changed.filter((f) => f !== 'configured').map((f) => [f, source])),\n      },\n    }\n  } else {\n    next.rev = prev.rev\n  }\n  project.settings = next\n  // 破坏性配置变更（画幅/风格/角色卡版本/字幕/音频…）让所有创作批准作废：\n  // 旧卡、旧镜头表、旧分镜、旧片段都不再可信，必须重做并重新确认。\n  if (changed.some((f) => BREAKING_FIELDS.has(f))) project.approvals = {}\n  const prevCard = findConfigCard(project)\n  const prevContent = prevCard?.content || ''\n  const card = upsertConfigCard(project, next, sessionId)\n  if (card.content !== prevContent || !card.file) await exportConfigCard(root, sessionId, card)\n  await saveProject(root, sessionId, project)\n  return {\n    ok: true,\n    rev: next.rev,\n    cardNodeId: card.id,\n    changed: [...new Set(changed)],\n    warnings,\n    impact: computeConfigImpact(project, changed),\n  }\n}\n\nfunction nextOrder(nodes) {\n  return nodes.reduce((m, n) => Math.max(m, Number(n.order) || 0), -1) + 1\n}\n\n// ---------------------------------------------------------------------------\n// workspace / session 解析\n// ---------------------------------------------------------------------------\n\n/**\n * 解析会话工作区根目录。\n * 优先级：显式 workspaceId → agent 会话 cwd → workspaceRegistry 会话成员扫描。\n */\nfunction resolveSessionRoot(ctx, sessionId, workspaceId, exec) {\n  const sid = sessionId || exec?.agent?.id\n  if (!sid) throw HttpError(400, 'sessionId required')\n\n  if (workspaceId) {\n    const w = ctx.workspaceRegistry.get(workspaceId)\n    if (w) return { sessionId: sid, root: w.path, workspaceId: String(w.id) }\n  }\n\n  const cwd = exec?.agent?.session?.meta?.cwd\n  if (cwd) return { sessionId: sid, root: cwd, workspaceId: '' }\n\n  for (const w of ctx.workspaceRegistry.list()) {\n    if (w.sessionIds.includes(sid)) return { sessionId: sid, root: w.path, workspaceId: String(w.id) }\n  }\n\n  throw HttpError(404, 'workspace not found for session ' + sid)\n}\n\n// ---------------------------------------------------------------------------\n// 归档搬迁：DSH 的「归档会话」只在 registry 里加一个 flag（不碰工作区文件）。\n// 这里订阅 domain/changed 的 workspace.global put，把 <工作区>/canvas/<sid>\n// 搬到配置的 archiveRoot，取消归档再从归档路径搬回工作区。\n// archiveRoot 为空 = 不迁移（与旧行为完全一致）。\n// ---------------------------------------------------------------------------\n\n/** 设置页「最近操作」环形缓冲（进程内，重启即空）。 */\nconst archiveRecent = []\nconst ARCHIVE_RECENT_MAX = 30\n\nfunction recordArchiveOp(entry) {\n  archiveRecent.unshift({ at: new Date().toISOString(), ...entry })\n  if (archiveRecent.length > ARCHIVE_RECENT_MAX) archiveRecent.length = ARCHIVE_RECENT_MAX\n}\n\n/** 归档路径（规范化后）。'' = 未配置 → 关闭；null = 非法（相对路径）。 */\nfunction configuredArchiveRoot() {\n  return normalizeArchiveRoot(getCfg().archiveRoot)\n}\n\n/** 会话 → 工作区记录。归档不动 workspace.sessionIds，所以归档中的会话仍能查到归属。 */\nfunction workspaceOfSession(ctx, sessionId) {\n  const sid = String(sessionId)\n  for (const w of ctx.workspaceRegistry.list()) {\n    if ((w.sessionIds || []).some((id) => String(id) === sid)) return w\n  }\n  return undefined\n}\n\nconst ARCHIVE_MOVED_STATUSES = new Set(['moved', 'copied', 'merged', 'deduped', 'conflict'])\n\n/** 归档一个会话的画布目录；返回迁移结果并记入最近操作。 */\nasync function archiveOneSession(ctx, sessionId) {\n  const archiveRoot = configuredArchiveRoot()\n  if (!archiveRoot) return { status: 'disabled' }\n  const sid = String(sessionId)\n  const ws = workspaceOfSession(ctx, sid)\n  if (!ws) {\n    recordArchiveOp({ action: 'archive', sessionId: sid, status: 'no-workspace' })\n    return { status: 'no-workspace' }\n  }\n  const stats = await dirStats(join(ws.path, CANVAS_DIR, sid))\n  const res = await archiveSessionDir({ workspacePath: ws.path, sessionId: sid, archiveRoot, canvasDirName: CANVAS_DIR })\n  if (ARCHIVE_MOVED_STATUSES.has(res.status)) {\n    await updateArchiveIndex(archiveRoot, sid, {\n      workspaceId: String(ws.id), workspaceTitle: ws.title || '', workspacePath: ws.path,\n      archivedAt: new Date().toISOString(), status: res.status,\n      files: stats?.files ?? null, bytes: stats?.bytes ?? null,\n    }).catch((error) => {\n      recordArchiveOp({ action: 'index', sessionId: sid, status: 'error', error: String(error?.message || error) })\n    })\n  }\n  recordArchiveOp({\n    action: 'archive', sessionId: sid, status: res.status, via: res.via || '',\n    files: stats?.files ?? null, bytes: stats?.bytes ?? null,\n    workspaceTitle: ws.title || '', workspacePath: ws.path,\n    ...(res.renamed ? { renamed: res.renamed } : {}),\n  })\n  return res\n}\n\n/** 取消归档：把归档区里的画布目录搬回工作区（工作区未知时用索引兜底定位）。 */\nasync function restoreOneSession(ctx, sessionId) {\n  const archiveRoot = configuredArchiveRoot()\n  if (!archiveRoot) return { status: 'disabled' }\n  const sid = String(sessionId)\n  let ws = workspaceOfSession(ctx, sid)\n  if (!ws) {\n    const index = await readArchiveIndex(archiveRoot).catch(() => ({ sessions: {} }))\n    const meta = index.sessions?.[sid]\n    if (meta?.workspacePath) ws = { id: meta.workspaceId || '', path: meta.workspacePath, title: meta.workspaceTitle || '' }\n  }\n  if (!ws) {\n    recordArchiveOp({ action: 'restore', sessionId: sid, status: 'no-workspace' })\n    return { status: 'no-workspace' }\n  }\n  const res = await restoreSessionDir({ workspacePath: ws.path, sessionId: sid, archiveRoot, canvasDirName: CANVAS_DIR })\n  if (res.status !== 'in-workspace' && res.status !== 'missing') {\n    await updateArchiveIndex(archiveRoot, sid, null).catch(() => {})\n  }\n  recordArchiveOp({\n    action: 'restore', sessionId: sid, status: res.status, via: res.via || '',\n    workspacePath: ws.path, ...(res.renamed ? { renamed: res.renamed } : {}),\n  })\n  return res\n}\n\n/**\n * 同一会话的搬迁任务串行化（watcher 的归档/取消归档、以及「打开画布时按需回迁」共用一条链）。\n * 用 catch 吞掉失败只影响链的推进，调用方拿到的是原始 promise。\n */\nconst archiveTaskChains = new Map()\n\nfunction queueArchiveTask(sessionId, task) {\n  const sid = String(sessionId)\n  const prev = archiveTaskChains.get(sid) || Promise.resolve()\n  const next = prev.then(task, task)\n  const tail = next.catch(() => {})\n  archiveTaskChains.set(sid, tail)\n  tail.finally(() => { if (archiveTaskChains.get(sid) === tail) archiveTaskChains.delete(sid) })\n  return next\n}\n\n/**\n * 打开画布前的按需回迁：会话已取消归档、但画布还在归档区（大工程从 NAS 回迁要几秒到几十秒），\n * 此时直接读 project.json 会得到空画布。GET /canvas 先等回迁落位再返回。\n * 与 watcher 共用同一会话的串行链，不会重复搬。\n */\nasync function ensureArchiveRestored(ctx, workspacePath, sessionId) {\n  const archiveRoot = configuredArchiveRoot()\n  if (!archiveRoot) return { status: 'disabled' }\n  const sid = String(sessionId)\n  if (existsSync(join(workspacePath, CANVAS_DIR, sid))) return { status: 'in-workspace' }\n  if (!existsSync(join(archiveRoot, sid))) return { status: 'missing' }\n  // 仍在归档中的会话不主动搬回（正常路径是 DSH 的「取消归档」事件）\n  try {\n    if (ctx.workspaceRegistry.archivedSessionIds.map(String).includes(sid)) return { status: 'still-archived' }\n  } catch { /* registry 未就绪：继续按缺失处理 */ }\n  return queueArchiveTask(sid, () => restoreOneSession(ctx, sid))\n}\n\nlet reconcileRunning = null\n\n/**\n * 手动 / 启动对账：把「已归档但画布还在工作区」的搬出去，把「已取消归档但画布还在归档区」的搬回来。\n * 幂等；同一时刻只跑一份。插件在会话已归档之后才加载时，靠它补一次。\n */\nfunction reconcileArchive(ctx) {\n  if (reconcileRunning) return reconcileRunning\n  reconcileRunning = (async () => {\n    const archiveRoot = configuredArchiveRoot()\n    if (!archiveRoot) return { ok: true, configured: false, skipped: 'archiveRoot 未配置' }\n    const summary = { ok: true, configured: true, archiveRoot, archivedMoved: 0, restored: 0, errors: [], details: [] }\n    let archived = new Set()\n    try { archived = new Set(ctx.workspaceRegistry.archivedSessionIds.map(String)) } catch { /* 域未就绪 */ }\n\n    // 1) 已归档 → 搬到归档区（只处理工作区里还留着 canvas 目录的）\n    for (const ws of ctx.workspaceRegistry.list()) {\n      for (const rawId of ws.sessionIds || []) {\n        const sid = String(rawId)\n        if (!archived.has(sid)) continue\n        if (!existsSync(join(ws.path, CANVAS_DIR, sid))) continue\n        try {\n          const res = await queueArchiveTask(sid, () => archiveOneSession(ctx, sid))\n          if (res.status === 'moved' || res.status === 'copied' || res.status === 'merged') summary.archivedMoved++\n          summary.details.push({ sessionId: sid, action: 'archive', status: res.status })\n        } catch (error) {\n          summary.errors.push(`archive ${sid}: ${error?.message || error}`)\n        }\n      }\n    }\n\n    // 2) 归档区里已取消归档的 → 搬回工作区（工作区未知的目录不动，避免无主回迁）\n    let entries = []\n    try { entries = await readdir(archiveRoot, { withFileTypes: true }) } catch { entries = [] }\n    for (const ent of entries) {\n      if (!ent.isDirectory()) continue\n      const sid = ent.name\n      if (archived.has(sid)) continue\n      if (!workspaceOfSession(ctx, sid)) continue\n      try {\n        const res = await queueArchiveTask(sid, () => restoreOneSession(ctx, sid))\n        if (res.status === 'restored' || res.status === 'copied' || res.status === 'merged') summary.restored++\n        summary.details.push({ sessionId: sid, action: 'restore', status: res.status })\n      } catch (error) {\n        summary.errors.push(`restore ${sid}: ${error?.message || error}`)\n      }\n    }\n    return summary\n  })().finally(() => { reconcileRunning = null })\n  return reconcileRunning\n}\n\n/**\n * 订阅 workspace 域的 global put，diff 出新增/移除的归档 id 并排搬迁。\n * 搬迁前留一点稳定时间（「停止并归档」的取消在事件之后才下达，别和还在飞的写入抢目录）；\n * 搬完再复查一次，防止 abort 期间又写回 canvas/<sid>。\n * @returns {() => void} 注销函数\n */\nfunction startArchiveWatcher(ctx) {\n  let known = null\n  try { known = new Set(ctx.workspaceRegistry.archivedSessionIds.map(String)) } catch { known = null }\n\n  const timers = new Map()\n  const rawSettle = Number(process.env.DSH_SVS_ARCHIVE_SETTLE_MS ?? DEFAULT_SETTLE_MS)\n  const settleMs = Number.isFinite(rawSettle) && rawSettle >= 0 ? rawSettle : DEFAULT_SETTLE_MS\n  const rawRecheck = Number(process.env.DSH_SVS_ARCHIVE_RECHECK_MS ?? DEFAULT_RECHECK_MS)\n  const recheckMs = Number.isFinite(rawRecheck) && rawRecheck >= 0 ? rawRecheck : DEFAULT_RECHECK_MS\n\n  /** 当前归档集里的成员判定（读 registry；读不到按\"非归档\"处理，避免误搬）。 */\n  const archivedNow = (sessionId) => {\n    try { return ctx.workspaceRegistry.archivedSessionIds.map(String).includes(String(sessionId)) } catch { return false }\n  }\n\n  /**\n   * 执行一次搬迁。**按 sessionId 串行**（归档与取消归档共用一条链），\n   * 并在执行前复核 registry 现状：期间用户可能又点了取消归档，\n   * 这时旧的 archive 任务必须作废，否则会把刚回迁的画布再搬走。\n   */\n  const run = (sessionId, action) => {\n    const sid = String(sessionId)\n    return queueArchiveTask(sid, () => {\n        if (archivedNow(sid) !== (action === 'archive')) {\n          recordArchiveOp({ action, sessionId: sid, status: 'superseded' })\n          return { status: 'superseded' }\n        }\n        return action === 'archive' ? archiveOneSession(ctx, sid) : restoreOneSession(ctx, sid)\n      })\n      .then((res) => {\n        // 复查：归档后再扫一次，处理 abort 竞态遗留的写回；取消归档则确认已回位。\n        const moved = res.status === 'moved' || res.status === 'copied' || res.status === 'merged' || res.status === 'conflict'\n        if (moved && !timers.has(sid)) {\n          const t = setTimeout(() => { timers.delete(sid); run(sid, action) }, recheckMs)\n          if (typeof t.unref === 'function') t.unref()\n          timers.set(sid, t)\n        }\n      })\n      .catch((error) => {\n        recordArchiveOp({ action, sessionId: sid, status: 'error', error: String(error?.message || error) })\n        console.warn('[dsh-short-video-studio] 归档搬迁失败:', sid, error?.message || error)\n      })\n  }\n\n  /** 排一次搬迁；同一会话只保留一个待执行动作（后到的覆盖先到的，例如快速\"归档→取消归档\"）。 */\n  const schedule = (sessionId, action, delay) => {\n    const sid = String(sessionId)\n    if (timers.has(sid)) clearTimeout(timers.get(sid))\n    const t = setTimeout(() => { timers.delete(sid); run(sid, action) }, Math.max(0, delay))\n    if (typeof t.unref === 'function') t.unref()\n    timers.set(sid, t)\n  }\n\n  const onChange = (change) => {\n    try {\n      if (!change || change.domain !== 'workspace' || change.table !== '' || change.operation !== 'put') return\n      const next = new Set(((change.value && change.value.archivedSessionIds) || []).map(String))\n      if (known === null) { known = next; return } // 首帧只做基线，不搬历史\n      const { added, removed } = diffArchived(known, [...next])\n      known = next\n      for (const id of added) schedule(id, 'archive', settleMs)\n      for (const id of removed) schedule(id, 'restore', 0)\n    } catch (error) {\n      console.warn('[dsh-short-video-studio] 归档事件处理失败:', error?.message || error)\n    }\n  }\n\n  const off = ctx.on('domain/changed', onChange, { global: true })\n\n  // 启动对账：插件可能在「已归档」之后才加载（或曾禁用/旧版本），补搬一次。\n  const reconcileTimer = setTimeout(() => {\n    reconcileArchive(ctx).catch((error) => console.warn('[dsh-short-video-studio] 归档对账失败:', error?.message || error))\n  }, 8000)\n  if (typeof reconcileTimer.unref === 'function') reconcileTimer.unref()\n\n  return () => {\n    off?.()\n    clearTimeout(reconcileTimer)\n    for (const t of timers.values()) clearTimeout(t)\n    timers.clear()\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 生成执行（图片 / 视频），写回画布\n// ---------------------------------------------------------------------------\n\n/**\n * 读图片的**真实像素尺寸**（PNG / JPEG / WebP）。读不出返回 null（不猜）。\n *\n * 为什么需要它：交付尺寸必须**如实记账**——i2i 的尺寸跟随参考图、放大类实现的交付 = 首遍 ×倍率，\n * 都与「图内推导出来的尺寸」不同。旧行为是拿推导值写进画布节点（i2i 会记 1344×768 而产物是 1056×1056），\n * 拼接/续接的一致性判断读这个字段就会错。\n */\nfunction probeImageSize(absPath) {\n  let buf\n  try { buf = readFileSync(absPath) } catch { return null }\n  if (buf.length > 24 && buf.toString('latin1', 1, 4) === 'PNG') {\n    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) }\n  }\n  if (buf.length > 30 && buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') {\n    const fmt = buf.toString('latin1', 12, 16)\n    try {\n      if (fmt === 'VP8X') return { w: 1 + buf.readUIntLE(24, 3), h: 1 + buf.readUIntLE(27, 3) }\n      if (fmt === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff }\n      if (fmt === 'VP8L') {\n        const b = buf.readUInt32LE(21)\n        return { w: (b & 0x3fff) + 1, h: ((b >> 14) & 0x3fff) + 1 }\n      }\n    } catch { return null }\n  }\n  if (buf.length > 4 && buf[0] === 0xff && buf[1] === 0xd8) {\n    let off = 2\n    while (off + 9 < buf.length) {\n      if (buf[off] !== 0xff) { off++; continue }\n      const marker = buf[off + 1]\n      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {\n        return { h: buf.readUInt16BE(off + 5), w: buf.readUInt16BE(off + 7) }\n      }\n      off += 2 + buf.readUInt16BE(off + 2)\n    }\n  }\n  return null\n}\n\nasync function persistMedia(root, sessionId, buffer, filename) {\n  const dir = projectDir(root, sessionId)\n  await mkdir(dir, { recursive: true })\n  const target = join(dir, filename)\n  await writeFile(target, buffer)\n  return CANVAS_DIR + '/' + sessionId + '/' + filename\n}\n\n// ---------------------------------------------------------------------------\n// 手动资产导入（画布「自己添加角色卡/场景卡」）\n//   importManualImage    — 上传的本地图片 → 画布 image 节点\n//   copyAssetToCanvas    — 资产库中的资产 → 画布 image 节点（工具/路由共用）\n// 入库仍是用户可选的独立动作（画布卡片「入库」按钮），与「入库由用户人工完成」\n// 的契约一致：此处只落画布卡，不写资产库。\n// ---------------------------------------------------------------------------\n\nconst UPLOAD_MIME = {\n  'image/png': '.png',\n  'image/jpeg': '.jpg',\n  'image/webp': '.webp',\n  'image/gif': '.gif',\n  // 参考音频（P1）：画布可以直接收人声样本，作为 H3 Ref2VA 的 <Audio N>\n  'audio/wav': '.wav',\n  'audio/x-wav': '.wav',\n  'audio/wave': '.wav',\n  'audio/mpeg': '.mp3',\n  'audio/mp4': '.m4a',\n  'audio/x-m4a': '.m4a',\n  'audio/flac': '.flac',\n  'audio/ogg': '.ogg',\n  'audio/webm': '.webm',\n  'audio/aac': '.aac',\n  'audio/opus': '.opus',\n}\nconst AUDIO_UPLOAD_EXTS = new Set(['.wav', '.mp3', '.m4a', '.flac', '.ogg', '.webm', '.aac', '.opus'])\nconst UPLOAD_MAX_FILE = 24 * 1024 * 1024\nconst UPLOAD_MAX_FILES = 12\n\n/** data:image/...;base64 → { buffer, ext }；非法输入抛错（图片专用，替换图片走这条）。 */\nfunction parseDataUrlImage(dataUrl) {\n  const m = /^data:(image\\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/=]+)$/.exec(String(dataUrl || '').trim())\n  if (!m) throw new Error('仅支持 png / jpg / webp / gif 图片的 dataURL')\n  const buffer = Buffer.from(m[2], 'base64')\n  if (!buffer.length) throw new Error('图片内容为空')\n  if (buffer.length > UPLOAD_MAX_FILE) throw new Error('图片超过 24MB 上限')\n  return { buffer, ext: UPLOAD_MIME[m[1]] }\n}\n\n/** data:<mime>;base64 → { buffer, ext, kind }；图片与音频都收（画布手动添加）。 */\nfunction parseDataUrlMedia(dataUrl) {\n  const m = /^data:((?:image|audio)\\/[a-z0-9.+-]+);base64,([A-Za-z0-9+/=]+)$/i.exec(String(dataUrl || '').trim())\n  if (!m) throw new Error('仅支持图片（png/jpg/webp/gif）或音频（wav/mp3/m4a/flac/ogg/webm）的 dataURL')\n  const ext = UPLOAD_MIME[m[1].toLowerCase()]\n  if (!ext) throw new Error('不支持的媒体类型：' + m[1])\n  const buffer = Buffer.from(m[2], 'base64')\n  if (!buffer.length) throw new Error('媒体内容为空')\n  if (buffer.length > UPLOAD_MAX_FILE) throw new Error('媒体超过 24MB 上限')\n  return { buffer, ext, kind: AUDIO_UPLOAD_EXTS.has(ext) ? 'audio' : 'image' }\n}\n\n/** 把上传的本地媒体（图片 / 音频）存成画布节点（params.source='manual-upload'）。 */\nasync function importManualImage(root, sessionId, item, group) {\n  const { buffer, ext, kind } = parseDataUrlMedia(item && item.dataUrl)\n  const durationSec = kind === 'audio' ? probeWavDurationSec(buffer) : null\n  const nodeId = randomUUID()\n  const rel = await persistMedia(root, sessionId, buffer, 'upload-' + nodeId + ext)\n  const fallbackName = kind === 'audio' ? '音频' : '图片'\n  const rawName = String((item && item.filename) || '').replace(/\\\\/g, '/').split('/').pop() || fallbackName\n  const baseName = rawName.replace(/\\.[^.]+$/, '').trim().slice(0, 60) || fallbackName\n  const project = await loadProject(root, sessionId)\n  const node = {\n    id: nodeId,\n    kind,\n    title: (item && typeof item.title === 'string' && item.title.trim()) ? item.title.trim().slice(0, 60) : baseName,\n    media: rel,\n    group: group || DEFAULT_GROUP,\n    params: {\n      source: 'manual-upload', originalName: rawName,\n      ...(durationSec ? { durationSec: Math.round(durationSec * 1000) / 1000 } : {}),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  project.nodes.push(node)\n  await saveProject(root, sessionId, project)\n  return node\n}\n\n/**\n * 把资产库（.dsh-assets/library.json）中的资产物化为当前画布节点，按 kind 决定产物：\n *   - image / video：库文件拷贝到 canvas/<sessionId>/，建同 kind 的媒体节点（params.assetId 绑定资产 id）\n *   - text：不落文件，直接建 text/table 节点，正文取资产记录的 text\n * 三种情况都写 params.assetId，方便「已入库」态与后续追溯。\n */\nasync function copyAssetToCanvas(root, sessionId, ref, opts = {}) {\n  const lib = loadLibrary(root)\n  const id = canonicalAssetId(ref)\n  const a = lib.assets[id]\n  if (!a) throw new Error('资产不存在: ' + ref)\n  const kind = assetKind(a)\n\n  const nodeId = opts.nodeId || randomUUID()\n  const project = await loadProject(root, sessionId)\n  const prev = project.nodes.find((n) => n.id === nodeId)\n\n  let node\n  if (kind === 'text') {\n    node = {\n      id: nodeId,\n      kind: a.nodeKind === 'table' ? 'table' : 'text',\n      title: opts.title || a.title || a.name || id,\n      content: String(a.text == null ? '' : a.text),\n      group: opts.group || DEFAULT_GROUP,\n      params: { assetId: id, model: 'asset:' + id, capability: opts.capability || null },\n      status: 'ready',\n      createdAt: Date.now(),\n      order: nextOrder(project.nodes),\n    }\n  } else {\n    const abs = resolveAssetPath(root, lib, id)\n    if (!abs) throw new Error('资产文件缺失: ' + (a.file || a.image || id))\n    const buf = await readFile(abs)\n    const rel = await persistMedia(root, sessionId, buf, 'asset-' + assetFilename(id) + (extname(abs) || '.png'))\n    node = {\n      id: nodeId,\n      kind, // image / video / audio\n      title: opts.title || a.name || id,\n      media: rel,\n      group: opts.group || DEFAULT_GROUP,\n      params: {\n        assetId: id,\n        model: 'asset:' + id,\n        speaksOnScreen: a.speaksOnScreen,\n        // 角色卡双版本：把资产里的配对元数据带到画布节点，显式 ref_variant 才能换到同角色目标版本\n        ...(a.character ? { character: String(a.character) } : {}),\n        ...(a.cardVariant === 'single' || a.cardVariant === 'three' ? { cardVariant: a.cardVariant } : {}),\n      },\n      status: 'ready',\n      createdAt: Date.now(),\n      order: nextOrder(project.nodes),\n    }\n  }\n\n  if (prev) { node.order = prev.order; node.createdAt = prev.createdAt }\n  if (prev) project.nodes[project.nodes.findIndex((n) => n.id === nodeId)] = node\n  else project.nodes.push(node)\n  await saveProject(root, sessionId, project)\n  return node\n}\n\n/**\n * 替换画布某 image 节点的图片（画布卡「编辑 → 本地上传替换」）。\n * - 新图落盘为 upload-<uuid><ext>，节点 media 指向新文件（原文件保留在磁盘）。\n * - 该节点此前若已绑定资产库（params.assetId，来自入库或 asset_to_canvas），\n *   替换后**解除绑定**（库中旧图不被被动更新），返回 prevAssetId 供提示用户按需重新「入库」。\n * - 生成类元数据（model/prompt/seed/steps/width/height 等）一并清掉，避免误导\n *   「这张图是按旧参数生成」；capability/状态类 params 保留。\n * - 清除 deliveredAt/deliveryError：替换后的新图会在下次 ask 前重新自动送达（飞书）。\n */\nasync function replaceNodeImage(root, sessionId, nodeId, item) {\n  const { buffer, ext } = parseDataUrlImage(item && item.dataUrl)\n  const project = await loadProject(root, sessionId)\n  const idx = project.nodes.findIndex((n) => n.id === nodeId)\n  if (idx < 0) throw new Error('节点不存在: ' + nodeId)\n  const n = project.nodes[idx]\n  if (n.kind !== 'image') throw new Error('仅 image 节点可替换图片（当前 ' + (n.kind || '?') + '）')\n\n  const rel = await persistMedia(root, sessionId, buffer, 'upload-' + randomUUID() + ext)\n  const params = { ...(n.params || {}) }\n  const prevAssetId = params.assetId\n  delete params.assetId\n  for (const k of ['model', 'prompt', 'seed', 'steps', 'guidance', 'width', 'height', 'length', 'count']) delete params[k]\n  const rawName = String((item && item.filename) || '').replace(/\\\\/g, '/').split('/').pop() || ''\n  params.source = 'manual-upload'\n  params.replacedAt = Date.now()\n  if (rawName) params.originalName = rawName\n  delete params.deliveredAt\n  delete params.deliveryError\n\n  n.media = rel\n  n.params = params\n  project.nodes[idx] = n\n  await saveProject(root, sessionId, project)\n  return { node: n, prevAssetId, assetIdCleared: Boolean(prevAssetId) }\n}\n\nasync function runImageGeneration(ctx, opts) {\n  const { workspaceId, exec } = opts\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, workspaceId, exec)\n  const width = intArg(opts, 'width', 1344)\n  const height = intArg(opts, 'height', 768)\n  const seed = intArg(opts, 'seed', Math.floor(Math.random() * 2 ** 31))\n  const steps = intArg(opts, 'steps', 20)\n  const guidance = floatArg(opts, 'guidance', 3.5)\n  const count = Math.min(Math.max(intArg(opts, 'count', 1), 1), 4)\n  const nodeId = opts.nodeId || randomUUID()\n\n  const files = []\n  for (let i = 0; i < count; i++) {\n    const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId\n    const graph = buildFluxImageWorkflow({ prompt: opts.prompt, width, height, seed: seed + i, steps, guidance, filenamePrefix: prefix })\n    const promptId = await comfySubmit(graph)\n    const entry = await comfyWait(promptId, opts.signal)\n    const outputs = comfyOutputs(entry)\n    if (outputs.length === 0) throw new Error('generation-error: ComfyUI 无输出')\n    for (const f of outputs) {\n      const buf = await comfyDownload(f)\n      files.push(await persistMedia(root, sessionId, buf, f.filename))\n    }\n  }\n\n  const project = await loadProject(root, sessionId)\n  const node = {\n    id: nodeId,\n    kind: 'image',\n    title: opts.title || 'FLUX 图片',\n    media: files[0] || '',\n    group: opts.group || DEFAULT_GROUP,\n    params: { model: 'flux', seed, width, height, steps, guidance, prompt: opts.prompt },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n  await saveProject(root, sessionId, project)\n\n  return { ok: true, node, files }\n}\n\nasync function runVideoGeneration(ctx, opts) {\n  const { workspaceId, exec } = opts\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, workspaceId, exec)\n  const explicitW = opts.width !== undefined && opts.width !== null && opts.width !== ''\n  const explicitH = opts.height !== undefined && opts.height !== null && opts.height !== ''\n  const width = intArg(opts, 'width', 1344)\n  const height = intArg(opts, 'height', 768)\n  const length = intArg(opts, 'length', 124)\n  const seed = intArg(opts, 'seed', Math.floor(Math.random() * 2 ** 31))\n  const steps = intArg(opts, 'steps', 20)\n  const mode = opts.mode === 'fast' ? 'fast' : 'quality'\n  const nodeId = opts.nodeId || randomUUID()\n\n  const project = await loadProject(root, sessionId)\n  // 实际生效分辨率：显式 width/height 优先，否则按画布 aspectRatio 推导（fast/quality 均支持任意比例）\n  const { w: effW, h: effH } = computeVideoSize({\n    mode,\n    width: explicitW ? width : undefined,\n    height: explicitH ? height : undefined,\n    aspectRatio: project.settings?.aspectRatio,\n  })\n  // 上传画布图片节点 → ComfyUI 文件名（参考图 / 首末帧）\n  const uploadNode = async (nid) => {\n    const n = project.nodes.find((x) => x.id === nid)\n    if (n?.media) {\n      const absPath = join(root, ...n.media.split('/'))\n      if (existsSync(absPath)) {\n        const buf = await readFile(absPath)\n        const up = await comfyUploadImage(buf, basename(n.media))\n        return up.name\n      }\n    }\n    return null\n  }\n\n  // 参考绑定（角色卡/场景卡）→ ReferenceToVideo 路径\n  const refNodeIds = Array.isArray(opts.ref_nodes) ? opts.ref_nodes : []\n  const refComfyNames = []\n  for (const rid of refNodeIds) {\n    const name = await uploadNode(rid)\n    if (name) refComfyNames.push(name)\n  }\n\n  // 首/末帧串联（同场景续接）→ ImageToVideo 路径\n  const firstFrameComfyName = opts.first_frame_node ? await uploadNode(opts.first_frame_node) : null\n  const lastFrameComfyName = opts.last_frame_node ? await uploadNode(opts.last_frame_node) : null\n  const useChaining = Boolean(firstFrameComfyName || lastFrameComfyName)\n\n  const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId\n  const graph = useChaining\n    ? buildH3ImageToVideoWorkflow({ prompt: opts.prompt, width: effW, height: effH, length, seed, steps, filenamePrefix: prefix, mode, firstFrameComfyName, lastFrameComfyName })\n    : buildH3VideoWorkflow({ prompt: opts.prompt, width: effW, height: effH, length, seed, steps, filenamePrefix: prefix, mode, refComfyNames })\n  const promptId = await comfySubmit(graph)\n  const entry = await comfyWait(promptId, opts.signal)\n  const outputs = comfyOutputs(entry)\n  if (outputs.length === 0) throw new Error('generation-error: ComfyUI 无输出')\n\n  const files = []\n  for (const f of outputs) {\n    const buf = await comfyDownload(f)\n    files.push(await persistMedia(root, sessionId, buf, f.filename))\n  }\n\n  // 记录实际生效分辨率（fast/quality 均按画布比例或传入宽高计算）\n  const node = {\n    id: nodeId,\n    kind: 'video',\n    title: opts.title || 'MiniMax H3 视频',\n    media: files[0] || '',\n    group: opts.group || DEFAULT_GROUP,\n    params: { model: 'minimax-h3' + (mode === 'fast' ? '-fast' : ''), seed, width: effW, height: effH, length, fps: H3_FPS, steps: mode === 'fast' ? 4 : steps, mode, ref_nodes: refNodeIds, first_frame_node: opts.first_frame_node || null, last_frame_node: opts.last_frame_node || null, prompt: opts.prompt },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n  await saveProject(root, sessionId, project)\n\n  return { ok: true, node, files }\n}\n\nfunction intArg(obj, key, dflt) {\n  const v = obj?.[key]\n  if (v === undefined || v === null || v === '') return dflt\n  const n = Number(v)\n  return Number.isFinite(n) ? Math.floor(n) : dflt\n}\nfunction floatArg(obj, key, dflt) {\n  const v = obj?.[key]\n  if (v === undefined || v === null || v === '') return dflt\n  const n = Number(v)\n  return Number.isFinite(n) ? n : dflt\n}\n\n// ---------------------------------------------------------------------------\n// 通用渲染（M2）：capability → manifest → 编译图 → ComfyUI → 写画布\n// ---------------------------------------------------------------------------\n\nlet _registry = null\nlet _registrySig = null\n// 用户清单目录。`DSH_SVS_USER_WORKFLOWS` 是**测试接缝**：e2e 脚本指到临时目录，\n// 就不必往用户真实配置目录里塞夹具（也能保证跑完不留垃圾）。缺省仍是标准位置。\nconst USER_WORKFLOWS_DIR = process.env.DSH_SVS_USER_WORKFLOWS || join(homedir(), '.dsh', 'dsh-short-video-studio', 'workflows')\n\n/**\n * 清单目录指纹：文件名 + mtime + size。任一清单被生成器重写、新增或删除都会变。\n * 两处目录都很小（内置 ~31 个 json），readdir + stat 约 0.1ms，够便宜到每次 getRegistry 都查。\n */\nfunction manifestSignature() {\n  return [resolve(packageRoot, 'workflows'), USER_WORKFLOWS_DIR].map((dir) => {\n    try {\n      return readdirSync(dir)\n        .filter((n) => n.endsWith('.json'))\n        .sort()\n        .map((n) => {\n          try { const s = statSync(join(dir, n)); return `${n}:${s.mtimeMs}:${s.size}` } catch { return `${n}:?` }\n        })\n        .join(',')\n    } catch { return '(absent)' }\n  }).join('|')\n}\n\n/** 重新加载内置 + 用户清单（用户同名遮蔽内置）。 */\nfunction reloadRegistry() {\n  // 先取指纹再读文件：若读取途中恰好有人改清单，指纹会偏旧 → 下次调用再重载一次（多一次无害）\n  const sig = manifestSignature()\n  const builtin = loadBuiltinManifests(resolve(packageRoot, 'workflows'))\n  const user = loadBuiltinManifests(USER_WORKFLOWS_DIR)\n  for (const m of builtin.manifests) m._source = 'builtin'\n  for (const m of user.manifests) m._source = 'user'\n  const byId = { ...builtin.byId, ...user.byId }\n  const byCapability = {}\n  for (const m of Object.values(byId)) (byCapability[m.capability] ||= []).push(m)\n  // 同能力候选**确定性排序**：priority 降序（缺省 0），再按 id 升序。\n  // 该顺序决定 `preferred` 为空时的隐式默认档（resolveManifest 取 candidates[0]），\n  // 所以不能依赖文件系统枚举顺序（曾导致\"新增一份清单就悄悄改掉默认档\"）。\n  // 约定：想永不被选为隐式默认的清单写负数 priority（如实验/依赖自定义节点的加速变体）。\n  for (const list of Object.values(byCapability)) {\n    list.sort((a, b) => (Number(b.priority) || 0) - (Number(a.priority) || 0) || String(a.id).localeCompare(String(b.id)))\n  }\n  _registry = {\n    manifests: Object.values(byId),\n    byId,\n    byCapability,\n    errors: [...builtin.errors, ...user.errors],\n  }\n  // 清单变动 → 节点可用性预检缓存作废（用户可能刚装了 Sol 之类的第三方节点）\n  _nodeProbe.clear()\n  _registrySig = sig\n  return _registry\n}\n\nfunction getRegistry() {\n  if (!_registry) return reloadRegistry()\n  // 清单目录变了（生成器重跑 / 用户新增）→ 自动重载。否则新清单要重启 dsh 才可见，\n  // 表现为「脚本刚生成的工作流在 comfy_list_workflows 里查不到、workflow= 也解析不到」。\n  if (_registrySig !== manifestSignature()) return reloadRegistry()\n  return _registry\n}\n\n/** 读取某 capability 的有序 preferred 工作流 id 列表（**家族序**：家族 = group，或清单自身 id）。 */\nfunction getPreferred(capability, cfg = null) {\n  const c = cfg || loadConfigFile()\n  return (Array.isArray(c.preferred?.[capability]) ? c.preferred[capability] : []).filter((id) => typeof id === 'string')\n}\n\n/**\n * 配置面「钉实现」：`cfg.pins[capability]` 可以是**实现 id**（如 `qwen-image-21-t2i-quality`）\n * 或**家族名**（如 `qwen-image-21-t2i`，= 清单的 group）。\n *\n * 存在意义：工具面不再接受 `workflow=`（实现选择归配置面），但排障与基准脚本仍需要一个\n * 「临时钉死某实现」的通道。钉死**不等于**允许跨档：钉的是 fast 档却请求 quality ⇒ 报错。\n *\n * @returns 命中的清单；未配置返回 null；配置非法/冲突抛错（不静默忽略）。\n */\nfunction resolvePinnedImplementation(capability, tier, cfg, registry) {\n  const raw = cfg?.pins?.[capability]\n  if (raw === undefined || raw === null || raw === '') return null\n  if (typeof raw !== 'string') throw new Error(`配置 pins[\"${capability}\"] 必须是字符串（实现 id 或家族名）`)\n  const key = raw.trim()\n  const direct = registry.byId[key]\n  if (direct) {\n    if (direct.capability !== capability) {\n      throw new Error(`配置 pins[\"${capability}\"] = \"${key}\" 的能力是 ${direct.capability}，与该能力不匹配：请在设置页修正`)\n    }\n    if (direct.tier && tier && direct.tier !== tier) {\n      throw new Error(`配置 pins[\"${capability}\"] 钉的是 ${direct.tier} 档实现 \"${key}\"，与请求的 ${tier} 档冲突（钉实现不跨档）：请改档位或改 pin`)\n    }\n    return direct\n  }\n  const pool = tierImplementations(capability, tier, registry)\n  const hit = pool.find((m) => groupNameOf(m) === key)\n  if (!hit) {\n    const fams = [...new Set(tierImplementations(capability, tier, registry).map(groupNameOf))]\n    throw new Error(\n      `配置 pins[\"${capability}\"] = \"${key}\" 既不是实现 id，也不是该能力 ${tier} 档的家族名` +\n      `（该档可用家族：${fams.join(' / ') || '无'}）：请在设置页修正`)\n  }\n  return hit\n}\n\n/**\n * 旧 models.* 键 → 各工作流资产的别名映射（升级后旧配置不失效）。\n * P2 拆分后每个档位是独立清单（<组名>-<档位>[-sol]），因此按族登记。\n */\nconst H3_REF2V_IDS = [\n  'minimax-h3-ref2v-fast', 'minimax-h3-ref2v-balanced', 'minimax-h3-ref2v-balanced-sol',\n  'minimax-h3-ref2v-quality', 'minimax-h3-ref2v-quality-sol',\n  // PDD 是**独立组/独立策略**（不是同组里的另一种\"加速\"）：base 仍属 ref2va 同族，\n  // 因此沿用本族资产表，只多一个 pdd 槽。\n  'minimax-h3-ref2v-balanced-pdd', 'minimax-h3-ref2v-balanced-pdd-sol',\n  // 链式续接（ctx）用同一批权重，只是多了上下文节点：资产继承与同档标准实现一致。\n  'minimax-h3-ref2v-ctx-fast', 'minimax-h3-ref2v-ctx-balanced', 'minimax-h3-ref2v-ctx-quality',\n  'minimax-h3-ref2v-ctx-balanced-pdd',\n  // 链式续接 + 原生块稀疏（BlockSparseAttention）：权重与 PDD 版完全一致（只多一个注意力 patch 节点），\n  // 资产继承与 PDD+ctx 相同（pdd 槽 → h3PddRef2v）。\n  'minimax-h3-ref2v-ctx-balanced-pdd-solattn',\n  // quality 版原生块稀疏：非 PDD 路径（20 步 base），资产继承与 ctx-quality 相同（无 pdd 槽）\n  'minimax-h3-ref2v-ctx-quality-solattn',\n  // 两阶段放大（hires）同样用 ref2va 同族权重（首遍与二遍共用一个 UNet），只是图里多了放大与二遍节点。\n  'minimax-h3-ref2v-hires',\n  // 学习式放大（2k）：仍是 ref2va 同族权重，只多一个 latent_upscaler 资产槽\n  // （该槽没有旧 models.* 键，所以不进 LEGACY 映射，仅继承本族其余资产）。\n  // ctx 版（同一族的 3 个档位）：链式续接 + 学习式放大可叠用——链上流动的是首遍 latent，\n  // 放大在其之后，所以续接契约落在首遍尺寸上而不是交付尺寸。\n  'minimax-h3-ref2v-ctx-quality-2k',\n  'minimax-h3-ref2v-ctx-quality-pdd2-2k',\n  'minimax-h3-ref2v-ctx-balanced-pdd-2k',\n  'minimax-h3-ref2v-ctx-balanced-2k',\n  'minimax-h3-ref2v-ctx-fast-2k',\n  // Pika H3 Flex（2026-11）：base 仍是 ref2va 同族，只多一个 lora_pika 槽（无旧 models.* 键）。\n  // 普通版与 ctx / ctx+原生块稀疏三个实现共用同一批权重，只是图结构不同。\n  'minimax-h3-ref2v-balanced-pika',\n  'minimax-h3-ref2v-ctx-balanced-pika',\n  'minimax-h3-ref2v-ctx-balanced-pika-solattn',\n  // Sol-H3-VAE 变体（解码器换 24 层蒸馏非因果解码，多一个只喂 VAEDecode 的 vae_decode 槽）\n  'minimax-h3-ref2v-ctx-balanced-pika-solattn-solvae',\n  'minimax-h3-ref2v-ctx-fast-solvae',\n  'minimax-h3-ref2v-ctx-fast-pika-solattn',\n  'minimax-h3-ref2v-ctx-fast-pika-solattn-solvae',\n  'minimax-h3-ref2v-fast-pika',\n  'minimax-h3-ref2v-fast-pika-solvae',\n  // Sol-H3-VAE × Pika lite / quality 组合（同为 ref2va 同族权重，只多 vae_decode 槽）\n  'minimax-h3-ref2v-ctx-balanced-pika-lite-solattn-solvae',\n  'minimax-h3-ref2v-ctx-quality-solattn-solvae',\n]\nconst H3_I2V_IDS = [\n  'minimax-h3-i2v-fast', 'minimax-h3-i2v-balanced', 'minimax-h3-i2v-balanced-sol',\n  'minimax-h3-i2v-quality', 'minimax-h3-i2v-quality-sol',\n  'minimax-h3-i2v-balanced-pdd', 'minimax-h3-i2v-balanced-pdd-sol',\n  // i2v 版链式续接（ctx）：同样只多上下文节点，资产与同档标准 i2v 实现一致（走 fl2va/fl2v 配对键）\n  'minimax-h3-i2v-ctx-fast', 'minimax-h3-i2v-ctx-balanced', 'minimax-h3-i2v-ctx-balanced-pdd', 'minimax-h3-i2v-ctx-quality',\n  // 链式续接 + 原生块稀疏：资产与 i2v 的 PDD+ctx 相同（含 pdd 槽 → h3PddFl2v）\n  'minimax-h3-i2v-ctx-balanced-pdd-solattn',\n  // quality 版（非 PDD 路径，20 步 base）：资产继承与 i2v ctx-quality 相同\n  'minimax-h3-i2v-ctx-quality-solattn',\n  // 两阶段放大（hires）：fl2va 同族权重\n  'minimax-h3-i2v-hires',\n  // 学习式放大（2k）：fl2va 同族权重（同上，latent_upscaler 无旧键）\n  // ctx 版三档：balanced-pdd 额外继承 pdd 槽（h3PddFl2v）\n  'minimax-h3-i2v-ctx-quality-2k',\n  'minimax-h3-i2v-ctx-quality-pdd2-2k',\n  'minimax-h3-i2v-ctx-balanced-pdd-2k',\n  'minimax-h3-i2v-ctx-balanced-2k',\n  'minimax-h3-i2v-ctx-fast-2k',\n  // Pika H3 Flex（i2v / FL2VA）：与 ref2v 同构，只多一个 lora_pika 槽（走 fl2va 配对键）\n  'minimax-h3-i2v-balanced-pika',\n  'minimax-h3-i2v-ctx-balanced-pika',\n  'minimax-h3-i2v-ctx-balanced-pika-solattn',\n  // Sol-H3-VAE × Pika（i2v 版）：同为 fl2va 同族权重，只多 vae_decode 槽\n  'minimax-h3-i2v-ctx-balanced-pika-solattn-solvae',\n  'minimax-h3-i2v-ctx-balanced-pika-lite-solattn-solvae',\n]\nconst H3_REF2V_ASSETS = { unet: 'h3RefUnet', clip: 'h3Clip', vae: 'h3VideoVae', audio_vae: 'h3AudioVae', fast_lora: 'h3FastLora', lora_8step: 'h3BalancedLora', pdd: 'h3PddRef2v', lora_pika: 'h3PikaLora', vae_decode: 'h3SolVae' }\n// i2v 走 fl2va/fl2v 配对：**不能**复用 ref2v 的 h3RefUnet/h3FastLora，\n// 否则 manifest 里的 fl2va 默认值会被旧键静默覆盖（跨变体错配复现）。\nconst H3_I2V_ASSETS = { unet: 'h3FlUnet', clip: 'h3Clip', vae: 'h3VideoVae', audio_vae: 'h3AudioVae', fast_lora: 'h3FlFastLora', lora_8step: 'h3FlBalancedLora', pdd: 'h3PddFl2v', lora_pika: 'h3PikaFlLora', vae_decode: 'h3SolVae' }\n\nconst LEGACY_MODEL_ASSET_MAP = {\n  'flux-text2image': { unet: 'fluxUnet', clip: 'fluxClip', vae: 'fluxVae' },\n  ...Object.fromEntries(H3_REF2V_IDS.map((id) => [id, H3_REF2V_ASSETS])),\n  ...Object.fromEntries(H3_I2V_IDS.map((id) => [id, H3_I2V_ASSETS])),\n  // 拆分前的旧 id：用户配置里可能仍写着它们，保留映射以便平滑迁移\n  'minimax-h3-ref2v': H3_REF2V_ASSETS,\n  'minimax-h3-ref2v-8step': H3_REF2V_ASSETS,\n  'minimax-h3-i2v': H3_I2V_ASSETS,\n}\n\n/**\n * 旧清单 id 的 assetOverrides 继承：拆分后新 id 会同时读旧 id 的覆盖，\n * 使用户既有的 assetOverrides（如 int8 VAE 选择）不因拆分而失效。\n */\nconst ASSET_OVERRIDE_ALIASES = Object.fromEntries([\n  // PDD 有独立的 base id（用户可能覆盖过它）；链式续接 / 两阶段放大沿用同档标准实现的覆盖\n  // （它们与标准实现共用同一批权重，只是图结构不同），显式覆盖仍以 assetOverrides[自身 id] 最优先。\n  ...H3_REF2V_IDS.map((id) => [id, id.includes('-pdd') ? ['minimax-h3-ref2v'] : (id.includes('balanced') ? ['minimax-h3-ref2v-8step', 'minimax-h3-ref2v'] : ['minimax-h3-ref2v'])]),\n  ...H3_I2V_IDS.map((id) => [id, id.includes('-pdd') ? ['minimax-h3-i2v-balanced-pdd', 'minimax-h3-i2v'] : (id.includes('balanced') ? ['minimax-h3-i2v-8step', 'minimax-h3-i2v'] : ['minimax-h3-i2v'])]),\n])\n\n/** 某工作流的资产覆盖：显式 assetOverrides[id] > 旧 id 覆盖 > 旧 models.* 兜底。 */\nfunction getAssetOverrides(workflowId) {\n  const c = loadConfigFile()\n  const explicit = (c.assetOverrides && c.assetOverrides[workflowId]) || {}\n  const alias = {}\n  for (const oldId of ASSET_OVERRIDE_ALIASES[workflowId] || []) {\n    Object.assign(alias, (c.assetOverrides && c.assetOverrides[oldId]) || {})\n  }\n  const legacy = {}\n  const map = LEGACY_MODEL_ASSET_MAP[workflowId] || {}\n  const models = c.models || {}\n  for (const [assetKey, modelKey] of Object.entries(map)) {\n    if (models[modelKey] !== undefined && models[modelKey] !== '') legacy[assetKey] = models[modelKey]\n  }\n  return { ...legacy, ...alias, ...explicit }\n}\n\n/**\n * 视频「形状」真值表：工具面对调用者显式声明走哪条条件路径（= capability），\n * 与「续接」正交——形状决定条件节点与必须/禁止的绑定参数，continuity_from 决定是否继承上一镜。\n *\n * 为什么要有这张表：形状此前是被**副作用**推断的（传了 first_frame 就当 i2v），\n * 于是\"两个都传\"会把参数静默丢掉（i2v 清单没有 refs 槽位 → 上传了但不接线）。\n * 现在：形状必须显式传，冲突直接报错并给出修法。\n * **跨形状续接是允许的**（上一镜 r2v → 本镜 i2v + continuity_from），所以这里不校验上一镜的形状。\n */\nconst VIDEO_SHAPES = {\n  r2v: {\n    capability: 'video.reference2video',\n    label: '参考绑定',\n    expect: ['ref_nodes'],\n    forbid: ['first_frame_node', 'last_frame_node'],\n    forbidHint: 'r2v 没有首帧/末帧槽位（以前会被静默忽略）。同场景续接请用 continuity_from=上一镜节点 id；要首帧锚定请改 type=i2v',\n  },\n  i2v: {\n    capability: 'video.image2video',\n    label: '首帧/末帧串联',\n    require: ['first_frame_node'],\n    forbid: ['ref_nodes'],\n    forbidHint: 'i2v 不接受 ref_nodes：身份与环境由首帧继承。请删掉 ref_nodes，或改 type=r2v（参考绑定）',\n    // 链式续接已支持：i2v 版 ctx 模板（scripts/make-h3-ctx-templates.mjs 派生 → minimax-h3-i2v-ctx-*）\n    // 把 Motion Context 挂在 MiniMaxH3ImageToVideo 之后 ⇒ 首帧锚定与\"继承上一镜尾部\"可同时用。\n    // 注意 i2v 的**普通实现不声明 chain**（无 clipIndex）：要用续接必须选到链式实现，否则报「上一镜没有链式序号」。\n    chain: true,\n  },\n}\nconst SHAPE_OF_CAPABILITY = Object.fromEntries(Object.entries(VIDEO_SHAPES).map(([k, v]) => [v.capability, k]))\n\n/**\n * 校验 shape × 参数。errors 抛错（带修法），warnings 随结果返回。\n * 只对视频能力生效；image.* / audio.* / image.from_video 直接放行。\n */\nfunction validateVideoArgs(capability, args = {}) {\n  const shapeId = SHAPE_OF_CAPABILITY[capability]\n  const warnings = []\n  if (!shapeId) return { shape: null, warnings }\n  const shape = VIDEO_SHAPES[shapeId]\n  if (args.type !== undefined && args.type !== null && args.type !== '' && args.type !== shapeId) {\n    throw new Error(`参数冲突：type=${args.type} 与 capability=${capability} 不一致（type=${args.type} 对应 ${VIDEO_SHAPES[args.type] ? VIDEO_SHAPES[args.type].capability : '未知'}）`)\n  }\n  const given = (v) => (Array.isArray(v) ? v.length > 0 : v !== undefined && v !== null && v !== '')\n  for (const k of shape.forbid || []) {\n    if (given(args[k])) throw new Error(`type=${shapeId}（${shape.label}）不接受 ${k}。${shape.forbidHint}`)\n  }\n  for (const k of shape.require || []) {\n    if (!given(args[k])) throw new Error(`type=${shapeId}（${shape.label}）必须传 ${k}：首帧决定身份与构图（末帧 last_frame_node 可选）`)\n  }\n  if (shapeId === 'r2v' && !given(args.ref_nodes)) {\n    warnings.push('r2v 未传 ref_nodes：本次按「只有文本提示词」生成，角色/场景一致性无从保证（要绑定身份请传角色卡/场景卡）')\n  }\n  if (given(args.continuity_from) && shape.chain === false) {\n    throw new Error(`type=${shapeId} 的形状不支持链式续接（continuity_from）。请改用支持续接的形状，或不传 continuity_from`)\n  }\n  // 参考音频（H3 Ref2VA 的 <Audio N>）：只有 r2v 有条件槽；官方要求音频必须伴随图像/视频，\n  // 不能单独作为唯一输入。放在上传之前校验，非法请求不产生副作用。\n  if (given(args.audio_ref_nodes)) {\n    const audioList = Array.isArray(args.audio_ref_nodes) ? args.audio_ref_nodes : [args.audio_ref_nodes]\n    if (shapeId !== 'r2v') {\n      throw new Error('audio-ref-shape: 参考音频只有 r2v（参考绑定）支持；i2v 的 ImageToVideo 节点没有音频输入槽。请改 type=r2v，或改成后期配音')\n    }\n    if (audioList.length > AUDIO_REF_MAX_COUNT) {\n      throw new Error(`audio-ref-limit: 参考音频最多 ${AUDIO_REF_MAX_COUNT} 段（当前 ${audioList.length} 段）`)\n    }\n    if (!given(args.ref_nodes)) {\n      throw new Error('audio-ref-companion: 参考音频不能单独作为唯一输入——H3 官方要求它必须伴随图像或视频。请同时传 ref_nodes（角色卡/场景卡）')\n    }\n  }\n  return { shape: shapeId, warnings }\n}\n\n/** 显式 workflow > preferred 顺序 > 该 capability 任意清单（internal 诊断清单不参与隐式选中）。 */\nfunction resolveManifest(registry, capability, workflowId) {\n  const candidates = (registry.byCapability[capability] || []).filter((m) => !m.internal)\n  if (workflowId) {\n    const m = registry.byId[workflowId]\n    if (!m) throw new Error(`workflow \"${workflowId}\" 不存在`)\n    if (m.capability !== capability) throw new Error(`workflow \"${workflowId}\" 能力是 ${m.capability}，非 ${capability}`)\n    return m\n  }\n  if (!candidates.length) throw new Error(`no workflow for capability ${capability}`)\n  for (const id of getPreferred(capability)) {\n    const m = registry.byId[id]\n    if (m && m.capability === capability && !m.internal) return m\n  }\n  return candidates[0]\n}\n\n/**\n * 解析 mode：显式合法 mode > 单档清单的唯一 mode > 清单首个 mode。\n * strict=true 时，显式请求的 mode 不存在于清单 → **报错**（禁止静默跨档替换）。\n * 例外：已声明 tier 且只有一个 mode 的清单（P2 之后的分档实现），其唯一 mode 就是该档的参数组，\n * 名称不同也照用——这不算跨档替换。\n */\nfunction resolveMode(manifest, mode, { strict = false } = {}) {\n  const names = Object.keys(manifest.modes || {})\n  if (!names.length) return null\n  if (mode && manifest.modes[mode]) return mode\n  if (mode && strict) {\n    if (manifest.tier && names.length === 1) return names[0]\n    throw new Error(\n      `工作流 \"${manifest.id}\" 不提供 \"${mode}\" 档（可用：${names.join(' / ')}）：` +\n      '本插件不会静默跨档替换，请改档位或改用提供该档的实现')\n  }\n  return names[0]\n}\n\n/** 首遍尺寸：图锁定 > 显式宽高 > aspect-ratio 推导（按 mode.longSide）> resolution.default。 */\nfunction computeManifestSize(manifest, mode, explicitW, explicitH, aspectRatio) {\n  // 只有**图锁定**形态（resolutionLock.graph）优先于一切：首遍尺寸是图结构的一部分\n  // （放大倍率写在图内节点上），显式 width/height 与画布比例都不得覆盖它，否则「放大」会从错的\n  // 底片开始。**只锁倍率**形态（只有 scale）不锁首遍，照常往下走。\n  // 无论哪种形态，交付尺寸都用 manifestDeliverySize() 推。\n  const lock = manifest.resolutionLock\n  if (lock && Array.isArray(lock.graph) && lock.graph.length >= 2) {\n    return { w: snap32(lock.graph[0]), h: snap32(lock.graph[1]) }\n  }\n  const hasW = Number.isFinite(explicitW) && explicitW > 0\n  const hasH = Number.isFinite(explicitH) && explicitH > 0\n  if (hasW && hasH) return { w: snap32(explicitW), h: snap32(explicitH) }\n  const res = manifest.resolution || {}\n  const ratioOf = (s) => {\n    const m = /^\\s*(\\d+)\\s*[:/x]\\s*(\\d+)\\s*$/.exec(String(s || '').trim())\n    if (!m) return null\n    const rw = Number(m[1]); const rh = Number(m[2])\n    return rw > 0 && rh > 0 ? rw / rh : null\n  }\n  const defaultPair = Array.isArray(res.default)\n    ? res.default\n    : (res.default && typeof res.default === 'object' && Array.isArray(res.default[mode]) ? res.default[mode] : null)\n  // 只给一边：另一边按「画布比例 → 本档 default 比例 → 16:9」推导。\n  // 旧行为是**静默忽略**（只有 hasW && hasH 才生效），调用方以为生效了——这里改成推导。\n  if (hasW || hasH) {\n    const ratio = ratioOf(aspectRatio) || (defaultPair ? defaultPair[0] / defaultPair[1] : 16 / 9)\n    if (hasW) return { w: snap32(explicitW), h: snap32(explicitW / ratio) }\n    return { w: snap32(explicitH * ratio), h: snap32(explicitH) }\n  }\n  if (res.policy === 'aspect-ratio') {\n    const long = (mode && manifest.modes?.[mode]?.longSide) || res.longSide || 1344\n    const ratio = ratioOf(aspectRatio)\n    if (ratio) {\n      return ratio >= 1 ? { w: long, h: snap32(long / ratio) } : { w: snap32(long * ratio), h: long }\n    }\n  }\n  const d = res.default\n  if (Array.isArray(d) && d.length >= 2) return { w: snap32(d[0]), h: snap32(d[1]) }\n  if (d && typeof d === 'object' && Array.isArray(d[mode]) && d[mode].length >= 2) return { w: snap32(d[mode][0]), h: snap32(d[mode][1]) }\n  return { w: 1344, h: 768 }\n}\n\n/** 交付分辨率 = 图分辨率 × resolutionLock.scale（缺省 1）。无锁时等于图分辨率。 */\nfunction manifestDeliverySize(manifest, graphSize) {\n  const scale = Number(manifest?.resolutionLock?.scale)\n  if (!Number.isFinite(scale) || scale <= 0 || scale === 1) return { w: graphSize.w, h: graphSize.h }\n  return { w: snap32(graphSize.w * scale), h: snap32(graphSize.h * scale) }\n}\n\n/**\n * 分辨率解析警告：让调用方知道「请求的尺寸」与「实际交付」的关系（不静默）。\n * 两种形态要分开措辞——被改写的东西不同：\n *   ① 图锁定   ：首遍尺寸被实现改写（显式宽高/画布比例都不生效）。\n *   ② 只锁倍率 ：首遍尺寸**照请求生效**，只是交付 = 首遍 × scale（二阶段，不是改写）。\n */\nfunction resolutionLockWarning(manifest, graphSize) {\n  const lock = manifest?.resolutionLock\n  if (!lock) return null\n  const del = manifestDeliverySize(manifest, graphSize)\n  const why = lock.note ? `（${lock.note}）` : ''\n  const scaleNote = Number(lock.scale) > 1 ? `（×${lock.scale} 潜空间放大）` : ''\n  if (Array.isArray(lock.graph)) {\n    return `实现 ${manifest.id} 锁定图分辨率 ${graphSize.w}x${graphSize.h}${why}：` +\n      `显式 width/height 与画布比例均不生效，实际交付 ${del.w}x${del.h}` + scaleNote\n  }\n  if (!(Number(lock.scale) > 1)) return null\n  return `实现 ${manifest.id} 为两阶段放大${why}：首遍 ${graphSize.w}x${graphSize.h}（按请求尺寸生效）` +\n    ` → 实际交付 ${del.w}x${del.h}` + scaleNote\n}\n\n/**\n * 链式续接的兼容性判据 = **首遍尺寸一致**（不是交付尺寸一致）。\n *\n * 为什么：链上流动的是**首遍 latent**——ctx 图的 `MiniMaxH3MotionContextSaveLatent`（node 22）\n * 存的是 node 10（采样器输出），而两阶段/学习式放大发生在它**之后**。\n * 所以带 resolutionLock 的实现（hires / 学习式 2K 族）同样可以续接，\n * 只要能保证「一条链内首遍尺寸一致」；交付尺寸可以不同。\n *\n * 节点上记的两个尺寸：`width/height` = 交付尺寸，`graphWidth/graphHeight` = 首遍尺寸\n * （后者只有两阶段实现才记；普通实现两者相同）。\n *\n * @returns 不兼容时返回可直接抛出的错误信息；兼容返回 null。\n */\nexport function chainGraphMismatch(prevParams, graphSize) {\n  const w = Number(prevParams?.graphWidth ?? prevParams?.width)\n  const h = Number(prevParams?.graphHeight ?? prevParams?.height)\n  if (!w || !h) return null                    // 旧节点没记尺寸：不判死，交给后续步骤\n  if (w === graphSize.w && h === graphSize.h) return null\n  return `链式续接要求**首遍尺寸**一致：上一镜首遍 ${w}×${h}，本镜 ${graphSize.w}×${graphSize.h}。` +\n    '链上传递的是首遍 latent（放大发生在其之后），latent 无法缩放——' +\n    '请让两镜用首遍尺寸相同的实现（交付尺寸可以不同），或从这里另起一链（不传 continuity_from）'\n}\n\n// ---------------------------------------------------------------------------\n// 档位解析层（契约见 docs/tier-strategy-design.md）\n//   产品层：capability + tier(fast|balanced|quality) → 一个实现清单\n//   注册层：同 group 聚合、无加速/有加速策略投影、可用性预检\n//   铁律：不静默跨档替换；选定的实现不可用就显式报错（可由用户改选，不自动换）\n// ---------------------------------------------------------------------------\n\n/** 同档候选排序：priority 降序 → 无加速优先 → id 升序（确定性；内置默认＝无加速）。 */\nfunction sortTierCandidates(list) {\n  return list.slice().sort((a, b) =>\n    (Number(b.priority) || 0) - (Number(a.priority) || 0)\n    || (a.accel ? 1 : 0) - (b.accel ? 1 : 0)\n    || String(a.id).localeCompare(String(b.id)))\n}\n\n/** 组名：显式 group 优先，缺省以自身 id 成组（不从文件名猜）。 */\nconst groupNameOf = (m) => (typeof m.group === 'string' && m.group ? m.group : m.id)\n\n/** 某能力某档的实现（排除 internal 诊断清单），已按确定性顺序排好。 */\nfunction tierImplementations(capability, tier, registry = getRegistry()) {\n  return sortTierCandidates((registry.byCapability[capability] || []).filter((m) => m.tier === tier && !m.internal))\n}\n\n/** 该能力是否已分档（至少有一档实现）。未分档 → 走旧清单兼容路径。 */\nfunction isTieredCapability(capability, registry = getRegistry()) {\n  return TIERS.some((t) => tierImplementations(capability, t, registry).length > 0)\n}\n\n/** 配置里的档位选择：capability → tier → 实现 id。 */\nfunction getTierSelection(capability, cfg = null) {\n  const c = cfg || loadConfigFile()\n  const t = c.tiers && c.tiers[capability]\n  return t && typeof t === 'object' && !Array.isArray(t) ? t : {}\n}\n\n/** 未分档能力的旧清单候选顺序：preferred 命中者优先，其余按注册表顺序。 */\nfunction orderLegacyCandidates(registry, capability) {\n  const list = (registry.byCapability[capability] || []).filter((m) => !m.internal)\n  const pref = getPreferred(capability)\n  const rank = (m) => { const i = pref.indexOf(m.id); return i < 0 ? pref.length + 1 : i }\n  return list.slice().sort((a, b) => rank(a) - rank(b))\n}\n\n// --- 可用性预检（读 ComfyUI /object_info，带 TTL 缓存；离线＝未知，不判死）---------\n\nconst NODE_PROBE_TTL_MS = 5 * 60 * 1000\nconst _nodeProbe = new Map() // class_type → { ok: true|false|null, at }\n\n/**\n * 探测 ComfyUI 是否注册某节点类。\n * true=已注册 / false=未注册 / null=未知（ComfyUI 不可达或探测失败）。\n * 离线时不判死：否则一断网整个设置页会被判为不可用。\n */\nasync function probeNodeClass(classType, { ttlMs = NODE_PROBE_TTL_MS, force = false } = {}) {\n  const hit = _nodeProbe.get(classType)\n  const now = Date.now()\n  if (!force && hit && now - hit.at < ttlMs) return hit.ok\n  let ok = null\n  try {\n    const res = await comfyFetch('/object_info/' + encodeURIComponent(classType))\n    if (res.ok) {\n      const json = await res.json()\n      // ComfyUI 对未知节点返回 {}（空对象），已注册则返回该类名的条目\n      ok = Boolean(json && typeof json === 'object' && Object.keys(json).length > 0)\n    }\n  } catch { ok = null }\n  _nodeProbe.set(classType, { ok, at: now })\n  return ok\n}\n\n// --- 存盘的 draft latent 列表（Open-H3 latent 交接用）-------------------------\nconst _latentFilesProbe = { at: 0, files: null }\n/**\n * 读 ComfyUI 的 `OpenH3LoadRefinedLatent` 下拉，拿到 output/open_h3_latents/ 里现存的文件名——\n * `handoff='auto'` 靠它确认「文件真的还在」，而不是盲信节点 params。ttl 很短：每次渲染都会新增文件。\n * 返回 null = 查不到（节点包没装 / 离线）⇒ 调用方跳过存在性检查，不据此判死。\n */\nasync function probeLatentFiles({ ttlMs = 15000, force = false } = {}) {\n  const now = Date.now()\n  if (!force && _latentFilesProbe.files && now - _latentFilesProbe.at < ttlMs) return _latentFilesProbe.files\n  try {\n    const res = await comfyFetch('/object_info/OpenH3LoadRefinedLatent')\n    if (res.ok) {\n      const json = await res.json()\n      const list = json?.OpenH3LoadRefinedLatent?.input?.required?.latent_file?.[0]\n      if (Array.isArray(list)) {\n        _latentFilesProbe.at = now\n        _latentFilesProbe.files = list.filter((x) => typeof x === 'string' && x.endsWith('.safetensors'))\n        return _latentFilesProbe.files\n      }\n    }\n  } catch {}\n  return null\n}\n\n/** 该实现的可用性：{ ok, unknown, missing }；无 requiresNodes 视为可用（不探测）。 */\nasync function checkAvailability(m, opts = {}) {\n  const req = Array.isArray(m.requiresNodes) ? m.requiresNodes : []\n  if (!req.length) return { ok: true, unknown: false, missing: [] }\n  const probe = typeof opts.probe === 'function' ? opts.probe : probeNodeClass\n  const missing = []\n  let unknown = false\n  for (const cls of req) {\n    const r = await probe(cls, opts)\n    if (r === false) missing.push(cls)\n    else if (r === null) unknown = true\n  }\n  return { ok: missing.length === 0, unknown, missing }\n}\n\n/** 不可用 → 显式报错（含补救指引；**绝不静默替换**用户选定的实现）。 */\nasync function assertImplementationUsable(m, tier, opts = {}) {\n  const a = await checkAvailability(m, opts)\n  if (a.ok) return a\n  const registry = opts.registry || getRegistry()\n  const std = sortTierCandidates(tierImplementations(m.capability, m.tier || tier, registry).filter((x) => !x.accel && x.id !== m.id))\n  throw new Error(\n    `档位 ${m.tier || tier} 的实现 \"${m.id}\" 不可用：ComfyUI 未注册节点 ${a.missing.join('、')}。` +\n    (std.length ? `可在设置页改选标准实现「${std[0].id}」，或安装对应节点后重试。` : '请安装对应节点后重试。') +\n    '（本插件不会静默替换你选定的实现）')\n}\n\n// --- 解析 -------------------------------------------------------------------\n\n/** 从调用参数取档位：显式 tier，或 mode 恰为档位名（mode 是档位的兼容别名）。 */\nfunction tierFromArgs(opts) {\n  const t = typeof opts.tier === 'string' ? opts.tier.trim() : ''\n  if (TIERS.includes(t)) return t\n  // 弃用别名：mode 曾是「图片 mode 轴 / 视频 mode」的入参，现在等同于 tier（兼容一版后删除）\n  const m = typeof opts.mode === 'string' ? opts.mode.trim() : ''\n  return TIERS.includes(m) ? m : null\n}\n\n/**\n * **内部通道**的「显式实现」：只有脚本 / 内部调用能传（`_internals.runRender(..., implementation: 'id')`）。\n *\n * 工具面**已删除** `workflow=`（实现由配置决定：设置页档位选择 / `cfg.preferred` / `cfg.pins`）。\n * 这里刻意：\n *   - 显式拒绝 `workflow=`——旧调用点必须报错，而不是静默生效（否则「实现由配置决定」立刻破功）；\n *   - 用新名字 `implementation`，与旧参数区分开。\n */\nfunction explicitImplementationOf(opts) {\n  if (opts.workflow !== undefined && opts.workflow !== null && opts.workflow !== '') {\n    throw new Error(\n      '不再接受 workflow=（实现由配置决定：设置页的档位选择 / cfg.preferred 家族 / cfg.pins 钉实现）。' +\n      '调用方请只表达能力 + tier；脚本要钉实现请走 _internals 的 implementation= 通道')\n  }\n  const v = opts.implementation\n  return typeof v === 'string' && v.trim() ? v.trim() : null\n}\n\n/** 非档位含义的 mode 名（旧清单自定义档，如 high/low），仅旧路径使用。 */\nfunction legacyModeFromArgs(opts) {\n  const m = typeof opts.mode === 'string' ? opts.mode.trim() : ''\n  return m && !TIERS.includes(m) ? m : null\n}\n\n/**\n * capability + tier → 清单。\n * 返回 { manifest, tier, resolution, warnings }，resolution ∈ explicit | tier-config | tier-default | legacy-mode | legacy。\n * 规则（docs/tier-strategy-design.md §5）：\n *   1. 显式 workflow 优先；其 tier 与请求档位不符 → 报错（不静默）\n *   2. 配置 tiers[capability][tier] 选定的实现\n *   3. 否则该档候选首个\n *   4. 该档无实现 → 报错并列出可用档位\n *   5. 该能力完全未分档（旧清单）→ 用旧清单的 mode 名匹配请求档位；匹配不到 → 报错（不猜）\n */\nasync function resolveTieredManifest(capability, tier, explicitWorkflow, opts = {}) {\n  const registry = opts.registry || getRegistry()\n  const warnings = []\n\n  if (explicitWorkflow) {\n    const m = registry.byId[explicitWorkflow]\n    if (!m) throw new Error(`workflow \"${explicitWorkflow}\" 不存在`)\n    if (m.capability !== capability) throw new Error(`workflow \"${explicitWorkflow}\" 能力是 ${m.capability}，非 ${capability}`)\n    if (tier && m.tier && m.tier !== tier) {\n      throw new Error(\n        `workflow \"${m.id}\" 是 ${m.tier} 档，与请求的 ${tier} 档不匹配（不静默跨档替换）：` +\n        `请改请求档位，或改用提供 ${tier} 档的实现`)\n    }\n    if (opts.chainOnly && !m.chain) {\n      const sizeHint = m.resolutionLock\n        ? (Array.isArray(m.resolutionLock.graph)\n          ? `。该实现锁定了图分辨率（${m.resolutionLock.graph.join('×')}）`\n          : `。该实现是两阶段放大（交付 = 首遍 ×${m.resolutionLock.scale}）`)\n        : ''\n      throw new Error(\n        `workflow \"${m.id}\" 不是链式续接实现：continuity_from 需要声明了 chain 的实现` +\n        `（契约见 docs/shot-chain-continuity.md）` +\n        sizeHint +\n        (sizeHint ? `：要与它续接，上一镜必须也是**首遍尺寸相同**的实现（放大在链式存档之后，交付尺寸不参与续接）` : ''))\n    }\n    await assertImplementationUsable(m, tier, { ...opts, registry })\n    return { manifest: m, tier: m.tier || tier || null, resolution: 'explicit', warnings }\n  }\n\n  // 未分档能力：只可能是**尚未迁移的旧清单**（如 image.from_video，或用户自建、还没声明 tier 的清单）。\n  // 【重构：删除】旧的「按 mode 名匹配请求档位」路径——`mode=quality` 会凭名字隐式挑一个实现，\n  // 正是「同一请求被悄悄换实现」的根源（实测踩过：漏传 workflow 时落到了别的模型）。\n  // 现在只按 preferred / 候选序取一个，并**明确告知未分档、忽略请求档位**。\n  if (!isTieredCapability(capability, registry)) {\n    const pick = resolveManifest(registry, capability, null)\n    if (tier) {\n      warnings.push(\n        `能力 ${capability} 尚未分档（清单 \"${pick.id}\" 未声明 tier）：按该实现执行，**忽略请求的 ${tier} 档**。` +\n        '要让该能力支持档位，请给它提供带 tier 声明的档位清单（见 docs/unified-tier-tool-design.md）')\n    }\n    if (pick.modes && Object.keys(pick.modes).length) {\n      warnings.push(`清单 \"${pick.id}\" 仍声明已废弃的 modes 字段（${Object.keys(pick.modes).join(' / ')}）：请迁移为「一档一清单 + tier 声明」`)\n    }\n    return { manifest: pick, tier: null, resolution: 'legacy', warnings }\n  }\n\n  let want = tier || DEFAULT_TIER\n  if (!tier) warnings.push(`未指定档位，按默认 ${DEFAULT_TIER} 档解析`)\n\n  const cfgForStrategy = opts.cfg || loadConfigFile()\n\n  // ① 配置面**钉实现**（cfg.pins[capability]）：钉死了就不再走策略/档位默认/家族序，\n  //    但**档位冲突仍然报错**（钉的是 fast 档却请求 quality ⇒ 不静默换档）。\n  //    这是「去掉工具面 workflow= 之后」留给排障与基准脚本的通道（设置页可写）。\n  const pinned = resolvePinnedImplementation(capability, want, cfgForStrategy, registry)\n  if (pinned) {\n    warnings.push(`能力 ${capability} 被配置 pin 到 \"${pinned.id}\"（家族 ${groupNameOf(pinned)}）：跳过档位默认与家族序`)\n    await assertImplementationUsable(pinned, want, { ...opts, registry })\n    return { manifest: pinned, tier: want, resolution: 'pin', warnings }\n  }\n\n  // 选中了用户自建策略时：该策略**没有**的档位就是\"不存在\"，显式报错而不是回退到别的实现。\n  // （逐档手写快照不受此限：手写条目本身就是显式选择，照常生效。）\n  const selMap = (opts.selection !== undefined ? (opts.selection || {}) : getTierSelection(capability, cfgForStrategy)) || {}\n  const strat = opts.strategy !== undefined ? opts.strategy : selectedUserStrategyOf(cfgForStrategy, capability)\n  // 「没指定档位」＝交给策略决定，不是\"点名要 quality\"：策略不含默认档时用**策略自己的**档位\n  // （取该策略里最靠前的一档），并发 warning。只有**显式**点名策略不提供的档位才报错。\n  if (strat && !tier && !strat.tiers[want] && !selMap[want]) {\n    const mine = TIERS.filter((t) => strat.tiers[t])\n    const fallback = mine[0] || Object.keys(strat.tiers)[0]\n    if (fallback) {\n      warnings.push(`未指定档位；当前策略「${strat.label}」只提供 ${mine.join(' / ')}，按 ${fallback} 档解析（策略没有的档位不会回退到别的实现；要 ${DEFAULT_TIER} 档请改请求或给策略加上该档）`)\n      want = fallback\n    }\n  }\n  if (strat && !strat.tiers[want] && !selMap[want]) {\n    const mine = Object.keys(strat.tiers)\n    throw new Error(\n      `当前策略「${strat.label}」只提供 ${mine.join(' / ') || '（无档位）'} 档，没有 ${want} 档（策略定义了它提供哪些档位，不是回退到默认实现）：` +\n      `请改请求档位（${mine.join(' / ')}），或在设置页把该策略加上 ${want} 档 / 改选内置默认策略 / 单档显式指定 workflow=`)\n  }\n\n  // 配置选定（opts.selection 可注入：让测试/预览不依赖本机配置里已保存的选择）\n  const selected = selMap[want]\n  if (selected) {\n    const m = registry.byId[selected]\n    if (!m) throw new Error(`档位 ${want} 选定的实现 \"${selected}\" 不存在（可能已被删除）：请在设置页重选`)\n    if (m.capability !== capability) throw new Error(`档位 ${want} 选定的实现 \"${selected}\" 能力是 ${m.capability}，非 ${capability}：请在设置页重选`)\n    if (m.internal) throw new Error(`档位 ${want} 选定的实现 \"${selected}\" 是内部诊断清单，不能作为档位实现：请在设置页重选`)\n    if (m.tier && m.tier !== want) throw new Error(`档位 ${want} 选定的实现 \"${selected}\" 实际是 ${m.tier} 档：请在设置页修正`)\n    if (opts.chainOnly && !m.chain) {\n      throw new Error(\n        `档位 ${want} 配置选定的实现 \"${selected}\" 不是链式续接实现：续接镜请显式指定 workflow=` +\n        `（该档声明了 chain 的实现），或在设置页把该档改成链式实现`)\n    }\n    await assertImplementationUsable(m, want, { ...opts, registry })\n    return { manifest: m, tier: want, resolution: 'tier-config', warnings }\n  }\n\n  // ④ 配置 preferred[capability] = **家族优先序**（家族 = group，或清单自身 id）：\n  //    取第一个在「请求档位」上**有实现**的家族。图片能力从「未分档 + mode 轴」迁移到\n  //    「一档一清单」后，用户原先写的 preferred: [\"qwen-image-21-t2i\"] **无需改动**即继续生效\n  //    （三份档位清单的 group 都是 qwen-image-21-t2i）。\n  const prefFamilies = getPreferred(capability, cfgForStrategy)\n  if (prefFamilies.length) {\n    const poolAll = tierImplementations(capability, want, registry)\n    const pool = opts.chainOnly ? poolAll.filter((m) => m.chain) : poolAll\n    for (const fam of prefFamilies) {\n      const hit = pool.find((m) => groupNameOf(m) === fam || m.id === fam)\n      if (!hit) continue\n      await assertImplementationUsable(hit, want, { ...opts, registry })\n      return { manifest: hit, tier: want, resolution: 'preferred-family', warnings }\n    }\n  }\n\n  // ⑤ 该档候选首个。chainOnly（请求了上一镜续接）时只在**声明了 chain 的实现**里挑：\n  // 不能悄悄退回普通实现——那会静默丢掉连续性，是把「续接」做成了「另起一镜」。\n  const candsAll = tierImplementations(capability, want, registry)\n  const cands = opts.chainOnly ? candsAll.filter((m) => m.chain) : candsAll\n  if (!cands.length) {\n    if (opts.chainOnly && candsAll.length) {\n      throw new Error(\n        `能力 ${capability} 的 ${want} 档没有链式续接实现（该档现有实现均未声明 chain）：` +\n        `请改档位、安装链式续接实现，或改用它档的链式实现（显式 workflow=）`)\n    }\n    const avail = TIERS.filter((t) => tierImplementations(capability, t, registry).length)\n    throw new Error(\n      `能力 ${capability} 没有 ${want} 档实现（可用档位：${avail.join(' / ') || '无'}）：` +\n      '请改档位，或上传/声明该档实现')\n  }\n  const pick = cands[0]\n  await assertImplementationUsable(pick, want, { ...opts, registry })\n  return { manifest: pick, tier: want, resolution: 'tier-default', warnings }\n}\n\n// --- 策略投影与矩阵（配置页 / UI / 技能读同一份数据） ------------------------\n\nconst DEFAULT_STRATEGY_ID = '__default'\n\n/**\n * 每能力的策略清单（配置页单选列表的唯一数据源）：\n *  ① 一条**内置默认**：跟随注册表首选（各档的非加速首选实现），label = 该能力主家族名；\n *  ② 用户自建策略：用户在配置页用现有 workflow 逐档组合、**自己命名**（见 cfg.strategies）。\n *\n * 为什么不再按组投影出「（无加速）/（有加速）」：workflow 是原材料，**策略该由用户命名与组合**\n * （Sol / PDD 只是可选清单，不应自动变成\"官方策略\"）。注册表只把\"默认\"这一条说清楚。\n */\nfunction projectCapabilityStrategies(registry, capability, cfg = {}, effective = null) {\n  // 内置默认策略的**快照与标题都取「实际生效」**（effective 由 effectiveTiersOf 算出，含 preferred 家族序 / pins）：\n  // 否则会出现「标题写 FLUX 2 文生图、实际跑 qwen-image-21-t2i」这种自相矛盾的显示。\n  const tiers = {}\n  for (const tier of TIERS) {\n    const list = tierImplementations(capability, tier, registry)\n    if (!list.length) continue\n    const eff = effective && effective[tier] ? list.find((m) => m.id === effective[tier]) : null\n    const pick = eff || list.find((m) => !m.accel) || list[0]\n    if (pick?.id) tiers[tier] = pick.id\n  }\n  if (!Object.keys(tiers).length) return []\n  const effFamily = (() => {\n    const firstTier = TIERS.find((t) => tiers[t])\n    const m = firstTier ? registry.byId[tiers[firstTier]] : null\n    return m ? familyDisplayName(registry, m.capability, groupNameOf(m)) : null\n  })()\n  const label = effFamily || groupDisplayNameOf(registry, capability) || capability\n  const sel = currentTierSelection(cfg, capability)\n  // \"选中态\"按**实际生效**口径判定：显式选择优先，未显式选择的档位取内置默认（= effective）。\n  const effOf = (tier) => sel[tier] || tiers[tier] || null\n  const matches = (s) =>\n    Object.keys(s.tiers || {}).length > 0 &&\n    Object.entries(s.tiers).every(([t, id]) => effOf(t) === id) &&\n    Object.entries(sel).every(([t, id]) => !s.tiers[t] || s.tiers[t] === id)\n  const builtin = { id: DEFAULT_STRATEGY_ID, label, tiers, builtin: true, available: true, selected: matches({ tiers }) }\n  const user = userStrategiesOf(cfg, capability).map((s) => ({ ...s, available: userStrategyAvailable(registry, capability, s), selected: matches(s) }))\n  const all = [builtin, ...user]\n  // 消歧：若某条用户策略的组合**恰好等于默认**，按匹配规则会两条同时点亮（UI 上出现两个选中单选）。\n  // 此时以用户实际点过的 strategyOf 为准，只点亮那一条；没记过就仍按匹配规则。\n  const picked = (cfg.strategyOf || {})[capability]\n  if (picked && all.some((s) => s.id === picked)) {\n    for (const s of all) s.selected = s.id === picked\n  } else if (all.filter((s) => s.selected).length > 1) {\n    for (const s of all) s.selected = s.builtin\n  }\n  return all\n}\n\n/** 该能力的主家族名（第一个有档位的实现所属组的显示名）；用于内置默认策略的显示名。 */\n/** 某**家族**（group）的展示名（去掉档位括号后缀）；找不到就退回家族 id。 */\nfunction familyDisplayName(registry, capability, family) {\n  const ms = (registry.byCapability || {})[capability] || []\n  const m = ms.find((x) => groupNameOf(x) === family && !x.internal)\n  if (!m) return family\n  return String(m.displayName || family).replace(/（[^）]*）\\s*$/, '').trim() || family\n}\n\nfunction groupDisplayNameOf(registry, capability) {\n  const ms = (registry.byCapability || {})[capability] || []\n  const first = ms.find((m) => m.tier && !m.internal)\n  return first ? (first.displayName || groupNameOf(first)) : ''\n}\n\n/**\n * 用户策略的规范形：`{ id, name, tiers:{tier→实现id} }`。\n * 只保留合法选择（未知 id / 跨能力跨档 id 一律丢弃），避免配置里留下死引用。\n */\nfunction userStrategiesOf(cfg, capability) {\n  const raw = ((cfg.strategies || {})[capability]) || []\n  if (!Array.isArray(raw)) return []\n  const out = []\n  for (const s of raw) {\n    if (!s || typeof s !== 'object') continue\n    const name = typeof s.name === 'string' ? s.name.trim().slice(0, 40) : ''\n    if (!name) continue\n    const tiers = {}\n    for (const [tier, id] of Object.entries(s.tiers || {})) if (typeof id === 'string' && id) tiers[tier] = id\n    out.push({ id: typeof s.id === 'string' && s.id ? s.id : 'strategy-' + (out.length + 1), label: name, tiers, builtin: false })\n  }\n  return out.slice(0, 24)\n}\n\n/**\n * 当前选中的**用户自建策略**（没有则 null）。\n * 用途：策略定义\"它提供哪些档位\"——不在其中的档位对该策略而言**就不存在**（不是回退到默认）。\n */\nfunction selectedUserStrategyOf(cfg, capability) {\n  const id = (cfg.strategyOf || {})[capability]\n  if (!id || id === DEFAULT_STRATEGY_ID) return null\n  return userStrategiesOf(cfg, capability).find((s) => s.id === id) || null\n}\n\n/** 该能力当前生效的档位选择（配置快照；未出现的档位 = 跟随注册表首选）。 */\nfunction currentTierSelection(cfg, capability) {\n  const t = ((cfg.tiers || {})[capability]) || {}\n  return typeof t === 'object' && t ? t : {}\n}\n\n/**\n * 每档**实际生效**的实现 id（与 runner 同一套顺序：pins → cfg.tiers/策略快照 → preferred 家族序 → 候选首个）。\n *\n * 为什么必须在后端算这一份：preferred 现在是**家族序**，UI 若只按「selection || 注册表首个」显示，\n * 就会把「配置指向 qwen 家族」显示成 flux —— 设置页会对用户撒谎（内置默认的标题、档位摘要、\n * 以及「编辑档位」表单的预填都会错）。唯一口径 = 这个函数。\n */\nfunction effectiveTiersOf(cap, cfg, registry) {\n  const eff = {}\n  const sel = getTierSelection(cap, cfg)\n  const pin = typeof cfg?.pins?.[cap] === 'string' ? cfg.pins[cap].trim() : ''\n  const pref = getPreferred(cap, cfg)\n  for (const tier of TIERS) {\n    const cands = tierImplementations(cap, tier, registry)\n    if (!cands.length) continue\n    if (pin) {\n      const hit = cands.find((m) => m.id === pin) || cands.find((m) => groupNameOf(m) === pin)\n      if (hit) { eff[tier] = hit.id; continue }\n    }\n    const chosen = sel[tier] ? cands.find((m) => m.id === sel[tier]) : null\n    if (chosen) { eff[tier] = chosen.id; continue }\n    let famHit = null\n    for (const fam of pref) {\n      const h = cands.find((m) => groupNameOf(m) === fam || m.id === fam)\n      if (h) { famHit = h; break }\n    }\n    eff[tier] = (famHit || cands[0]).id\n  }\n  return eff\n}\n\n/** 用户策略里选中的实现是否都可用（任一不可用 → 该策略如实置灰）。 */\nfunction userStrategyAvailable(registry, capability, strategy) {\n  for (const [tier, id] of Object.entries(strategy.tiers || {})) {\n    const list = tierImplementations(capability, tier, registry)\n    const hit = list.find((m) => m.id === id)\n    if (!hit) return false\n    if (hit.available === false) return false\n  }\n  return true\n}\n\n/**\n * 档位 × 实现 × 可用性矩阵（UI 与技能的唯一数据源）。\n * opts.probe=false 时不做节点预检（可用性返回 null=未知）。\n */\nasync function describeTierMatrix(registry = getRegistry(), opts = {}) {\n  const probe = opts.probe !== false\n  // 配置来源可注入（测试与工具都读同一份口径）；默认读真实配置文件。\n  const cfg = opts.cfg || loadConfigFile()\n  const out = {}\n  for (const [cap, ms] of Object.entries(registry.byCapability)) {\n    const classified = ms.filter((m) => m.tier && !m.internal)\n    const unclassified = ms.filter((m) => !m.tier && !m.internal)\n    if (!classified.length && !unclassified.length) continue\n    const groups = {}\n    for (const m of classified) (groups[groupNameOf(m)] ||= { id: groupNameOf(m), displayName: m.displayName || groupNameOf(m), tiers: {} })\n    for (const m of classified) (groups[groupNameOf(m)].tiers[m.tier] ||= []).push(m)\n    const desc = async (m) => {\n      const a = probe ? await checkAvailability(m, opts) : { ok: null, unknown: true, missing: [] }\n      return {\n        id: m.id,\n        displayName: m.displayName || m.id,\n        tier: m.tier,\n        group: groupNameOf(m),\n        accel: m.accel || '',\n        available: a.ok,\n        missingNodes: a.missing,\n        requiresNodes: m.requiresNodes || [],\n        estSeconds: Number.isFinite(m.estSeconds) ? m.estSeconds : null,\n        note: m.note || '',\n        source: m._source || 'builtin',\n        modes: Object.keys(m.modes || {}),\n        // 该档的生效参数（UI 显示尺寸/步数与后端同源，不硬编码）\n        longSide: (m.modes && m.modes[m.tier] && m.modes[m.tier].longSide) || null,\n        steps: (m.modes && m.modes[m.tier] && m.modes[m.tier].steps) || null,\n      }\n    }\n    const groupList = []\n    for (const g of Object.values(groups)) {\n      const tiers = {}\n      for (const [tier, list] of Object.entries(g.tiers)) {\n        tiers[tier] = await Promise.all(sortTierCandidates(list).map(desc))\n      }\n      const built = { id: g.id, displayName: g.displayName, tiers }\n      groupList.push(built)\n    }\n    out[cap] = {\n      capability: cap,\n      tiered: classified.length > 0,\n      tiers: TIERS.filter((t) => classified.some((m) => m.tier === t)),\n      groups: groupList,\n      // 策略：一条内置默认 + 用户自建（命名）策略。组只负责\"清单怎么分组显示\"，不再自动生成策略。\n      strategies: projectCapabilityStrategies(registry, cap, cfg, effectiveTiersOf(cap, cfg, registry)),\n      // 当前选中策略实际提供的档位：工具条/UI 据此收敛（策略没这个档位＝不提供，而不是回退）\n      availableTiers: (() => {\n        const st = selectedUserStrategyOf(cfg, cap)\n        return st ? TIERS.filter((t) => st.tiers[t]) : null\n      })(),\n      selection: getTierSelection(cap, cfg),\n      // **实际生效**的实现（与 runner 同一套顺序：pins → cfg.tiers/策略快照 → preferred 家族序 → 候选首个）。\n      // 为什么必须在后端算：preferred 现在是**家族序**，UI 若只按「selection || 注册表首个」显示，\n      // 就会把「配置指向 qwen 家族」显示成 flux——设置页会对用户撒谎（且内置默认的编辑表单预填也会错）。\n      effective: effectiveTiersOf(cap, cfg, registry),\n      unclassified: unclassified.map((m) => {\n        const firstMode = Object.values(m.modes || {})[0] || {}\n        // 未分档清单的分辨率声明原样透出（mode.longSide / resolution.longSide / resolution.default），\n        // UI 不再硬编码 1344 之类的尺寸\n        const longSide = firstMode.longSide || (m.resolution && m.resolution.longSide) || null\n        const def = (m.resolution && m.resolution.default) || null\n        return {\n          id: m.id, displayName: m.displayName || m.id, modes: Object.keys(m.modes || {}), source: m._source || 'builtin',\n          longSide,\n          resolution: { policy: (m.resolution && m.resolution.policy) || null, longSide, default: def },\n        }\n      }),\n    }\n  }\n  return out\n}\n\n/** /api/workflows 的响应体（设置页与工具条的唯一数据源；抽成函数便于测试与复用）。 */\nasync function describeWorkflowsApi(registry = getRegistry(), opts = {}) {\n  const matrix = await describeTierMatrix(registry, opts)\n  const capabilities = Object.entries(registry.byCapability).map(([cap, ms]) => ({\n    capability: cap,\n    preferred: getPreferred(cap),\n    tiered: Boolean((matrix[cap] || {}).tiered),\n    tiers: (matrix[cap] || {}).tiers || [],\n    effective: (matrix[cap] || {}).effective || {},\n    selection: (matrix[cap] || {}).selection || {},\n    groups: (matrix[cap] || {}).groups || [],\n    // 策略：一条内置默认 + 用户自建（配置页单选列表的数据源）\n    strategies: (matrix[cap] || {}).strategies || [],\n    // null/undefined = 未选用户策略（档位＝各实现并集）；数组 = 当前策略只提供这些档位\n    availableTiers: (matrix[cap] || {}).availableTiers || null,\n    unclassified: (matrix[cap] || {}).unclassified || [],\n    workflows: ms.map((m) => ({\n      id: m.id,\n      displayName: m.displayName || m.id,\n      modes: Object.keys(m.modes || {}),\n      tier: m.tier || '',\n      group: groupNameOf(m),\n      accel: m.accel || '',\n      internal: Boolean(m.internal),\n      requiresNodes: m.requiresNodes || [],\n      estSeconds: Number.isFinite(m.estSeconds) ? m.estSeconds : null,\n      note: m.note || '',\n      output: m.output || {},\n      constraints: m.constraints || {},\n      assets: m.assets || {},\n      // 实际生效的资产值（清单默认 ← 旧配置 models.* 映射 ← 旧 id 覆盖继承 ← 显式覆盖），\n      // 供设置页显示：避免\"界面显示 fp16、实际跑 int8\"这类失真。\n      effectiveAssets: effectiveAssetsOf(m),\n      source: m._source || 'builtin',\n    })),\n  }))\n  return { ok: true, capabilities, tiers: TIERS, errors: registry.errors }\n}\n\n/** 某清单的资产键 → 实际生效值（覆盖 > 别名/旧配置 > 清单默认）。 */\nfunction effectiveAssetsOf(m) {\n  const ov = getAssetOverrides(m.id)\n  const out = {}\n  for (const [k, a] of Object.entries(m.assets || {})) {\n    out[k] = (ov && ov[k] !== undefined) ? ov[k] : ((a && a.default) || '')\n  }\n  return out\n}\n\n/** 纯逻辑：manifest + opts + aspectRatio → { mode, job, graph }（opts.refs/first_frame/last_frame 为已上传 comfy 文件名）。 */\nfunction buildRenderGraph(manifest, opts, aspectRatio) {\n  const mode = resolveMode(manifest, opts.mode)\n  const isAudio = manifest.output?.mediaType === 'audio'\n  const explicitW = opts.width !== undefined && opts.width !== null && opts.width !== '' ? intArg(opts, 'width', 1344) : undefined\n  const explicitH = opts.height !== undefined && opts.height !== null && opts.height !== '' ? intArg(opts, 'height', 768) : undefined\n  const { w, h } = computeManifestSize(manifest, mode, explicitW, explicitH, aspectRatio)\n  const length = intArg(opts, 'length', 124)\n  const seed = intArg(opts, 'seed', Math.floor(Math.random() * 2 ** 31))\n  const modeCfg = mode && manifest.modes ? (manifest.modes[mode] || {}) : {}\n  const steps = opts.steps !== undefined && opts.steps !== null && opts.steps !== ''\n    ? intArg(opts, 'steps', 20)\n    : (isAudio && manifest.params?.steps?.default !== undefined\n      ? Math.max(1, Math.floor(Number(manifest.params.steps.default) || 30))\n      : (modeCfg.steps ?? 20))\n  const guidance = floatArg(opts, 'guidance', 3.5)\n  const fps = (manifest.params?.fps?.default) || 24\n  const job = {\n    prompt: opts.prompt,\n    width: w,\n    height: h,\n    length,\n    seed,\n    steps,\n    guidance,\n    fps,\n    mode,\n    prefix: opts.prefix || '',\n    assetOverrides: getAssetOverrides(manifest.id),\n  }\n  if (opts.refs !== undefined) job.refs = opts.refs\n  if (opts.first_frame !== undefined && opts.first_frame !== null) job.first_frame = opts.first_frame\n  if (opts.last_frame !== undefined && opts.last_frame !== null) job.last_frame = opts.last_frame\n  // 自动注入 manifest params 中 opts 提供的其余字段（source_video / frame_index / 未来新 param），\n  // 避免新 param 漏注入（曾致 extract-frame 的 LoadVideo.file 为 null → ComfyUI 校验失败）。\n  for (const pname of Object.keys(manifest.params || {})) {\n    if (opts[pname] !== undefined && opts[pname] !== null && job[pname] === undefined) job[pname] = opts[pname]\n  }\n  const graph = buildGraphFromManifest(manifest, job)\n  return { mode, job, graph }\n}\n\n/** 把画布图片节点上传到 ComfyUI，返回文件名（不存在返回 null）。 */\nasync function uploadCanvasNodeImage(root, project, nid) {\n  const n = project.nodes.find((x) => x.id === nid)\n  if (!n?.media) return null\n  const absPath = join(root, ...String(n.media).split('/'))\n  if (!existsSync(absPath)) return null\n  const buf = await readFile(absPath)\n  const up = await comfyUploadImage(buf, basename(n.media))\n  return up.name\n}\n\n/** 解析参考图 → ComfyUI 文件名：资产 id（character:/scene:/style:）或画布节点 id 均可。 */\nasync function resolveRefImage(root, project, lib, ref) {\n  if (!ref) return null\n  if (isAssetRef(ref)) {\n    const abs = resolveAssetImagePath(root, lib, ref)\n    if (!abs) return null\n    const buf = await readFile(abs)\n    const up = await comfyUploadImage(buf, basename(abs))\n    return up.name\n  }\n  return uploadCanvasNodeImage(root, project, ref)\n}\n\n/**\n * 解析参考音频 → ComfyUI input 文件名。\n * 来源：画布 audio 节点 / 画布 video 节点（取其音轨——LoadAudio 能直接读 mp4，实测无需 ffmpeg）/\n * voice:（音频资产）或 clip:（视频资产）。返回 { name, source, file, bytes, durationSec, kind }。\n */\nasync function resolveRefAudio(root, project, lib, ref) {\n  let abs = ''\n  let kind = ''\n  let durationSec = null\n  if (isAssetRef(ref)) {\n    const id = canonicalAssetId(ref)\n    const a = lib.assets[id]\n    if (!a) throw new Error(`audio-ref-invalid: 资产不存在 ${ref}`)\n    kind = assetKind(a)\n    if (kind !== 'audio' && kind !== 'video') {\n      throw new Error(`audio-ref-invalid: 资产 ${ref} 是 ${kind}，参考音频只接受音频/视频资产（图片资产请放 ref_nodes）`)\n    }\n    abs = resolveAssetPath(root, lib, id)\n  } else {\n    // 镜头表里写的是 `canvas:<音频节点 id>`（skill 的规范），工具这里同时接受带前缀与裸 id，\n    // 否则「表里写 canvas:、调用传裸 id」两套写法永远对不上，门也无法逐字比对。\n    const nodeId = String(ref).replace(/^canvas:/, '')\n    const n = project.nodes.find((x) => x.id === nodeId)\n    if (!n) throw new Error(`audio-ref-invalid: 画布节点不存在 ${ref}（可传画布音频/视频节点 id（可带 canvas: 前缀），或 voice:/clip: 资产 id）`)\n    if (n.kind !== 'audio' && n.kind !== 'video') {\n      throw new Error(`audio-ref-invalid: 节点 ${ref} 是 ${n.kind}，参考音频只接受画布音频节点或视频节点（视频取其音轨）`)\n    }\n    if (!n.media) throw new Error(`audio-ref-invalid: 节点 ${ref} 没有媒体文件`)\n    kind = n.kind\n    abs = join(root, ...String(n.media).split('/'))\n    // 节点自带时长优先：上传音频时按 WAV 头记过 durationSec；H3 视频节点有 length/fps。\n    const recorded = Number(n.params?.durationSec)\n    if (Number.isFinite(recorded) && recorded > 0) durationSec = recorded\n    const len = Number(n.params?.length)\n    const fps = Number(n.params?.fps) || 24\n    if (durationSec == null && Number.isFinite(len) && len > 0 && fps > 0) durationSec = len / fps\n  }\n  if (!abs || !existsSync(abs)) throw new Error(`audio-ref-invalid: 文件不存在（${ref}）`)\n  const buf = await readFile(abs)\n  if (buf.length > AUDIO_REF_MAX_BYTES) {\n    throw new Error(`audio-ref-limit: 参考音频 ${basename(abs)} 超过 15MB（实际 ${(buf.length / 1048576).toFixed(1)}MB）`)\n  }\n  if (durationSec == null && kind === 'audio') durationSec = probeWavDurationSec(buf)\n  if (durationSec == null) durationSec = await probeMediaDurationSec(abs)\n  const up = await comfyUploadMedia(buf, basename(abs))\n  return { name: up.name, source: String(ref), file: basename(abs), bytes: buf.length, durationSec, kind }\n}\n\n/** 画布 video 节点 → 上传到 ComfyUI input（LoadVideo 只认 input 目录）→ 返回文件名。 */\nasync function resolveSourceVideo(root, project, ref) {\n  const n = project.nodes.find((x) => x.id === ref)\n  if (!n) throw new Error('extract-invalid: 画布无此节点 ' + ref)\n  if (n.kind !== 'video') throw new Error(`extract-invalid: 节点 ${ref} 不是视频节点（kind=${n.kind}）`)\n  if (!n.media) throw new Error('extract-invalid: 节点无媒体文件 ' + ref)\n  const abs = join(root, ...String(n.media).split('/'))\n  if (!existsSync(abs)) throw new Error('extract-invalid: 媒体文件不存在 ' + n.media)\n  const up = await comfyUploadImage(await readFile(abs), basename(abs))\n  return up.subfolder ? up.subfolder + '/' + up.name : up.name\n}\n\n// ---------------------------------------------------------------------------\n// 分档提示词库（prompt bank）\n// ---------------------------------------------------------------------------\n// 每个镜头一份画布文本节点，用 `## fast` / `## balanced` / `## quality` 分段存\n// 该档的完整提示词。视频生成传 `prompt_node` 时按 `tier` 取对应段：缺该档就\n// 降级到最近的较低档（没有则较高档）并回告 warnings——升档重渲时不会因为\n// 「只写过 fast」而丢掉原提示词。生成后自动把本次实际使用的 prompt 回写本档段，\n// 所以「每次生成视频的提示词都持久化在画布」不依赖调用方记得另存。\n\nconst PROMPT_BANK_MARK = 'dsh-svs-prompt-bank'\nconst PROMPT_BANK_VERSION = 1\nconst PROMPT_TIERS = TIERS\n\n/** 从视频标题推导提示词库标题：`S01 片段` → `S01 提示词（分档）`。 */\nfunction promptBankTitleFor(title) {\n  const base = String(title || '')\n    .replace(/（分档）\\s*$/, '')\n    .replace(/\\s*[·\\-—]\\s*(升档|降档|重渲|重渲染|重出|quality|balanced|fast)\\s*$/i, '')\n    .replace(/\\s*(片段|视频|镜头)\\s*$/g, '')\n    .replace(/[·]/g, ' ')\n    .replace(/\\s+/g, ' ')\n    .replace(/[\\s·\\-—]+$/, '')\n    .trim()\n  return `${base || '单镜'} 提示词（分档）`\n}\n\n/**\n * 解析提示词库节点正文。\n * 返回 { title, note, tiers:{fast?,balanced?,quality?}, raw }：\n * - `tiers` 是 `## <tier>` 分段内容；\n * - `raw` 是「没有分档标题、但整段就是提示词」的旧式文本节点（兼容手写）。\n */\nfunction parsePromptBank(content) {\n  const text = String(content == null ? '' : content)\n  const titleMatch = /^\\s*#\\s+(.+?)\\s*$/m.exec(text)\n  const title = titleMatch ? titleMatch[1].trim() : ''\n  const lines = text.split(/\\r?\\n/)\n  const tiers = {}\n  const noteLines = []\n  let current = null\n  for (const line of lines) {\n    if (/^\\s*#\\s+/.test(line)) continue\n    if (/^\\s*<!--\\s*dsh-svs-prompt-bank\\b/.test(line)) continue\n    const m = /^\\s*##\\s+(fast|balanced|quality)\\s*$/i.exec(line)\n    if (m) {\n      current = m[1].toLowerCase()\n      if (!tiers[current]) tiers[current] = []\n      continue\n    }\n    if (current) tiers[current].push(line)\n    else noteLines.push(line)\n  }\n  const out = {}\n  for (const tier of PROMPT_TIERS) {\n    const body = (tiers[tier] || []).join('\\n').trim()\n    if (body) out[tier] = body\n  }\n  const raw = Object.keys(out).length ? '' : text.trim()\n  return { title, note: noteLines.join('\\n').trim(), tiers: out, raw }\n}\n\n/** 序列化提示词库节点正文（固定分段顺序，空段不写）。 */\nfunction serializePromptBank({ title, note, tiers }) {\n  const lines = [`# ${title || '提示词（分档）'}`]\n  if (note) lines.push('', note)\n  lines.push('', `<!-- ${PROMPT_BANK_MARK} v${PROMPT_BANK_VERSION} -->`)\n  for (const tier of PROMPT_TIERS) {\n    const body = String(tiers?.[tier] == null ? '' : tiers[tier]).trim()\n    if (!body) continue\n    lines.push('', `## ${tier}`, '', body)\n  }\n  return lines.join('\\n').trim() + '\\n'\n}\n\n/** 按档位取提示词：同档 → 最近较低档 → 最近较高档。 */\nfunction resolvePromptForTier(bank, tier) {\n  const want = PROMPT_TIERS.includes(tier) ? tier : 'quality'\n  if (!bank) return { prompt: '', tierUsed: null, fallback: false, availableTiers: [] }\n  if (bank.raw) return { prompt: bank.raw, tierUsed: 'raw', fallback: want !== 'quality', availableTiers: ['raw'] }\n  const availableTiers = PROMPT_TIERS.filter((t) => bank.tiers?.[t])\n  if (bank.tiers?.[want]) return { prompt: bank.tiers[want], tierUsed: want, fallback: false, availableTiers }\n  const wi = PROMPT_TIERS.indexOf(want)\n  const lower = PROMPT_TIERS.slice(0, wi).reverse().find((t) => bank.tiers?.[t])\n  const higher = PROMPT_TIERS.slice(wi + 1).find((t) => bank.tiers?.[t])\n  const used = lower || higher || null\n  return {\n    prompt: used ? bank.tiers[used] : '',\n    tierUsed: used,\n    fallback: Boolean(used),\n    availableTiers,\n  }\n}\n\n/** 找画布上属于某个视频节点的提示词库。 */\nfunction findPromptBankForNode(project, videoNodeId) {\n  if (!videoNodeId) return null\n  return (project.nodes || []).find((n) => n.params?.promptBank && (n.params?.promptFor === videoNodeId || n.params?.promptForNode === videoNodeId)) || null\n}\n\n/** 找提示词库节点本身（画布文本/表格节点）。 */\nfunction findPromptBankNode(project, nodeId) {\n  if (!nodeId) return null\n  return (project.nodes || []).find((n) => n.id === nodeId) || null\n}\n\n/**\n * 写入/更新提示词库节点。返回节点（已挂到 project.nodes）。\n * - 已有节点：保留标题/分组/顺序，只更新正文与提示词元数据；\n * - 新节点：用 opts.title 建文本节点（不导出 PDF，避免被自动送达当成交付物）。\n */\nfunction upsertPromptBankNode(project, opts) {\n  const { nodeId, title, group, tier, prompt, promptFor } = opts\n  let node = nodeId ? findPromptBankNode(project, nodeId) : null\n  if (node && node.kind !== 'text' && node.kind !== 'table') {\n    throw new Error(`prompt_node 必须是画布文本节点（当前是 ${node.kind || '未知'}）：${nodeId}`)\n  }\n  const isNew = !node\n  if (!node) {\n    node = {\n      id: randomUUID(),\n      kind: 'text',\n      title: title || '提示词（分档）',\n      content: '',\n      group: group || DEFAULT_GROUP,\n      params: {},\n      status: 'ready',\n      createdAt: Date.now(),\n      order: nextOrder(project.nodes),\n    }\n    project.nodes.push(node)\n  }\n  const parsed = parsePromptBank(node.content)\n  const nextTiers = { ...parsed.tiers }\n  if (tier) nextTiers[tier] = String(prompt || '').trim()\n  const keepTitle = parsed.title || node.title || title || '提示词（分档）'\n  const nextTitle = title && (isNew || !parsed.title) ? title : keepTitle\n  node.title = nextTitle\n  node.content = serializePromptBank({ title: nextTitle, note: parsed.note, tiers: nextTiers })\n  // 内容变了：之前由 canvas_write_node 导出的 PDF/HTML 已过期，清掉避免自动送达旧文件\n  delete node.file\n  node.group = node.group || group || DEFAULT_GROUP\n  node.status = 'ready'\n  node.params = {\n    ...(node.params || {}),\n    promptBank: true,\n    promptBankVersion: PROMPT_BANK_VERSION,\n    promptFor: promptFor || node.params?.promptFor || null,\n    tiers: PROMPT_TIERS.filter((t) => nextTiers[t]),\n    updatedAt: Date.now(),\n  }\n  return node\n}\n\n/**\n * 角色卡双版本显式选版（仅视频 ref_nodes）：\n * - `ref_variant='single'|'three'`：换成该版本；这由 STEP 0 的用户选择驱动，**不按 tier 自动选**。\n * - 不传 / 非法值：原样使用传入的卡（只做去重）。\n * 支持两种 ref：\n *   - 画布图片节点：读 `params.character` / `cardVariant` / `pairedNodeId`，换成配对节点；\n *   - 资产 id（character:xxx）：读资产库的 `character` / `cardVariant`，在同角色资产里找目标版本。\n * 找不到配对时给 warning 并用原 ref。场景卡 / 道具卡 / 无元数据的老资产原样保留。\n */\nfunction resolveCharacterRefs(project, refNodes, requested, tier, warnings = [], lib = null) {\n  const target = requested === 'single' || requested === 'three' ? requested : null\n  const out = []\n  const seen = new Set()\n  const swaps = []\n  let usedThree = false\n  for (const rid of refNodes || []) {\n    let useId = rid\n    if (isAssetRef(rid)) {\n      const cur = lib?.assets?.[canonicalAssetId(rid)]\n      const character = cur?.character\n      const variant = cur?.cardVariant\n      if (character && (variant === 'single' || variant === 'three')) {\n        if (target && variant !== target) {\n          const cand = Object.values(lib.assets).find((a) => a.type === 'character' && a.character === character && a.cardVariant === target && assetKind(a) === 'image')\n          if (cand) {\n            useId = cand.id\n            swaps.push({ from: rid, to: cand.id, character, target })\n          } else {\n            warnings.push(`角色资产「${rid}」没有可用的 ${target} 版同角色资产，按原资产使用`)\n          }\n        }\n        if ((useId === rid ? variant : target) === 'three') usedThree = true\n      }\n    } else {\n      const node = (project.nodes || []).find((n) => n.id === rid)\n      const p = node?.params || {}\n      if (node && p.character && (p.cardVariant === 'single' || p.cardVariant === 'three')) {\n        if (target && p.cardVariant !== target) {\n          // 优先用显式配对 id；物化复用的卡可能没有 pairedNodeId，就在同会话里按 character + 目标版本找\n          const pair = (p.pairedNodeId ? (project.nodes || []).find((n) => n.id === p.pairedNodeId) : null)\n            || (project.nodes || []).find((n) => n.id !== node.id && n.params?.character === p.character && n.params?.cardVariant === target && n.media)\n          if (pair && pair.params?.cardVariant === target && pair.media) {\n            useId = pair.id\n            swaps.push({ from: node.id, to: pair.id, character: p.character, target })\n          } else {\n            warnings.push(`角色卡「${node.title || node.id}」没有可用的 ${target} 版配对，按原卡使用`)\n          }\n        }\n        if ((useId === rid ? p.cardVariant : target) === 'three') usedThree = true\n      }\n    }\n    if (seen.has(useId)) continue\n    seen.add(useId)\n    out.push(useId)\n  }\n  if (tier === 'fast' && usedThree) {\n    throw new Error('fast 档只支持单视图角色卡：请把 ref_variant 设为 single（或换同角色单视图卡；STEP 0 选 fast 时也只能选单视图）')\n  }\n  return { refs: out, target, swaps }\n}\n\n/** 通用渲染：capability → manifest → 编译图 → ComfyUI → 下载 → 写画布节点。 */\n/** 抽取类能力不需要提示词：不要用生成能力的 prompt 门禁拦截它。 */\nexport function isPromptFreeCapability(capability) {\n  return String(capability) === 'image.from_video' || String(capability) === 'image.crop'\n}\n\n/**\n * 通用渲染入口：能力 + 档位 → 注册表解析实现 → 构图 → 提交 ComfyUI。\n */\nasync function runRender(ctx, opts) {\n  const { workspaceId, exec } = opts\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, workspaceId, exec)\n  const project = await loadProject(root, sessionId)\n  const aspectRatio = project.settings?.aspectRatio\n  const settings = project.settings || {}\n\n  // 配置卡：缺省档位 / 角色卡版本由画布配置注入（显式参数优先；配置门已校验矛盾）。\n  // 只在「已建配置卡」的项目生效——旧项目 / 自由模式保持原有默认，避免行为漂移。\n  const cap = String(opts.capability || '')\n  if (settings.configured === true) {\n    if (opts.tier === undefined && opts.mode === undefined && !opts.implementation) {\n      if (cap === 'image.text2image' || cap === 'image.image2image') opts = { ...opts, tier: settings.imageTier || undefined }\n      else if (cap === 'video.reference2video' || cap === 'video.image2video' || cap === 'video.text2video') opts = { ...opts, tier: settings.mode || undefined }\n    }\n    if (opts.ref_variant === undefined && cap === 'video.reference2video' && settings.characterCardVariant) {\n      opts = { ...opts, ref_variant: settings.characterCardVariant }\n    }\n  }\n\n  const registry = getRegistry()\n  // 档位解析：capability + tier → 实现清单（不静默跨档替换；不可用显式报错）\n  const wantTier = tierFromArgs(opts)\n  const legacyMode = legacyModeFromArgs(opts)\n  const wantContinuity = typeof opts.continuity_from === 'string' && opts.continuity_from.trim() !== ''\n  const resolved = await resolveTieredManifest(opts.capability, wantTier, explicitImplementationOf(opts), { registry, chainOnly: wantContinuity })\n  const manifest = resolved.manifest\n  // 音频能力（如 audio.music）：没有画面尺寸，runner 要跳过分辨率推导与尺寸告警。\n  const isAudioOutput = manifest.output?.mediaType === 'audio'\n  // 形状 × 参数校验：尽早做，所有入口（工具面 / HTTP 路由 / 脚本）受同一张真值表约束；\n  // 放在上传之前，非法请求不产生任何副作用（不上传参考图、不建节点）。\n  const shapeCheck = validateVideoArgs(manifest.capability, { ...opts, capability: manifest.capability })\n  if (shapeCheck.warnings.length) resolved.warnings = [...(resolved.warnings || []), ...shapeCheck.warnings]\n  // 参数支持面检查：调用方传了、但所选实现**没有注入点**的参数 → 明确告警（禁止静默丢弃）。\n  // 典型：给 Qwen 清单传 guidance（cfg 固定 1）、给 i2i 传 width/height（尺寸跟随参考图）。\n  const supportedParams = isAudioOutput\n    ? ['steps', 'seed', 'guidance', 'duration', 'cfg']\n    : ['width', 'height', 'length', 'steps', 'seed', 'guidance']\n  for (const k of ['width', 'height', 'length', 'steps', 'seed', 'guidance', 'duration', 'cfg']) {\n    const v = opts[k]\n    if (v === undefined || v === null || v === '') continue\n    if (supportedParams.includes(k) && manifest.params && manifest.params[k] !== undefined) continue\n    resolved.warnings = [...(resolved.warnings || []), `参数 ${k} 未生效：实现 ${manifest.id} 没有它的注入点（该参数由实现自身固定或由输入决定）`]\n  }\n  if (isAudioOutput) {\n    if (opts.duration !== undefined && opts.duration !== null && opts.duration !== '') {\n      const dur = Number(opts.duration)\n      const c = manifest.constraints?.audio || {}\n      if (!Number.isFinite(dur) || dur <= 0) throw new Error(`duration 非法：${opts.duration}（应为正数秒）`)\n      if (c.minSeconds !== undefined && dur < c.minSeconds) throw new Error(`duration 太小：${dur}s（实现下限 ${c.minSeconds}s）`)\n      if (c.maxSeconds !== undefined && dur > c.maxSeconds) throw new Error(`duration 太大：${dur}s（实现上限 ${c.maxSeconds}s）`)\n    }\n  }\n  const mode = resolveMode(manifest, legacyMode || resolved.tier || (typeof opts.mode === 'string' ? opts.mode : null), {\n    strict: Boolean(legacyMode || wantTier || resolved.tier),\n  })\n  const nodeId = opts.nodeId || randomUUID()\n  const effSize = isAudioOutput ? { w: 0, h: 0 } : computeManifestSize(manifest, mode,\n    opts.width !== undefined && opts.width !== null && opts.width !== '' ? intArg(opts, 'width', 1344) : undefined,\n    opts.height !== undefined && opts.height !== null && opts.height !== '' ? intArg(opts, 'height', 768) : undefined,\n    aspectRatio)\n  // effSize 是**图分辨率**（注入到图里的 width/height）。带 resolutionLock 的实现（两阶段潜空间放大）\n  // 在二遍把 latent 放大 scale 倍，所以**实际交付**尺寸是 manifestDeliverySize()——画布节点要记交付尺寸，\n  // 否则「同分辨率才能拼接」的判断会拿底片尺寸去比成片。\n  const lockSize = isAudioOutput ? { w: 0, h: 0 } : manifestDeliverySize(manifest, effSize)\n  const lockWarn = isAudioOutput ? null : resolutionLockWarning(manifest, effSize)\n  if (lockWarn) resolved.warnings = [...(resolved.warnings || []), lockWarn]\n  const modeCfg = mode && manifest.modes ? (manifest.modes[mode] || {}) : {}\n  const steps = opts.steps !== undefined && opts.steps !== null && opts.steps !== ''\n    ? intArg(opts, 'steps', 20)\n    : (isAudioOutput && manifest.params?.steps?.default !== undefined\n      ? Math.max(1, Math.floor(Number(manifest.params.steps.default) || 30))\n      : (modeCfg.steps ?? 20))\n  const guidance = floatArg(opts, 'guidance', 3.5)\n\n  // ---- 分档提示词：prompt_node（或同一视频节点上次的提示词库）→ 本档 prompt ----\n  const promptFree = isPromptFreeCapability(manifest.capability)\n  const promptTier = resolved.tier || wantTier || (PROMPT_TIERS.includes(mode) ? mode : 'quality')\n  const inlinePrompt = String(opts.prompt == null ? '' : opts.prompt).trim()\n  let promptBankNode = null\n  let promptBankId = typeof opts.prompt_node === 'string' ? opts.prompt_node.trim() : ''\n  if (!promptBankId && !inlinePrompt && opts.nodeId) {\n    // 升档重渲的零参数路径：同一个视频节点重渲时，沿节点上记录的 prompt_node 读提示词库\n    const prev = project.nodes.find((n) => n.id === opts.nodeId)\n    if (prev?.params?.prompt_node) promptBankId = String(prev.params.prompt_node)\n  }\n  if (!promptBankId && !inlinePrompt && opts.title && String(opts.capability).startsWith('video.')) {\n    // 新 nodeId + 同标题升级重渲：按「标题 + 分组」找回该镜提示词库（与自动持久化同一套命名）\n    const hintTitle = promptBankTitleFor(opts.title)\n    const hintGroup = opts.prompt_group || opts.group || DEFAULT_GROUP\n    const hint = project.nodes.find((n) => n.params?.promptBank && n.title === hintTitle && n.group === hintGroup)\n    if (hint) promptBankId = hint.id\n  }\n  if (promptBankId) {\n    promptBankNode = findPromptBankNode(project, promptBankId)\n    if (!promptBankNode) throw new Error(`prompt_node 指向的画布节点不存在: ${promptBankId}`)\n  }\n  let effectivePrompt = inlinePrompt\n  let promptPick = null\n  let promptSource = inlinePrompt ? 'inline' : 'bank'\n  if (!effectivePrompt && !promptFree) {\n    if (!promptBankNode) throw new Error('缺少 prompt：请传 prompt，或传 prompt_node（分档提示词库画布文本节点）')\n    const bank = parsePromptBank(promptBankNode.content)\n    promptPick = resolvePromptForTier(bank, promptTier)\n    if (!promptPick.prompt) {\n      throw new Error(`提示词库「${promptBankNode.title || promptBankNode.id}」没有可用的 ${promptTier} 档提示词（已有：${promptPick.availableTiers.join(' / ') || '无'}）`)\n    }\n    effectivePrompt = promptPick.prompt\n    if (promptPick.tierUsed === 'raw') {\n      resolved.warnings = [...(resolved.warnings || []), `提示词库「${promptBankNode.title || promptBankNode.id}」是旧式单段文本，已按 ${promptTier} 档原样使用`]\n    } else if (promptPick.fallback) {\n      resolved.warnings = [...(resolved.warnings || []), `提示词库「${promptBankNode.title || promptBankNode.id}」没有 ${promptTier} 档段落，已回退到 ${promptPick.tierUsed} 档（已有：${promptPick.availableTiers.join(' / ')}）`]\n    }\n  }\n\n  // 角色卡双版本：视频 ref_nodes 按当次 tier 自动选 single / three（显式 ref_variant 可强制）\n  const lib = loadLibrary(root)\n  let refNodes = Array.isArray(opts.ref_nodes) ? [...opts.ref_nodes] : []\n  let refVariantTarget = ''\n  let refVariantSwaps = []\n  if (refNodes.length && String(manifest.capability).startsWith('video.')) {\n    const picked = resolveCharacterRefs(project, refNodes, opts.ref_variant, promptTier, resolved.warnings, lib)\n    refNodes = picked.refs\n    refVariantTarget = picked.target\n    refVariantSwaps = picked.swaps\n  }\n\n  // 参考音频（Ref2VA <Audio N>）→ 上传 ComfyUI。放在参考图之前解析，校验失败不上传任何东西。\n  const audioRefIds = (Array.isArray(opts.audio_ref_nodes) ? opts.audio_ref_nodes : [])\n    .map((x) => String(x == null ? '' : x).trim()).filter(Boolean)\n  const audioRefsResolved = []\n  if (audioRefIds.length) {\n    if (manifest.capability !== 'video.reference2video') {\n      throw new Error(`audio-ref-shape: 参考音频只支持视频参考生成（video.reference2video），当前实现 ${manifest.id} 是 ${manifest.capability}`)\n    }\n    // 所选实现必须有音频注入点（清单声明 params.ref_audios）。没有 = 显式失败，不静默丢弃。\n    if (!manifest.params || manifest.params.ref_audios === undefined) {\n      throw new Error(`audio-ref-unsupported: 实现 ${manifest.id} 没有参考音频注入点（params.ref_audios）。请换支持 <Audio N> 的 ref2v 实现，或不传 audio_ref_nodes`)\n    }\n    for (const rid of audioRefIds) audioRefsResolved.push(await resolveRefAudio(root, project, lib, rid))\n    const totalSec = audioRefsResolved.reduce((acc, a) => acc + (a.durationSec || 0), 0)\n    const unknown = audioRefsResolved.some((a) => a.durationSec == null)\n    for (const a of audioRefsResolved) {\n      if (a.durationSec == null) continue\n      if (a.durationSec < AUDIO_REF_MIN_SEC - 0.05 || a.durationSec > AUDIO_REF_MAX_SEC + 0.05) {\n        throw new Error(`audio-ref-invalid: 参考音频 ${a.file} 时长 ${a.durationSec.toFixed(2)}s，官方要求每段 2–15s`)\n      }\n    }\n    if (!unknown && totalSec > AUDIO_REF_TOTAL_SEC + 0.05) {\n      throw new Error(`audio-ref-invalid: 参考音频总时长 ${totalSec.toFixed(2)}s 超过 15s 上限`)\n    }\n    resolved.warnings = [...(resolved.warnings || [])]\n    if (unknown) resolved.warnings.push('参考音频时长无法校验（本机无 ffprobe 且来源节点未记录时长）：请自行确认每段 2–15s、总时长 ≤15s')\n    if (promptTier === 'fast') resolved.warnings.push('fast 档是 4 步 turbo 蒸馏：官方文档说明会削弱 reference/audio 强度。要稳住声线建议 balanced / quality')\n    // prompt 守卫：传了音频却没写 <Audio N>，参考可能只被当环境音；反过来声明了却没输入也是空绑定。\n    if (!/<Audio\\s*\\d/i.test(effectivePrompt)) {\n      resolved.warnings.push('已传参考音频，但 prompt 未出现 <Audio N> 声明：参考可能只被当环境音。按官方 Ref2VA 规范补 \"<Audio 1> is the voice-timbre reference for <Subject 1> (S1).\" 与 \"<Audio 1>: reference - ...\"')\n    }\n  } else if (/<Audio\\s*\\d/i.test(effectivePrompt)) {\n    resolved.warnings = [...(resolved.warnings || []), 'prompt 声明了 <Audio N> 但本次没有传 audio_ref_nodes：这是空绑定，模型只能靠文字描述猜音色']\n  }\n\n  // 上传参考图/首末帧（资产 id 或画布节点 id → ComfyUI 文件名）\n  const refs = []\n  for (const rid of refNodes) {\n    const name = await resolveRefImage(root, project, lib, rid)\n    if (name) refs.push(name)\n  }\n  const firstFrame = opts.first_frame_node ? await resolveRefImage(root, project, lib, opts.first_frame_node) : undefined\n  const lastFrame = opts.last_frame_node ? await resolveRefImage(root, project, lib, opts.last_frame_node) : undefined\n  const sourceVideo = opts.video_node ? await resolveSourceVideo(root, project, opts.video_node) : undefined\n\n  // 链式续接（manifest.chain）。协议由清单声明，runner 只管两件事：\n  //   ① 序号：上一镜的链序号从**画布上一镜节点**取（params.clipIndex），本镜 Load=它、Save=它+1；\n  //      不传 continuity_from = **起链**（Load 0：没有上文，上下文节点原样放行、不裁帧）。\n  //   ② 长度：请求的是「交付帧数」，续接要多采 sampleExtra 帧做继承再裁掉，并按模型合法长度网格向上取整。\n  // 序号在 ComfyUI 输出目录里是跨会话共享的文件槽位，所以起链起点按会话随机取、会话内单调递增。\n  const chain = manifest.chain || null\n  const wantLength = intArg(opts, 'length', 124)\n  const lengthGrid = chain?.lengthGrid || manifest.lengthGrid || null\n  let sampledLength = wantLength\n  let deliveredLength = wantLength\n  let chainLoadIdx = null\n  let chainSaveIdx = null\n  if (!chain && lengthGrid) {\n    // 非链式：模型自己也会按网格取整，这里先取整并如实记账（否则 length 与产物差最多一个步长）\n    sampledLength = snapLengthToGrid(wantLength, lengthGrid)\n    deliveredLength = sampledLength\n  }\n  if (chain) {\n    const grid = chain.lengthGrid\n    if (wantContinuity) {\n      const fromId = String(opts.continuity_from).trim()\n      const prev = project.nodes.find((n) => n.id === fromId)\n      if (!prev) throw new Error(`continuity_from 指向的画布节点不存在: ${fromId}`)\n      if (prev.kind !== 'video') throw new Error(`continuity_from 必须是画布视频节点（当前是 ${prev.kind}）：${fromId}`)\n      const prevIdx = Number(prev.params?.clipIndex)\n      if (!Number.isInteger(prevIdx) || prevIdx < 1) {\n        throw new Error(\n          `上一镜没有链式序号（params.clipIndex）：它必须也是链式实现渲染的。` +\n          `上一镜「${prev.title || fromId}」用的是 ${prev.params?.workflow || '未知'}——` +\n          '同场景第一镜请直接用链式实现渲染（不传 continuity_from 就是起链），后续镜再传它的节点 id')\n      }\n      // 续接的一致性判据是**首遍尺寸**，不是交付尺寸（判据本身是纯函数，见 chainGraphMismatch）：\n      // 链上流动的是首遍 latent（ctx 图的 node 22 存 node 10），放大发生在它之后\n      // ⇒ 学习式/两阶段放大的实现同样可以续接，只要两镜的首遍尺寸一致。\n      const mismatch = chainGraphMismatch(prev.params, effSize)\n      if (mismatch) throw new Error(mismatch)\n      chainLoadIdx = prevIdx\n      chainSaveIdx = prevIdx + 1\n      sampledLength = snapLengthToGrid(wantLength + chain.sampleExtra, grid)\n      // 网格向上取整会让**交付**略长于请求（146 → 采样 158 → 交付 136）：以实际交付为准记录，\n      // 否则下游按 length 排时长/拼接会跟成片差出去。\n      deliveredLength = Math.max(1, sampledLength - chain.sampleExtra)\n    } else {\n      chainLoadIdx = 0                       // 起链：没有上文\n      chainSaveIdx = allocateChainIndex(project)\n      sampledLength = snapLengthToGrid(wantLength, grid)\n      deliveredLength = sampledLength        // 起链没有继承帧要裁，采样即交付\n    }\n    project.settings.chainNext = Math.max(Number(project.settings.chainNext) || 1, chainSaveIdx + 1)\n  }\n\n  const prefix = CANV