defined && opts.duration !== null && opts.duration !== ''\n          ? Number(opts.duration)\n          : (manifest.params?.duration?.default ?? null),\n        ...(manifest.output?.sampleRate ? { sampleRate: manifest.output.sampleRate } : {}),\n        ...(manifest.license ? { license: manifest.license } : {}),\n        ...(typeof opts.lyrics === 'string' && opts.lyrics ? { lyrics: opts.lyrics } : {}),\n      } : {}),\n      seed: baseSeed,\n      // 画布上记**交付**分辨率（成片尺寸），不是图内首遍尺寸——拼接/续接的一致性判断都读这里。\n      // 图片以**产物真实像素**为准（probeImageSize）；读不出才退回推导值。\n      ...(isAudioOutput ? {} : {\n        width: deliverySize.w,\n        height: deliverySize.h,\n        // 与图内首遍/推导尺寸不同时，把底片尺寸也记下来（i2i 跟随参考图、两阶段放大都属此类）\n        ...(deliverySize.w !== effSize.w || deliverySize.h !== effSize.h\n          ? { graphWidth: effSize.w, graphHeight: effSize.h, ...(Number(manifest.resolutionLock?.scale) > 1 ? { upscaleScale: Number(manifest.resolutionLock.scale) } : {}) }\n          : {}),\n      }),\n      ...(resolved.warnings && resolved.warnings.length ? { warnings: resolved.warnings } : {}),\n      ...(isAudioOutput ? {} : { length: deliveredLength }),\n      ...(chain ? {\n        requestedLength: wantLength,\n        sampledLength,\n        clipIndex: chainSaveIdx,\n        contextClipIndex: chainLoadIdx,\n        continuityFrom: wantContinuity ? String(opts.continuity_from).trim() : null,\n        chain: { source: chain.source, sampleExtra: chain.sampleExtra },\n      } : {}),\n      // 逐镜自检门：视频产物默认「待自检」。渲完必须抽帧核对 + canvas_record_check\n      // 通过（重渲同一 nodeId 不受限），否则 pre-execute 门会拒绝下一镜（见 makeShotGateListener）。\n      ...(mediaType === 'video' && shotGateLevel(project.settings) !== 'off'\n        ? { shot: true, selfCheck: { status: 'pending', at: Date.now(), frames: [], checks: {}, notes: '' } }\n        : {}),\n      steps,\n      ...(isAudioOutput ? {} : { guidance, fps: (manifest.params?.fps?.default) || 24 }),\n      ref_nodes: refNodes,\n      ...(refVariantTarget ? { ref_variant: refVariantTarget } : {}),\n      ...(refVariantSwaps.length ? { ref_variant_swaps: refVariantSwaps } : {}),\n      first_frame_node: opts.first_frame_node || null,\n      last_frame_node: opts.last_frame_node || null,\n      ...(audioRefIds.length ? {\n        audio_ref_nodes: audioRefIds,\n        audioRefMeta: audioRefsResolved.map((a) => ({ source: a.source, file: a.file, kind: a.kind, durationSec: a.durationSec })),\n        audio_ref_declared: /<Audio\\s*\\d/i.test(effectivePrompt),\n      } : {}),\n      prompt: effectivePrompt,\n      // B 方案交接：这次渲染顺手存下的 draft latent（清单里声明了 OpenH3SaveRefinedLatent 才有）。\n      // 只记**文件名**（在 ComfyUI output/open_h3_latents/ 下）+ 交付帧数/首遍尺寸；\n      // `video_regenerate(handoff='auto')` 靠这几个字段判定能不能走 latent 交接。\n      ...(latentFile ? {\n        latentFile,\n        latentFrames: deliveredLength,\n        latentWidth: effSize.w,\n        latentHeight: effSize.h,\n      } : {}),\n      // 角色卡双版本元数据（单视图 / 三视图互配；两版节点都记同一个 character）\n      ...(opts.character ? { character: String(opts.character).trim() } : {}),\n      ...(opts.card_variant === 'single' || opts.card_variant === 'three' ? { cardVariant: opts.card_variant } : {}),\n      ...(opts.paired_node_id ? { pairedNodeId: String(opts.paired_node_id) } : {}),\n      assets: resolveAssets(manifest, getAssetOverrides(manifest.id)),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n\n  // ---- 创作批准失效：新产物 / 重渲替换了内容，旧批准不再代表这一版 ----\n  if (!project.approvals) project.approvals = {}\n  if (mediaType === 'image') {\n    const kind = assetKindOf(node)\n    if (kind) node.params = { ...(node.params || {}), assetKind: kind }\n    if (isAssetCard(node) && project.approvals.assets) {\n      const ap = project.approvals.assets\n      ap.nodeIds = (Array.isArray(ap.nodeIds) ? ap.nodeIds : []).filter((id) => id !== node.id)\n      if (!ap.nodeIds.length) delete project.approvals.assets\n    }\n  }\n  if (mediaType === 'video' && (node.params?.shot === true || shotIdFromText(node.title)) && project.approvals.clips) {\n    const ap = project.approvals.clips\n    ap.nodeIds = (Array.isArray(ap.nodeIds) ? ap.nodeIds : []).filter((id) => id !== node.id)\n    if (!ap.nodeIds.length) delete project.approvals.clips\n  }\n\n  // ---- 视频提示词持久化：每次生成都落到画布的提示词库节点（升档可读） ----\n  if (mediaType === 'video' && opts.persist_prompt !== false) {\n    let bank = promptBankNode\n    const bankTitle = promptBankTitleFor(opts.title || node.title)\n    const bankGroup = opts.prompt_group || opts.group || DEFAULT_GROUP\n    // 同镜重渲（新 nodeId）但标题/分组一致 → 复用同一份提示词库，避免画布上堆同名库\n    if (!bank && opts.nodeId) bank = findPromptBankForNode(project, nodeId)\n    if (!bank) bank = (project.nodes || []).find((n) => n.params?.promptBank && n.title === bankTitle && n.group === bankGroup) || null\n    if (bank) {\n      if (inlinePrompt) {\n        bank = upsertPromptBankNode(project, { nodeId: bank.id, tier: promptTier, prompt: effectivePrompt, promptFor: nodeId })\n      } else {\n        bank.params = {\n          ...(bank.params || {}),\n          promptBank: true,\n          promptBankVersion: PROMPT_BANK_VERSION,\n          promptFor: bank.params?.promptFor || nodeId,\n          lastTier: promptPick?.tierUsed || promptTier,\n          updatedAt: Date.now(),\n        }\n      }\n    } else if (inlinePrompt) {\n      bank = upsertPromptBankNode(project, {\n        title: bankTitle,\n        group: bankGroup,\n        tier: promptTier,\n        prompt: effectivePrompt,\n        promptFor: nodeId,\n      })\n    }\n    if (bank) {\n      node.params = {\n        ...node.params,\n        prompt_node: bank.id,\n        prompt_tier: promptTier,\n        prompt_used_tier: promptPick?.tierUsed || promptTier,\n        prompt_source: promptSource,\n        prompt_tiers: bank.params?.tiers || [],\n        ...(promptPick?.fallback ? { prompt_fallback_from: promptPick.tierUsed } : {}),\n      }\n    }\n  }\n\n  // ---- 角色卡双版本配对：两节点互记 pairedNodeId（不传就只记自己的 cardVariant） ----\n  if (opts.paired_node_id) {\n    const pairId = String(opts.paired_node_id)\n    if (pairId && pairId !== nodeId) {\n      const pair = project.nodes.find((n) => n.id === pairId)\n      if (pair) {\n        pair.params = {\n          ...(pair.params || {}),\n          pairedNodeId: nodeId,\n          ...(opts.character ? { character: String(opts.character).trim() } : {}),\n        }\n      }\n    }\n  }\n\n  await saveProject(root, sessionId, project)\n\n  return {\n    ok: true,\n    node,\n    files,\n    tier: resolved.tier,\n    implementation: manifest.id,\n    resolution: resolved.resolution,\n    warnings: resolved.warnings,\n    promptNodeId: node.params?.prompt_node || '',\n    promptTier: node.params?.prompt_used_tier || '',\n    promptFallback: node.params?.prompt_fallback_from || '',\n    audioRefs: audioRefsResolved.map((a) => ({ source: a.source, file: a.file, durationSec: a.durationSec })),\n    ...mediaDelivery(root, node.media),\n  }\n}\n\n/**\n * 按顺序拼接画布上的多个视频节点，产物写回画布。\n * 后端：本机有 ffmpeg 走 ffmpeg（stream copy），否则退化到 ComfyUI 纯节点链路。\n */\n/**\n * 从画布视频节点抽音轨 → 画布 audio 节点（声线参考素材）。\n * 后端与 video_concat 同构：有 ffmpeg 走 ffmpeg（零模型开销）；没有就走 ComfyUI 的\n * LoadVideo → GetVideoComponents → SaveAudio 纯节点链路（本机实测无需本地二进制）。\n */\nasync function runExtractAudio(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n  const src = project.nodes.find((n) => n.id === opts.video_node)\n  if (!src) throw new Error('extract-audio-invalid: 画布无此节点 ' + opts.video_node)\n  if (src.kind !== 'video') throw new Error(`extract-audio-invalid: 节点 ${opts.video_node} 不是视频节点（kind=${src.kind}）`)\n  if (!src.media) throw new Error('extract-audio-invalid: 节点无媒体文件')\n  const abs = join(root, ...String(src.media).split('/'))\n  if (!existsSync(abs)) throw new Error('extract-audio-invalid: 媒体文件不存在 ' + src.media)\n\n  const nodeId = opts.nodeId || randomUUID()\n  const dir = projectDir(root, sessionId)\n  await mkdir(dir, { recursive: true })\n  let media = ''\n  let backend = ''\n  if (await detectFfmpeg()) {\n    const outName = nodeId + '.wav'\n    const ok = await new Promise((resolvePromise) => {\n      execFile('ffmpeg', ['-y', '-i', abs, '-vn', '-ac', '2', '-ar', '32000', join(dir, outName)],\n        { timeout: 120000 }, (error) => resolvePromise(!error))\n    })\n    if (ok) { backend = 'ffmpeg'; media = CANVAS_DIR + '/' + sessionId + '/' + outName }\n  }\n  if (!media) {\n    const up = await comfyUploadMedia(await readFile(abs), basename(abs))\n    const name = up.subfolder ? up.subfolder + '/' + up.name : up.name\n    const graph = {\n      load: { class_type: 'LoadVideo', inputs: { file: name } },\n      comp: { class_type: 'GetVideoComponents', inputs: { video: ['load', 0] } },\n      save: { class_type: 'SaveAudio', inputs: { audio: ['comp', 1], filename_prefix: 'extract-audio/' + nodeId } },\n    }\n    const promptId = await comfySubmit(graph)\n    const entry = await comfyWait(promptId, opts.signal)\n    const outputs = comfyOutputs(entry)\n    if (!outputs.length) throw new Error('extract-audio-error: ComfyUI 没有返回音频（该视频可能没有音轨）')\n    const buf = await comfyDownload(outputs[0])\n    const ext = extname(outputs[0].filename) || '.flac'\n    media = await persistMedia(root, sessionId, buf, nodeId + ext)\n    backend = 'comfyui'\n  }\n\n  const node = {\n    id: nodeId,\n    kind: 'audio',\n    title: opts.title || ((src.title || '片段') + ' 音轨'),\n    media,\n    group: opts.group || DEFAULT_GROUP,\n    params: { source: src.id, sourceTitle: src.title || '', backend },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) {\n    node.order = project.nodes[existing].order\n    node.createdAt = project.nodes[existing].createdAt\n    project.nodes[existing] = node\n  } else {\n    project.nodes.push(node)\n  }\n  await saveProject(root, sessionId, project)\n  return { ok: true, node, backend, ...mediaDelivery(root, node.media) }\n}\n\nasync function runConcat(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n\n  const ids = Array.isArray(opts.nodes) ? opts.nodes : []\n  if (ids.length < 2) throw new Error('concat-invalid: nodes 至少要 2 个视频节点 id')\n\n  // 解析素材：必须是画布上已就绪的 video 节点，且媒体文件存在\n  const sources = []\n  for (const id of ids) {\n    const n = project.nodes.find((x) => x.id === id)\n    if (!n) throw new Error('concat-invalid: 画布无此节点 ' + id)\n    if (n.kind !== 'video') throw new Error(`concat-invalid: 节点 ${id} 不是视频节点（kind=${n.kind}）`)\n    if (!n.media) throw new Error('concat-invalid: 节点无媒体文件 ' + id)\n    const abs = join(root, ...String(n.media).split('/'))\n    if (!existsSync(abs)) throw new Error('concat-invalid: 媒体文件不存在 ' + n.media)\n    const probe = probeMp4(abs)\n    sources.push({\n      id, abs, node: n, probe,\n      fps: Number(n.params?.fps) || (probe.frames && probe.duration ? probe.frames / probe.duration : null),\n    })\n  }\n\n  // 帧率一致性守卫（fail-closed）：混 fps 拼接不会报错，但非首段会按错误速度播放。\n  // 这是补帧（video.interpolate）引入后最容易踩的坑：48fps 镜混进 24fps 成片 = 半速。\n  const fpsGuard = concatFpsGuard(sources)\n\n  const nodeId = opts.nodeId || randomUUID()\n  let media\n  let backend\n  let reencoded = false\n\n  const ffmpegBin = await detectFfmpeg({ roots: [root, packageRoot], extraPaths: [getCfg().ffmpegPath].filter(Boolean) })\n  if (ffmpegBin) {\n    backend = 'ffmpeg'\n    const dir = projectDir(root, sessionId)\n    await mkdir(dir, { recursive: true })\n    const outName = no