)\n\n  return { ok: true, node, backend, ...mediaDelivery(root, media) }\n}\n\n// ---------------------------------------------------------------------------\n// 图片裁切（纯像素后处理）：capability=image.crop\n// ---------------------------------------------------------------------------\n/**\n * 裁切矩形（纯逻辑）：源图尺寸 + 面板均分 / 显式矩形 → { x, y, w, h }。\n *\n * 优先显式矩形（x / y / width / height 给任意一个就走显式路径，缺的分量按面板/整高补），\n * 否则按 panel / panels 均分：第 panel 格（0 起）= 图上第 (panel/panels) 竖条、高度取满。\n * 三视图定妆图（1×3）默认切第 0 格 = **正面**。\n *\n * 全部夹在源图边界内：越界裁切在 ComfyUI 侧要么给黑边要么直接报错，错误点离调用方很远，\n * 这里先收敛掉（宽高不足时缩小、坐标越界时贴边），调用方拿到的一定是合法矩形。\n */\nexport function computeCropRect({ srcW, srcH, panel = 0, panels = 3, x, y, width, height } = {}) {\n  const W = Math.floor(Number(srcW))\n  const H = Math.floor(Number(srcH))\n  if (!Number.isFinite(W) || !Number.isFinite(H) || W < 1 || H < 1) {\n    throw new Error(`crop-invalid: 源图尺寸非法（${srcW}×${srcH}）：读不出像素尺寸，请显式传 width/height`)\n  }\n  const int = (v) => (v === undefined || v === null || v === '' ? undefined : (Number.isFinite(Number(v)) ? Math.round(Number(v)) : undefined))\n  const n = Math.max(1, int(panels) || 3)\n  const hasExplicit = [x, y, width, height].some((v) => v !== undefined && v !== null && v !== '')\n  let rect\n  if (hasExplicit) {\n    const w = int(width) ?? Math.floor(W / n)\n    const h = int(height) ?? H\n    rect = { x: int(x) ?? 0, y: int(y) ?? 0, w, h }\n  } else {\n    const idx = Math.min(Math.max(0, int(panel) ?? 0), n - 1)\n    const w = Math.floor(W / n)\n    rect = { x: idx * w, y: 0, w, h: H }\n  }\n  if (!Number.isFinite(rect.w) || !Number.isFinite(rect.h) || rect.w < 1 || rect.h < 1) {\n    throw new Error(`crop-invalid: 裁切尺寸非法（${rect.w}×${rect.h}）`)\n  }\n  rect.w = Math.min(rect.w, W)\n  rect.h = Math.min(rect.h, H)\n  rect.x = Math.min(Math.max(0, rect.x), W - rect.w)\n  rect.y = Math.min(Math.max(0, rect.y), H - rect.h)\n  return rect\n}\n\n/**\n * 把画布上的一个图片节点（或图片资产）裁出一块，产物写成新的画布图片节点。\n *\n * 为什么要有它：角色卡\"两版身份一致\"最省事的做法是**先出三视图、再从里面裁正面**\n * ——裁切不重绘，正面格与三视图逐像素同源，一致性按构造成立（不需要同 seed / 文本锁 / 自检兜底）。\n * 走注册表（capability=image.crop → 唯一实现 image-crop），与超分/补帧同构：\n * 没有提示词、没有采样器、不推导分辨率，产物尺寸 = 裁切矩形。\n */\nasync function runCrop(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n\n  const srcRef = String(opts.image_node || opts.source_node || '').trim()\n  if (!srcRef) throw new Error('crop-invalid: 必须给 image_node（画布图片节点 id 或图片资产 id）')\n\n  // 来源解析：资产 id（character:…）或画布图片节点\n  let srcAbs = ''\n  let srcNode = null\n  let srcTitle = srcRef\n  if (isAssetRef(srcRef)) {\n    const lib = loadLibrary(root)\n    srcAbs = resolveAssetImagePath(root, lib, srcRef) || ''\n    if (!srcAbs) throw new Error(`crop-invalid: 资产 ${srcRef} 不是图片（只有图片资产能裁切）`)\n    if (!existsSync(srcAbs)) throw new Error(`crop-invalid: 资产文件不存在（${srcAbs}）`)\n    srcTitle = srcRef\n  } else {\n    srcNode = project.nodes.find((n) => n.id === srcRef)\n    if (!srcNode) throw new Error('crop-invalid: 画布无此节点 ' + srcRef)\n    if (srcNode.kind !== 'image') throw new Error(`crop-invalid: 节点 ${srcRef} 不是图片节点（kind=${srcNode.kind}）`)\n    if (!srcNode.media) throw new Error('crop-invalid: 节点无媒体文件 ' + srcRef)\n    srcAbs = join(root, ...String(srcNode.media).split('/'))\n    if (!existsSync(srcAbs)) throw new Error('crop-invalid: 媒体文件不存在 ' + srcNode.media)\n    srcTitle = srcNode.title || srcRef\n  }\n\n  // 源尺寸：**读真实像素**优先（画布 params 只是记账，可能被手传/替换过的文件推翻）\n  const probed = probeImageSize(srcAbs)\n  const srcW = probed?.w || Number(srcNode?.params?.width) || 0\n  const srcH = probed?.h || Number(srcNode?.params?.height) || 0\n  const rect = computeCropRect({\n    srcW, srcH,\n    panel: opts.panel,\n    panels: opts.panels,\n    x: opts.x,\n    y: opts.y,\n    width: opts.width,\n    height: opts.height,\n  })\n\n  const registry = getRegistry()\n  const { manifest } = await resolveTieredManifest('image.crop', null, null, { registry })\n  const nodeId = opts.nodeId || randomUUID()\n  const uploaded = await comfyUploadImage(await readFile(srcAbs), basename(srcAbs))\n  const name = uploaded.subfolder ? uploaded.subfolder + '/' + uploaded.name : uploaded.name\n  const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId\n\n  const graph = buildGraphFromManifest(manifest, {\n    assetOverrides: getAssetOverrides(manifest.id),\n    source_image: name,\n    crop_x: rect.x,\n    crop_y: rect.y,\n    crop_width: rect.w,\n    crop_height: rect.h,\n    prefix,\n  })\n  const promptId = await comfySubmit(graph)\n  const entry = await comfyWait(promptId, opts.signal)\n  const outs = comfyOutputs(entry)\n  if (!outs.length) throw new Error('crop-error: ComfyUI 无输出')\n  const media = await persistMedia(root, sessionId, await comfyDownload(outs[0]), outs[0].filename)\n\n  const node = {\n    id: nodeId,\n    kind: 'image',\n    title: opts.title || `${srcTitle} · 裁切 ${rect.w}×${rect.h}`,\n    media,\n    group: opts.group || DEFAULT_GROUP,\n    params: {\n      workflow: manifest.id,\n      capability: 'image.crop',\n      model: manifest.id,\n      // 产物尺寸照常记：下游（例如后续再裁/再引用）不必重新读文件\n      width: rect.w,\n      height: rect.h,\n      cropFrom: srcRef,\n      cropFromMedia: srcNode?.media || srcAbs,\n      sourceWidth: srcW,\n      sourceHeight: srcH,\n      crop: rect,\n      panel: opts.panel === undefined || opts.panel === null ? null : Math.max(0, Math.round(Number(opts.panel)) || 0),\n      panels: opts.panels === undefined || opts.panels === null ? null : Math.max(1, Math.round(Number(opts.panels)) || 3),\n      // 角色卡双版本元数据（与 comfy_generate_image 的 single/three 同一套键）\n      ...(opts.character ? { character: String(opts.character).trim() } : {}),\n      ...(opts.card_variant === 'single' || opts.card_variant === 'three' ? { cardVariant: opts.card_variant } : {}),\n      ...(opts.paired_node_id ? { pairedNodeId: String(opts.paired_node_id) } : {}),\n      assets: resolveAssets(manifest, getAssetOverrides(manifest.id)),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n\n  // 裁切产物也是资产卡：复用已批准节点重裁时，旧批准失效（像素内容变了）。\n  if (!project.approvals) project.approvals = {}\n  if (project.approvals.assets) {\n    const ap = project.approvals.assets\n    ap.nodeIds = (Array.isArray(ap.nodeIds) ? ap.nodeIds : []).filter((id) => id !== node.id)\n    if (!ap.nodeIds.length) delete project.approvals.assets\n  }\n\n  // 角色卡双版本配对：两节点互记 pairedNodeId（与 comfy_generate_image 完全同一条规则）\n  if (opts.paired_node_id) {\n    const pairId = String(opts.paired_node_id)\n    if (pairId && pairId !== nodeId) {\n      const pair = project.nodes.find((n) => n.id === pairId)\n      if (pair) {\n        pair.params = {\n          ...(pair.params || {}),\n          pairedNodeId: nodeId,\n          ...(opts.character ? { character: String(opts.character).trim() } : {}),\n        }\n      }\n    }\n  }\n\n  await saveProject(root, sessionId, project)\n  return { ok: true, node, rect, srcW, srcH, ...mediaDelivery(root, media) }\n}\n\n// ---------------------------------------------------------------------------\n// 视频超分（U3）：工具层的确定性后处理，走注册表（capability=video.upscale）\n// ---------------------------------------------------------------------------\n/**\n * 把画布上的一个视频节点放大，产物写回画布。\n *\n * 与 runRender 的分工：这里没有提示词、没有采样器、不推导分辨率——尺寸来自**源视频本身**\n * （清单声明尺寸来源：`upscale.sizing='factor'` 交付 = 源 × 倍率；`='short-side'` 交付由实现的\n * 目标短边推导），所以不经过 buildRenderGraph 的尺寸策略。\n *\n * 长片：`upscale.chunking`（缺省 caller）说清显存归谁管。逐帧独立 ⇒ 可按「像素-帧预算」自动分块\n * （ImageFromBatch 切帧 + TrimAudioDuration 切音轨），再把各块拼回一条（ComfyUI 纯节点链路；\n * 本机无 ffmpeg 时这是唯一后端）。声明 `internal` 的实现（自带跨帧时间先验，如 SeedVR2）\n * **不自动分块**——切开会打断它自己的时间窗。\n */\nasync function runUpscale(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n\n  const srcId = String(opts.video_node || '').trim()\n  if (!srcId) throw new Error('upscale-invalid: 必须给 video_node（画布上的视频节点 id）')\n  const srcNode = project.nodes.find((n) => n.id === srcId)\n  if (!srcNode) throw new Error('upscale-invalid: 画布无此节点 ' + srcId)\n  if (srcNode.kind !== 'video') throw new Error(`upscale-invalid: 节点 ${srcId} 不是视频节点（kind=${srcNode.kind}）`)\n  if (!srcNode.media) throw new Error('upscale-invalid: 节点无媒体文件 ' + srcId)\n  const abs = join(root, ...String(srcNode.media).split('/'))\n  if (!existsSync(abs)) throw new Error('upscale-invalid: 媒体文件不存在 ' + srcNode.media)\n\n  // 档位：写错了必须报错。**不许静默退化成 quality** —— 曾因此把一次「非法档位」的校验用例\n  // 变成了一次真的 5376×3072 渲染（多花 ~300s GPU、还悄悄多出一个画布节点）。\n  const rawTier = (typeof opts.tier === 'string' && opts.tier.trim()) ||\n    (typeof opts.mode === 'string' && opts.mode.trim()) || ''\n  if (rawTier && !TIERS.includes(rawTier)) {\n    throw new Error(`upscale-invalid: tier \"${rawTier}\" 不在档位词汇表（${TIERS.join('|')}）`)\n  }\n  const tier = rawTier || 'quality'\n  const { manifest } = await resolveTieredManifest('video.upscale', tier, explicitImplementationOf(opts), { registry: getRegistry() })\n  const u = manifest.upscale\n  if (!u) throw new Error(`upscale-invalid: 实现 ${manifest.id} 没有声明尺寸来源（upscale.factor / upscale.shortSide）`)\n\n  // 源尺寸：优先画布 params（生成时就记下了），缺失回退到容器解析（手传/拼接的节点没有 params）\n  const probe = probeMp4(abs)\n  const srcW = Number(srcNode.params?.width) || probe.w\n  const srcH = Number(srcNode.params?.height) || probe.h\n  if (!(srcW > 0) || !(srcH > 0)) throw new Error('upscale-invalid: 读不出源视频尺寸（' + srcNode.media + '）')\n  const frames = Number(srcNode.params?.length) || probe.frames || 0\n  const fps = Number(srcNode.params?.fps) || 24\n  const plan = planUpscale({\n    srcW,\n    srcH,\n    sizing: u.sizing || 'factor',\n    factor: u.factor,\n    shortSide: u.shortSide,\n    maxEdge: u.maxEdge || 0,\n    align: u.align || 32,\n    targetWidth: intArg(opts, 'target_width', 0),\n  })\n  const warnings = []\n  if (plan.warning) warnings.push(plan.warning)\n  if (!probe.hasAudio && !(Number(srcNode.params?.length) > 0)) warnings.push('源片没有音轨（或读不出）——产物也将无音轨')\n\n  // 显存安全阀：像素-帧总量（帧数 × 交付宽 × 交付高）。实测 248 帧 × 5376×3072 = 4.09e9 通过；\n  // 超过告警线就分块，每块压到预算内（代价线性，分块几乎不额外花时间）。\n  // **但这条预算只对「逐帧独立」的实现成立**（chunking='caller'）：自带跨帧时间先验的实现\n  // 声明 chunking='internal'，显存由它自己管（batch / tiling / offload），外层切开会出接缝。\n  const chunking = u.chunking || 'caller'\n  const chunkPlan = planUpscaleChunks({\n    frames,\n    deliveryW: plan.delivery.w,\n    deliveryH: plan.delivery.h,\n    chunking,\n    explicitChunkFrames: intArg(opts, 'chunk_frames', 0),\n  })\n  warnings.push(...chunkPlan.warnings)\n  const chunks = chunkRanges(frames, chunkPlan.frameLimit)\n  if (chunks.length > 1) {\n    // 文案必须说清**为什么**分块：说是\"超过安全线\"但其实没超，就是在误导排障\n    const amount = `${frames} 帧 × 交付 ${plan.delivery.w}×${plan.delivery.h} = ${(chunkPlan.pixelFrames / 1e9).toFixed(2)}e9 像素-帧`\n    warnings.push(chunkPlan.reason === 'manual'\n      ? `按调用方指定分 ${chunks.length} 块（${chunkPlan.frameLimit} 帧/块）；${amount}（安全线 ${(PIXEL_FRAME_WARN / 1e9).toFixed(1)}e9）`\n      : `${amount}，超过安全线 ${(PIXEL_FRAME_WARN / 1e9).toFixed(1)}e9 ⇒ 自动分 ${chunks.length} 块逐段超分再拼回`)\n  }\n\n  const nodeId = opts.nodeId || randomUUID()\n  const uploaded = await comfyUploadImage(await readFile(abs), basename(abs))\n  const srcName = uploaded.subfolder ? uploaded.subfolder + '/' + uploaded.name : uploaded.name\n  const assetOverrides = getAssetOverrides(manifest.id)\n\n  const outFiles = []\n  for (const [i, c] of chunks.entries()) {\n    const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId + (chunks.length > 1 ? '-c' + String(i).padStart(3, '0') : '')\n    const base = buildGraphFromManifest(manifest, {\n      mode: null,\n      assetOverrides,\n      source_video: srcName,\n      out_width: plan.delivery.w,\n      out_height: plan.delivery.h,\n      // 只有 sizing='short-side' 的实现会声明这个参数（校验器强制）——把**已对齐的**短边回注给模型，\n      // 让 target_width 变成「按目标渲染」而不是「先渲染再降采样」。\n      out_short_side: plan.shortSide,\n      prefix,\n    })\n    const graph = sliceUpscaleGraph(base, { start: c.start, frames: c.frames, fps, sourceNode: '2' })\n    const promptId = await comfySubmit(graph)\n    const entry = await comfyWait(promptId, opts.signal)\n    const outs = comfyOutputs(entry)\n    if (!outs.length) throw new Error('upscale-error: ComfyUI 无输出' + (chunks.length > 1 ? `（第 ${i + 1}/${chunks.length} 块）` : ''))\n    outFiles.push(outs[0])\n  }\n\n  let media\n  let backend = 'comfyui-pixel'\n  if (outFiles.length === 1) {\n    media = await persistMedia(root, sessionId, await comfyDownload(outFiles[0]), outFiles[0].filename)\n  } else {\n    // 分块拼接：把各块**下载再上传**（concat 图吃 input 目录里的文件名）。\n    // 不用 ffmpeg：本机多半没有，而这条链路已在 concat 工具里验证过。\n    backend = 'comfyui-pixel+concat'\n    const names = []\n    for (let i = 0; i < outFiles.length; i++) {\n      const chunkAbs = await tmpChunkPath(root, sessionId, nodeId, i)\n      await writeFile(chunkAbs, await comfyDownload(outFiles[i]))\n      const up = await comfyUploadImage(await readFile(chunkAbs), basename(chunkAbs))\n      names.push(up.subfolder ? up.subfolder + '/' + up.name : up.name)\n    }\n    const graph = buildConcatGraph(names, CANVAS_DIR + '/' + sessionId + '/' + nodeId)\n    const promptId = await comfySubmit(graph)\n    const entry = await comfyWait(promptId, opts.signal)\n    const outs = comfyOutputs(entry)\n    if (!outs.length) throw new Error('upscale-error: 分块拼接无输出')\n    media = await persistMedia(root, sessionId, await comfyDownload(outs[0]), outs[0].filename)\n    for (const nm of names) { /* 临时块文件留在 input 目录由 ComfyUI 管理，不额外清理 */ void nm }\n  }\n\n  // 标题里的尺寸口径要跟**尺寸来源**一致：倍率形态写 ×N，短边形态写短边（编个倍率出来会与交付不符）\n  const sizeLabel = plan.sizing === 'short-side' ? `短边 ${plan.shortSide}` : `×${u.factor}`\n  const node = {\n    id: nodeId,\n    kind: 'video',\n    title: opts.title || `${srcNode.title || '片段'} · 超分 ${sizeLabel}`,\n    media,\n    group: opts.group || DEFAULT_GROUP,\n    params: {\n      workflow: manifest.id,\n      capability: 'video.upscale',\n      model: manifest.id,\n      tier,\n      // 交付尺寸与帧数照常记（画布靠这两个字段判断拼接/续接一致性）\n      width: plan.delivery.w,\n      height: plan.delivery.h,\n      length: frames,\n      fps,\n      // 超分特有的溯源\n      upscaleFrom: srcId,\n      upscaleFromMedia: srcNode.media,\n      sourceWidth: srcW,\n      sourceHeight: srcH,\n      sizing: plan.sizing,\n      // 倍率只在 factor 形态下成立；short-side 形态如实记 null（不编一个数出来）\n      factor: plan.factor,\n      shortSide: plan.shortSide,\n      naturalWidth: plan.natural.w,\n      naturalHeight: plan.natural.h,\n      targetWidth: intArg(opts, 'target_width', 0) || null,\n      chunks: chunks.length,\n      assets: resolveAssets(manifest, assetOverrides),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n  invalidateClipApproval(project, node.id)\n  await saveProject(root, sessionId, project)\n\n  return { ok: true, node, backend, plan, chunks: chunks.length, warnings, ...mediaDelivery(root, media) }\n}\n\n/** 分块临时文件的落点（与画布同目录，便于排障；ComfyUI 只认 input 目录的副本）。 */\nasync function tmpChunkPath(root, sessionId, nodeId, i) {\n  const dir = projectDir(root, sessionId)\n  await mkdir(dir, { recursive: true })\n  return join(dir, `${nodeId}-chunk${String(i).padStart(3, '0')}.mp4`)\n}\n\n// ---------------------------------------------------------------------------\n// 视频重生成（video.regenerate）：输入「已存在的片段 + 提示词」，在**固定目标网格**上重画\n// ---------------------------------------------------------------------------\n/**\n * 与 runUpscale 的分工：这里**没有尺寸推导**——交付尺寸是清单声明的目标网格（重生成模型在固定\n * 分辨率上训练），源片的比例只决定横/竖方向；也正因如此它不能塞进 upscale 契约（见 docs/video-regenerate.md）。\n *\n * 与 runRender 的分工：输入不是提示词 + 参考图，而是**画布上已有的视频**；提示词缺省沿用源节点\n * 记录的那一份（我们自己生成/续接的视频节点都存了 `params.prompt`）。外部导入、拼接成片没有 prompt\n * ⇒ 必须显式传，否则报错（精修是条件生成，空条件等于让它自由发挥）。\n *\n * 音频：图里用 `OpenH3RegenRefineLatent` 把音频 mask 在 σ=0（不参与重采样），出片再把**源音轨原样接回**\n * —— 音轨逐字节不变，口型跟着源音轨走；画面是重画的，所以口型/身份是否还贴合必须抽帧+听核。\n */\nasync function runRegenerate(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n\n  const srcId = String(opts.video_node || '').trim()\n  if (!srcId) throw new Error('regenerate-invalid: 必须给 video_node（画布上的视频节点 id）')\n  const srcNode = project.nodes.find((n) => n.id === srcId)\n  if (!srcNode) throw new Error('regenerate-invalid: 画布无此节点 ' + srcId)\n  if (srcNode.kind !== 'video') throw new Error(`regenerate-invalid: 节点 ${srcId} 不是视频节点（kind=${srcNode.kind}）`)\n  if (!srcNode.media) throw new Error('regenerate-invalid: 节点无媒体文件 ' + srcId)\n  const abs = join(root, ...String(srcNode.media).split('/'))\n  if (!existsSync(abs)) throw new Error('regenerate-invalid: 媒体文件不存在 ' + srcNode.media)\n\n  // 档位：写错必须报错（与超分同口径，不静默退化）。\n  const rawTier = (typeof opts.tier === 'string' && opts.tier.trim()) ||\n    (typeof opts.mode === 'string' && opts.mode.trim()) || ''\n  if (rawTier && !TIERS.includes(rawTier)) {\n    throw new Error(`regenerate-invalid: tier \"${rawTier}\" 不在档位词汇表（${TIERS.join('|')}）`)\n  }\n  const tier = rawTier || 'quality'\n  const registry = getRegistry()\n  // 先解析「视频入口」实现（C）：它同时提供目标网格与护栏声明，handoff 的判定要用它们。\n  const { manifest: videoManifest } = await resolveTieredManifest('video.regenerate', tier, explicitImplementationOf(opts), { registry })\n  const videoCfg = videoManifest.regenerate\n  if (!videoCfg) throw new Error(`regenerate-invalid: 实现 ${videoManifest.id} 没有声明 regenerate 块（目标网格 / 训练域护栏）`)\n\n  // 交接方式：auto（默认）/ latent / video。latent 入口是同一能力下的另一份清单（regenerate.input==='latent'），\n  // **只在同档内找**（不跨档替换）；找不到就按 handoff 的语义退/报错。\n  const requestedHandoff = String(opts.handoff || 'auto').trim()\n  const targetName = String(opts.target || '').trim() || videoCfg.default\n  const targetSpec = resolveRegenerateTarget({ targets: videoCfg.targets, target: targetName })\n  const latentCandidates = (registry.byCapability['video.regenerate'] || [])\n    .filter((m) => m.regenerate?.input === 'latent' && (!m.tier || m.tier === tier))\n    .sort((a, b) => (Number(b.priority) || 0) - (Number(a.priority) || 0))\n  const latentManifest = latentCandidates[0] || null\n  const availableLatentFiles = await probeLatentFiles()\n  let decision = decideRegenerateHandoff({\n    requested: requestedHandoff,\n    latent: {\n      file: srcNode.params?.latentFile,\n      frames: srcNode.params?.latentFrames,\n      width: srcNode.params?.latentWidth,\n      height: srcNode.params?.latentHeight,\n    },\n    cfg: videoCfg,\n    targetGraph: { w: targetSpec.graph[0], h: targetSpec.graph[1] },\n    availableLatentFiles,\n  })\n  if (decision.mode === 'latent' && !latentManifest) {\n    if (requestedHandoff.toLowerCase() === 'latent') {\n      throw new Error(`regenerate-invalid: ${tier} 档没有 latent 入口实现（handoff=latent 需要它）。请改用 handoff=video，或换一个提供 latent 入口的档位`)\n    }\n    decision = { mode: 'video', reason: `没有 ${tier} 档的 latent 入口实现，已退回视频交接`, warnings: decision.warnings }\n  }\n  const useLatent = decision.mode === 'latent'\n  const manifest = useLatent ? latentManifest : videoManifest\n  const cfg = manifest.regenerate\n\n  const probe = probeMp4(abs)\n  // latent 入口的「源片」是存下来的 draft latent：尺寸/帧数用渲染时登记的值（不是画布节点的交付尺寸）\n  const srcW = Number((useLatent ? srcNode.params?.latentWidth : srcNode.params?.width) || probe.w)\n  const srcH = Number((useLatent ? srcNode.params?.latentHeight : srcNode.params?.height) || probe.h)\n  const frames = Number((useLatent ? srcNode.params?.latentFrames : srcNode.params?.length) || probe.frames) || 0\n  const fps = useLatent\n    ? (Number(cfg.inputFps) || 24)\n    : (Number(srcNode.params?.fps) || (probe.frames && probe.duration ? probe.frames / probe.duration : null))\n\n  const ownPrompt = String(srcNode.params?.prompt || '').trim()\n  const prompt = String(opts.prompt ?? '').trim() || ownPrompt\n  const plan = planRegenerate({\n    srcW, srcH, frames, fps,\n    targets: cfg.targets,\n    target: targetName,\n    guards: cfg,\n    hasPrompt: !!prompt,\n  })\n\n  const warnings = [...plan.warnings, ...(decision.warnings || [])]\n  warnings.push(useLatent\n    ? `交接：latent（${decision.reason}）——没有经过 mp4 解码 / VAE 重编码`\n    : `交接：video（${decision.reason}）`)\n  if (useLatent && manifest.internal) warnings.push('latent 入口是 experimental（internal）清单：与视频入口的输出差异在 3 步模型的敏感度内，改用前请抽帧比对')\n  if (!ownPrompt) warnings.push('源节点没有记录 prompt：本次用的是显式传入的提示词（精修条件与源片可能不是同一段描述）')\n  // 音频：latent 入口的音轨来自存盘的 draft（含 waveform），不用再上传/重编码源片\n  if (!useLatent && !probe.hasAudio) warnings.push('源片没有音轨：精修用编码静音，产物也将无音轨')\n  warnings.push('重生成会重画内容（σ0.909 起 3 步）：请 extract_frame 抽帧核对身份/口型，再用 canvas_record_check 记录')\n\n  const nodeId = opts.nodeId || randomUUID()\n  const assetOverrides = getAssetOverrides(manifest.id)\n  const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId\n  const seed = intArg(opts, 'seed', Math.floor(Math.random() * 2 ** 31))\n  // 只有视频入口需要上传源片；latent 入口直接引用服务端 output/open_h3_latents/ 里的文件\n  let srcName = null\n  if (!useLatent) {\n    const uploaded = await comfyUploadImage(await readFile(abs), basename(abs))\n    srcName = uploaded.subfolder ? uploaded.subfolder + '/' + uploaded.name : uploaded.name\n  }\n  const graph = useLatent\n    ? buildGraphFromManifest(manifest, {\n        mode: null,\n        assetOverrides,\n        latent_file: String(srcNode.params.latentFile),\n        prompt,\n        width: plan.graph.w,\n        height: plan.graph.h,\n        seed,\n        steps: opts.steps,\n        start_sigma: opts.start_sigma,\n        prefix,\n      })\n    : buildGraphFromManifest(manifest, {\n        mode: null,\n        assetOverrides,\n        source_video: srcName,\n        prompt,\n        // 图内按 **graph** 网格渲染（1080p 是 1088 行），交付尺寸由 Finish 裁回 delivery\n        width: plan.graph.w,\n        height: plan.graph.h,\n        seed,\n        // 源片有音轨就用它（mask 在 σ=0）；没有就用参考实现的编码静音\n        audio_mode: probe.hasAudio ? 'draft audio (AUDIO input)' : 'silence (reference)',\n        steps: opts.steps,\n        start_sigma: opts.start_sigma,\n        prefix,\n      })\n  const promptId = await comfySubmit(graph)\n  const entry = await comfyWait(promptId, opts.signal)\n  const outs = comfyOutputs(entry)\n  if (!outs.length) throw new Error('regenerate-error: ComfyUI 无输出')\n  const media = await persistMedia(root, sessionId, await comfyDownload(outs[0]), outs[0].filename)\n\n  // 产物实测：尺寸/帧数与规划不一致时**以产物为准**记账（下游拼接按这里的 width/height/length 判一致性）\n  const outAbs = join(root, ...String(media).split('/'))\n  const outProbe = probeMp4(outAbs)\n  let delivery = { ...plan.delivery }\n  if (outProbe.w && outProbe.h && (outProbe.w !== plan.delivery.w || outProbe.h !== plan.delivery.h)) {\n    warnings.push(`交付尺寸以产物为准：${outProbe.w}×${outProbe.h}（规划 ${plan.delivery.w}×${plan.delivery.h}）`)\n    delivery = { w: outProbe.w, h: outProbe.h }\n  }\n  let length = plan.frames\n  if (outProbe.frames && outProbe.frames !== plan.frames) {\n    warnings.push(`交付帧数以产物为准：${outProbe.frames} 帧（规划 ${plan.frames}）`)\n    length = outProbe.frames\n  }\n\n  const stepsValue = opts.steps !== undefined && opts.steps !== '' ? Number(opts.steps) : (manifest.params?.steps?.default ?? 3)\n  const startSigmaValue = opts.start_sigma !== undefined && opts.start_sigma !== '' ? Number(opts.start_sigma) : (manifest.params?.start_sigma?.default ?? 0)\n  const node = {\n    id: nodeId,\n    kind: 'video',\n    title: opts.title || `${srcNode.title || '片段'} · 重生成 ${plan.target} ${delivery.w}×${delivery.h}`,\n    media,\n    group: opts.group || DEFAULT_GROUP,\n    params: {\n      workflow: manifest.id,\n      capability: 'video.regenerate',\n      model: manifest.id,\n      tier,\n      width: delivery.w,\n      height: delivery.h,\n      length,\n      fps: Number(cfg.inputFps) || 24,\n      // 溯源：从哪个片段重生成的（与超分的 upscaleFrom 同构）\n      regenerateFrom: srcId,\n      regenerateFromMedia: srcNode.media,\n      // 交接方式与原因（auto 退回到 video 时这里能看到为什么，不静默）\n      handoff: decision.mode,\n      handoffReason: decision.reason,\n      ...(useLatent ? { latentFile: String(srcNode.params.latentFile) } : {}),\n      sourceWidth: srcW,\n      sourceHeight: srcH,\n      target: plan.target,\n      graphWidth: plan.graph.w,\n      graphHeight: plan.graph.h,\n      steps: stepsValue,\n      startSigma: startSigmaValue,\n      audioMode: probe.hasAudio ? 'draft audio' : 'silence',\n      prompt,\n      seed,\n      assets: resolveAssets(manifest, assetOverrides),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) {\n    node.order = project.nodes[existing].order\n    node.createdAt = project.nodes[existing].createdAt\n    project.nodes[existing] = node\n  } else project.nodes.push(node)\n  invalidateClipApproval(project, node.id)\n  await saveProject(root, sessionId, project)\n\n  return {\n    ok: true,\n    node,\n    backend: useLatent ? 'comfyui-regenerate-latent' : 'comfyui-regenerate',\n    handoff: decision.mode,\n    handoffReason: decision.reason,\n    plan: { ...plan, delivery },\n    seed,\n    warnings,\n    ...mediaDelivery(root, media),\n  }\n}\n\n\n// ---------------------------------------------------------------------------\n// 视频补帧（VFI）：工具层的确定性后处理，走注册表（capability=video.interpolate）\n// ---------------------------------------------------------------------------\n/**\n * 拼接前的帧率一致性检查（纯函数，可测）。\n * 混 fps 拼接**不会报错**（ComfyUI 后端取首段 fps、ffmpeg copy 也可能成功），\n * 但非首段会按错误速度播放 —— 补帧引入后这是最容易踩的坑，所以 fail-closed。\n * @param {Array<{id:string, fps:number|null}>} sources\n */\nfunction concatFpsGuard(sources) {\n  const known = sources.map((s) => ({ id: s.id, fps: Number(s.fps) || null }))\n  const first = known.find((x) => x.fps)\n  if (!first) return { fps: null, warnings: ['所有片段都读不出帧率（容器探测失败）——拼接后时基以首段为准'] }\n  const bad = known.filter((x) => x.fps && Math.abs(x.fps - first.fps) > 0.02)\n  if (bad.length) {\n    const detail = bad.map((b) => `${b.id}=${b.fps}fps`).join('、')\n    throw new Error(\n      `concat-fps-mismatch: 片段帧率不一致（首段 ${first.id}=${first.fps}fps；${detail}）。` +\n      '混帧率拼接会让非首段片段按错误速度播放，且不会报错（ComfyUI 后端取首段 fps）。' +\n      `请先把片段统一到同一帧率：video_interpolate(video_node=…, target_fps=${first.fps})，或重出/去掉该镜。`)\n  }\n  return { fps: first.fps, warnings: [] }\n}\n\n/**\n * 补帧计划（纯函数，可测）：源 fps/帧数 + 目标帧率 → 倍率 m、母版 fps、抽取步长、帧数账。\n *\n * 契约（docs/video-interpolate.md）：\n *  - 模型只支持整数倍 2–16（ComfyUI FrameInterpolate）；\n *  - 目标帧率必须是母版（srcFps×m）的整数因子，否则抽取不整；\n *  - D2：模型输出 (N−1)m+1 帧，比 N×m 少 m−1 帧 ⇒ 尾部补 m−1 帧（末帧重复），\n *    母版帧数 = N×m、时长严格等于源；否则每镜短 1/(m·f) 秒，逐镜拼接会累积漂移。\n */\nfunction planInterpolate({ srcFps, frames, targetFps, multiplier, min = 2, max = 16 }) {\n  const warnings = []\n  if (!(srcFps > 0) || !(frames > 0)) throw new Error('interpolate-invalid: 读不出源视频的帧率或帧数')\n  if (!(targetFps > 0)) throw new Error('interpolate-invalid: target_fps 必须是正数')\n  if (Math.abs(targetFps - srcFps) < 1e-6) throw new Error(`interpolate-invalid: 源片已经是 ${srcFps}fps，无需补帧`)\n  if (targetFps < srcFps) throw new Error(`interpolate-invalid: 只做提帧率：源 ${srcFps}fps → 目标 ${targetFps}fps 是降帧`)\n\n  let m = null\n  if (multiplier !== undefined && multiplier !== null && multiplier !== '') {\n    const mm = Number(multiplier)\n    if (!Number.isInteger(mm) || mm < min || mm > max) throw new Error(`interpolate-invalid: multiplier 必须是 ${min}–${max} 的整数`)\n    const out = srcFps * mm\n    if (Math.abs(out - targetFps) > 1e-6 && Math.abs(out % targetFps) > 1e-6) {\n      throw new Error(`interpolate-invalid: 源 ${srcFps}fps × ${mm} = ${out}fps，不是目标 ${targetFps}fps 的整数倍，抽取不整`)\n    }\n    m = mm\n  } else {\n    for (let cand = min; cand <= max; cand++) {\n      const out = srcFps * cand\n      if (out + 1e-9 < targetFps) continue\n      if (Math.abs(out - targetFps) < 1e-6 || Math.abs(out % targetFps) < 1e-6) { m = cand; break }\n    }\n    if (!m) {\n      const reachable = []\n      for (let cand = min; cand <= max; cand++) {\n        const out = srcFps * cand\n        if (Math.abs(out % targetFps) < 1e-6) reachable.push(out)\n      }\n      throw new Error(\n        `interpolate-invalid: 从 ${srcFps}fps 到 ${targetFps}fps 没有整数倍路径（模型只支持 ×${min}–×${max}）。` +\n        (reachable.length\n          ? `可达母版帧率：${reachable.join(' / ')}fps`\n          : `请改目标为源帧率的整数倍（如 ${srcFps * 2}fps）`))\n    }\n  }\n  const outFps = srcFps * m\n  const stage = Math.round(outFps / targetFps)\n  const vfiFrames = (frames - 1) * m + 1\n  const targetFrames = frames * m\n  const padFrames = targetFrames - vfiFrames\n  const finalFrames = Math.round((frames / srcFps) * targetFps)\n  if (padFrames > 0) {\n    warnings.push(`D2 补齐：模型输出 ${vfiFrames} 帧，比目标母版 ${targetFrames} 帧（源 ${frames} 帧 × ${m}）少 ${padFrames} 帧 ⇒ 尾部重复末帧补齐，时长钉回 ${(frames / srcFps).toFixed(3)}s`)\n  }\n  if (stage > 1) {\n    warnings.push(`目标 ${targetFps}fps 不是源帧率的整数倍：先出 ${outFps}fps 母版，再由 ffmpeg 每 ${stage} 帧取 1 帧抽到 ${targetFps}fps（需要本机 ffmpeg）`)\n  }\n  return { m, outFps, stage, vfiFrames, targetFrames, padFrames, finalFrames, srcFps, frames, targetFps, warnings }\n}\n\n/**\n * 把画布上的一个视频节点补帧，产物写回画布。\n * 与 runUpscale 同构：无提示词、无采样器；源片上传 → 清单编译 → ComfyUI →（必要时 ffmpeg 抽取）→ 落画布。\n */\nasync function runInterpolate(ctx, opts) {\n  const { root, sessionId } = resolveSessionRoot(ctx, opts.sessionId, opts.workspaceId, opts.exec)\n  const project = await loadProject(root, sessionId)\n\n  // 便宜参数先校验（报错优先指向调用方传错的参数，而不是画布内容）\n  const rawTier = (typeof opts.tier === 'string' && opts.tier.trim()) || ''\n  if (rawTier && !TIERS.includes(rawTier)) throw new Error(`interpolate-invalid: tier \"${rawTier}\" 不在档位词汇表（${TIERS.join('|')}）`)\n  const srcId = String(opts.video_node || '').trim()\n  if (!srcId) throw new Error('interpolate-invalid: 必须给 video_node（画布上的视频节点 id）')\n  const srcNode = project.nodes.find((n) => n.id === srcId)\n  if (!srcNode) throw new Error('interpolate-invalid: 画布无此节点 ' + srcId)\n  if (srcNode.kind !== 'video') throw new Error(`interpolate-invalid: 节点 ${srcId} 不是视频节点（kind=${srcNode.kind}）`)\n  if (!srcNode.media) throw new Error('interpolate-invalid: 节点无媒体文件 ' + srcId)\n  const abs = join(root, ...String(srcNode.media).split('/'))\n  if (!existsSync(abs)) throw new Error('interpolate-invalid: 媒体文件不存在 ' + srcNode.media)\n\n  const tier = rawTier || 'quality'\n  const { manifest } = await resolveTieredManifest('video.interpolate', tier, explicitImplementationOf(opts), { registry: getRegistry() })\n  const spec = manifest.interpolate\n  if (!spec) throw new Error(`interpolate-invalid: 实现 ${manifest.id} 没有声明 interpolate 块`)\n\n  const probe = probeMp4(abs)\n  const frames = Number(srcNode.params?.length) || probe.frames || 0\n  const fps = Number(srcNode.params?.fps) || (probe.frames && probe.duration ? Number((probe.frames / probe.duration).toFixed(3)) : 0) || 24\n  const srcW = Number(srcNode.params?.width) || probe.w\n  const srcH = Number(srcNode.params?.height) || probe.h\n  if (!(srcW > 0) || !(srcH > 0)) throw new Error('interpolate-invalid: 读不出源视频尺寸（' + srcNode.media + '）')\n\n  const multArg = opts.multiplier === undefined || opts.multiplier === null || opts.multiplier === '' ? null : Number(opts.multiplier)\n  const defaultM = Number(spec.defaultMultiplier) || 2\n  const targetFps = intArg(opts, 'target_fps', 0) || fps * (multArg || defaultM)\n  const plan = planInterpolate({\n    srcFps: fps, frames, targetFps, multiplier: multArg,\n    min: spec.minMultiplier ?? 2, max: spec.maxMultiplier ?? 16,\n  })\n\n  const nodeId = opts.nodeId || randomUUID()\n  const uploaded = await comfyUploadImage(await readFile(abs), basename(abs))\n  const srcName = uploaded.subfolder ? uploaded.subfolder + '/' + uploaded.name : uploaded.name\n  const assetOverrides = getAssetOverrides(manifest.id)\n  const prefix = CANVAS_DIR + '/' + sessionId + '/' + nodeId\n  const graph = buildGraphFromManifest(manifest, {\n    mode: null,\n    assetOverrides,\n    source_video: srcName,\n    multiplier: plan.m,\n    out_fps: plan.outFps,\n    // D2：VFI 输出的最后一帧索引 = (N−1)·m；补 m−1 帧到 N×m\n    pad_from: (frames - 1) * plan.m,\n    pad_amount: plan.padFrames,\n    prefix,\n  })\n  const promptId = await comfySubmit(graph)\n  const entry = await comfyWait(promptId, opts.signal)\n  const outs = comfyOutputs(entry)\n  if (!outs.length) throw new Error('interpolate-error: ComfyUI 无输出')\n  let media = await persistMedia(root, sessionId, await comfyDownload(outs[0]), outs[0].filename)\n\n  let retimed = false\n  if (plan.stage > 1) {\n    const bin = await detectFfmpeg({ roots: [root, packageRoot], extraPaths: [getCfg().ffmpegPath].filter(Boolean) })\n    if (!bin) {\n      throw new Error(\n        `interpolate-needs-ffmpeg: 目标 ${plan.targetFps}fps 需要从 ${plan.outFps}fps 母版抽取（每 ${plan.stage} 帧取 1），本机没有 ffmpeg。` +\n        `装 ffmpeg（或配 ffmpegPath / env DSH_SVS_FFMPEG），或把目标改成源帧率的整数倍（如 ${fps * 2}fps，纯 ComfyUI 即可）`)\n    }\n    const vfiAbs = join(root, ...String(media).split('/'))\n    const outRel = CANVAS_DIR + '/' + sessionId + '/' + nodeId + '.mp4'\n    const outAbs = join(root, ...outRel.split('/'))\n    await ffmpegRetimeFps(bin, vfiAbs, outAbs, plan.targetFps)\n    await unlink(vfiAbs).catch(() => {})\n    media = outRel\n    retimed = true\n  }\n\n  const node = {\n    id: nodeId,\n    kind: 'video',\n    title: opts.title || `${srcNode.title || '片段'} · 补帧 ${plan.targetFps}fps`,\n    media,\n    group: opts.group || DEFAULT_GROUP,\n    params: {\n      workflow: manifest.id,\n      capability: 'video.interpolate',\n      model: manifest.id,\n      tier,\n      // 分辨率不变（补帧只改时间轴），尺寸照常记，供拼接一致性判断\n      width: srcW,\n      height: srcH,\n      length: plan.finalFrames,\n      fps: plan.targetFps,\n      // 补帧溯源：源片 + 倍率链路 + D2 补齐账\n      interpolateFrom: srcId,\n      interpolateFromMedia: srcNode.media,\n      sourceFps: fps,\n      sourceFrames: frames,\n      multiplier: plan.m,\n      masterFps: plan.outFps,\n      stage: plan.stage,\n      vfiFrames: plan.vfiFrames,\n      padFrames: plan.padFrames,\n      retimed,\n      assets: resolveAssets(manifest, assetOverrides),\n    },\n    status: 'ready',\n    createdAt: Date.now(),\n    order: nextOrder(project.nodes),\n  }\n  const existing = project.nodes.findIndex((n) => n.id === nodeId)\n  if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n  else project.nodes.push(node)\n  invalidateClipApproval(project, node.id)\n  await saveProject(root, sessionId, project)\n\n  return { ok: true, node, plan, retimed, warnings: plan.warnings, ...mediaDelivery(root, media) }\n}\n\n// ---------------------------------------------------------------------------\n// pre-ask 自动送达（飞书渠道）\n// ---------------------------------------------------------------------------\n// 机制：宿主每个工具执行前都过 `tools/pre-execute` waterfall（可扩展、异步、\n// 按 agent scope 分发）。本插件注册一个监听器：当 agent 即将调用\n// `ask_user_question` 时，先把画布中「未送达」的产物程序化调 send_file\n// 送达，再放行 ask。\n// - 媒体（图片/视频/音频）直接发原文件；文本/表格节点导出为 .pdf 发送\n//   （puppeteer-core/Chrome 渲染 HTML→PDF；无 PDF 工具时兜底 .html）。\n// - 文件名：send_file 没有 name 参数（聊天显示名 = 路径 basename），钩子把产物\n//   以「节点标题」命名的副本放到 workspace 内 .delivery/<sid>/ 再发送\n//   （如 主角卡.png / 简报.pdf），发完即删；副本建不出来退回原路径。\n// - send_file 是 dsh-lark per-agent 注册的工具；本插件用 ctx.tools.get(name, agent)\n//   探测可见性（不可见 = Web/TUI 或 sendFiles=false → 自动跳过，不推）。\n// - 去重：送达成功后写回节点 params.deliveredAt；失败不标记，下次 ask 前重试。\n// - 该监听器只对 ask_user_question 生效，send_file 自身执行不会递归触发。\n// 开关（改这里即可整体关闭 / 关闭文本导出）：\nconst AUTO_DELIVER_BEFORE_ASK = true\nconst TEXT_NODE_EXPORT_PDF = true\n\n/** 收集画布中尚未送达的产物（按 order 升序）。 */\nfunction collectUndelivered(project) {\n  const pending = []\n  for (const n of (project?.nodes || [])) {\n    if (n.status !== 'ready') continue\n    if (n.params?.deliveredAt) continue\n    if (n.kind === 'image' || n.kind === 'video' || n.kind === 'audio') {\n      if (n.media) pending.push({ node: n, path: n.media })\n    } else if (TEXT_NODE_EXPORT_PDF && (n.kind === 'text' || n.kind === 'table')) {\n      if (n.file) pending.push({ node: n, path: n.file })\n    }\n  }\n  return pending.sort((a, b) => (a.node.order || 0) - (b.node.order || 0))\n}\n\n// ---- 文本节点 markdown → HTML：渲染器在 studio/markdown.js（双端共享，与画布一致）----\n\n/** 文本/表格节点 → 完整 HTML 文档。 */\nfunction renderNodeHtml(title, kind, group, content) {\n  return `<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<title>${escapeHtmlText(title)}</title>\n<style>\nbody{font-family:-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;max-width:860px;margin:32px auto;padding:0 20px;color:#1f2328;line-height:1.7}\nh1{font-size:1.5em;border-bottom:1px solid #e5e7eb;padding-bottom:8px}\nh2,h3,h4{line-height:1.3}\ntable{border-collapse:collapse;width:100%;margin:12px 0}\nth,td{border:1px solid #d8dee4;padding:6px 10px;text-align:left;font-size:0.92em}\nth{background:#f6f8fa}\npre{background:#f6f8fa;border:1px solid #d8dee4;border-radius:6px;padding:12px;overflow-x:auto}\ncode{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:0.9em}\nblockquote{border-left:4px solid #d0d7de;margin:12px 0;padding:4px 14px;color:#57606a}\n.meta{color:#6e7781;font-size:0.85em;margin-bottom:16px}\n</style>\n</head>\n<body>\n<h1>${escapeHtmlText(title)}</h1>\n<p class=\"meta\">kind: ${escapeHtmlText(kind)} · group: ${escapeHtmlText(group)}</p>\n${markdownToHtml(content)}\n</body>\n</html>`\n}\n\n/**\n * 文本/表格节点导出交付文件：PDF 优先（puppeteer/Chrome/soffice/cupsfilter），\n * 无 PDF 工具或转换失败时兜底导出 .html。返回 { rel, ext }（失败也返回 html 兜底）。\n */\nasync function exportTextNode(root, sid, nodeId, title, kind, group, content, pdfTool) {\n  const htmlRel = CANVAS_DIR + '/' + sid + '/' + nodeId + '.html'\n  const htmlAbs = join(root, ...htmlRel.split('/'))\n  await mkdir(dirname(htmlAbs), { recursive: true })\n  await writeFile(htmlAbs, renderNodeHtml(title, kind, group, content), 'utf8')\n  if (pdfTool) {\n    try {\n      const pdfRel = CANVAS_DIR + '/' + sid + '/' + nodeId + '.pdf'\n      const pdfAbs = join(root, ...pdfRel.split('/'))\n      await htmlToPdf(pdfTool, htmlAbs, pdfAbs)\n      await unlink(htmlAbs).catch(() => {})\n      return { rel: pdfRel, ext: 'pdf' }\n    } catch (error) {\n      console.warn('[dsh-short-video-studio] html→pdf failed, fallback .html:', error?.message || String(error))\n    }\n  }\n  return { rel: htmlRel, ext: 'html' }\n}\n\n// ---- 交付文件名：send_file 没有 name 参数（dsh-lark 只收 {path}），\n//      聊天显示名 = path 的 basename（outbound-file.ts `fileName: basename(canonical)`）。\n//      因此把产物以「节点标题」命名的副本放到 workspace 内 .delivery/<sid>/，\n//      发副本路径 → 飞书显示 主角卡.png / 简报.pdf，而不是内部 nodeId。发完即删。\n\n/** workspace 内交付副本目录（隐藏目录，不参与画布伺服/资产）。 */\nconst DELIVERY_DIR = '.delivery'\n\n/** 由节点派生友好文件名：`<title>.<ext>`，清理非法字符；title 为空回退 `<kind>-<nodeId前8>.<ext>`。 */\nfunction deliveryFilename(node, path) {\n  const ext = extname(path).toLowerCase()\n  let base = String(node.title || '').trim()\n  base = base.replace(/[\\\\/:*?\"<>|\\u0000-\\u001f]/g, ' ').replace(/\\s+/g, ' ').trim().replace(/\\.+$/g, '').slice(0, 60)\n  if (!base) base = (node.kind || 'file') + '-' + String(node.id || '').slice(0, 8)\n  return base + ext\n}\n\n/**\n * 为送达建友好名副本（硬链接零拷贝，失败退复制）。同名冲突加 -2/-3 后缀。\n * 副本建不出来返回 null（调用方退回原路径发送，不阻塞送达）。\n * @returns {{rel:string, abs:string}|null} 副本的 workspace 相对路径与绝对路径\n */\nasync function stageDeliveryFile(root, sid, item) {\n  const name = deliveryFilename(item.node, item.path)\n  if (name === basename(item.path)) return null // 原名已是友好名\n  const srcAbs = join(root, ...item.path.split('/'))\n  const relDir = DELIVERY_DIR + '/' + sid\n  const dirAbs = join(root, ...relDir.split('/'))\n  await mkdir(dirAbs, { recursive: true })\n  let rel = relDir + '/' + name\n  let abs = join(dirAbs, name)\n  const stem = name.replace(/\\.[^.]*$/, '')\n  const ext = extname(name)\n  let i = 2\n  while (existsSync(abs)) {\n    rel = relDir + '/' + `${stem}-${i}${ext}`\n    abs = join(dirAbs, `${stem}-${i}${ext}`)\n    i++\n  }\n  try {\n    await link(srcAbs, abs)\n  } catch {\n    try { await copyFile(srcAbs, abs) } catch { return null }\n  }\n  return { rel, abs }\n}\n\n/**\n * 把 pending 列表逐个经 send_file 送达（友好文件名副本）；成功者打 deliveredAt 标记，\n * 失败者记 deliveryError（下次 ask 前会重试，模型可用 canvas_get_node 查原因）。\n * 失败只 console.warn（不阻塞 ask）。返回 { sent, errored }。\n */\nasync function deliverPending(ctx, exec, root, sid, project, pending) {\n  let sent = 0\n  let errored = 0\n  for (const item of pending) {\n    const n = project.nodes.find((x) => x.id === item.node.id)\n    let staged = null\n    try {\n      staged = await stageDeliveryFile(root, sid, item)\n      await ctx.tools.execute({\n        name: 'send_file',\n        arguments: { path: staged ? staged.rel : item.path },\n        agent: exec.agent,\n        signal: exec.signal,\n      })\n      if (n) n.params = { ...(n.params || {}), deliveredAt: Date.now() }\n      sent++\n    } catch (error) {\n      if (n) n.params = { ...(n.params || {}), deliveryError: String(error?.message || error) }\n      errored++\n      console.warn(`[dsh-short-video-studio] pre-ask deliver failed for ${item.path}:`, error?.message || String(error))\n    } finally {\n      if (staged) await unlink(staged.abs).catch(() => {})\n    }\n  }\n  if (sent > 0 || errored > 0) await saveProject(root, sid, project)\n  return { sent, errored }\n}\n\n/**\n * 构造 tools/pre-execute 监听器：只拦 ask_user_question；当前 agent scope 可见\n * send_file 时（飞书渠道），先把画布未送达产物送达，再放行 ask。\n * 任何异常都不阻塞 ask（只 warn）。\n */\nfunction makePreAskDeliverListener(ctx) {\n  return async function preAskDeliverListener(exec, next) {\n    if (!AUTO_DELIVER_BEFORE_ASK || exec?.name !== 'ask_user_question') return next()\n    try {\n      const agent = exec.agent\n      if (!agent || typeof ctx.tools?.get !== 'function') return next()\n      // 渠道探测：当前 agent scope 看不到 send_file（Web/TUI，或飞书 sendFiles=false）→ 不推送\n      if (!ctx.tools.get('send_file', agent)) return next()\n      const sid = agent.id\n      const { root } = resolveSessionRoot(ctx, sid, '', exec)\n      const project = await loadProject(root, sid)\n      const pending = collectUndelivered(project)\n      if (pending.length > 0) await deliverPending(ctx, exec, root, sid, project, pending)\n    } catch (error) {\n      console.warn('[dsh-short-video-studio] pre-ask deliver skipped:', error?.message || String(error))\n    }\n    return next()\n  }\n}\n\n// ---------------------------------------------------------------------------\n// H3 结构化 prompt 质检门（tools/pre-execute 兜底）\n// ---------------------------------------------------------------------------\n// 机制：宿主每个工具执行前都过 `tools/pre-execute` waterfall。本监听器对\n// 视频生成工具（comfy_generate_video / comfy_render）做 H3 结构化 prompt 校验：\n// - 仅当解析出的工作流 id 前缀为 minimax-h3- 时启用（模型无关：其他工作流直接放行）；\n// - 参考绑定镜（video.reference2video）要求 Ref2VA 六段式字段齐全；\n//   首末帧串联镜 / 转场镜（video.image2video）要求 I2VA/FL2VA 三段式 + 对齐指令；\n// - 不满足 → deny，reason 列出缺失字段并指引加载 h3-prompt-writing skill 重写；\n// - 防死循环：同一 agent 连续 deny ≥ H3_GATE_MAX_DENIES 次后降级放行（不无限打回）。\n// 开关（改这里即可整体关闭）：\nconst H3_PROMPT_GATE = true\nconst H3_GATE_MAX_DENIES = 2\nconst H3_WORKFLOW_PREFIX = 'minimax-h3-'\nconst H3_REF2V_SECTIONS = ['subject_definitions', 'summary', 'retention_analysis', 'detailed_description', 'overall_soundscape', 'non_diegetic_music']\nconst H3_I2V_SECTIONS = ['integrated_multimodal_description', 'overall_soundscape', 'non_diegetic_music']\nconst h3GateDenies = new Map() // agentId -> 连续 deny 次数\n\n/** prompt 是否已含某 H3 字段标题（行首 `<字段>:`）。 */\nfunction h3HasSection(prompt, section) {\n  return new RegExp(`(^|\\\\n)\\\\s*${section}\\\\s*:`, 'm').test(prompt)\n}\n\n/**\n * 质检门前置读提示词库：`prompt_node` + `tier` → 本档 prompt。\n * 读不到就返回空串（门放行，交给 execute 显式报错，避免把「节点丢了」误报成结构化缺失）。\n */\nasync function readPromptBankPromptForGate(ctx, exec, args) {\n  try {\n    const sid = args.sessionId || exec?.agent?.id\n    const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n    const project = await loadProject(root, sid)\n    const node = findPromptBankNode(project, args.prompt_node)\n    if (!node) return ''\n    const tier = tierFromArgs(args) || DEFAULT_TIER\n    return resolvePromptForTier(parsePromptBank(node.content), tier).prompt || ''\n  } catch {\n    return ''\n  }\n}\n\n/**\n * 构造 tools/pre-execute 监听器：只拦 H3 系工作流的视频生成；校验结构化字段，\n * 缺失则 deny 引导（防死循环上限后降级放行）。任何异常都放行（不阻塞生成）。\n */\nfunction makeH3PromptGateListener(ctx) {\n  return async function h3PromptGateListener(exec, next) {\n    try {\n      if (!H3_PROMPT_GATE || !exec?.arguments) return next()\n      const name = exec.name\n      const args = exec.arguments\n      // 定位 capability\n      let capability = null\n      if (name === 'comfy_generate_video') {\n        capability = (args.type && VIDEO_SHAPES[args.type]?.capability) || (args.first_frame_node || args.last_frame_node ? 'video.image2video' : 'video.reference2video')\n      } else if (name === 'comfy_render' && typeof args.capability === 'string') {\n        capability = args.capability\n      } else {\n        return next()\n      }\n      if (!capability || !String(capability).startsWith('video.')) return next()\n      let prompt = typeof args.prompt === 'string' ? args.prompt : ''\n      // 分档提示词库：prompt 省略时按 tier 从 prompt_node 读取（与 runRender 同一套回退规则）\n      if (!prompt.trim() && args.prompt_node) prompt = await readPromptBankPromptForGate(ctx, exec, args)\n      if (!prompt.trim()) return next()\n      // 显式回退通道：skill 失败回退时在 prompt 首行加 [PROMPT_FALLBACK]，质检门放行\n      // （结构化重写质量倒退 → 该镜回退自由格式时使用，避免被误拦）。\n      if (/^\\s*\\[PROMPT_FALLBACK\\]/.test(prompt)) return next()\n      // 解析工作流 id（显式 workflow > preferred > 任意清单）；解析失败放行\n      let manifest\n      try {\n        manifest = resolveManifest(getRegistry(), capability, typeof args.workflow === 'string' ? args.workflow : undefined)\n      } catch {\n        return next()\n      }\n      if (!manifest || typeof manifest.id !== 'string' || !manifest.id.startsWith(H3_WORKFLOW_PREFIX)) return next()\n      // 结构校验\n      const isI2V = capability === 'video.image2video'\n      const required = isI2V ? H3_I2V_SECTIONS : H3_REF2V_SECTIONS\n      const missing = required.filter((s) => !h3HasSection(prompt, s))\n      if (isI2V && !/For the target video|How the reference pictures align/.test(prompt)) missing.unshift('对齐指令（For the target video… / How the reference pictures align…）')\n      if (missing.length === 0) {\n        h3GateDenies.delete(exec.agent?.id || 'unknown')\n        return next()\n      }\n      // 防死循环：连续 deny 超上限 → 降级放行\n      const key = exec.agent?.id || 'unknown'\n      const denies = (h3GateDenies.get(key) || 0) + 1\n      h3GateDenies.set(key, denies)\n      if (denies > H3_GATE_MAX_DENIES) return next()\n      const expect = isI2V\n        ? 'I2VA/FL2VA 三段式（对齐指令 + integrated_multimodal_description + overall_soundscape + non_diegetic_music）'\n        : 'Ref2VA 六段式（subject_definitions / summary / retention_analysis / detailed_description / overall_soundscape / non_diegetic_music）'\n      return {\n        kind: 'deny',\n        reason: `H3 结构化 prompt 校验未通过，缺失：${missing.join(' / ')}。请调用 skill 工具加载 h3-prompt-writing，按它的 references/studio-mapping.md 把本镜 prompt 重写为 ${expect} 后重新调用。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 短剧制片门（production gate，tools/pre-execute）\n//\n// 为什么要有：planGate / shotGate 都在**画布层**，没人读 series/production-state.json，\n// 于是「阶段还没到就开渲」「G-P 方案卡没批准就烧 GPU」「library 模式资产没锁定」这些\n// 系列层违规，代码完全看不见（L3 才暴露）。本门只在 workspace 里存在\n// `series/production-state.json` 时激活，单片流程零影响。\n//\n// 它验的是**留痕**（state 里写了什么），不是「人真的点过头」——真实性由会话审计补。\n// 任何读取/解析异常一律放行（不许把缺文件当成违规）。\nconst PRODUCTION_GATE_MAX_DENIES = 2\nconst PRODUCTION_GATE_STAGES = ['shotlist', 'clips', 'final', 'delivered']\nconst productionGateDenies = new Map()\n\nfunction readJsonSafe(abs) {\n  try { return JSON.parse(readFileSync(abs, 'utf8')) } catch { return null }\n}\n\nfunction packageJsonOf(md) {\n  const m = String(md || '').match(/```json\\n([\\s\\S]*?)\\n```/)\n  if (!m) return null\n  try { return JSON.parse(m[1]) } catch { return null }\n}\n\n/**\n * 构造 tools/pre-execute 监听器：视频生成前校验系列层前置条件。\n * 检查项：stage / G-P 批准 / 包与剧本版本一致 / library 模式资产锁定与 ref 来源。\n */\nfunction makeProductionGateListener(ctx) {\n  return async function productionGateListener(exec, next) {\n    try {\n      if (String(process.env.DSH_SVS_PRODUCTION_GATE || '').toLowerCase() === 'off') return next()\n      if (!exec?.arguments) return next()\n      const name = exec.name\n      const args = exec.arguments\n      const isGenerate = name === 'comfy_generate_video'\n        || (name === 'comfy_render' && typeof args.capability === 'string'\n          && args.capability.startsWith('video.')\n          && args.capability !== 'video.upscale'\n          && args.capability !== 'video.interpolate'\n          && args.capability !== 'video.regenerate')\n      if (!isGenerate) return next()\n      const sid = args.sessionId || exec?.agent?.id\n      if (!sid) return next()\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const projectForProfile = await loadProject(root, sid)\n      if (!gateOn(projectForProfile.settings, 'production')) return next()\n      const statePath = join(root, 'series', 'production-state.json')\n      if (!existsSync(statePath)) return next()\n      const state = readJsonSafe(statePath)\n      if (!state || typeof state !== 'object') return next()\n\n      const eps = state.episodes || {}\n      const epId = state.currentEpisode\n        || String(state.next || '').split('/')[0]\n        || Object.keys(eps)[0]\n      const ep = eps[epId]\n      if (!ep) return next()\n\n      const issues = []\n      // ① 阶段：没过方案卡（G-P）就不该出片\n      if (!PRODUCTION_GATE_STAGES.includes(String(ep.stage || ''))) {\n        issues.push(`本集 stage=${ep.stage || '?'}：还没过方案卡（G-P）就开渲；先「方案卡批准 → stage=shotlist」`)\n      }\n      // ② G-P 批准留痕\n      const pkgGate = ep.gate?.package?.status\n      if (pkgGate !== 'approved') {\n        issues.push(`方案卡（G-P）未批准：state.episodes.${epId}.gate.package.status=${pkgGate || 'missing'}（批准后写 approved 再渲）`)\n      }\n      // ③ 包 / 剧本版本一致（改台词不重建包 = 版本对不上）\n      const pkgRel = String(ep.package || `series/episodes/${epId}/package.md`)\n      const pkgPath = join(root, ...pkgRel.split('/'))\n      const pkg = existsSync(pkgPath) ? packageJsonOf(readFileSync(pkgPath, 'utf8')) : null\n      if (pkg?.episode) {\n        if (Number(pkg.episode.packageVersion) !== Number(ep.packageVersion)) {\n          issues.push(`集制作包版本不一致：package=${pkg.episode.packageVersion} / state=${ep.packageVersion}（改包后回写 state）`)\n        }\n        if (Number(pkg.episode.scriptVersion) !== Number(ep.scriptVersion)) {\n          issues.push(`剧本版本不一致：package=${pkg.episode.scriptVersion} / state=${ep.scriptVersion}（改台词必须重建包并同步版本）`)\n        }\n      }\n      // ④ library 模式：资产必须锁定，参考图必须来自资产库\n      if (pkg?.params?.assetMode === 'library') {\n        const assets = state.assets || {}\n        for (const [kind, list] of [['characters', assets.characters], ['scenes', assets.scenes], ['voices', assets.voices]]) {\n          if (!Array.isArray(list) || list.length === 0) {\n            issues.push(`assetMode=library 但 assets.${kind} 为空：阶段 C（G-A）没做完`)\n          } else if (list.some((x) => !['locked', 'deprecated'].includes(String(x.status || '')))) {\n            issues.push(`assetMode=library 但 assets.${kind} 有未锁定条目（status≠locked）`)\n          }\n        }\n        const refIds = Array.isArray(args.ref_nodes) ? args.ref_nodes : []\n        if (refIds.length) {\n          const project = await loadProject(root, sid)\n          const loose = refIds.filter((id) => {\n            const n = (project?.nodes || []).find((x) => x.id === id)\n            return n && !n.params?.assetId\n          })\n          if (loose.length) issues.push(`library 模式下参考图必须是资产库物化的节点（缺 params.assetId）：${loose.join('、')}`)\n        }\n      }\n\n      if (!issues.length) {\n        productionGateDenies.delete(exec.agent?.id || 'unknown')\n        return next()\n      }\n      const key = exec.agent?.id || 'unknown'\n      const denies = (productionGateDenies.get(key) || 0) + 1\n      productionGateDenies.set(key, denies)\n      if (denies > PRODUCTION_GATE_MAX_DENIES) return next()\n      return {\n        kind: 'deny',\n        reason: `制片门未通过：${issues.join('；')}。先补 state / 重建包，再渲（连续 ${PRODUCTION_GATE_MAX_DENIES} 次后降级放行；DSH_SVS_PRODUCTION_GATE=off 可关）。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// 镜头表一致性门（plan gate，tools/pre-execute）\n// ---------------------------------------------------------------------------\n// 机制：视频生成前，按标题里的 Sxx 在画布「七列镜头表」里找到该行，核对\n//   · prompt ↔ 表：台词 / 字幕逐字（dialogue 镜）、时长 vs 表时长；\n//   · 参数 ↔ 表：声线参考 vs audio_ref_nodes、画幅比例 vs 项目 aspectRatio；\n//   · 档位 ↔ 参考图：fast 档不得用三视图卡（ref_variant=three / 直接传 three 卡）。\n// 不一致 → deny 并列出差异；同一 agent 连续 deny ≥ PLAN_GATE_MAX_DENIES 次后降级放行（防死循环）。\n// 不参与：转场镜（标题含「转场」/「→」）、锚点式重渲（标题含「锚点」）、试镜片段、\n// 无 Sxx 标题、画布没有可解析的镜头表（老项目平滑接入）。\nconst PLAN_GATE = true\nconst PLAN_GATE_MAX_DENIES = 2\nconst PLAN_GATE_SEC_TOLERANCE = 1.0\n// 3%：容忍 fast 档 832×480 / 480×832 与 16:9 / 9:16 的 snap 误差（2.5%），仍能拦住竖横混用。\nconst PLAN_GATE_RATIO_TOLERANCE = 0.03\nconst PLAN_GATE_FIELDS = ['模式', '对白', '口型', '声线参考', '音效', 'BGM', '画面文案', '字幕', '表演备注']\nconst planGateDenies = new Map() // agentId -> 连续 deny 次数\n\n/** `<br>` → 换行，去掉首尾空白（表格单元格里的富文本）。 */\nfunction normalizeCellText(value) {\n  return String(value == null ? '' : value).replace(/<br\\s*\\/?>/gi, '\\n').trim()\n}\n\n/** 台词 / 字幕比对用：去空白、去引号与标点、忽略大小写（只比文字本身）。 */\nfunction normForMatch(value) {\n  return String(value == null ? '' : value)\n    .replace(/<br\\s*\\/?>/gi, ' ')\n    .replace(/\\s+/g, '')\n    .replace(/[“”\"'‘’「」『』《》〈〉（）()【】\\[\\]，。！？、；：,.!?;:—–\\-…·]/g, '')\n    .toLowerCase()\n}\n\n/** 从表格「对白」子字段里抽出真正要说出口的台词（引号优先，其次去说话人前缀/时间备注）。 */\nfunction cleanPlanDialogue(raw) {\n  let s = String(raw == null ? '' : raw).replace(/<br\\s*\\/?>/gi, ' ').replace(/<\\/?d>/gi, '').trim()\n  const quotes = [...s.matchAll(/[“\"「『]([^”\"」』]{1,200})[”\"」』]/g)].map((m) => m[1]).filter(Boolean)\n  if (quotes.length) s = quotes.join(' ')\n  else s = s.replace(/^[^:：]{1,24}[:：]\\s*/, '')\n  return s.replace(/[（(][^）)]{0,60}[）)]/g, ' ').replace(/\\s+/g, ' ').trim()\n}\n\n/** 从「S01 / 5s」里取时长（秒）；也接受帧数写法（如 124f）。 */\nfunction parsePlanDuration(cell, fps = 24) {\n  const s = normalizeCellText(cell)\n  let m = s.match(/(\\d+(?:\\.\\d+)?)\\s*(?:s|秒|sec(?:onds?)?)(?![a-z])/i)\n  if (m) return Number(m[1])\n  m = s.match(/(\\d+)\\s*f(?:rames?)?(?![a-z])/i)\n  if (m) return Number(m[1]) / fps\n  return null\n}\n\n/** 表格行里的 `镜头描述` 首行 `剧本依据: B01, B03a` → beat 编号。 */\nfunction extractBeatIds(text) {\n  return [...String(text == null ? '' : text).matchAll(/(?:^|[^A-Za-z0-9])B(\\d{1,3})([a-z])?(?![0-9])/gi)]\n    .map((m) => 'B' + m[1].padStart(2, '0') + (m[2] ? m[2].toUpperCase() : ''))\n}\n\n/** 标题 / 表格里的镜头号：S01 / S01a。 */\nfunction shotIdFromText(text) {\n  const m = String(text == null ? '' : text).match(/(?:^|[^A-Za-z0-9])S(\\d{1,3})([A-Za-z])?(?![0-9])/i)\n  return m ? 'S' + m[1].padStart(2, '0') + (m[2] ? m[2].toUpperCase() : '') : ''\n}\n\n/** 拆 markdown 表格行（容忍首尾竖线）。 */\nfunction splitMarkdownRow(line) {\n  let s = String(line == null ? '' : line).trim()\n  if (s.startsWith('|')) s = s.slice(1)\n  if (s.endsWith('|')) s = s.slice(0, -1)\n  return s.split('|').map((c) => c.trim())\n}\n\n/** 解析「音频与对白轨」单元格里的 `键: 值` 子字段（按换行 / 分号切，支持多行值）。 */\nfunction parsePlanSubfields(cell) {\n  const text = normalizeCellText(cell)\n  const out = {}\n  const label = `(?:${PLAN_GATE_FIELDS.join('|')})`\n  const parts = text\n    .split(new RegExp(`\\\\n|(?=[;；]\\\\s*${label}\\\\s*[:：])`))\n    .map((s) => s.replace(/^[;；]\\s*/, '').trim())\n    .filter(Boolean)\n  let current = ''\n  for (const part of parts) {\n    const m = part.match(new RegExp(`^(${PLAN_GATE_FIELDS.join('|')})\\\\s*[:：]\\\\s*([\\\\s\\\\S]*)$`))\n    if (m) { current = m[1]; out[current] = m[2].replace(/[;；]\\s*$/, '').trim() }\n    else if (current) out[current] += '\\n' + part.replace(/[;；]\\s*$/, '')\n  }\n  return out\n}\n\n/**\n * 解析七列镜头表（markdown 表格或带表格的文本节点内容）：\n * 按表头定位列（镜头编号 / 镜头描述 / 音频与对白轨 / 可选剧本依据），逐行产出结构化镜头。\n * 解析不出表头 → null（门直接放行，老项目不受影响）。\n */\nfunction parseShotTableContent(content) {\n  const lines = String(content == null ? '' : content).replace(/\\r\\n?/g, '\\n').split('\\n')\n  const headerIdx = lines.findIndex((l) => l.includes('|') && /镜头编号/.test(l) && /音频与对白轨/.test(l))\n  if (headerIdx < 0) return null\n  const headers = splitMarkdownRow(lines[headerIdx])\n  const col = (kw) => headers.findIndex((h) => h.includes(kw))\n  const idx = { shot: col('镜头编号'), desc: col('镜头描述'), audio: col('音频与对白轨'), beats: col('剧本依据') }\n  if (idx.shot < 0 || idx.audio < 0) return null\n  const shots = []\n  for (let i = headerIdx + 1; i < lines.length; i++) {\n    const line = lines[i].trim()\n    if (!line.includes('|')) continue\n    const cells = splitMarkdownRow(line)\n    if (!cells.some((c) => c && !/^:?-{2,}:?$/.test(c))) continue\n    const shotId = shotIdFromText(cells[idx.shot])\n    if (!shotId) continue\n    const audio = parsePlanSubfields(cells[idx.audio])\n    const desc = idx.desc >= 0 ? normalizeCellText(cells[idx.desc]) : ''\n    let beats = idx.beats >= 0 ? extractBeatIds(cells[idx.beats]) : []\n    if (!beats.length) {\n      const m = desc.match(/剧本依据\\s*[:：]\\s*([^\\n]*)/)\n      if (m) beats = extractBeatIds(m[1])\n    }\n    const modeRaw = String(audio['模式'] || '')\n    const mode = /dialogue/i.test(modeRaw) ? 'dialogue'\n      : /silent/i.test(modeRaw) ? 'silent'\n        : (audio['对白'] ? 'dialogue' : '')\n    shots.push({\n      shotId,\n      durationSec: parsePlanDuration(cells[idx.shot]),\n      mode,\n      dialogue: cleanPlanDialogue(audio['对白'] || ''),\n      subtitle: String(audio['字幕'] || '').trim(),\n      voiceRef: String(audio['声线参考'] || '').trim(),\n      beats,\n    })\n  }\n  return shots.length ? { headers, shots } : null\n}\n\n/** 画布上最后一份可解析的镜头表（按 order；同名多份时取最新）。 */\nfunction findShotPlan(project) {\n  const candidates = []\n  for (const node of project?.nodes || []) {\n    if (node?.kind !== 'table' || typeof node.content !== 'string') continue\n    const parsed = parseShotTableContent(node.content)\n    if (parsed) candidates.push({ node, ...parsed })\n  }\n  if (!candidates.length) return null\n  candidates.sort((a, b) => (Number(a.node.order) || 0) - (Number(b.node.order) || 0))\n  return candidates[candidates.length - 1]\n}\n\n/** 画布宽高比（\"9:16\" / \"16:9\" / \"1:1\"）→ 数值；解析不出返回 null。 */\nfunction parseAspectRatio(text) {\n  const m = String(text == null ? '' : text).match(/(\\d+(?:\\.\\d+)?)\\s*[:：/x×]\\s*(\\d+(?:\\.\\d+)?)/)\n  if (!m) return null\n  const a = Number(m[1])\n  const b = Number(m[2])\n  return a > 0 && b > 0 ? a / b : null\n}\n\n/** 声线参考是否等于「没有」。 */\nfunction isNoneRef(value) {\n  return !String(value || '').trim() || /^(none|n\\/a|na|无|—|-)$/i.test(String(value).trim())\n}\n\n/**\n * 构造 tools/pre-execute 监听器：视频生成前做镜头表一致性校验。\n * 任何解析异常都放行（不阻塞生成），只有**能确证**的不一致才 deny。\n */\nfunction makePlanGateListener(ctx) {\n  return async function planGateListener(exec, next) {\n    try {\n      if (!PLAN_GATE || !exec?.arguments) return next()\n      const name = exec.name\n      const args = exec.arguments\n      const isGenerate = name === 'comfy_generate_video'\n        || (name === 'comfy_render' && typeof args.capability === 'string'\n          && args.capability.startsWith('video.')\n          && args.capability !== 'video.upscale'\n          && args.capability !== 'video.interpolate'\n          && args.capability !== 'video.regenerate')\n      if (!isGenerate) return next()\n      const sid = args.sessionId || exec?.agent?.id\n      if (!sid) return next()\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      if (!gateOn(project.settings, 'plan')) return next()\n      const plan = findShotPlan(project)\n      if (!plan) return next()\n      // 转场镜 / 锚点式重渲不是镜头表里的独立行，不参与按行比对\n      const title = String(args.title || '')\n      if (/转场|→|->|锚点/.test(title)) return next()\n      let shotId = shotIdFromText(title)\n      if (!shotId && args.prompt_node) {\n        const bank = project.nodes.find((n) => n.id === args.prompt_node)\n        shotId = shotIdFromText(bank?.title || '')\n      }\n      if (!shotId) return next()\n      const shot = plan.shots.find((s) => s.shotId === shotId)\n      const issues = []\n      if (!shot) {\n        issues.push(`镜头表「${plan.node.title || plan.node.id}」里没有 ${shotId}（新镜 / 拆镜必须先落表再渲）`)\n      } else {\n        // 画幅比例：显式传了 width+height 才校验（缺省由画布比例推导）\n        const ar = parseAspectRatio(project.settings?.aspectRatio)\n        const w = Number(args.width)\n        const h = Number(args.height)\n        if (ar && Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0\n          && Math.abs((w / h) / ar - 1) > PLAN_GATE_RATIO_TOLERANCE) {\n          issues.push(`画幅比例不一致：请求 ${w}×${h}（${(w / h).toFixed(3)}）≠ 项目 ${project.settings?.aspectRatio}（${ar.toFixed(3)}）；去掉 width/height 让工具按项目比例推导`)\n        }\n        // 档位 ↔ 参考图：fast 档只能用单视图\n        const tier = tierFromArgs(args) || (TIERS.includes(String(project.settings?.mode)) ? String(project.settings.mode) : DEFAULT_TIER)\n        if (tier === 'fast') {\n          const rv = typeof args.ref_variant === 'string' ? args.ref_variant.trim() : ''\n          if (rv === 'three') issues.push('fast 档只能用单视图角色卡：ref_variant 不能传 three（改 single）')\n          if (rv !== 'single') {\n            const threeCards = (Array.isArray(args.ref_nodes) ? args.ref_nodes : [])\n              .map((id) => project.nodes.find((n) => n.id === id))\n              .filter((n) => n?.params?.cardVariant === 'three')\n            if (threeCards.length) {\n              issues.push(`fast 档不能引用三视图卡：${threeCards.map((n) => `「${n.title || n.id}」`).join('、')}（改传同角色 single 卡 / ref_variant=single）`)\n            }\n          }\n        }\n        // 声线参考 ↔ audio_ref_nodes\n        const audioRefs = (Array.isArray(args.audio_ref_nodes) ? args.audio_ref_nodes : [])\n          .filter((x) => typeof x === 'string' && x.trim())\n        const voiceRef = String(shot.voiceRef || '').trim()\n        if (shot.mode === 'dialogue' && !isNoneRef(voiceRef) && audioRefs.length === 0) {\n          issues.push(`对白镜 ${shotId} 缺声线参考：镜头表写的是 ${voiceRef}，本次没有传 audio_ref_nodes（声线方案 audition/existing 必须传；text-only 请把表里改成 none）`)\n        }\n        // 时长 ↔ length（24fps）\n        const wantLen = Number(args.length)\n        if (shot.durationSec && Number.isFinite(wantLen) && wantLen > 0) {\n          const reqSec = wantLen / 24\n          if (Math.abs(reqSec - shot.durationSec) > PLAN_GATE_SEC_TOLERANCE) {\n            issues.push(`时长与镜头表 ${shotId} 不一致：请求 ${reqSec.toFixed(1)}s（${wantLen} 帧 @24fps）≠ 表 ${shot.durationSec}s（先改表再渲，或按表改 length）`)\n          }\n        }\n        // prompt ↔ 表：台词 / 字幕逐字（prompt_node / 重渲节点上的 prompt_node 都可读）\n        let prompt = String(args.prompt || '')\n        if (!prompt.trim() && args.prompt_node) prompt = await readPromptBankPromptForGate(ctx, exec, args)\n        if (!prompt.trim() && args.nodeId) {\n          const prev = project.nodes.find((n) => n.id === args.nodeId)\n          const bankId = prev?.params?.prompt_node\n          if (bankId) prompt = await readPromptBankPromptForGate(ctx, exec, { ...args, prompt_node: bankId })\n        }\n        if (prompt.trim()) {\n          const pn = normForMatch(prompt)\n          if (shot.mode === 'dialogue' && shot.dialogue) {\n            const dn = normForMatch(shot.dialogue)\n            if (dn.length >= 2 && !pn.includes(dn)) {\n              issues.push(`台词与镜头表 ${shotId} 不一致：prompt 里找不到「${shot.dialogue}」（台词必须逐字）`)\n            }\n          }\n          const sub = String(shot.subtitle || '').trim()\n          if (!isNoneRef(sub) && normForMatch(sub) !== normForMatch(shot.dialogue)) {\n            const sn = normForMatch(sub)\n            if (sn.length >= 2 && !pn.includes(sn)) {\n              issues.push(`字幕与镜头表 ${shotId} 不一致：prompt 里找不到「${sub}」（字幕必须逐字）`)\n            }\n          }\n          if (audioRefs.length && !/<Audio\\s*\\d/i.test(prompt)) {\n            console.warn(`[dsh-short-video-studio] plan gate: ${shotId} 传了 audio_ref_nodes 但 prompt 未声明 <Audio N>（参考可能只被当环境音）`)\n          }\n        }\n      }\n      if (!issues.length) {\n        planGateDenies.delete(exec.agent?.id || 'unknown')\n        return next()\n      }\n      // 防死循环：连续 deny 超上限 → 降级放行（与 H3 门同策略）\n      const key = exec.agent?.id || 'unknown'\n      const denies = (planGateDenies.get(key) || 0) + 1\n      planGateDenies.set(key, denies)\n      if (denies > PLAN_GATE_MAX_DENIES) return next()\n      return {\n        kind: 'deny',\n        reason: `镜头表一致性门未通过：${issues.join('；')}。先按镜头表改 prompt / 参数（新镜或拆镜先改表）再重渲。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// 逐镜自检（门 3）结构化结论：六项内容 + audio 的人工听核占位。\n// pass|fail 由 AI 判定；na = 本镜不适用 / 只能人工核（audio 恒为 na 或人工结论）。\nconst RECORD_CHECK_KEYS = ['plan', 'character', 'lipsync', 'subtitle', 'contamination', 'audio', 'style']\nconst RECORD_CHECK_VALUES = ['pass', 'fail', 'na']\n\n// ---------------------------------------------------------------------------\n// 逐镜自检门（shot gate，tools/pre-execute）\n// ---------------------------------------------------------------------------\n// 机制：宿主每个工具执行前都过 `tools/pre-execute` waterfall。本监听器把\n// 「一镜自检通过后才能开下一镜」从流程纪律变成代码门：\n// - 视频生成（comfy_generate_video / comfy_render 的 video.*）前，检查画布上\n//   已打标的镜头（params.shot=true，由 runRender 的视频产物自动打标）：\n//   · verdict 档（默认）：镜头必须 selfCheck.status === 'pass'；任何 pending / fail\n//     的镜头都会挡住新镜（防「渲完就忘」）；continuity_from 指向的镜头必须在 pass。\n//   · frames 档：镜头至少要抽过一帧（params.checkFrames 非空）——只强制看片，不强制结论。\n//   · off：完全关闭。\n// - 显式重渲同一节点（nodeId = 被挡的那一镜）放行——修片本来就该重渲。\n// - 老镜头（打标前生成的）没有 params.shot，不参与门控，便于旧项目平滑接入。\n// - 防死循环：同一 agent 连续 deny ≥ SHOT_GATE_MAX_DENIES 次后降级放行。\n// 开关：项目设置 shotGate = off | frames | verdict（canvas_set_state）。\nconst SHOT_GATE = true\nconst SHOT_GATE_MAX_DENIES = 2\nconst shotGateDenies = new Map() // agentId -> 连续 deny 次数\n\n/** 项目设置 → 门控档（缺省 verdict；非法值按 verdict）。 */\nfunction shotGateLevel(settings) {\n  const v = settings?.shotGate\n  return v === 'off' || v === 'frames' ? v : 'verdict'\n}\n\n/** 镜头节点：视频产物（runRender 打 shot=true）；拼接 / 超分节点不算。 */\nfunction isShotNode(n) {\n  return n?.kind === 'video' && n?.params?.shot === true\n}\n\nfunction selfCheckStatus(n) {\n  return String(n?.params?.selfCheck?.status || '')\n}\n\nfunction shotFrames(n) {\n  const f = n?.params?.checkFrames\n  return Array.isArray(f) ? f : []\n}\n\n/** 镜头是否已过门：verdict 档看结论，frames 档只看有没有抽帧。 */\nfunction shotGateSatisfied(n, level) {\n  return level === 'frames' ? shotFrames(n).length > 0 : selfCheckStatus(n) === 'pass'\n}\n\nfunction shotLabel(n) {\n  return `「${n?.title || n?.id || '?'}」(${n?.id || '?'})`\n}\n\n/** deny reason 里的可执行下一步。 */\nfunction shotGateFixHint(level) {\n  return level === 'frames'\n    ? '先用 extract_frame 抽 1–3 帧看图核对，再继续'\n    : '先 extract_frame 抽首/中/末帧 → 看图核对 → canvas_record_check(nodeId=…, verdict=\"pass\", notes=…)'\n}\n\n/**\n * 构造 tools/pre-execute 监听器：视频生成 / 拼接前检查镜头自检状态，\n * 未过门则 deny 并给出下一步（防死循环上限后降级放行）。任何异常都放行。\n */\nfunction makeShotGateListener(ctx) {\n  return async function shotGateListener(exec, next) {\n    try {\n      if (!SHOT_GATE || !exec?.arguments) return next()\n      const name = exec.name\n      const args = exec.arguments\n      // 只拦视频**生成**；video_concat / video_upscale / video_regenerate 是后处理，不要求先过自检。\n      const isGenerate = name === 'comfy_generate_video'\n        || (name === 'comfy_render' && typeof args.capability === 'string' && args.capability.startsWith('video.') && args.capability !== 'video.upscale' && args.capability !== 'video.regenerate')\n      if (!isGenerate) return next()\n      const sid = args.sessionId || exec?.agent?.id\n      if (!sid) return next()\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      if (!gateOn(project.settings, 'shot')) return next()\n      const level = shotGateLevel(project.settings)\n      if (level === 'off') return next()\n      const shots = project.nodes.filter(isShotNode).sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0))\n      const blocking = []\n      const add = (n, why) => {\n        if (n && !blocking.some((b) => b.node.id === n.id)) blocking.push({ node: n, why })\n      }\n      // 1) 续接来源必须已过门（不能从没看过的镜头接着往下走）\n      const fromId = typeof args.continuity_from === 'string' ? args.continuity_from.trim() : ''\n      if (fromId) {\n        const prev = project.nodes.find((n) => n.id === fromId)\n        if (prev && isShotNode(prev) && !shotGateSatisfied(prev, level)) add(prev, '是本镜的续接来源')\n      }\n      // 2) 显式重渲某镜：放过它本人（修片就是重渲）\n      const targetId = typeof args.nodeId === 'string' ? args.nodeId.trim() : ''\n      const latest = shots[shots.length - 1]\n      for (const s of shots) {\n        if (s.id === targetId) continue\n        if (!shotGateSatisfied(s, level)) add(s, s === latest ? '是最近一镜' : '自检未通过')\n      }\n      if (!blocking.length) {\n        shotGateDenies.delete(exec.agent?.id || 'unknown')\n        return next()\n      }\n      // 防死循环：连续 deny 超上限 → 降级放行\n      const key = exec.agent?.id || 'unknown'\n      const denies = (shotGateDenies.get(key) || 0) + 1\n      shotGateDenies.set(key, denies)\n      if (denies > SHOT_GATE_MAX_DENIES) return next()\n      const detail = blocking.slice(0, 5).map(({ node, why }) =>\n        `${shotLabel(node)} ${why}（selfCheck=${selfCheckStatus(node) || 'none'}，抽帧=${shotFrames(node).length}）`).join('；')\n      const action = `${shotGateFixHint(level)}；通过后才能生成下一镜。只改这一镜请复用它自己的 nodeId 重渲（重渲会把自检重置为 pending）。`\n      return {\n        kind: 'deny',\n        reason: `逐镜自检门未通过：${detail}。${action}要整体关闭/降档：canvas_set_state(shotGate='off'|'frames'|'verdict')。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 配置门（config gate，tools/pre-execute）\n//\n// 把「STEP 0 配置卡是唯一真相源」从纪律变成代码门（P0 契约检查）：\n// - R12 未建配置卡（configured=false）→ 生成/后处理 deny 一次，提示先建卡；\n// - R1 显式 width/height 与画布 aspectRatio 不一致 → deny；\n// - R2 fast 档 + 三视图参考 → deny；\n// - R3 配置=single 却显式要 three → deny（three→single 回退放行）。\n// 契约门（几何/形态）不受 flow 影响；流程门按 flow 选择（§10，P1 接入）。\n// 逃生阀：DSH_SVS_CONFIG_GATE=off（测试/脚本）。门自身异常一律放行。\nconst CONFIG_GATE = true\nconst CONFIG_GATE_MAX_DENIES = 3\nconst configGateDenies = new Map()\nconst CONFIG_GEN_CAPABILITIES = ['image.text2image', 'image.image2image', 'video.reference2video', 'video.image2video', 'video.text2video']\nconst CONFIG_POST_CAPABILITIES = ['video.upscale', 'video.regenerate', 'video.interpolate']\nconst CONFIG_POST_TOOLS = new Set(['video_upscale', 'video_regenerate', 'video_interpolate', 'video_concat'])\n\n/** 配置门覆盖的操作：image / video / post；其余返回 null。 */\nfunction configGateOp(name, args) {\n  if (name === 'comfy_generate_image') return 'image'\n  if (name === 'comfy_generate_video') return 'video'\n  if (name === 'comfy_generate_music') return 'post'\n  if (name === 'comfy_render' && typeof args?.capability === 'string') {\n    if (args.capability.startsWith('image.') && args.capability !== 'image.from_video' && args.capability !== 'image.crop') return 'image'\n    if (CONFIG_GEN_CAPABILITIES.includes(args.capability)) return 'video'\n    if (CONFIG_POST_CAPABILITIES.includes(args.capability)) return 'post'\n    if (args.capability === 'audio.music') return 'post'\n  }\n  if (CONFIG_POST_TOOLS.has(name)) return 'post'\n  return null\n}\n\n/** 本次调用引用了三视图卡（显式 ref_variant=three 或 ref_nodes 指向三视图节点）。 */\nfunction threeViewRefIds(project, args) {\n  const ids = []\n  if (args.ref_variant === 'three') ids.push('__variant__')\n  for (const rid of Array.isArray(args.ref_nodes) ? args.ref_nodes : []) {\n    if (typeof rid !== 'string' || /^(character|scene|style|clip|voice|text):/.test(rid)) continue\n    const node = (project.nodes || []).find((n) => n.id === rid)\n    if (node?.params?.cardVariant === 'three') ids.push(rid)\n  }\n  return ids\n}\n\n/** 纯检查：返回配置冲突列表（空 = 通过）。pre-execute 门与 HTTP 生成入口共用同一份规则。 */\nfunction configIssuesFor(project, op, args = {}) {\n  const settings = project?.settings || {}\n  const issues = []\n  // R12：未建卡（Q3：首次生成前强制建配置卡）\n  if (settings.configured !== true) {\n    issues.push('本项目还没有配置卡：先调用 canvas_set_state(flow=\\'story\\'|\\'series\\'|\\'brand\\'|\\'ecommerce\\'|\\'free\\', aspectRatio=…, mode=…, …) 建卡（画布「⚙ 配置」也可建），再生成')\n    return issues\n  }\n  // R1：显式宽高必须与画布比例一致\n  const w = Number(args.width)\n  const h = Number(args.height)\n  if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {\n    const want = parseAspectRatio(settings.aspectRatio)\n    if (want && Math.abs((w / h) - want) / want > 0.01) {\n      issues.push(`画幅比例不一致：请求 ${w}×${h}（${(w / h).toFixed(3)}）≠ 画布 ${settings.aspectRatio}（${want.toFixed(3)}）；去掉 width/height 让工具按配置推导`)\n    }\n  }\n  // R2/R3：角色卡版本（只对视频生成）\n  const breakingRev = Number(settings.breakingRev) || 0\n  const staleOf = (node) => {\n    const rev = Number(node?.params?.configRev)\n    return Number.isFinite(rev) && rev < breakingRev ? rev : null\n  }\n  if (op === 'video') {\n    const tier = typeof args.tier === 'string' && TIERS.includes(args.tier) ? args.tier : (settings.mode || 'quality')\n    const threeRefs = threeViewRefIds(project, args)\n    if (tier === 'fast' && threeRefs.length) {\n      issues.push('fast 档只能引用单视图角色卡：请把 ref_variant 设为 single（或换同角色单视图卡）')\n    } else if (tier !== 'fast' && settings.characterCardVariant === 'single' && threeRefs.length) {\n      issues.push('STEP 0 配置的是单视图角色卡，但本次引用了三视图卡 / ref_variant=three；要改用三视图请先在配置卡把 characterCardVariant 改为 three（three→single 回退允许）')\n    }\n    // R6：镜头表过期（配置改过破坏性字段后必须先重建镜头表）\n    const plan = findShotPlan(project)\n    const planRev = staleOf(plan?.node)\n    if (planRev !== null) {\n      issues.push(`镜头表「${plan.node.title || plan.node.id}」是 rev ${planRev} 写的，当前配置 breakingRev=${breakingRev}；请先按新配置重建镜头表再渲`)\n    }\n    // R9：参考卡过期（画幅 / 风格 / 角色卡版本等破坏性变更后需重出卡片）\n    for (const rid of Array.isArray(args.ref_nodes) ? args.ref_nodes : []) {\n      if (typeof rid !== 'string' || /^(character|scene|style|clip|voice|text):/.test(rid)) continue\n      const node = project.nodes.find((n) => n.id === rid)\n      const rev = staleOf(node)\n      if (rev !== null) issues.push(`参考卡「${node.title || rid}」是 rev ${rev} 生成的，当前配置 breakingRev=${breakingRev}；请先按新配置重出该卡`)\n    }\n  }\n  // R8：拼接旧片段（配置变更后旧片段需重渲，或先接受混版）\n  if (op === 'post' && Array.isArray(args.nodes)) {\n    for (const nid of args.nodes) {\n      const node = project.nodes.find((n) => n.id === nid)\n      const rev = staleOf(node)\n      if (rev !== null) issues.push(`片段「${node.title || nid}」是 rev ${rev} 生成的，当前配置 breakingRev=${breakingRev}；请先重渲或明确接受混版`)\n    }\n  }\n  return issues\n}\n\n/**\n * 构造 tools/pre-execute 监听器：生成 / 后处理前读画布配置做契约检查。\n * 连续 deny 超上限后降级放行（防死循环；逃生阀见 DSH_SVS_CONFIG_GATE）。\n */\nfunction makeConfigGateListener(ctx) {\n  return async function configGateListener(exec, next) {\n    try {\n      if (!CONFIG_GATE || !exec?.arguments) return next()\n      if (String(process.env.DSH_SVS_CONFIG_GATE || '').toLowerCase() === 'off') return next()\n      const args = exec.arguments\n      const op = configGateOp(exec.name, args)\n      if (!op) return next()\n      const sid = args.sessionId || exec?.agent?.id\n      if (!sid) return next()\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      const issues = configIssuesFor(project, op, args)\n\n      if (!issues.length) {\n        configGateDenies.delete(exec.agent?.id || 'unknown')\n        return next()\n      }\n      // 防死循环：同一 agent 连续 deny 超上限 → 降级放行\n      const key = exec.agent?.id || 'unknown'\n      const denies = (configGateDenies.get(key) || 0) + 1\n      configGateDenies.set(key, denies)\n      if (denies > CONFIG_GATE_MAX_DENIES) return next()\n      return {\n        kind: 'deny',\n        reason: `配置门未通过：${issues.join('；')}。修复：画布「⚙ 配置」或 canvas_set_state；整体关闭：DSH_SVS_CONFIG_GATE=off。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 创作批准账本（approval ledger）+ 批准门（approval gate，tools/pre-execute）\n//\n// 为什么要有：config / plan / shot / production 四道门都在**参数/产物层**，\n// 「角色卡锁定、场景卡锁定、镜头表批准、分镜批准、门 3 人工确认」这些\n// **创作批准**在代码里没有任何凭据——agent 不出选项卡直接推进也合法\n// （实测会话 ff621764：6 张角色卡前后 0 次 ask，audit 仍 7/7）。\n//\n// 本门把「用户已批准某阶段产物」落成 project.approvals，并在推进下一步前校验：\n//   assets    角色卡/场景卡/道具卡锁定（每张卡）\n//   shotTable 七列镜头表批准（必须已打 shot-table self-check: passed 戳）\n//   storyboard 分镜批准\n//   clips     门 3 片段批准（per-shot 逐镜 / batch 批量）\n// 批准按 settings.breakingRev 失效；重出卡 / 改表 / 改分镜 / 重渲片段会失效对应项；\n// 破坏性配置变更清空全部批准。本门**没有**连续 deny 降级（批准只需一次显式调用，\n// 不满足就是流程没走到），逃生阀 DSH_SVS_APPROVAL_GATE=off。\n// ---------------------------------------------------------------------------\nconst APPROVAL_GATE = true\nconst APPROVAL_TARGETS = ['assets', 'shotTable', 'storyboard', 'clips']\n\nfunction textHash(text) {\n  return createHash('sha1').update(String(text || '')).digest('hex').slice(0, 16)\n}\n\n/** 图片节点的资产类别：character / scene / prop / ''（分镜图、检查帧等不是资产卡）。 */\nfunction assetKindOf(node) {\n  if (!node || node.kind !== 'image') return ''\n  const p = node.params || {}\n  if (p.assetKind) return String(p.assetKind)\n  if (p.character || p.cardVariant) return 'character'\n  const s = `${node.title || ''} ${node.group || ''}`\n  if (/角色卡|角色设计|character\\s*(card|design)/i.test(s)) return 'character'\n  if (/场景卡|场景设计|scene\\s*(card|design)|environment/i.test(s)) return 'scene'\n  if (/道具卡|prop\\s*card/i.test(s)) return 'prop'\n  return ''\n}\n\nfunction isAssetCard(node) {\n  return ['character', 'scene', 'prop'].includes(assetKindOf(node))\n}\n\nfunction assetCardsOf(project) {\n  return (project?.nodes || []).filter(isAssetCard)\n}\n\n/** 分镜文本节点（标题/分组含「分镜」；提示词库不算）。 */\nfunction storyboardNodeOf(project) {\n  const nodes = (project?.nodes || []).filter((n) =>\n    n?.kind === 'text' && /分镜/.test(`${n.title || ''} ${n.group || ''}`) && !/提示词/.test(String(n.title || '')))\n  nodes.sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0))\n  return nodes[nodes.length - 1] || null\n}\n\nfunction approvalEntry(project, target) {\n  return project?.approvals?.[target] || null\n}\n\nfunction approvalConfigRev(project) {\n  return Number(project?.settings?.breakingRev) || 0\n}\n\n/** 该 target 的批准是否仍然有效（配置版本 + 内容哈希 + 卡片集合）。 */\nfunction approvalIsCurrent(project, target) {\n  const ap = approvalEntry(project, target)\n  if (!ap) return false\n  if (Number(ap.configRev) !== approvalConfigRev(project)) return false\n  if (target === 'shotTable') {\n    const node = findShotPlan(project)?.node\n    return !!node && ap.nodeId === node.id && ap.hash === textHash(node.content)\n  }\n  if (target === 'storyboard') {\n    const node = (project.nodes || []).find((n) => n.id === ap.nodeId)\n    return !!node && ap.hash === textHash(node.content)\n  }\n  if (target === 'assets') {\n    const ids = new Set(Array.isArray(ap.nodeIds) ? ap.nodeIds : [])\n    const cards = assetCardsOf(project)\n    return cards.length > 0 && cards.every((c) => ids.has(c.id))\n  }\n  if (target === 'clips') return true\n  return false\n}\n\n/** 已批准资产卡的 id 集合（只按 configRev 与单卡成员判断，不要求全集）。 */\nfunction approvedAssetIds(project) {\n  const ap = approvalEntry(project, 'assets')\n  if (!ap || Number(ap.configRev) !== approvalConfigRev(project)) return new Set()\n  return new Set(Array.isArray(ap.nodeIds) ? ap.nodeIds : [])\n}\n\nfunction unapprovedCards(project) {\n  const approved = approvedAssetIds(project)\n  return assetCardsOf(project).filter((c) => !approved.has(c.id))\n}\n\nfunction cardsLabel(cards) {\n  const list = cards || []\n  const head = list.slice(0, 4).map((c) => `「${c.title || c.id}」`).join('、')\n  return head + (list.length > 4 ? ` 等 ${list.length} 张` : '')\n}\n\n/** 同一张卡重出（允许，不算推进下一步）；title 忽略空格与尾部 v2/v3。 */\nfunction sameCardTitle(a, b) {\n  const norm = (s) => String(s || '').replace(/\\s+/g, '').replace(/v\\d+$/i, '')\n  return !!a && !!b && norm(a) === norm(b)\n}\n\n/** 图片生成阶段的批准检查（只拦「出新卡」，重出同一张卡放行）。 */\nfunction imageApprovalIssues(project, args) {\n  const issues = []\n  const title = String(args.title || '')\n  const character = typeof args.character === 'string' ? args.character.trim() : ''\n  const group = String(args.group || '')\n  const targetId = typeof args.nodeId === 'string' ? args.nodeId.trim() : ''\n  const targetNode = targetId ? (project.nodes || []).find((n) => n.id === targetId) : null\n  const isCharacter = !!character || /角色卡|角色设计|character\\s*card/i.test(title)\n  const isScene = !isCharacter && /场景卡|场景设计|scene\\s*card|environment/i.test(`${title} ${group}`)\n  const isProp = !isCharacter && !isScene && /道具卡|prop\\s*card/i.test(`${title} ${group}`)\n  if (!isCharacter && !isScene && !isProp) return issues\n  const cards = assetCardsOf(project)\n  const sameIdentity = (targetNode && isAssetCard(targetNode))\n    || (isCharacter && character && cards.some((n) => assetKindOf(n) === 'character' && n.params?.character === character))\n    || ((isScene || isProp) && cards.some((n) => sameCardTitle(n.title, title)))\n  if (sameIdentity) return issues\n  const pending = unapprovedCards(project)\n  if (!pending.length) return issues\n  if (isCharacter) {\n    const others = pending.filter((n) => assetKindOf(n) === 'character' && (n.params?.character || '') !== character)\n    if (others.length) {\n      issues.push(`角色卡还没人工锁定：${cardsLabel(others)}。先出锁定选项卡，用户确认后 canvas_approve(target='assets', nodeIds=[...])，再生成下一个角色。`)\n    }\n  } else {\n    const chars = pending.filter((n) => assetKindOf(n) === 'character')\n    if (chars.length) {\n      issues.push(`角色卡还没人工锁定：${cardsLabel(chars)}。场景卡/道具卡必须在角色卡锁定之后才生成（先 canvas_approve(target='assets')）。`)\n    } else {\n      const sameKind = pending.filter((n) => assetKindOf(n) === (isScene ? 'scene' : 'prop'))\n      if (sameKind.length) {\n        issues.push(`上一张${isScene ? '场景' : '道具'}卡还没人工锁定：${cardsLabel(sameKind)}。先 canvas_approve(target='assets')，再生成下一张。`)\n      }\n    }\n  }\n  return issues\n}\n\n/** 写七列镜头表前的批准检查。 */\nfunction tableApprovalIssues(project) {\n  const pending = unapprovedCards(project)\n  if (!pending.length) return []\n  return [`资产卡还没人工锁定：${cardsLabel(pending)}。先逐张/汇总出锁定选项卡，用户确认后 canvas_approve(target='assets')，再写镜头表。`]\n}\n\n/** Sxx 视频生成前的批准检查（试镜/无镜头号片段不参与）。 */\nfunction videoApprovalIssues(project, args) {\n  let shotId = shotIdFromText(String(args.title || ''))\n  if (!shotId && args.prompt_node) {\n    const bank = (project.nodes || []).find((n) => n.id === args.prompt_node)\n    shotId = shotIdFromText(bank?.title || '')\n  }\n  if (!shotId) return []\n  const issues = []\n  const cards = assetCardsOf(project)\n  if (cards.length && !approvalIsCurrent(project, 'assets')) {\n    issues.push(`资产卡未全部人工锁定（${cards.length} 张，未锁：${cardsLabel(unapprovedCards(project)) || '—'}）→ canvas_approve(target='assets')`)\n  }\n  const plan = findShotPlan(project)\n  if (plan?.node && !approvalIsCurrent(project, 'shotTable')) {\n    issues.push(`镜头表未人工批准（先跑 STEP 5.5 并在表格顶部写 shot-table self-check: passed，再 canvas_approve(target='shotTable', nodeId='${plan.node.id}')）`)\n  }\n  const sb = storyboardNodeOf(project)\n  if (sb && !approvalIsCurrent(project, 'storyboard')) {\n    issues.push(`分镜未人工批准（canvas_approve(target='storyboard', nodeId='${sb.id}')）`)\n  }\n  return issues\n}\n\n/** 拼接前的片段批准检查。 */\nfunction concatApprovalIssues(project, args) {\n  const ids = (Array.isArray(args.nodes) ? args.nodes : []).filter((x) => typeof x === 'string' && x.trim())\n  const shotIds = ids.filter((id) => {\n    const n = (project.nodes || []).find((x) => x.id === id)\n    return n && (isShotNode(n) || (n.kind === 'video' && shotIdFromText(n.title)))\n  })\n  if (!shotIds.length) return []\n  const ap = approvalEntry(project, 'clips')\n  const approved = new Set(Number(ap?.configRev) === approvalConfigRev(project) ? (ap?.nodeIds || []) : [])\n  const missing = shotIds.filter((id) => !approved.has(id))\n  if (!missing.length) return []\n  return [`这些镜头还没有人工片段批准：${missing.join('、')}。按 reviewMode 逐镜/批量确认后 canvas_approve(target='clips', nodeIds=[...])。`]\n}\n\n/** 重渲/换媒体的片段：把它从 clips 批准里移除（内容变了，旧批准作废）。 */\nfunction invalidateClipApproval(project, nodeId) {\n  if (!project?.approvals?.clips) return\n  const ap = project.approvals.clips\n  ap.nodeIds = (Array.isArray(ap.nodeIds) ? ap.nodeIds : []).filter((id) => id !== nodeId)\n  if (!ap.nodeIds.length) delete project.approvals.clips\n}\n\n/** 批准状态摘要（canvas_get_state 用）。 */\nfunction approvalSummary(project) {\n  const out = {}\n  for (const target of APPROVAL_TARGETS) {\n    const ap = approvalEntry(project, target)\n    out[target] = {\n      approved: approvalIsCurrent(project, target),\n      at: ap?.at || null,\n      count: target === 'assets' ? (ap?.nodeIds || []).length : target === 'clips' ? (ap?.nodeIds || []).length : undefined,\n    }\n  }\n  return out\n}\n\n/**\n * 构造 tools/pre-execute 监听器：卡 → 表 → 视频 → 拼接 四道创作批准门。\n * 任何异常都放行（不阻塞生成）；但**不做连续 deny 降级**——批准是显式一次调用。\n */\nfunction makeApprovalGateListener(ctx) {\n  return async function approvalGateListener(exec, next) {\n    try {\n      if (!APPROVAL_GATE || !exec?.arguments) return next()\n      if (String(process.env.DSH_SVS_APPROVAL_GATE || '').toLowerCase() === 'off') return next()\n      const name = exec.name\n      const args = exec.arguments\n      const sid = args.sessionId || exec?.agent?.id\n      if (!sid) return next()\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      if (!gateOn(project.settings, 'approval')) return next()\n      let issues = []\n      const capability = String(args.capability || '')\n      const isImageGen = name === 'comfy_generate_image'\n        || (name === 'comfy_render' && (capability === 'image.text2image' || capability === 'image.image2image'))\n      const isVideoGen = name === 'comfy_generate_video'\n        || (name === 'comfy_render' && capability.startsWith('video.')\n          && capability !== 'video.upscale' && capability !== 'video.interpolate' && capability !== 'video.regenerate')\n      if (isImageGen) {\n        issues = imageApprovalIssues(project, args)\n      } else if (name === 'canvas_write_node' && args.kind === 'table'\n        && typeof args.content === 'string' && parseShotTableContent(args.content)) {\n        issues = tableApprovalIssues(project)\n      } else if (isVideoGen) {\n        issues = videoApprovalIssues(project, args)\n      } else if (name === 'video_concat') {\n        issues = concatApprovalIssues(project, args)\n      }\n      if (!issues.length) return next()\n      return {\n        kind: 'deny',\n        reason: `创作批准门未通过：${issues.join('；')}。批准账本：canvas_approve(target=assets|shotTable|storyboard|clips)；整体关闭：DSH_SVS_APPROVAL_GATE=off。`,\n      }\n    } catch {\n      return next()\n    }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// Agent 工具（原生 ToolDefinition，parameters 用 JSON Schema）\n// ---------------------------------------------------------------------------\n\nfunction makeTools() {\n  const imageTool = {\n    name: 'comfy_generate_image',\n    description:\n      '生成图片（默认档 quality）。**模型/实现由配置决定**（设置页的档位选择 / cfg.preferred），调用方只表达能力（文生图）与档位。产物写入会话画布并返回节点 id 与媒体相对路径（在「画布」tab 可见）。用于角色卡、场景卡、铅笔分镜等图片资产。角色卡出两版的正确做法：先 `card_variant=three` 出三视图横排，再用 **image_crop(panel=0, panels=3, card_variant=single, paired_node_id=<三视图节点>)** 裁正面格当单视图（同源像素、身份按构造一致），别分两次文生图。触发词：生成图片/角色卡/场景卡/分镜图。',\n    parameters: {\n      type: 'object',\n      properties: {\n        prompt: { type: 'string', description: '图片提示词（含风格、角色/场景描述、负向约束）。' },\n        tier: { type: 'string', enum: TIERS, description: '档位（见 comfy_list_workflows；缺省 quality）。抽卡迭代建议用 fast/balanced，定稿用 quality。' },\n        width: { type: 'integer', description: '宽（可选；缺省按画布 aspectRatio × 档位长边推导）。' },\n        height: { type: 'integer', description: '高（可选；只传一边时另一边按画布比例推导）。' },\n        seed: { type: 'integer', description: '随机种子（可选，缺省随机）。' },\n        steps: { type: 'integer', description: '采样步数（缺省取该档声明的步数）。' },\n        guidance: { type: 'number', description: '引导强度（仅对声明了 guidance 注入点的实现生效，如 FLUX；Qwen 走 cfg=1 官方路径，传了会收到 warning）。' },\n        count: { type: 'integer', description: '生成张数（1–4，默认 1）。' },\n        character: { type: 'string', description: '角色名（角色卡双版本：同一角色的单视图 / 三视图卡共用）。' },\n        card_variant: { type: 'string', enum: ['single', 'three'], description: '角色卡形态标记：single=单视图正面全身 / three=三视图横排。' },\n        paired_node_id: { type: 'string', description: '配对节点 id（角色卡另一版）；两节点会互记 pairedNodeId。' },\n        title: { type: 'string', description: '画布节点标题，如「主角卡·单视图」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['prompt'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok\n        ? `已生成图片节点 ${value.nodeId}\\n${mediaResultDetail(value)}`\n        : `生成失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runRender(ctx, { ...args, capability: 'image.text2image', exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const videoTool = {\n    name: 'comfy_generate_video',\n    description:\n      '用 ComfyUI 的 MiniMax H3 音视频模型生成单镜头视频（带声音）。两种路径：传 first_frame_node/last_frame_node（画布图片节点）→ 用 ImageToVideo 做首/末帧串联（同场景续接，身份/环境由首帧继承，改善过渡）；不传 → 用 ReferenceToVideo 并支持 ref_nodes（角色/场景卡）作参考绑定。**档位用 tier**（fast 调试 / balanced 日常 / quality 成片），由注册表解析到具体实现——不会静默跨档替换，所选实现不可用会显式报错。提示词可按 fast / balanced / quality 分档持久化到画布（传 prompt_node 按 tier 读取，生成后自动回写）；角色卡版本由 STEP 0 的用户选择驱动（ref_variant=single / three；fast 只能 single），工具不再按 tier 自动选版。产物写入画布并返回节点 id + 媒体相对路径。用于单镜头视频。触发词：生成视频/单镜头/片段。',\n    parameters: {\n      type: 'object',\n      properties: {\n        prompt: { type: 'string', description: '视频提示词（含每秒动作、镜头运动、说话人绑定等）。传了 prompt_node 时可省略（工具按 tier 从提示词库读对应段落）。' },\n        prompt_node: { type: 'string', description: '分档提示词库的画布文本节点 id（canvas_write_prompt_bank 产物）。按 tier 读取对应段落；缺该档自动回退到最近档并在 warnings 说明；生成后会把本次 prompt 回写本档段落。' },\n        persist_prompt: { type: 'boolean', description: '是否把本次提示词持久化到画布提示词库（默认 true）。' },\n        prompt_group: { type: 'string', description: '自动创建的提示词库节点分组（缺省沿用视频节点 group）。' },\n        type: { type: 'string', enum: Object.keys(VIDEO_SHAPES), description: '**必填**：单镜头视频的形状（条件路径）。r2v=参考绑定（传 ref_nodes=角色卡/场景卡；不许传 first/last_frame）；i2v=首末帧串联（传 first_frame_node，可选 last_frame_node；不许传 ref_nodes）。形状与\"续接\"正交：同场景续接 = type=r2v + continuity_from。' },\n        tier: { type: 'string', enum: TIERS, description: '档位：一个能力支持哪些档、每档意味着什么（分辨率/步数/加速件/耗时）由注册表决定，**以 comfy_list_workflows 为准**，不要预设。缺省 quality。具体实现由配置决定，调用方不指定工作流。' },\n        ref_nodes: { type: 'array', items: { type: 'string' }, description: '参考图：画布图片节点 id 或资产 id（character:luna / scene:bridge，跨会话复用）。绑定身份/环境（一致性）。与 first/last_frame 二选一。角色卡可只传双版本中的任意一张，工具按 tier 自动换成正确版本。' },\n        ref_variant: { type: 'string', enum: ['single', 'three'], description: '角色卡双版本选版（仅视频 ref_nodes）：按 STEP 0 用户选择传 single / three（fast 档只能 single）；不传则原样使用传入的卡。非 fast 档参考图形态类问题回退时用 single。普通场景/道具卡不受影响。' },\n        audio_ref_nodes: { type: 'array', items: { type: 'string' }, description: '参考音频（H3 Ref2VA 的 <Audio N>）：≤3 段，每段 2–15s、总 ≤15s、单文件 ≤15MB。传画布音频节点 id / 画布视频节点 id（取其音轨）/ voice:（音频资产）或 clip:（视频资产）。只在 type=r2v 生效，且必须同时传 ref_nodes（官方要求音频伴随视觉输入）；prompt 里要写 <Audio N> 声明。' },\n        first_frame_node: { type: 'string', description: '首帧：画布图片节点 id 或资产 id（末帧串联：传上一镜末帧来接续）。' },\n        last_frame_node: { type: 'string', description: '末帧：画布图片节点 id 或资产 id（供下一镜首帧串联）。' },\n        continuity_from: { type: 'string', description: '同场景续接（链式续接）：传**上一镜的画布视频节点 id**。选中的实现会消费上一镜的服务端 latent，逐帧钉住它的结尾、音频从接缝继续（画质无损、不需上传）。传了它=只要支持续接的实现（没有则显式报错，不会悄悄退回普通生成）；首次续接的那一镜本身也必须由支持续接的实现渲染。跨场景/首镜不要传。用 comfy_list_workflows 可查当前哪些实现支持续接。' },\n        width: { type: 'integer', description: '宽，显式传入则优先采用（snap 到 32 倍数）；缺省按画布 aspectRatio 推导，默认 1344。fast/quality 均支持任意比例。**例外**：若该档解析到的实现锁定了自己的原生分辨率（放大类实现），本参数不生效，交付尺寸由该实现决定，返回里会带 warnings 说明。' },\n        height: { type: 'integer', description: '高，显式传入则优先采用（snap 到 32 倍数）；缺省按画布 aspectRatio 推导，默认 768。fast/quality 均支持任意比例。**例外**：若该档解析到的实现锁定了自己的原生分辨率（放大类实现），本参数不生效，交付尺寸由该实现决定，返回里会带 warnings 说明。' },\n        length: { type: 'integer', description: '帧数（24fps；124≈5s，步进 17）。默认 124。' },\n        seed: { type: 'integer', description: '随机种子（可选）。' },\n        steps: { type: 'integer', description: '采样步数，默认 20（fast 档强制 4）。' },\n        title: { type: 'string', description: '画布节点标题，如「S01 片段」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['type'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, tier: { type: 'string' }, implementation: { type: 'string' }, resolution: { type: 'string' }, warnings: { type: 'array', items: { type: 'string' } }, promptNodeId: { type: 'string' }, promptTier: { type: 'string' }, promptFallback: { type: 'string' }, audioRefs: { type: 'array', items: { type: 'object' } }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok\n        ? `已生成视频节点 ${value.nodeId}${renderResolutionNote(value)}${promptBankNote(value)}\\n${mediaResultDetail(value)}`\n        : `生成失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        // 形状**必须显式声明**（type=r2v|i2v）：不再按\"传没传 first_frame\"猜能力，\n        // 否则两个都传时会把参数静默丢掉（i2v 清单没有参考图槽位）。\n        const capability = args.type ? VIDEO_SHAPES[args.type]?.capability : null\n        if (!capability) {\n          return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: `缺少或非法的 type：${args.type === undefined ? '必须显式声明' : String(args.type)}。type=r2v（参考绑定：ref_nodes=角色卡/场景卡）或 type=i2v（首帧/末帧串联：first_frame_node，可选 last_frame_node）。同场景续接用 type=r2v + continuity_from=上一镜节点 id。` }\n        }\n        const hasPrompt = typeof args.prompt === 'string' && args.prompt.trim() !== ''\n        if (!hasPrompt && !args.prompt_node && !args.nodeId && !args.title) {\n          return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: '缺少 prompt：请传 prompt，或传 prompt_node（分档提示词库节点），或复用同一个 nodeId / 同标题（会读回该镜上次持久化的提示词）' }\n        }\n        const r = await runRender(ctx, { ...args, capability, exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, tier: r.tier || '', implementation: r.implementation || '', resolution: r.resolution || '', warnings: r.warnings || [], promptNodeId: r.promptNodeId || '', promptTier: r.promptTier || '', promptFallback: r.promptFallback || '', audioRefs: r.audioRefs || [], error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const listNodesTool = {\n    name: 'canvas_list_nodes',\n    description: '列出会话画布的所有节点（含分组、状态、媒体相对路径）。',\n    parameters: {\n      type: 'object',\n      properties: {\n        sessionId: { type: 'string', description: '会话 id。' },\n        workspaceId: { type: 'string', description: '工作区 id。' },\n      },\n      required: [],\n    },\n    output: {\n      schema: { type: 'object', properties: { nodes: { type: 'array', items: { type: 'object' } } } },\n      render: (_args, value) => text((value.nodes || []).map((n) => `${n.kind}\\t${n.group}\\t${n.id}\\t${n.title}\\t${n.status}`).join('\\n') || '(空画布)'),\n    },\n    async execute(args, exec) {\n      const sid = args.sessionId || exec?.agent?.id\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      return { nodes: project.nodes }\n    },\n  }\n\n  const writeNodeTool = {\n    name: 'canvas_write_node',\n    description: '在会话画布写入/更新文本或表格节点（项目简报、故事大纲、七列镜头表、文本分镜等）。',\n    parameters: {\n      type: 'object',\n      properties: {\n        kind: { type: 'string', description: '节点类型：text / table。' },\n        title: { type: 'string', description: '节点标题。' },\n        content: { type: 'string', description: '文本/markdown 内容。' },\n        group: { type: 'string', description: '分组。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id。' },\n        workspaceId: { type: 'string', description: '工作区 id。' },\n      },\n      required: ['kind', 'title', 'content'],\n    },\n    output: {\n      schema: { type: 'object', properties: { nodeId: { type: 'string' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.error ? '写入失败: ' + value.error : '已写入画布节点 ' + value.nodeId),\n    },\n    async execute(args, exec) {\n      try {\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const project = await loadProject(root, sid)\n        const nodeId = args.nodeId || randomUUID()\n        const prevCard = project.nodes.find((n) => n.id === nodeId)\n        if (prevCard?.params?.configCard) {\n          return { nodeId: '', error: '配置卡由系统维护：请用画布「⚙ 配置」或 canvas_set_state 修改，不要直接写配置卡节点' }\n        }\n        const node = {\n          id: nodeId,\n          kind: args.kind === 'table' ? 'table' : 'text',\n          title: args.title,\n          content: args.content,\n          group: args.group || DEFAULT_GROUP,\n          status: 'ready',\n          createdAt: Date.now(),\n          order: nextOrder(project.nodes),\n        }\n        // 文本/表格节点导出交付文件：PDF 优先（puppeteer/Chrome），无工具兜底 .html\n        // （随 pre-ask 钩子送达飞书；失败不阻塞画布写入）\n        if (TEXT_NODE_EXPORT_PDF) {\n          try {\n            const pdfTool = await detectPdfTool()\n            const out = await exportTextNode(root, sid, nodeId, args.title, node.kind, node.group || DEFAULT_GROUP, args.content, pdfTool)\n            node.file = out.rel\n          } catch (error) {\n            console.warn('[dsh-short-video-studio] text node export failed:', error?.message || String(error))\n          }\n        }\n        node.params = { ...(node.params || {}), configRev: Number(project.settings?.rev) || 0 }\n        // 内容变了 → 对应的创作批准失效（表/分镜批准绑定内容哈希）。\n        if (!project.approvals) project.approvals = {}\n        const contentHash = textHash(node.content)\n        if (node.kind === 'table' && parseShotTableContent(node.content)) {\n          const prevHash = prevCard?.content ? textHash(prevCard.content) : ''\n          if (prevHash !== contentHash) delete project.approvals.shotTable\n        }\n        if (node.kind === 'text' && /分镜/.test(String(node.title || ''))) {\n          const prevHash = prevCard?.content ? textHash(prevCard.content) : ''\n          if (prevHash !== contentHash) delete project.approvals.storyboard\n        }\n        const existing = project.nodes.findIndex((n) => n.id === nodeId)\n        if (existing >= 0) { node.order = project.nodes[existing].order; node.createdAt = project.nodes[existing].createdAt; project.nodes[existing] = node }\n        else project.nodes.push(node)\n        await saveProject(root, sid, project)\n        return { nodeId, error: '' }\n      } catch (error) {\n        return { nodeId: '', error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const getNodeTool = {\n    name: 'canvas_get_node',\n    description: '读取会话画布单个节点。',\n    parameters: {\n      type: 'object',\n      properties: {\n        nodeId: { type: 'string', description: '节点 id。' },\n        sessionId: { type: 'string', description: '会话 id。' },\n        worksp