g', description: '会话 id。' },\n        workspaceId: { type: 'string', description: '工作区 id。' },\n      },\n      required: ['title', 'prompts'],\n    },\n    output: {\n      schema: { type: 'object', properties: { nodeId: { type: 'string' }, tiers: { type: 'array', items: { type: 'string' } }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.error\n        ? '写入失败: ' + value.error\n        : `已写入提示词库 ${value.nodeId}（${(value.tiers || []).join(' / ')}）`),\n    },\n    async execute(args, exec) {\n      try {\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const project = await loadProject(root, sid)\n        const tiers = {}\n        for (const tier of PROMPT_TIERS) {\n          const body = String(args.prompts?.[tier] == null ? '' : args.prompts[tier]).trim()\n          if (body) tiers[tier] = body\n        }\n        const usedTiers = PROMPT_TIERS.filter((t) => tiers[t])\n        if (!usedTiers.length) return { nodeId: '', tiers: [], error: 'prompts 至少给一档（fast / balanced / quality）' }\n        let node = args.nodeId ? findPromptBankNode(project, args.nodeId) : null\n        if (node && node.kind !== 'text' && node.kind !== 'table') {\n          return { nodeId: '', tiers: [], error: `nodeId 不是文本节点：${args.nodeId}` }\n        }\n        const isNew = !node\n        if (!node) {\n          node = {\n            id: randomUUID(),\n            kind: 'text',\n            title: args.title,\n            content: '',\n            group: args.group || DEFAULT_GROUP,\n            params: {},\n            status: 'ready',\n            createdAt: Date.now(),\n            order: nextOrder(project.nodes),\n          }\n          project.nodes.push(node)\n        }\n        node.title = args.title || node.title\n        // 更新已有库时按档合并：只补/改本次给出的档，未给出的档保留，避免一次单档更新把其它档冲掉\n        const prevBank = isNew ? { tiers: {}, note: '' } : parsePromptBank(node.content)\n    