  properties: {\n        flow: { type: 'string', enum: FLOW_VALUES, description: '片型（门组）：story=单片故事 / series=连续短剧单集 / brand=品牌宣传 / ecommerce=电商 / free=自由。决定哪些流程门生效（§10）。' },\n        aspectRatio: { type: 'string', description: '画面比例，如 16:9 / 9:16 / 1:1。' },\n        duration: { type: 'string', description: '总时长，如 30 秒 / 90s。' },\n        audioMode: { type: 'string', enum: ['silent', 'dialogue-led', 'narration-led'], description: '音频模式。' },\n        mode: { type: 'string', enum: TIERS, description: '视频档位（项目默认档位；工具缺省按此注入）。各档语义见 comfy_list_workflows。' },\n        imageTier: { type: 'string', enum: TIERS, description: '图片档位（角色卡 / 分镜图；工具缺省按此注入）。' },\n        delivery: { type: 'string', enum: DELIVERY_VALUES, description: '交付画质路线：native / upscale1080 / upscale2k / upscale4k / regen2k / fps48。' },\n        characterCardVariant: { type: 'string', enum: ['single', 'three'], description: '角色卡引用版本（视频 ref_nodes 的 STEP 0 用户选择）：single=单视图 / three=三视图。fast 档只能 single。' },\n        voicePlan: { type: 'string', enum: ['existing', 'audition', 'text-only'], description: '声线方案：existing=复用/补建 / audition=重新试镜 / text-only=无音色锚点。' },\n        subtitles: { type: 'string', enum: ['none', 'burned-in'], description: '画面内字幕：none=无 / burned-in=逐字烧进画面。' },\n        language: { type: 'string', enum: ['zh', 'en', 'auto'], description: '台词/字幕语言。' },\n        style: { type: 'string', description: '视觉风格 id（7 套之一，如 cinematic-live-action / pixar-3d）。' },\n        bgmMode: { type: 'string', enum: ['none', 'in-model'], description: 'BGM 模式：none / in-model（H3 逐镜自带）。' },\n        reviewMode: {\n          type: 'string',\n          enum: ['per-shot', 'batch'],\n          description:\n            '片段审查节奏（流程 skill 的开场选择，缺省 per-shot 逐镜审查）：per-shot = 每渲完一镜先人工确认再渲下一镜；batch = 全部片段渲完再一次人工确认。只决定人工确认的时机，AI 自检仍逐镜进行。',\n        },\n        shotGate: {\n          type: 'string',\n          enum: ['off', 'frames', 'verdict'],\n          description:\n            '逐镜自检门（缺省 verdict，工具层 pre-execute 硬门）：verdict = 每镜必须 canvas_record_check(pass) 才能生成下一镜；frames = 只要求上一镜抽过帧（只强制看片，不强制结论）；off = 关闭。重渲同一 nodeId 始终放行。',\n        },\n        groupOrder: {\n          type: 'array',\n          items: { type: 'string' },\n          description: '画布分组的展示顺序（分组名由流程 skill 自由定义）。画布按此顺序渲染分组；未列出的分组排在其后、按首次出现顺序。流程 skill 应在开场一次性声明。',\n        },\n        sessionId: { type: 'string', description: '会话 id。' },\n        workspaceId: { type: 'string', description: '工作区 id。' },\n      },\n      required: [],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          rev: { type: 'number' },\n          cardNodeId: { type: 'string' },\n          warnings: { type: 'array', items: { type: 'string' } },\n          changed: { type: 'array', items: { type: 'string' } },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已保存画布设置（rev ${value.rev}，配置卡 ${value.cardNodeId}）` + (Array.isArray(value.warnings) && value.warnings.length ? '\\n注意：' + value.warnings.join('；') : '')\n        : '保存失败: ' + value.error),\n    },\n    async execute(args, exec) {\n      try {\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const keys = [\n          'flow', 'aspectRatio', 'duration', 'audioMode', 'mode', 'imageTier', 'delivery',\n          'characterCardVariant', 'voicePlan', 'subtitles', 'language', 'style', 'bgmMode',\n          'reviewMode', 'shotGate', 'groupOrder',\n        ]\n        const patch = {}\n        for (const k of keys) if (args[k] !== undefined) patch[k] = args[k]\n        const r = await applyProjectConfig(root, sid, patch, { source: 'agent' })\n        return { ok: true, rev: r.rev, cardNodeId: r.cardNodeId, warnings: r.warnings, changed: r.changed, error: '' }\n      } catch (error) {\n        return { ok: false, rev: 0, cardNodeId: '', warnings: [], changed: [], error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const musicTool = {\n    name: 'comfy_generate_music',\n    description:\n      '用本地 ComfyUI 的 MiniMax Music 3 生成背景音乐（BGM）。输入文本描述（风格/乐器/情绪/BPM/结构），输出 44.1kHz 立体声画布音频节点。纯器乐：prompt 写 instrumental / no vocals，lyrics 留空；带人声：lyrics 用 [Verse] / [Chorus] 分段。触发词：BGM/配乐/背景音乐/生成音乐。',\n    parameters: {\n      type: 'object',\n      properties: {\n        prompt: { type: 'string', description: '音乐描述：风格、乐器、情绪、BPM、结构。纯器乐务必写 instrumental / no vocals。' },\n        duration: { type: 'number', description: '时长（秒，1–360；缺省 30）。' },\n        lyrics: { type: 'string', description: '歌词（可选）。纯器乐留空。' },\n        seed: { type: 'integer', description: '随机种子（可选；同 seed 可复现）。' },\n        steps: { type: 'integer', description: '采样步数（可选，默认 30）。' },\n        cfg: { type: 'number', description: '引导强度（可选，默认 1.7）。' },\n        title: { type: 'string', description: '画布节点标题，如「BGM 主题」。' },\n        group: { type: 'string', description: '画布分组（如 music）。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['prompt'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, tier: { type: 'string' }, implementation: { type: 'string' }, resolution: { type: 'string' }, warnings: { type: 'array', items: { type: 'string' } }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok\n        ? `已生成音乐节点 ${value.nodeId}（${value.implementation || 'audio.music'}）\\n${mediaResultDetail(value)}`\n        : `生成音乐失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runRender(ctx, { ...args, capability: 'audio.music', exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, tier: r.tier || '', implementation: r.implementation || '', resolution: r.resolution || '', warnings: r.warnings || [], error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const renderTool = {\n    name: 'comfy_render',\n    description:\n      '通用渲染入口（模型/实现无关）：按 capability + tier 调用注册表解析出的实现。**实现由配置决定**（设置页/配置文件的 preferred、tiers、pins），调用方只表达能力与档位——不接受 workflow。视频提示词可传 prompt_node 按 tier 读取分档提示词。产物写入画布。触发词：生成/渲染。',\n    parameters: {\n      type: 'object',\n      properties: {\n        capability: { type: 'string', enum: CAPABILITIES, description: '能力（见 comfy_list_workflows）。' },\n        type: { type: 'string', enum: Object.keys(VIDEO_SHAPES), description: '视频形状别名（可选）：r2v=视频参考绑定、i2v=视频首末帧串联；传了就必须与 capability 一致。不传则按 capability 推导形状做参数校验（例如 capability=video.reference2video 时不许传 first/last_frame）。' },\n        tier: { type: 'string', enum: TIERS, description: '档位（见 comfy_list_workflows；缺省 quality）。实现由配置按档位解析，调用方不指定具体工作流。' },\n        prompt: { type: 'string', description: '提示词。传了 prompt_node 时可省略（工具按 tier 从提示词库读对应段落）。' },\n        prompt_node: { type: 'string', description: '分档提示词库的画布文本节点 id（canvas_write_prompt_bank 产物）。按 tier 读取对应段落；缺该档自动回退到最近档并在 warnings 说明。生成后会把本次 prompt 回写本档段落。' },\n        persist_prompt: { type: 'boolean', description: '是否把本次提示词持久化到画布提示词库（默认 true；视频专用）。' },\n        prompt_group: { type: 'string', description: '自动创建的提示词库节点分组（缺省沿用视频节点 group）。' },\n        character: { type: 'string', description: '角色名（角色卡双版本：同一角色的单视图 / 三视图卡共用）。' },\n        card_variant: { type: 'string', enum: ['single', 'three'], description: '角色卡形态标记：single=单视图 / three=三视图横排。' },\n        paired_node_id: { type: 'string', description: '配对节点 id（角色卡另一版）；两节点会互记 pairedNodeId。' },\n        width: { type: 'integer', description: '宽（可选，缺省按能力/画布推导）。' },\n        height: { type: 'integer', description: '高（可选，缺省按能力/画布推导）。' },\n        length: { type: 'integer', description: '帧数（视频，默认 124）。' },\n        duration: { type: 'number', description: '音频时长（秒，audio.music 用；1–360）。视频请用 length。' },\n        lyrics: { type: 'string', description: '歌词（audio.music 可选；纯器乐留空）。' },\n        cfg: { type: 'number', description: '音乐 CFG（audio.music 可选，默认 1.7）。' },\n        seed: { type: 'integer', description: '随机种子（可选）。' },\n        steps: { type: 'integer', description: '采样步数（缺省取 mode 声明的 steps）。' },\n        guidance: { type: 'number', description: '引导强度。' },\n        count: { type: 'integer', description: '图片张数（1–4，默认 1）。' },\n        ref_nodes: { type: 'array', items: { type: 'string' }, description: '参考图：画布图片节点 id 或资产 id（character:luna / scene:bridge）。角色卡版本由 ref_variant 显式选择（不传则原样使用传入的卡）。' },\n        ref_variant: { type: 'string', enum: ['single', 'three'], description: '角色卡双版本选版（仅视频 ref_nodes）：按 STEP 0 用户选择传 single / three（fast 档只能 single）；不传则原样使用传入的卡。' },\n        audio_ref_nodes: { type: 'array', items: { type: 'string' }, description: '参考音频（H3 Ref2VA 的 <Audio N>）：≤3 段，每段 2–15s、总 ≤15s、单文件 ≤15MB。传画布音频节点 id / 画布视频节点 id（取其音轨）/ voice:（音频资产）或 clip:（视频资产）。只在 type=r2v 生效，且必须同时传 ref_nodes（官方要求音频伴随视觉输入）；prompt 里要写 <Audio N> 声明。' },\n        first_frame_node: { type: 'string', description: '首帧（画布图片节点 id 或资产 id）。' },\n        last_frame_node: { type: 'string', description: '末帧（画布图片节点 id 或资产 id）。' },\n        continuity_from: { type: 'string', description: '同场景续接（链式续接）：传**上一镜的画布视频节点 id**。选中的实现会消费上一镜的服务端 latent，逐帧钉住它的结尾、音频从接缝继续（画质无损、不需上传）。传了它=只要支持续接的实现（没有则显式报错，不会悄悄退回普通生成）；首次续接的那一镜本身也必须由支持续接的实现渲染。跨场景/首镜不要传。用 comfy_list_workflows 可查当前哪些实现支持续接。' },\n        title: { type: 'string', description: '画布节点标题。' },\n        group: { type: 'string', description: '画布分组。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id。' },\n        workspaceId: { type: 'string', description: '工作区 id。' },\n      },\n      required: ['capability'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, tier: { type: 'string' }, implementation: { type: 'string' }, resolution: { type: 'string' }, warnings: { type: 'array', items: { type: 'string' } }, promptNodeId: { type: 'string' }, promptTier: { type: 'string' }, promptFallback: { type: 'string' }, audioRefs: { type: 'array', items: { type: 'object' } }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok\n        ? `已渲染节点 ${value.nodeId}${renderResolutionNote(value)}${promptBankNote(value)}\\n${mediaResultDetail(value)}`\n        : `渲染失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        // 后处理能力走各自 runner（与专用工具同一条路径，避免落到 runRender 的生成图逻辑）\n        if (args.capability === 'video.interpolate') {\n          const ir = await runInterpolate(ctx, { ...args, exec })\n          return {\n            ok: true, nodeId: ir.node.id, media: ir.node.media, absPath: ir.absPath, mediaType: ir.mediaType, bytes: ir.bytes,\n            tier: ir.node.params.tier, implementation: ir.node.params.workflow,\n            resolution: `${ir.node.params.width}×${ir.node.params.height}`,\n            warnings: ir.warnings || [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: '',\n          }\n        }\n        if (args.capability === 'image.crop') {\n          const cr = await runCrop(ctx, { ...args, exec })\n          const res = `${cr.node.params.width}×${cr.node.params.height}`\n          return {\n            ok: true, nodeId: cr.node.id, media: cr.node.media, absPath: cr.absPath, mediaType: cr.mediaType, bytes: cr.bytes,\n            tier: '', implementation: cr.node.params.workflow, resolution: res,\n            warnings: [`裁切不重绘：产物与源图逐像素同源（${res}）`],\n            promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: '',\n          }\n        }\n        // 输入是「画布上已有的视频」的能力不走 runRender（它按提示词 + 参考图建图）。\n        // 这两个能力在工具面有专用入口；这里给一条能指路的错误，而不是让它落到生成图逻辑里报难懂的错。\n        if (args.capability === 'video.upscale' || args.capability === 'video.regenerate') {\n          const toolName = args.capability === 'video.upscale' ? 'video_upscale' : 'video_regenerate'\n          return {\n            ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '',\n            warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [],\n            error: `capability=${args.capability} 的输入是画布上**已有的视频**（不是 prompt/参考图）：请用 ${toolName}(video_node=…)`,\n          }\n        }\n        const hasPrompt = typeof args.prompt === 'string' && args.prompt.trim() !== ''\n        if (!hasPrompt && !args.prompt_node && !args.nodeId && !args.title) {\n          return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: '缺少 prompt：请传 prompt，或传 prompt_node（分档提示词库节点），或复用同一个 nodeId / 同标题' }\n        }\n        const r = await runRender(ctx, { ...args, exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, tier: r.tier || '', implementation: r.implementation || '', resolution: r.resolution || '', warnings: r.warnings || [], promptNodeId: r.promptNodeId || '', promptTier: r.promptTier || '', promptFallback: r.promptFallback || '', audioRefs: r.audioRefs || [], error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, tier: '', implementation: '', resolution: '', warnings: [], promptNodeId: '', promptTier: '', promptFallback: '', audioRefs: [], error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const concatTool = {\n    name: 'video_concat',\n    description:\n      '按给定顺序把画布上的多个视频节点拼接成一条完整成片，产物写回画布。后端自动选择：本机有 ffmpeg 走 ffmpeg（零重编码、秒级），否则退化到 ComfyUI 纯节点链路（无需任何本地二进制）。只做硬切，不做转场。触发词：拼接/合成全片/连成一条。',\n    parameters: {\n      type: 'object',\n      properties: {\n        nodes: {\n          type: 'array',\n          items: { type: 'string' },\n          description: '要拼接的画布视频节点 id，按成片顺序排列（至少 2 个）。',\n        },\n        title: { type: 'string', description: '画布节点标题，如「拼接成片」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['nodes'],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, backend: { type: 'string' }, error: { type: 'string' } },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已拼接节点 ${value.nodeId}（后端 ${value.backend}）\\n${mediaResultDetail(value)}`\n        : `拼接失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runConcat(ctx, { ...args, exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, backend: r.backend, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, backend: '', error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const extractFrameTool = {\n    name: 'extract_frame',\n    description:\n      '从画布上的视频节点抽取一帧存为画布图片节点（默认末帧）。用途：① 同场景续接镜——抽上一镜末帧作 comfy_generate_video 的 first_frame_node；② 跨场景转场镜——抽前一镜末帧 + 后一镜首帧，作首末帧生成一个真实的过渡镜头。触发词：抽帧/取末帧/取首帧。',\n    parameters: {\n      type: 'object',\n      properties: {\n        video_node: { type: 'string', description: '来源视频节点的画布 id。' },\n        frame_index: {\n          type: 'integer',\n          description: '帧序号。负数从末尾数：-1 = 末帧（默认），0 = 首帧。',\n        },\n        title: { type: 'string', description: '画布节点标题，如「S03 末帧」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['video_node'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok ? `已抽帧节点 ${value.nodeId}\\n${mediaResultDetail(value)}` : `抽帧失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runRender(ctx, {\n          ...args,\n          capability: 'image.from_video',\n          frame_index: args.frame_index === undefined ? -1 : args.frame_index,\n          exec,\n        })\n        // 自检留痕：把这张帧记进来源镜头的 params.checkFrames（canvas_record_check 的 pass 凭据）。\n        // 记账失败不影响抽帧本身。\n        try {\n          const sid = args.sessionId || exec?.agent?.id\n          const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n          const project = await loadProject(root, sid)\n          const src = project.nodes.find((n) => n.id === args.video_node)\n          if (src) {\n            const prev = Array.isArray(src.params?.checkFrames) ? src.params.checkFrames : []\n            if (!prev.includes(r.node.id)) prev.push(r.node.id)\n            src.params = { ...(src.params || {}), checkFrames: prev }\n            await saveProject(root, sid, project)\n          }\n        } catch (e) {\n          console.warn('[dsh-short-video-studio] extract_frame 记账失败（不影响抽帧）:', e?.message || String(e))\n        }\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const cropTool = {\n    name: 'image_crop',\n    description:\n      '从画布上的图片节点（或图片资产）裁出一块，写成新的图片节点。**纯像素裁切**：不重绘、不采样、无提示词，产物与源图逐像素同源。默认按「面板均分」切：panels=3（三视图横排）+ panel=0 ⇒ 左侧正面格。角色卡流程用它从三视图定妆图裁出单视图卡（两版身份按构造一致，不靠同 seed / 文本锁）。触发词：裁切/裁出正面/裁单视图/切一格。',\n    parameters: {\n      type: 'object',\n      properties: {\n        image_node: { type: 'string', description: '来源：画布图片节点 id 或图片资产 id（character:…）。只有图片能裁。' },\n        panel: { type: 'integer', description: '面板序号（0 起，默认 0）。只在没给 x/y/width/height 时生效：按 panels 均分取第 panel 竖条。' },\n        panels: { type: 'integer', description: '面板数（默认 3，即 1×3 三视图横排）。' },\n        x: { type: 'integer', description: '显式裁切左上角 x（像素）。给了任一显式矩形就走显式路径。' },\n        y: { type: 'integer', description: '显式裁切左上角 y（像素），默认 0。' },\n        width: { type: 'integer', description: '显式裁切宽（像素），缺省按 panels 均分。' },\n        height: { type: 'integer', description: '显式裁切高（像素），缺省取满高度。' },\n        character: { type: 'string', description: '角色名（角色卡双版本：与三视图卡共用同一 character）。' },\n        card_variant: { type: 'string', enum: ['single', 'three'], description: '角色卡形态标记：裁正面格通常填 single。' },\n        paired_node_id: { type: 'string', description: '配对节点 id（三视图卡节点）；两节点互记 pairedNodeId。' },\n        title: { type: 'string', description: '画布节点标题，如「Mia 角色卡·单视图」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['image_node'],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' },\n          mediaType: { type: 'string' }, bytes: { type: 'number' }, width: { type: 'number' }, height: { type: 'number' },\n          crop: { type: 'object' }, error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已裁切节点 ${value.nodeId}（${value.width}×${value.height}，来自 x=${value.crop?.x} y=${value.crop?.y}）\\n${mediaResultDetail(value)}`\n        : `裁切失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runCrop(ctx, { ...args, exec })\n        return {\n          ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes,\n          width: r.node.params.width, height: r.node.params.height, crop: r.rect, error: '',\n        }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, width: 0, height: 0, crop: {}, error: error?.message || String(error) }\n      }\n    },\n  }\n\n  // 逐镜自检门：把「这镜看过、判定通过」落成画布上的凭据。\n  // 没有 pass 记录的镜头会挡住下一镜生成（pre-execute 门，见 makeShotGateListener）。\n  const recordCheckTool = {\n    name: 'canvas_record_check',\n    description:\n      '记录某镜头的自检结论（写 node.params.selfCheck），是「逐镜自检门」的放行凭据：verdict=pass 后才会放行下一镜生成。' +\n      'pass 必须至少有一张抽帧证据（extract_frame 产出的图片节点，或 frames 参数显式给出）。' +\n      'checks 可选但推荐（plan/character/lipsync/subtitle/contamination/audio/style → pass|fail|na）：把门 3 六项落成结构化结论；verdict=pass 时任何一项 fail 会被拒绝。触发词：自检通过/记录自检/标记已看。',\n    parameters: {\n      type: 'object',\n      properties: {\n        nodeId: { type: 'string', description: '要记录的画布视频节点 id（片段）。' },\n        verdict: { type: 'string', enum: ['pass', 'fail'], description: '自检结论：pass=通过、可进入下一镜；fail=不通过、需重渲本镜（重渲会重置为 pending）。' },\n        frames: { type: 'array', items: { type: 'string' }, description: '本次核对用到的帧（画布图片节点 id，extract_frame 产物）。不传则用该镜头已抽的帧（params.checkFrames）。' },\n        notes: { type: 'string', description: '判定说明：角色一致性 / 动作锚点 / 音频 / 字幕 / 参考图污染等，便于追溯。' },\n        checks: {\n          type: 'object',\n          description: '门 3 六项结构化结论（推荐）：plan/character/lipsync/subtitle/contamination/audio/style → pass|fail|na。audio 由人工听核时写 na；silent 镜 lipsync/subtitle 可写 na。verdict=pass 时任何一项 fail 都会被拒绝。',\n          properties: Object.fromEntries(RECORD_CHECK_KEYS.map((k) => [k, { type: 'string', enum: RECORD_CHECK_VALUES }])),\n          additionalProperties: false,\n        },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['nodeId', 'verdict'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, status: { type: 'string' }, frames: { type: 'array', items: { type: 'string' } }, checks: { type: 'object' }, hint: { type: 'string' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok\n        ? `已记录 ${value.nodeId} 自检=${value.status}（抽帧 ${value.frames.length} 张${Object.keys(value.checks || {}).length ? `，checks ${Object.entries(value.checks).map(([k, v]) => `${k}=${v}`).join(' ')}` : ''}）\\n${value.hint}`\n        : `记录失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const verdict = args.verdict === 'pass' ? 'pass' : args.verdict === 'fail' ? 'fail' : ''\n        const empty = (error) => ({ ok: false, nodeId: args.nodeId || '', status: '', frames: [], checks: {}, hint: '', error })\n        if (!verdict) return empty(\"verdict 必须是 'pass' 或 'fail'\")\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const project = await loadProject(root, sid)\n        const node = project.nodes.find((n) => n.id === args.nodeId)\n        if (!node) return empty('画布节点不存在: ' + args.nodeId)\n        if (node.kind !== 'video') return empty(`只有视频节点可以记录自检（当前 kind=${node.kind}）`)\n        const given = Array.isArray(args.frames) ? args.frames.filter((x) => typeof x === 'string' && x.trim()) : []\n        for (const fid of given) {\n          const f = project.nodes.find((n) => n.id === fid)\n          if (!f) return empty(`抽帧节点不存在: ${fid}`)\n          if (f.kind !== 'image') return empty(`抽帧节点必须是图片节点: ${fid}（当前 ${f.kind}）`)\n        }\n        const known = Array.isArray(node.params?.checkFrames) ? node.params.checkFrames : []\n        const frames = [...new Set([...known, ...given])]\n        if (verdict === 'pass' && frames.length === 0) {\n          return empty(`pass 需要抽帧证据：先 extract_frame(video_node='${node.id}', frame_index=0 或 -1) 抽 1–3 帧看过画面，再记录（或用 frames 参数传已抽的帧节点 id）。`)\n        }\n        // 结构化 checks（可选；给了就必须是已知键 + 合法值）\n        let checks = {}\n        if (args.checks !== undefined && args.checks !== null) {\n          if (typeof args.checks !== 'object' || Array.isArray(args.checks)) return empty('checks 必须是对象')\n          const unknown = Object.keys(args.checks).filter((k) => !RECORD_CHECK_KEYS.includes(k))\n          if (unknown.length) return empty(`checks 含未知项：${unknown.join(' / ')}（允许：${RECORD_CHECK_KEYS.join(' / ')}）`)\n          const bad = Object.entries(args.checks).filter(([, v]) => !RECORD_CHECK_VALUES.includes(v))\n          if (bad.length) return empty(`checks 值非法：${bad.map(([k, v]) => `${k}=${v}`).join(' / ')}（只允许 pass / fail / na）`)\n          checks = { ...args.checks }\n          if (verdict === 'pass') {\n            const fails = Object.entries(checks).filter(([, v]) => v === 'fail').map(([k]) => k)\n            if (fails.length) {\n              return empty(`verdict=pass 与 checks 冲突：${fails.join(' / ')} 是 fail。要么把 verdict 改成 fail 并重渲，要么确认后把这些项改成 pass/na。`)\n            }\n          }\n        }\n        node.params = {\n          ...(node.params || {}),\n          checkFrames: frames,\n          selfCheck: { status: verdict, at: Date.now(), frames, checks, notes: String(args.notes || '').slice(0, 2000), by: 'canvas_record_check' },\n        }\n        await saveProject(root, sid, project)\n        const level = shotGateLevel(project.settings)\n        const hint = verdict === 'pass'\n          ? (level === 'off' ? '（shotGate=off，门控未启用）' : '下一镜可以继续渲染了。')\n          : '本镜未通过：改本镜 prompt 后复用同一 nodeId 重渲（重渲会把自检重置为 pending），再自检。'\n        return { ok: true, nodeId: node.id, status: verdict, frames, checks, hint, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', status: '', frames: [], checks: {}, hint: '', error: error?.message || String(error) }\n      }\n    },\n  }\n\n  // 创作批准账本：把「用户已确认某阶段产物」落成 project.approvals。\n  // 这是 approval gate 的放行凭据——没有它，新卡/写表/Sxx 视频/拼接都会被挡。\n  const approveTool = {\n    name: 'canvas_approve',\n    description:\n      '记录「用户已人工批准某阶段产物」的凭据（写 project.approvals），是创作批准门的放行凭据。' +\n      'target=assets（角色卡/场景卡/道具卡锁定，每张卡/每组卡一次）、shotTable（七列镜头表批准，先跑 STEP 5.5 并打 shot-table self-check: passed 戳）、' +\n      'storyboard（分镜批准）、clips（门 3 片段批准：per-shot 每镜一次 / batch 批量一次，要求片段已 canvas_record_check pass）。' +\n      '未调用时：生成新卡、写七列镜头表、生成 Sxx 视频、video_concat 都会被 pre-execute 门 deny。' +\n      '批准按配置 breakingRev 失效；重出卡 / 改表 / 改分镜 / 重渲片段会让对应批准失效。触发词：用户确认/锁定/批准。',\n    parameters: {\n      type: 'object',\n      properties: {\n        target: { type: 'string', enum: APPROVAL_TARGETS, description: '批准对象：assets / shotTable / storyboard / clips。' },\n        nodeIds: { type: 'array', items: { type: 'string' }, description: '目标节点 id。assets 缺省=当前全部资产卡；clips 缺省=全部镜头视频节点（params.shot=true）；会与已有 clips 批准合并。' },\n        nodeId: { type: 'string', description: 'shotTable / storyboard 的节点 id（缺省自动找镜头表 / 分镜节点）。' },\n        note: { type: 'string', description: '用户选择或备注（可选，便于追溯）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['target'],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          target: { type: 'string' },\n          nodeIds: { type: 'array', items: { type: 'string' } },\n          nodeId: { type: 'string' },\n          hint: { type: 'string' },\n          approvals: { type: 'object' },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已记录 ${value.target} 批准${value.nodeId ? `（节点 ${value.nodeId}）` : ''}${value.nodeIds?.length ? `（${value.nodeIds.length} 个节点）` : ''}\\n${value.hint}`\n        : `批准失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      const target = String(args.target || '')\n      const fail = (error) => ({ ok: false, target, nodeIds: [], nodeId: '', hint: '', approvals: {}, error })\n      try {\n        if (!APPROVAL_TARGETS.includes(target)) return fail(`target 必须是 ${APPROVAL_TARGETS.join(' / ')}`)\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const project = await loadProject(root, sid)\n        if (!project.approvals) project.approvals = {}\n        const rev = approvalConfigRev(project)\n        const at = Date.now()\n        const note = String(args.note || '').slice(0, 500)\n        let entry\n        let nodeIds = []\n        let nodeId = ''\n        const givenIds = Array.isArray(args.nodeIds)\n          ? args.nodeIds.filter((x) => typeof x === 'string' && x.trim()).map((x) => x.trim())\n          : []\n        if (target === 'assets') {\n          const cards = givenIds.length\n            ? givenIds.map((id) => (project.nodes || []).find((n) => n.id === id))\n            : assetCardsOf(project)\n          if (!cards.length) return fail('画布上还没有资产卡（角色卡/场景卡/道具卡）；先出卡，锁定后再批准')\n          const bad = cards.filter((n) => !n || !isAssetCard(n))\n          if (bad.length) return fail('以下节点不是资产卡：' + bad.map((n) => n?.id || '?').join('、'))\n          nodeIds = cards.map((n) => n.id)\n          entry = { at, configRev: rev, nodeIds, by: 'canvas_approve', note }\n        } else if (target === 'shotTable') {\n          const node = args.nodeId\n            ? (project.nodes || []).find((n) => n.id === args.nodeId)\n            : findShotPlan(project)?.node\n          if (!node) return fail('找不到镜头表节点：先用 canvas_write_node(kind=table) 写七列镜头表')\n          if (!parseShotTableContent(node.content)) return fail('该节点不是七列镜头表（列头/分隔不匹配）')\n          if (!/shot-table self-check:\\s*passed/i.test(String(node.content))) {\n            return fail('镜头表还没打自检戳：先跑 STEP 5.5 十四项自检，在表格顶部写 `shot-table self-check: passed at <时间戳>`，再批准')\n          }\n          nodeId = node.id\n          entry = { at, configRev: rev, nodeId, hash: textHash(node.content), by: 'canvas_approve', note }\n        } else if (target === 'storyboard') {\n          const node = args.nodeId\n            ? (project.nodes || []).find((n) => n.id === args.nodeId)\n            : storyboardNodeOf(project)\n          if (!node) return fail('找不到分镜文本节点：先 canvas_write_node(kind=text, title 含「分镜」) 写分镜')\n          if (node.kind !== 'text') return fail(`分镜节点必须是 text（当前 kind=${node.kind}）`)\n          nodeId = node.id\n          entry = { at, configRev: rev, nodeId, hash: textHash(node.content), by: 'canvas_approve', note }\n        } else if (target === 'clips') {\n          const videos = givenIds.length\n            ? givenIds.map((id) => (project.nodes || []).find((n) => n.id === id))\n            : (project.nodes || []).filter((n) => n.kind === 'video' && (n.params?.shot === true || shotIdFromText(n.title)))\n          if (!videos.length) return fail('没有可批准的片段（镜头节点需 params.shot=true；先渲片段）')\n          const bad = videos.filter((n) => !n || n.kind !== 'video')\n          if (bad.length) return fail('以下节点不是视频：' + bad.map((n) => n?.id || '?').join('、'))\n          const level = shotGateLevel(project.settings)\n          if (level !== 'off') {\n            const pending = videos.filter((n) => String(n.params?.selfCheck?.status || '') !== 'pass')\n            if (pending.length) {\n              return fail(`这些片段还没通过 AI 自检（先 extract_frame 抽帧核对 + canvas_record_check pass）：${pending.map((n) => n.id).join('、')}`)\n            }\n          }\n          const prev = approvalEntry(project, 'clips')\n          const keep = Number(prev?.configRev) === rev && Array.isArray(prev?.nodeIds) ? prev.nodeIds : []\n          nodeIds = [...new Set([...keep, ...videos.map((n) => n.id)])]\n          entry = { at, configRev: rev, nodeIds, by: 'canvas_approve', note }\n        }\n        project.approvals[target] = entry\n        await saveProject(root, sid, project)\n        return {\n          ok: true,\n          target,\n          nodeIds,\n          nodeId,\n          hint: target === 'clips'\n            ? '片段批准已记录；可以 video_concat 拼接了。'\n            : '批准已记录；下一步可以继续（生成下一张卡 / 写镜头表 / 渲 Sxx 视频）。',\n          approvals: approvalSummary(project),\n          error: '',\n        }\n      } catch (error) {\n        return fail(error?.message || String(error))\n      }\n    },\n  }\n\n  const extractAudioTool = {\n    name: 'extract_audio',\n    description:\n      '从画布视频节点抽取音轨，存为画布音频节点（可再作 comfy_generate_video 的 audio_ref_nodes 声线参考）。优先 ffmpeg；本机没有 ffmpeg 时自动走 ComfyUI 的 LoadVideo→GetVideoComponents→SaveAudio，无需本地二进制。触发词：抽音轨/取声线/提取声音。',\n    parameters: {\n      type: 'object',\n      properties: {\n        video_node: { type: 'string', description: '来源视频节点的画布 id。' },\n        title: { type: 'string', description: '画布节点标题，如「S01 声线参考」。' },\n        group: { type: 'string', description: '画布分组。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['video_node'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' }, mediaType: { type: 'string' }, bytes: { type: 'number' }, backend: { type: 'string' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok ? `已抽音轨节点 ${value.nodeId}（后端 ${value.backend}）\\n${mediaResultDetail(value)}` : `抽音轨失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runExtractAudio(ctx, { ...args, exec })\n        return { ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes, backend: r.backend, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, backend: '', error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const upscaleTool = {\n    name: 'video_upscale',\n    description:\n      '视频超分/恢复（U3）：把画布上一个**已生成的视频节点**放大并写回画布（音轨原样带回——音频从不经过模型）。' +\n      '与生成工具同构：tier 走注册表解析，workflow 可显式指定实现，模型走资产槽可替换。' +\n      '交付尺寸由实现的**尺寸来源**决定：倍率形态（像素空间 CNN，交付 = 源 × 倍率）或短边形态' +\n      '（扩散/恢复类模型，交付由实现的目标短边推导）。target_width 两种形态都可用——' +\n      '前者是事后收敛（超出倍率能力只是插值，会告警），后者**回注给模型按目标渲染**；都按 32 对齐。' +\n      '长片只在实现声明可被外层切块（chunking=caller，逐帧独立）时按像素-帧预算自动分块再拼回；' +\n      '自带跨帧时间先验的实现由它自己管显存（batch / tiling），外层不切。' +\n      '推荐**对单个分镜放大**（成片先拼后放会让失败代价与显存峰值都放大到全片）。触发词：超分/放大/提分辨率/2K/4K。',\n    parameters: {\n      type: 'object',\n      properties: {\n        video_node: { type: 'string', description: '要放大的画布视频节点 id（源片）。' },\n        tier: { type: 'string', enum: TIERS, description: '档位（缺省 quality）。**实现由配置决定**（如 x2 / x4 是两个并列实现，用设置页或 cfg.pins 选），调用方不指定工作流。' },\n        target_width: { type: 'integer', description: '目标交付宽度（可选；按 32 对齐，高度按原比例同步）。倍率形态=事后收敛到该宽度（超过实现的倍率能力时只是插值，会告警）；短边形态=反解短边回注实现，让它按目标渲染。不传=用实现自己的尺寸。' },\n        chunk_frames: { type: 'integer', description: '每块帧数（可选；缺省按像素-帧预算自动决定，只有超预算的长片才会分块）。实现声明 upscale.chunking=\"internal\"（自带跨帧时间先验）时不会自动分块，显式传它会出警告。' },\n        title: { type: 'string', description: '画布节点标题。' },\n        group: { type: 'string', description: '画布分组。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['video_node'],\n    },\n    // 宿主 tools.register 强制要求 output { schema, render }：缺了会在注册时抛\n    // TypeError，整条 apply 随之失败（工具与路由一起没了）。schema 只允许\n    // type/oneOf/properties/required/additionalProperties/items/enum/const 子集，\n    // 且 type 不能写成数组 ⇒ plan 的\"空\"用 {} 而不是 null。\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          nodeId: { type: 'string' },\n          media: { type: 'string' },\n          absPath: { type: 'string' },\n          mediaType: { type: 'string' },\n          bytes: { type: 'number' },\n          backend: { type: 'string' },\n          chunks: { type: 'integer' },\n          plan: {\n            type: 'object',\n            properties: {\n              natural: { type: 'object' },\n              delivery: { type: 'object' },\n              // sizing='short-side' 时 factor 为 null（倍率是推导的），输出侧省略该键（见 execute）\n              factor: { type: 'number' },\n              shortSide: { type: 'integer' },\n              maxEdge: { type: 'integer' },\n              sizing: { type: 'string' },\n              align: { type: 'integer' },\n              warning: { type: 'string' },\n            },\n          },\n          warnings: { type: 'array', items: { type: 'string' } },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已超分 ${value.nodeId} → ${value.media}` +\n          (value.plan && value.plan.delivery ? `（交付 ${value.plan.delivery.w}×${value.plan.delivery.h}）` : '') +\n          (value.chunks > 1 ? ` · 分 ${value.chunks} 块` : '') +\n          (value.warnings && value.warnings.length ? `\\n⚠ ${value.warnings.join('\\n⚠ ')}` : '')\n        : `超分失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runUpscale(ctx, { ...args, exec })\n        // output schema 里 factor 是 number、shortSide 是 integer，而两个形态各自会把**不属于自己的**\n        // 那个键置为 null（短边形态无倍率、倍率形态无短边——都不编数）。宿主 schema 子集不支持\n        // type 数组 / null 联合 ⇒ 输出侧统一**省略** null 键，改由 sizing 表明是哪种形态。\n        const plan = {}\n        for (const [k, v] of Object.entries(r.plan || {})) if (v !== null) plan[k] = v\n        return {\n          ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType,\n          bytes: r.bytes, backend: r.backend, chunks: r.chunks, plan, warnings: r.warnings || [], error: '',\n        }\n      } catch (error) {\n        return {\n          ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0,\n          backend: '', chunks: 0, plan: {}, warnings: [], error: error?.message || String(error),\n        }\n      }\n    },\n  }\n\n  const regenerateTool = {\n    name: 'video_regenerate',\n    description:\n      '视频重生成（1080p / 2K）：把画布上一个**已生成的 768p 片段**在目标分辨率上**重新生成**——' +\n      'latent 3D 放大 → σ0.909 起 3 步 Euler（CFG=1）→ 快解码，**会重画内容**（不是超分，也不保身份）。' +\n      '输入是画布视频节点；提示词缺省沿用源片段记录的那一份（外部导入/拼接成片没有 prompt，必须显式传）。' +\n      '音频不参与重采样（σ=0），产物把**源音轨原样接回**；帧数与源片一致，交付尺寸由实现声明的目标网格决定' +\n      '（1080p → 1920×1080、2k → 2560×1440，竖屏自动翻转）。' +\n      '源片护栏：24fps、帧数在实现训练区间内（约 121–362 帧）、必须有提示词——不符合会**显式报错**而不是硬跑。' +\n      '**产物必须抽帧核对**（身份/口型会漂），`start_sigma` 0.8 更贴草稿。要保内容的放大请用 video_upscale。',\n    parameters: {\n      type: 'object',\n      properties: {\n        video_node: { type: 'string', description: '要重生成的画布视频节点 id（源片，通常是 768p 片段）。' },\n        prompt: { type: 'string', description: '提示词（可选）。缺省沿用源节点记录的 prompt；外部/拼接片段必须显式传。' },\n        handoff: { type: 'string', enum: ['auto', 'latent', 'video'], description: '交接方式（缺省 auto）：auto=源节点有可用 draft latent 就走 latent（无 mp4 往返），否则退回视频入口并说明原因；latent=强制，不满足直接报错；video=强制走视频入口。返回里 handoff/handoffReason 会写明这次实际走了哪条。' },\n        target: { type: 'string', description: '目标网格名（由实现声明，如 1080p / 2k）。缺省用实现的默认目标。' },\n        start_sigma: { type: 'number', description: '起始噪声（可选，0 = 发布配方 0.909；0.8 更贴草稿但细节少）。' },\n        steps: { type: 'integer', description: '重生成步数（可选，缺省 3；2 步更快但细纹理更软）。' },\n        tier: { type: 'string', enum: TIERS, description: '档位（实现由配置解析，缺省 quality）。' },\n        seed: { type: 'integer', description: '随机种子（可选；同源同 seed 可复现）。' },\n        title: { type: 'string', description: '画布节点标题。' },\n        group: { type: 'string', description: '画布分组。' },\n        nodeId: { type: 'string', description: '复用节点 id（重生成同一节点时传它）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['video_node'],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' },\n          mediaType: { type: 'string' }, bytes: { type: 'number' }, backend: { type: 'string' },\n          target: { type: 'string' },\n          handoff: { type: 'string' }, handoffReason: { type: 'string' },\n          delivery: { type: 'object', properties: { w: { type: 'integer' }, h: { type: 'integer' } } },\n          frames: { type: 'integer' }, seed: { type: 'integer' },\n          warnings: { type: 'array', items: { type: 'string' } }, error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已重生成 ${value.nodeId} → ${value.media}` +\n          (value.delivery ? `（${value.target} ${value.delivery.w}×${value.delivery.h} · ${value.frames} 帧）` : '') +\n          (value.handoff ? ` · 交接 ${value.handoff}${value.handoffReason ? `（${value.handoffReason}）` : ''}` : '') +\n          (value.warnings && value.warnings.length ? `\\n⚠ ${value.warnings.join('\\n⚠ ')}` : '')\n        : `重生成失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runRegenerate(ctx, { ...args, exec })\n        return {\n          ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType,\n          bytes: r.bytes, backend: r.backend, target: r.node.params.target,\n          handoff: r.handoff || '', handoffReason: r.handoffReason || '',\n          delivery: r.plan.delivery, frames: r.node.params.length, seed: r.seed,\n          warnings: r.warnings || [], error: '',\n        }\n      } catch (error) {\n        return {\n          ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0, backend: '',\n          target: '', handoff: '', handoffReason: '', delivery: { w: 0, h: 0 }, frames: 0, seed: 0, warnings: [], error: error?.message || String(error),\n        }\n      }\n    },\n  }\n\n  const interpolateTool = {\n    name: 'video_interpolate',\n    description:\n      '视频补帧（VFI）：把画布上一个**已生成的视频节点**提升帧率并写回画布（音轨直通、时长与源一致、分辨率不变）。' +\n      '整数倍目标（24→48/72/96）走 ComfyUI 原生补帧；非整数倍（24→60、24→30）先出整数倍母版，再由 runner 用 ffmpeg 抽到目标帧率（需本机 ffmpeg）。' +\n      'D2：尾部补齐到「源帧数 × 倍率」，避免逐镜拼接累积漂移。**逐镜补、不要对成片补**（硬切处会生成两场之间的形变帧）。触发词：补帧/提帧率/48fps/60fps/丝滑。',\n    parameters: {\n      type: 'object',\n      properties: {\n        video_node: { type: 'string', description: '要补帧的画布视频节点 id（源片，kind=video）。' },\n        target_fps: { type: 'integer', description: '目标帧率（如 48 / 60 / 30）。缺省 = 源帧率 × 默认倍率（清单 defaultMultiplier，RIFE 为 ×2 ⇒ 48fps）。' },\n        multiplier: { type: 'integer', description: '模型补帧倍率（2–16 整数）。显式传时母版帧率 = 源×倍率；不传则按 target_fps 自动反解最小整数倍（24→60 解得 ×5）。' },\n        tier: { type: 'string', enum: TIERS, description: '档位（补帧目前只有 quality 一档；传别的档会显式报错）。' },\n        title: { type: 'string', description: '画布节点标题，如「S01 片段 · 补帧 48fps」。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id（更新而非新增）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['video_node'],\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, absPath: { type: 'string' },\n          mediaType: { type: 'string' }, bytes: { type: 'number' },\n          targetFps: { type: 'integer' }, sourceFps: { type: 'number' }, multiplier: { type: 'integer' },\n          plan: { type: 'object' }, retimed: { type: 'boolean' },\n          warnings: { type: 'array', items: { type: 'string' } }, error: { type: 'string' },\n        },\n      },\n      render: (_args, value) => text(value.ok\n        ? `已补帧 ${value.nodeId} → ${value.media}\\n源 ${value.sourceFps}fps ×${value.multiplier} → ${value.targetFps}fps`\n          + (value.warnings && value.warnings.length ? `\\n⚠ ${value.warnings.join('\\n⚠ ')}` : '')\n        : `补帧失败: ${value.error}`),\n    },\n    async execute(args, exec) {\n      try {\n        const r = await runInterpolate(ctx, { ...args, exec })\n        return {\n          ok: true, nodeId: r.node.id, media: r.node.media, absPath: r.absPath, mediaType: r.mediaType, bytes: r.bytes,\n          targetFps: r.node.params.fps, sourceFps: r.node.params.sourceFps, multiplier: r.node.params.multiplier,\n          plan: r.plan, retimed: r.retimed, warnings: r.warnings || [], error: '',\n        }\n      } catch (error) {\n        return {\n          ok: false, nodeId: '', media: '', absPath: '', mediaType: '', bytes: 0,\n          targetFps: 0, sourceFps: 0, multiplier: 0, plan: {}, retimed: false, warnings: [], error: error?.message || String(error),\n        }\n      }\n    },\n  }\n\n  const listWorkflowsTool = {\n    name: 'comfy_list_workflows',\n    description: '列出可用的生成能力与**档位**（含可用性、交付尺寸、实测耗时）。**实现由配置决定**，调用方只按「能力 + 档位」请求，不需要（也不应该）知道具体工作流 id。',\n    parameters: { type: 'object', properties: {}, required: [] },\n    output: {\n      schema: { type: 'object', properties: { capabilities: { type: 'array', items: { type: 'object' } }, diagnostics: { type: 'string' } } },\n      render: (_args, value) => {\n        const main = (value.capabilities || []).map((c) => {\n          if (!c.tiered) {\n            return `${c.capability}（未分档：只有唯一实现，忽略档位请求）`\n          }\n          const lines = [`${c.capability}\\t档位=${(c.tiers || []).join(' / ')}`]\n          for (const t of c.tierInfo || []) {\n            const av = t.ok ? '✓可用' : `✗不可用${t.missing && t.missing.length ? `(缺节点 ${t.missing.join(',')})` : ''}`\n            const size = t.regenerateTargets && t.regenerateTargets.length\n              ? `目标 ${t.regenerateTargets.join(' / ')}`\n              : (t.longSide ? `长边 ${t.longSide}` : (t.referencePixels ? `参考图预算 ${t.referencePixels}px` : '跟随输入'))\n            lines.push(`  [${t.tier}] ${av} · ${size}${t.estSeconds ? ` · 约 ${t.estSeconds}s` : ''}${t.count > 1 ? ` · ${t.count} 个并列实现` : ''}`)\n          }\n          return lines.join('\\n')\n        }).join('\\n') || '(无工作流)'\n        const diag = value.diagnostics ? `\\n\\n诊断（排障用，技能/流程不必引用）：\\n${value.diagnostics}` : ''\n        return text(main + diag)\n      },\n    },\n    async execute() {\n      const registry = getRegistry()\n      const matrix = await describeTierMatrix(registry)\n      const capabilities = Object.entries(registry.byCapability).map(([cap, ms]) => {\n        const preferred = getPreferred(cap)\n        const m = matrix[cap] || {}\n        return {\n          capability: cap,\n          default: preferred[0] || (ms[0] && ms[0].id) || '',\n          tiered: Boolean(m.tiered),\n          tiers: m.tiers || [],\n          selection: m.selection || {},\n          groups: m.groups || [],\n          unclassified: m.unclassified || [],\n          workflows: ms.map((w) => ({\n            id: w.id,\n            displayName: w.displayName || w.id,\n            modes: Object.keys(w.modes || {}),\n            tier: w.tier || '',\n            group: groupNameOf(w),\n            accel: w.accel || '',\n            internal: Boolean(w.internal),\n            requiresNodes: w.requiresNodes || [],\n            estSeconds: Number.isFinite(w.estSeconds) ? w.estSeconds : null,\n            output: w.output || {},\n            constraints: w.constraints || {},\n          })),\n          // 主输出用的**档位视角**：每个档位一行（可用性 / 交付尺寸 / 耗时 / 并列实现数）。\n          // 实现 id 只出现在 diagnostics 里——调用方按「能力 + 档位」请求，不需要知道工作流。\n          tierInfo: (m.tiers || []).map((t) => {\n            const list = (m.groups || []).flatMap((g) => g.tiers?.[t] || [])\n            const pick = list.find((w) => !w.accel) || list[0]\n            const man = pick ? registry.byId[pick.id] : null\n            const mp = (man && man.modes && man.modes[man.tier]) || {}\n            return {\n              tier: t,\n              ok: list.some((w) => w.available !== false),\n              count: list.length,\n              longSide: mp.longSide || man?.resolution?.longSide || null,\n              referencePixels: mp.referencePixels || null,\n              // 重生成类能力的交付尺寸是**目标网格**（不跟随输入）：矩阵里如实显示可选目标，\n              // 否则会被渲染成「跟随输入」——那正好是它与超分的区别所在。\n              regenerateTargets: man?.regenerate ? Object.keys(man.regenerate.targets || {}) : null,\n              estSeconds: pick && Number.isFinite(pick.estSeconds) ? Math.round(pick.estSeconds) : null,\n              missing: [...new Set(list.filter((w) => w.available === false).flatMap((w) => w.missingNodes || []))],\n            }\n          }),\n        }\n      })\n      // 诊断段：实现 id / 家族 / 策略 / 未分级清单——排障与配置用，技能与流程不必引用\n      const diagLines = []\n      for (const c of capabilities) {\n        if (!c.tiered) {\n          diagLines.push(`${c.capability}（未分档）: ` + ((c.workflows || []).filter((w) => !w.internal).map((w) => w.id).join(', ') || '(无)'))\n          continue\n        }\n        diagLines.push(`${c.capability}`)\n        for (const g of c.groups || []) {\n          for (const [tier, list] of Object.entries(g.tiers || {})) {\n            for (const w of list) {\n              const av = w.available === true ? '✓' : w.available === false ? `✗缺${(w.missingNodes || []).join(',')}` : '?未知'\n              diagLines.push(`  [${tier}] 家族=${w.group || g.id} 实现=${w.id}${w.accel ? ` 加速=${w.accel}` : ''} ${av}`)\n            }\n          }\n        }\n        for (const s of c.strategies || []) {\n          diagLines.push(`  策略「${s.label}」${s.builtin ? '(内置默认)' : '(用户自建)'} = ` +\n            Object.entries(s.tiers || {}).map(([t, id]) => `${t}→${id}`).join(' ') + (s.available === false ? '  ✗ 所选实现缺节点' : ''))\n        }\n        if ((c.unclassified || []).length) diagLines.push(`  未分级清单（不参与档位解析）: ` + c.unclassified.map((w) => w.id).join(', '))\n      }\n      return { capabilities, diagnostics: diagLines.join('\\n') }\n    },\n  }\n\n  const assetListTool = {\n    name: 'asset_list',\n    description:\n      '列出跨会话资产库中的素材（角色卡/场景卡/风格锚点/视频片段/文本/声线）。返回稳定资产 id（新入库形如 character:<16 位 hex>；老资产可能是 character:luna、clip:shot01、text:shotlist），图片类可用 ref_nodes 直接引用；音频类（voice:，声线样本）可作 audio_ref_nodes（视频/文本不可作参考图）。触发词：资产库/已有角色/已有场景/复用。',\n    parameters: {\n      type: 'object',\n      properties: {\n        type: { type: 'string', enum: ASSET_TYPES, description: '按类型过滤（character/scene/style/clip/text/voice）。' },\n        query: { type: 'string', description: '按 name/state/tags 模糊匹配（可选）。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: [],\n    },\n    output: {\n      schema: { type: 'object', properties: { assets: { type: 'array', items: { type: 'object' } } } },\n      render: (_args, value) => text((value.assets || []).map((a) =>\n        `${a.id}\\t${assetKind(a)}\\t${a.displayState || a.state}\\t${a.displayName || a.name}${a.tags && a.tags.length ? '\\t[' + a.tags.join(',') + ']' : ''}`\n      ).join('\\n') || '(资产库为空)'),\n    },\n    async execute(args, exec) {\n      const sid = args.sessionId || exec?.agent?.id\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const lib = loadLibrary(root)\n      let list = Object.values(lib.assets).map((a) => ({\n        ...a, displayName: assetDisplayName(a), displayState: assetDisplayState(a),\n      }))\n      if (args.type) list = list.filter((a) => a.type === args.type)\n      if (args.query) {\n        const q = String(args.query).toLowerCase()\n        list = list.filter((a) =>\n          (a.displayName && String(a.displayName).toLowerCase().includes(q)) ||\n          (a.displayState && String(a.displayState).toLowerCase().includes(q)) ||\n          (a.id && String(a.id).toLowerCase().includes(q)) ||\n          (Array.isArray(a.tags) && a.tags.some((t) => String(t).toLowerCase().includes(q))))\n      }\n      return { assets: list }\n    },\n  }\n\n  const assetToCanvasTool = {\n    name: 'asset_to_canvas',\n    description:\n      '把资产库中的素材物化为当前会话画布节点（复用资产时，卡片仍要出现在画布）。图片/视频/音频资产拷贝库文件并建同 kind 的媒体节点；文本资产直接建 text/table 节点。返回节点 id；图片类节点的 id 或资产 id 可再传给 ref_nodes，音频类（voice:）可传给 audio_ref_nodes。',\n    parameters: {\n      type: 'object',\n      properties: {\n        id: { type: 'string', description: '资产 id（如 character:luna）。' },\n        title: { type: 'string', description: '画布节点标题（缺省用资产显示名）。' },\n        group: { type: 'string', description: '画布分组（自由字符串，由流程 skill 定义；缺省 ungrouped）。' },\n        nodeId: { type: 'string', description: '复用节点 id。' },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['id'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, nodeId: { type: 'string' }, media: { type: 'string' }, error: { type: 'string' } } },\n      render: (_args, value) => text(value.ok ? '已物化画布节点 ' + value.nodeId : '物化失败: ' + value.error),\n    },\n    async execute(args, exec) {\n      try {\n        const sid = args.sessionId || exec?.agent?.id\n        const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n        const node = await copyAssetToCanvas(root, sid, args.id, { title: args.title, group: args.group, nodeId: args.nodeId })\n        return { ok: true, nodeId: node.id, media: node.media, error: '' }\n      } catch (error) {\n        return { ok: false, nodeId: '', media: '', error: error?.message || String(error) }\n      }\n    },\n  }\n\n  const assetIngestTool = {\n    name: 'asset_ingest',\n    description:\n      '系列模式下，把用户已批准的画布节点/文件登记进跨会话资产库（人工批准清单后由 AI 执行）。必须传 approvalNodeId（画布文本节点，正文含 asset-ingest-approved 与本次每个 nodeId/srcPath/name）。默认不覆盖同名资产；allowOverwrite=true 才覆盖并 version+1。返回稳定 assetId；单项目/未批准场景不要调用。',\n    parameters: {\n      type: 'object',\n      properties: {\n        approvalNodeId: { type: 'string', description: '用户批准清单的画布文本节点 id（正文必须含 asset-ingest-approved 与本次条目）。' },\n        allowOverwrite: { type: 'boolean', description: '允许覆盖同名资产（version+1）。默认 false。' },\n        items: {\n          type: 'array',\n          description: '要入库的条目。每项给 nodeId（画布节点）或 srcPath（文件），二选一。',\n          items: {\n            type: 'object',\n            properties: {\n              nodeId: { type: 'string', description: '画布节点 id（与 srcPath 二选一）。' },\n              srcPath: { type: 'string', description: '工作区内文件路径（与 nodeId 二选一；限 canvas/ 或 .dsh-assets/）。' },\n              type: { type: 'string', enum: ASSET_TYPES, description: '资产类型。' },\n              name: { type: 'string', description: '资产显示名（建议「角色-状态-版本」）。' },\n              state: { type: 'string', description: '状态（可选）。' },\n              character: { type: 'string', description: '角色名（角色卡必填，用于 ref_variant 配对）。' },\n              cardVariant: { type: 'string', enum: ['single', 'three'], description: '角色卡版本（角色卡必填）。' },\n              source: { type: 'string', enum: ['audition', 'existing', 'text-only'], description: '声线来源（voice 可选）。' },\n              tags: { type: 'array', items: { type: 'string' }, description: '标签（可选）。' },\n            },\n            required: ['type', 'name'],\n          },\n        },\n        sessionId: { type: 'string', description: '会话 id（缺省取当前 agent 会话）。' },\n        workspaceId: { type: 'string', description: '工作区 id（缺省自动解析）。' },\n      },\n      required: ['approvalNodeId', 'items'],\n    },\n    output: {\n      schema: { type: 'object', properties: { ok: { type: 'boolean' }, items: { type: 'array', items: { type: 'object' } }, errors: { type: 'array', items: { type: 'object' } } } },\n      render: (_args, value) => text(\n        (value.items || []).map((x) => `${x.created ? '新增' : '更新'} ${x.assetId}\\t${x.name}\\tv${x.version}`).join('\\n') +\n        ((value.errors || []).length ? `\\n失败 ${value.errors.length}: ` + value.errors.map((e) => `${e.name}: ${e.error}`).join('; ') : '')\n      ) || '未入库任何条目',\n    },\n    async execute(args, exec) {\n      const sid = args.sessionId || exec?.agent?.id\n      const { root } = resolveSessionRoot(ctx, sid, args.workspaceId, exec)\n      const project = await loadProject(root, sid)\n      const approval = project.nodes.find((n) => n.id === args.approvalNodeId)\n      const approvalText = approval && (approval.kind === 'text' || approval.kind === 'table') ? String(approval.content || '') : ''\n      if (!approvalText.includes('asset-ingest-approved')) {\n        return { ok: false, items: [], errors: [{ name: '(approval)', error: '缺少有效的用户批准节点（正文需含 asset-ingest-approved）' }] }\n      }\n      const lib = loadLibrary(root)\n      const done = []\n      const errors = []\n      const kindExt = {\n        image: ['.png', '.jpg', '.jpeg', '.webp'],\n        video: ['.mp4', '.webm', '.mov'],\n        audio: ['.wav', '.mp3', '.m4a', '.flac', '.ogg'],\n      }\n      const expectedKind = (type) => TYPE_KINDS[type]\n      for (const item of args.items || []) {\n        try {\n          const type = String(item.type || '')\n          const kind = expectedKind(type)\n          if (!kind) throw new Error(`资产类型非法: ${type}`)\n          const name = normalizeDisplayName(item.name)\n          if (!name) throw new Error('name 不能为空')\n          const token = item.nodeId || item.srcPath || name\n          if (!approvalText.includes(String(token)) || !approvalText.includes(name)) {\n            throw new Error('批准节点未包含该条目的 nodeId/srcPath 与 name')\n          }\n          let srcAbs = ''\n          let node = null\n          let textContent\n          if (item.nodeId) {\n            node = project.nodes.find((n) => n.id === item.nodeId)\n            if (!node) throw new Error('画布节点不存在: ' + item.nodeId)\n            if (node.status && node.status !== 'ready') throw new Error('节点未 ready: ' + node.status)\n            const nodeKind = node.kind === 'table' ? 'text' : node.kind\n            if (nodeKind !== kind) throw new Error(`节点载体 ${nodeKind} 与资产类型 ${type}(${kind}) 不匹配`)\n            if (kind === 'text') textContent = String(node.content || '')\n            else {\n              if (!node.media) throw new Error('节点没有 media 文件')\n              srcAbs = join(root, ...String(node.media).split('/'))\n              if (!existsSync(srcAbs)) throw new Error('节点 media 文件不存在: ' + node.media)\n            }\n          } else if (item.srcPath) {\n            const rel = String(item.srcPath)\n            if (isAbsolute(rel)) throw new Error('srcPath 必须是工作区相对路径')\n            const abs = resolve(root, rel)\n            const relToRoot = relative(root, abs)\n            if (!relToRoot || relToRoot.startsWith('..') || isAbsolute(relToRoot)) throw new Error('srcPath 越出工作区')\n            if (!/^(canvas|\\.dsh-assets)[\\/\\\\]/.test(relToRoot)) throw new Error('srcPath 仅允许 canvas/ 或 .dsh-assets/')\n            if (!existsSync(abs)) throw new Error('srcPath 文件不存在')\n            const ext = extname(abs).toLowerCase()\n            if (kind !== 'text' && !(kindExt[kind] || []).includes(ext)) throw new Error(`文件扩展名 ${ext} 与 ${kind} 不匹配`)\n            if (kind === 'text') throw new Error('text 资产请用 nodeId')\n            srcAbs = abs\n          } else {\n            throw new Error('缺少 nodeId 或 srcPath')\n          }\n          const existingId = findAssetByLabel(lib, type, name)\n          if (existingId && !args.allowOverwrite) throw new Error('同名资产已存在；需覆盖请传 allowOverwrite=true')\n          const prev = existingId ? lib.assets[existingId] : null\n          const id = existingId || newAssetId(lib, type)\n          const version = prev ? (Number(prev.version) || 1) + 1 : 1\n          const meta = {\n            sourceSession: sid,\n            sourceNode: node ? node.id : '',\n            ingestedBy: 'agent',\n            approvedAt: Date.now(),\n            approvalNodeId: args.approvalNodeId,\n            version,\n            ...(node?.params?.prompt ? { prompt: node.params.prompt } : {}),\n            ...(node?.params?.seed !== undefined ? { seed: node.params.seed } : {}),\n            ...(item.character || node?.params?.character ? { character: String(item.character || node.params.character) } : {}),\n            ...((item.cardVariant === 'single' || item.cardVariant === 'three') || node?.params?.cardVariant === 'single' || node?.params?.cardVariant === 'three' ? { cardVariant: item.cardVariant || node.params.cardVariant } : {}),\n            ...(item.source ? { source: item.source } : {}),\n            ...(Array.isArray(item.tags) ? { tags: item.tags } : {}),\n          }\n          const rec = registerAsset(root, lib, {\n            id, type, name, state: item.state, srcAbsPath: srcAbs,\n            text: textContent, title: node?.title || name, nodeKind: node?.kind, meta,\n          })\n          done.push({ name, assetId: rec.id, created: !prev, version })\n        } catch (e) {\n          errors.push({ name: item?.name || '(unknown)', error: e?.message || String(e) })\n        }\n      }\n      return { ok: errors.length === 0, items: done, errors }\n    },\n  }\n\n  return [imageTool, videoTool, musicTool, renderTool, concatTool, extractFrameTool, cropTool, recordCheckTool, approveTool, extractAudioTool, upscaleTool, regenerateTool, interpolateTool, listWorkflowsTool, listNodesTool, writeNodeTool, getNodeTool, writePromptBankTool, getPromptTool, groupTool, reorderTool, stateTool, setStateTool, assetListTool, assetToCanvasTool, assetIngestTool]\n}\n\n// ---------------------------------------------------------------------------\n// HTTP 路由\n// ---------------------------------------------------------------------------\n\nfunction makeRoutes(runtime) {\n  const apiPrefix = ROUTE_ROOT + '/api'\n\n  /** 从 query 解析 workspace（显式 workspaceId 优先，否则按 session 成员扫描）。 */\n  function resolveFromQuery(ctx, url) {\n    const sessionId = url.searchParams.get('sessionId')?.trim()\n    const workspaceId = url.searchParams.get('workspaceId')?.trim()\n    if (!sessionId) throw HttpError(400, 'sessionId required')\n    if (workspaceId) {\n      const w = ctx.workspaceRegistry.get(workspaceId)\n      if (w) return { sessionId, root: w.path, workspaceId: String(w.id) }\n    }\n    for (const w of ctx.workspaceRegistry.list()) {\n      if (w.sessionIds.includes(sessionId)) return { sessionId, root: w.path, workspaceId: String(w.id) }\n    }\n    throw HttpError(404, 'workspace not found for session ' + sessionId)\n  }\n\n  async function handleApi(ctx, req, res, url) {\n    const action = url.pathname.slice(apiPrefix.length)\n\n    // 配置路由（供 DSH 设置页调用；tokenless，仅读写本插件配置）\n    if (req.method === 'GET' && action === '/config') {\n      sendJson(res, 200, { ok: true, config: getCfg(), path: CONFIG_PATH })\n      return\n    }\n    if (req.method === 'POST' && action === '/config') {\n      const body = await requestJson(req)\n      const safe = {\n        baseUrl: typeof body.baseUrl === 'string' ? body.baseUrl : getCfg().baseUrl,\n        apiKey: typeof body.apiKey === 'string' ? body.apiKey : getCfg().apiKey,\n        pollMs: body.pollMs != null ? Number(body.pollMs) : getCfg().pollMs,\n        timeoutMs: body.timeoutMs != null ? Number(body.timeoutMs) : getCfg().timeoutMs,\n        canvasHome: body.canvasHome === 'sidebar' ? 'sidebar' : (body.canvasHome === 'tab' ? 'tab' : getCfg().canvasHome),\n        archiveRoot: typeof body.archiveRoot === 'string' ? body.archiveRoot.trim() : getCfg().archiveRoot,\n        models: body.models && typeof body.models === 'object' ? body.models : getCfg().models,\n        assetOverrides: body.assetOverrides && typeof body.assetOverrides === 'object' ? body.assetOverrides : getCfg().assetOverrides,\n        preferred: body.preferred && typeof body.preferred === 'object' ? body.preferred : getCfg().preferred,\n        tiers: body.tiers && typeof body.tiers === 'object' ? body.tiers : getCfg().tiers,\n        strategies: body.strategies && typeof body.strategies === 'object' ? body.strategies : getCfg().strategies,\n        strategyOf: body.strategyOf && typeof body.strategyOf === 'object' ? body.strategyOf : getCfg().strategyOf,\n      }\n      try {\n        mkdirSync(dirname(CONFIG_PATH), { recursive: true })\n        writeFileSync(CONFIG_PATH, JSON.stringify(safe, null, 2), 'utf8')\n        sendJson(res, 200, { ok: true, config: safe })\n      } catch (error) {\n        sendJson(res, 500, { ok: false, error: error?.message || String(error) })\n      }\n      return\n    }\n\n    // 归档搬迁：状态（配置 / 路径探测 / 索引 / 最近操作）与手动对账。\n    // tokenless，与 /config 同级：只读本插件配置 + 归档区，不读写会话数据。\n    if (req.method === 'GET' && action === '/archive/status') {\n      const cfg = getCfg()\n      const raw = cfg.archiveRoot || ''\n      const archiveRoot = normalizeArchiveRoot(raw)\n      const probe = archiveRoot ? await probeArchiveRoot(archiveRoot) : { configured: false, path: '', exists: false, writable: false, error: '' }\n      const index = archiveRoot ? await readArchiveIndex(archiveRoot) : { sessions: {} }\n      let archivedCount = 0\n      try { archivedCount = ctx.workspaceRegistry.archivedSessionIds.length } catch { /* 域未就绪 */ }\n      const entries = Object.values(index.sessions || {})\n        .sort((a, b) => String(b?.archivedAt || '').localeCompare(String(a?.archivedAt || '')))\n      sendJson(res, 200, {\n        ok: true,\n        config: { archiveRoot: raw, normalized: archiveRoot, valid: archiveRoot !== null },\n        probe,\n        archivedCount,\n        index: { count: entries.length, sessions: entries.slice(0, 50) },\n        recent: archiveRecent.slice(0, 20),\n      })\n      return\n    }\n    if (req.method === 'POST' && action === '/archive/sync') {\n      sendJson(res, 200, await reconcileArchive(ctx))\n      return\n    }\n\n    // 工作流注册表（tokenless，与 /config 同级：管理本地清单，不涉及会话数据）\n    // ?probe=0 跳过节点预检（可用性返回 null=未知），用于加速首屏。\n    if (req.method === 'GET' && action === '/workflows') {\n      const payload = await describeWorkflowsApi(getRegistry(), { probe: url.searchParams.get('probe') !== '0' })\n      sendJson(res, 200, payload)\n      return\n    }\n\n    if (req.method === 'POST' && action === '/workflows') {\n      const body = await requestJson(req)\n      let manifest = body\n      let todos = []\n\n      // 原始 ComfyUI 导出自动转换：body = { raw: {...nodes}, id, capability, displayName? }\n      if (body && typeof body === 'object' && body.raw && isRawComfyExport(body.raw)) {\n        const r = convertComfyExport(body.raw, { id: body.id, capability: body.capability, displayName: body.displayName })\n        if (!r.ok) { sendJson(res, 400, { ok: false, errors: r.errors }); return }\n        manifest = r.manifest\n        todos = r.todos\n      } else if (isLegacyWorkflowFormat(body)) {\n        sendJson(res, 400, { ok: false, errors: ['检测到旧版 ComfyUI「Save workflow」格式（nodes/links 数组）。请改用菜单里的「Export (API)」导出（{nodeId:{class_type,inputs}} 格式），再导入。'] })\n        return\n      } else if (isRawComfyExport(body)) {\n        sendJson(res, 400, { ok: false, errors: ['检测到 ComfyUI 原始导出（缺少 id/capability 字段）。请在导入时填写 id 与能力，或先运行 scripts/import-comfy.mjs 转换。'] })\n        return\n      }\n\n      // 档位声明（导入时选择档位 → 落盘约定 <组名>-<档位>）：字段为准，文件名只是约定\n      if (body && typeof body === 'object' && (body.tier || body.group || body.accel)) {\n        const tier = typeof body.tier === 'string' ? body.tier.trim() : ''\n        if (tier && !TIERS.includes(tier)) { sendJson(res, 400, { ok: false, errors: [`tier \"${tier}\" 不在档位词汇表（${TIERS.join('|')}）`] }); return }\n        const group = typeof body.group === 'string' && body.group.trim() ? body.group.trim() : (manifest.group || '')\n        if (tier) manifest.tier = tier\n        if (group) manifest.group = group\n        if (typeof body.accel === 'string' && body.accel.trim()) manifest.accel = body.accel.trim()\n        // 未显式给 id 时按约定合成 <组名>-<档位>[-加速]\n        if (!body.id && group && tier) manifest.id = `${group}-${tier}${manifest.accel ? '-' + manifest.accel : ''}`\n      }\n\n      const idOk = typeof manifest?.id === 'string' && /^[a-z0-9][a-z0-9._-]*$/.test(manifest.id)\n      if (!idOk) { sendJson(res, 400, { ok: false, errors: ['id 非法（仅小写字母/数字/._-，且字母或数字开头）'] }); return }\n      const v = validateManifest(manifest, manifest.id || 'workflow')\n      if (!v.ok) { sendJson(res, 400, { ok: false, errors: v.errors }); return }\n      mkdirSync(USER_WORKFLOWS_DIR, { recursive: true })\n      writeFileSync(join(USER_WORKFLOWS_DIR, manifest.id + '.json'), JSON.stringify(manifest, null, 2), 'utf8')\n      reloadRegistry()\n      sendJson(res, 200, { ok: true, id: manifest.id, todos })\n      return\n    }\n\n    if (req.method === 'DELETE' && action === '/workflows') {\n      const id = url.searchParams.get('id')?.trim()\n      if (!id || !/^[a-z0-9][a-z0-9._-]*$/.test(id)) { sendJson(res, 400, { ok: false, message: 'id 非法' }); return }\n      const file = join(USER_WORKFLOWS_DIR, id + '.json')\n      if (!existsSync(file)) { sendJson(res, 404, { ok: false, message: 'workflow not found (仅用户清单可删)' }); return }\n      await unlink(file)\n      reloadRegistry()\n      sendJson(res, 200, { ok: true })\n      return\n    }\n\n    requireToken(req, runtime)\n\n    // GET /canvas\n    if (req.method === 'GET' && action === '/canvas') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      // 已取消归档但画布还在归档区（NAS 回迁未完成）时先等回迁落位，避免用户看到空画布后又写出一份新工程。\n      await ensureArchiveRestored(ctx, root, sessionId).catch(() => {})\n      sendJson(res, 200, await loadProject(root, sessionId))\n      return\n    }\n\n    // POST /canvas/state（配置面板保存：乐观并发 expectedRev；返回 rev / 影响面）\n    if (req.method === 'POST' && action === '/canvas/state') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const patch = body.patch && typeof body.patch === 'object' ? body.patch : {}\n      try {\n        const r = await applyProjectConfig(root, sessionId, patch, { source: 'user', expectedRev: body.expectedRev })\n        sendJson(res, 200, r)\n      } catch (error) {\n        if (error?.code === 'CONFIG_REV_CONFLICT') {\n          sendJson(res, 409, { ok: false, message: error.message, settings: error.settings || {} })\n          return\n        }\n        throw error\n      }\n      return\n    }\n\n    // POST /canvas/node  (写入/更新节点，含文本编辑、分组、排序、状态)\n    if (req.method === 'POST' && action === '/canvas/node') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const project = await loadProject(root, sessionId)\n      const nodeId = typeof body.id === 'string' && body.id ? body.id : randomUUID()\n      const existingIdx = project.nodes.findIndex((n) => n.id === nodeId)\n      const prev = existingIdx >= 0 ? project.nodes[existingIdx] : null\n      // 配置卡写保护：内容/参数由 applyProjectConfig 维护，只允许改分组 / 排序 / 作废状态。\n      if (prev?.params?.configCard) {\n        if (body.content !== undefined && body.content !== prev.content) {\n          throw HttpError(400, '配置卡由系统维护：请用画布「⚙ 配置」或 canvas_set_state 修改')\n        }\n        const params = { ...(prev.params || {}) }\n        if (body.params && typeof body.params === 'object') {\n          if (body.params.deprecated) params.deprecated = true\n          else delete params.deprecated\n        }\n        const node = {\n          ...prev,\n          group: typeof body.group === 'string' ? body.group : prev.group,\n          order: typeof body.order === 'number' ? body.order : prev.order,\n          status: typeof body.status === 'string' ? body.status : prev.status,\n          params,\n        }\n        project.nodes[existingIdx] = node\n        await saveProject(root, sessionId, project)\n        sendJson(res, 200, { node })\n        return\n      }\n      const node = {\n        id: nodeId,\n        kind: ['text', 'table', 'image', 'video', 'audio'].includes(body.kind) ? body.kind : (prev?.kind || 'text'),\n        title: typeof body.title === 'string' ? body.title : (prev?.title || ''),\n        content: typeof body.content === 'string' ? body.content : (prev?.content || ''),\n        media: typeof body.media === 'string' ? body.media : (prev?.media || ''),\n        group: typeof body.group === 'string' ? body.group : (prev?.group || DEFAULT_GROUP),\n        params: body.params && typeof body.params === 'object' ? body.params : (prev?.params || {}),\n        status: typeof body.status === 'string' ? body.status : (prev?.status || 'ready'),\n        error: typeof body.error === 'string' ? body.error : (prev?.error || ''),\n        createdAt: prev?.createdAt || Date.now(),\n        order: typeof body.order === 'number' ? body.order : (prev?.order ?? nextOrder(project.nodes)),\n      }\n      if (existingIdx >= 0) project.nodes[existingIdx] = node\n      else project.nodes.push(node)\n      await saveProject(root, sessionId, project)\n      sendJson(res, 200, { node })\n      return\n    }\n\n    // POST /canvas/group\n    if (req.method === 'POST' && action === '/canvas/group') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const group = typeof body.group === 'string' ? body.group : ''\n      const ids = Array.isArray(body.nodeIds) ? body.nodeIds : []\n      const project = await loadProject(root, sessionId)\n      for (const n of project.nodes) if (ids.includes(n.id)) n.group = group\n      await saveProject(root, sessionId, project)\n      sendJson(res, 200, { ok: true })\n      return\n    }\n\n    // POST /canvas/reorder\n    if (req.method === 'POST' && action === '/canvas/reorder') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const ids = Array.isArray(body.nodeIds) ? body.nodeIds : []\n      const project = await loadProject(root, sessionId)\n      const byId = new Map(project.nodes.map((n) => [n.id, n]))\n      const ordered = []\n      for (const id of ids) { const n = byId.get(id); if (n) { ordered.push(n); byId.delete(id) } }\n      for (const n of project.nodes) if (byId.has(n.id)) ordered.push(n)\n      ordered.forEach((n, i) => { n.order = i })\n      project.nodes = ordered\n      await saveProject(root, sessionId, project)\n      sendJson(res, 200, { ok: true })\n      return\n    }\n\n    // DELETE /canvas/node?id=\n    if (req.method === 'DELETE' && action === '/canvas/node') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const id = url.searchParams.get('id')?.trim()\n      if (!id) throw HttpError(400, 'id required')\n      const project = await loadProject(root, sessionId)\n      const target = project.nodes.find((n) => n.id === id)\n      if (target?.params?.configCard) throw HttpError(400, '配置卡不能删除：请在画布「⚙ 配置」里改（改配置会同步更新本卡）')\n      const removed = project.nodes.filter((n) => n.id === id)\n      project.nodes = project.nodes.filter((n) => n.id !== id)\n      await saveProject(root, sessionId, project)\n      // 同步清理被删节点的媒体文件（参考图/首末帧等手动上传节点），避免画布残留孤儿文件\n      const mediaBase = join(root, CANVAS_DIR) + '/'\n      for (const n of removed) {\n        if (!n.media) continue\n        try {\n          const abs = join(root, ...String(n.media).split('/'))\n          if (abs.startsWith(mediaBase) && existsSync(abs)) await unlink(abs)\n        } catch (e) {\n          console.warn('[dsh-short-video-studio] 节点媒体文件清理失败:', n.id, e?.message || e)\n        }\n      }\n      sendJson(res, 200, { ok: true })\n      return\n    }\n\n    // GET /assets（资产库列表；老记录没有 kind 字段，这里补齐后再给前端）\n    if (req.method === 'GET' && action === '/assets') {\n      const { root } = resolveFromQuery(ctx, url)\n      const lib = loadLibrary(root)\n      // displayName / displayState 是给 UI 与 Agent 看的可读字段（老记录缺字段时从 id 兜底解析）\n      const assets = Object.values(lib.assets).map((a) => ({\n        ...a, kind: assetKind(a), displayName: assetDisplayName(a), displayState: assetDisplayState(a),\n      }))\n      sendJson(res, 200, { ok: true, assets })\n      return\n    }\n\n    // POST /assets（把画布节点一键入库：图片/视频拷文件，text/table 存正文）\n    if (req.method === 'POST' && action === '/assets') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const project = await loadProject(root, sessionId)\n      const n = project.nodes.find((x) => x.id === body.nodeId)\n      if (!n) throw HttpError(404, '画布节点不存在: ' + (body.nodeId || '(空)'))\n\n      const kind = NODE_KINDS[n.kind]\n      if (!kind) throw HttpError(400, `该节点类型不可入库（${n.kind || '未知'}）：只有 image / video / text / table 可以`)\n      const allowed = assetTypesForKind(kind)\n      const type = body.type || allowed[0]\n      if (!allowed.includes(type)) {\n        throw HttpError(400, `载体为 ${kind} 的节点只能用这些资产类型：${allowed.join(' / ')}`)\n      }\n\n      // 显示名是自由文本（不再是 id 的一部分）；没填就用节点标题 slug 一版兜底\n      let name = normalizeDisplayName(body.name)\n      if (!name) name = normalizeDisplayName(slugifyName(n.title || ''))\n      if (!name) throw HttpError(400, '请提供显示名（支持中文 / 英文 / 拼音，如 小狐狸 / luna）')\n\n      let srcAbs = null\n      if (kind === 'text') {\n        if (!n.content) throw HttpError(400, '节点没有文本内容')\n      } else {\n        if (!n.media) throw HttpError(400, '节点无媒体文件')\n        srcAbs = join(root, ...String(n.media).split('/'))\n        if (!existsSync(srcAbs)) throw HttpError(404, '媒体文件不存在')\n      }\n\n      const lib = loadLibrary(root)\n      // 唯一性只看「类型 + 显示名」（state 不参与）：同名即更新同一资产，沿用旧 id、保留 createdAt。\n      // 这样重出角色卡后再入库仍是同一个引用；没有命中才新建随机 id。\n      // UI 入库表单不填 state，所以同名更新时保留原资产的状态，不要被默认值冲掉。\n      const existingId = findAssetByLabel(lib, type, name)\n      const state = normalizeDisplayName(body.state)\n        || (existingId ? assetDisplayState(lib.assets[existingId]) : 'default')\n      // registerAsset 抛的是普通 Error（纯模块，不依赖 HttpError），转成 400 给出原因分类。\n      let rec\n      try {\n        const id = existingId || newAssetId(lib, type)\n        const meta = { sourceSession: sessionId, sourceNode: n.id }\n        if (n.params?.seed !== undefined && n.params?.seed !== null) meta.seed = n.params.seed\n        if (n.params?.prompt) meta.prompt = n.params.prompt\n        // 角色卡双版本：把配对元数据带进资产库，跨会话显式 ref_variant 才能换到同角色目标版本\n        if (n.params?.character) meta.character = String(n.params.character)\n        if (n.params?.cardVariant === 'single' || n.params?.cardVariant === 'three') meta.cardVariant = n.params.cardVariant\n        if (body.tags) meta.tags = body.tags\n        if (body.speaksOnScreen !== undefined) meta.speaksOnScreen = Boolean(body.speaksOnScreen)\n\n        rec = registerAsset(root, lib, {\n          id, type, name, state, srcAbsPath: srcAbs, meta,\n          text: kind === 'text' ? n.content : undefined,\n          title: n.title,\n          nodeKind: n.kind,\n        })\n      } catch (e) {\n        throw HttpError(400, e?.message || String(e))\n      }\n      sendJson(res, 200, { ok: true, id: rec.id, kind: rec.kind })\n      return\n    }\n\n    // DELETE /assets?id=xxx（从库里删除；它留下的文件在没有别的记录引用时一并清理）\n    if (req.method === 'DELETE' && action === '/assets') {\n      const { root } = resolveFromQuery(ctx, url)\n      const id = (url.searchParams.get('id') || '').trim()\n      if (!id) throw HttpError(400, 'id 必填（如 character:luna）')\n      const lib = loadLibrary(root)\n      const r = removeAsset(root, lib, id)\n      if (!r.removed) throw HttpError(404, '资产不存在: ' + id)\n      sendJson(res, 200, { ok: true, id: r.id, fileDeleted: r.fileDeleted })\n      return\n    }\n\n    // POST /assets/rename（重命名：只改显示名，id 与所有引用不变；state 仅作 API 兼容）\n    if (req.method === 'POST' && action === '/assets/rename') {\n      const { root } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const rawId = typeof body.id === 'string' ? body.id.trim() : ''\n      if (!rawId) throw HttpError(400, 'id 必填')\n      const lib = loadLibrary(root)\n      let r\n      try {\n        r = renameAsset(root, lib, rawId, {\n          name: typeof body.name === 'string' ? body.name : undefined,\n          state: typeof body.state === 'string' ? body.state : undefined,\n        })\n      } catch (e) {\n        const status = e?.code === 'ASSET_NOT_FOUND' ? 404 : e?.code === 'ASSET_EXISTS' ? 409 : 400\n        throw HttpError(status, e?.message || String(e))\n      }\n      sendJson(res, 200, { ok: true, ...r })\n      return\n    }\n\n    // POST /canvas/upload（画布手动添加资产：本地图片 → 资产卡；JSON 带 base64 dataURL）\n    if (req.method === 'POST' && action === '/canvas/upload') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req, 64 * 1024 * 1024)\n      const files = Array.isArray(body.files) ? body.files.slice(0, UPLOAD_MAX_FILES) : []\n      if (!files.length) throw HttpError(400, 'files 为空（最多 ' + UPLOAD_MAX_FILES + ' 个媒体文件）')\n      const group = typeof body.group === 'string' && body.group.trim() ? body.group.trim() : DEFAULT_GROUP\n      const added = []\n      const errors = []\n      for (const f of files) {\n        try {\n          const node = await importManualImage(root, sessionId, f, group)\n          added.push({ id: node.id, title: node.title, media: node.media })\n        } catch (error) {\n          errors.push({ filename: (f && f.filename) || '', message: error?.message || String(error) })\n        }\n      }\n      if (!added.length) throw HttpError(400, '没有可用媒体：' + errors.map((e) => e.message).join('；'))\n      sendJson(res, 200, { ok: true, added, errors })\n      return\n    }\n\n    // POST /assets/to-canvas（把资产库中的资产物化到当前画布，带缩略图取用）\n    if (req.method === 'POST' && action === '/assets/to-canvas') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      if (!body.id || typeof body.id !== 'string') throw HttpError(400, 'id 必填（如 character:luna）')\n      const node = await copyAssetToCanvas(root, sessionId, body.id, {\n        title: typeof body.title === 'string' ? body.title : undefined,\n        group: typeof body.group === 'string' ? body.group : undefined,\n        nodeId: typeof body.nodeId === 'string' ? body.nodeId : undefined,\n      })\n      sendJson(res, 200, { ok: true, nodeId: node.id, media: node.media, title: node.title })\n      return\n    }\n\n    // POST /canvas/node/replace-image（画布卡「编辑 → 本地上传替换图片」）\n    if (req.method === 'POST' && action === '/canvas/node/replace-image') {\n      const { root, sessionId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req, 64 * 1024 * 1024)\n      if (!body.nodeId) throw HttpError(400, 'nodeId 必填')\n      const r = await replaceNodeImage(root, sessionId, body.nodeId, { filename: body.filename, dataUrl: body.dataUrl })\n      sendJson(res, 200, { ok: true, nodeId: r.node.id, media: r.node.media, prevAssetId: r.prevAssetId || '', assetIdCleared: r.assetIdCleared })\n      return\n    }\n\n    // POST /generate/image\n    if (req.method === 'POST' && action === '/generate/image') {\n      const { root, sessionId, workspaceId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      // HTTP 入口不走 tools/pre-execute：用同一份 configIssuesFor 规则兜底。\n      const gateIssues = configIssuesFor(await loadProject(root, sessionId), 'image', body)\n      if (gateIssues.length) throw HttpError(403, '配置门未通过：' + gateIssues.join('；'))\n      const r = await runRender(ctx, { ...body, capability: 'image.text2image', sessionId, workspaceId, exec: null })\n      sendJson(res, 200, r)\n      return\n    }\n\n    // POST /generate/video\n    if (req.method === 'POST' && action === '/generate/video') {\n      const { root, sessionId, workspaceId } = resolveFromQuery(ctx, url)\n      const body = await requestJson(req)\n      const capability = body.type ? VIDEO_SHAPES[body.type]?.capability : null\n      if (!capability) throw HttpError(400, `type 必须显式声明且合法（${Object.keys(VIDEO_SHAPES).join(' / ')}）`)\n      const gateIssues = configIssuesFor(await loadProject(root, sessionId), 'video', body)\n      if (gateIssues.length) throw HttpError(403, '配置门未通过：' + gateIssues.join('；'))\n      const r = await runRender(ctx, { ...body, capability, sessionId, workspaceId, exec: null })\n      sendJson(res, 200, r)\n      return\n    }\n\n    throw HttpError(404, 'unknown canvas api route: ' + action)\n  }\n\n  // 媒体伺服（token 走 query，便于 <img>/<video> 直接加载）\n  // 两种来源：path=canvas/<sessionId>/…（画布媒体）；asset=<id>（跨会话资产库图，供缩略图预览）\n  async function handleMedia(ctx, res, url) {\n    if (url.searchParams.get('token') !== runtime.token) throw HttpError(403, 'unauthorized')\n    const { root } = resolveFromQuery(ctx, url)\n    const assetId = url.searchParams.get('asset')?.trim()\n    let target\n    if (assetId) {\n      const lib = loadLibrary(root)\n      // 用 resolveAssetPath（任意 kind）而不是 resolveAssetImagePath：\n      // 视频资产走 <video src=\"/media?asset=clip:xxx\">，只认图片会让它 404。\n      const abs = resolveAssetPath(root, lib, canonicalAssetId(assetId))\n      if (!abs) throw HttpError(404, 'asset file not found: ' + assetId)\n      target = abs\n    } else {\n      const path = url.searchParams.get('path')?.trim()\n      if (!path) throw HttpError(400, 'path required')\n      const rel = safeRelative(path, CANVAS_DIR)\n      target = resolve(root, rel)\n      if (!inside(root, target)) throw HttpError(403, 'path escapes workspace')\n    }\n    const canonical = await realpath(target).catch((e) => { if (errorCode(e) === 'ENOENT') throw HttpError(404, 'media not found'); throw e })\n    if (!inside(root, canonical)) throw HttpError(403, 'symlink escapes workspace')\n    const info = await stat(canonical)\n    if (!info.isFile()) throw HttpError(400, 'not a file')\n    res.writeHead(200, { 'content-type': contentType(canonical), 'content-length': info.size, 'cache-control': 'no-store' })\n    createReadStream(canonical).pipe(res)\n  }\n\n  // 静态 studio\n  async function handleStatic(res, url) {\n    let requested = url.pathname.slice(ROUTE_ROOT.length).replace(/^\\/+/, '')\n    if (requested === '') requested = 'index.html'\n    const file = resolve(runtime.studioRoot, requested)\n    if (!inside(runtime.studioRoot, file)) throw HttpError(403, 'asset path escape')\n    const info = await stat(file).catch((e) => { if (errorCode(e) === 'ENOENT') throw HttpError(404, 'studio asset not found'); throw e })\n    if (!info.isFile()) throw HttpError(404, 'studio asset not found')\n    if (basename(file) === 'index.html') {\n      const html = (await readFile(file, 'utf8')).replace('__DSH_SVS_TOKEN_VALUE__', runtime.token)\n      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(html), 'cache-control': 'no-store', 'x-content-type-options': 'nosniff' })\n      res.end(html)\n      return\n    }\n    // 开发期反复改 app.js/app.css，用 no-cache 让浏览器每次重验，避免旧代码被 immutable 永久缓存\n    res.writeHead(200, { 'content-type': contentType(file), 'content-length': info.size, 'cache-control': 'no-cache' })\n    createReadStream(file).pipe(res)\n  }\n\n  return { apiPrefix, handleApi, handleMedia, handleStatic }\n}\n\nfunction requireToken(req, runtime) {\n  if (req.headers['x-dsh-svs-token'] !== runtime.token) throw HttpError(403, 'unauthorized')\n}\n\n// ---------------------------------------------------------------------------\n// systemPrompt 段\n// ---------------------------------------------------------------------------\n\nconst GUIDANCE = `本机已安装 dsh-short-video-studio 插件（短剧/动画画布工作室）。它给每个会话提供一个「画布」视图 tab，并把生成请求经「能力注册表」派发到本地 ComfyUI（http://localhost:8188）执行。用户提到「画布/短剧/动画短片/故事转视频/卡通短片」时即指本插件。\n\n## 基本约定\n- **只表达能力与档位，不写死模型/工作流**：capability（image.text2image / video.reference2video / ...）+ tier（fast/balanced/quality）由注册表按**配置**解析到具体实现；实现可随时增删替换。勿在 prompt、流程或对话里出现工作流 id 或模型名；换实现是配置面的事（设置页）。\n- **耐用产物必须落画布**：简报/大纲/角色卡/场景卡/镜头表/分镜/片段都要写成画布节点，不要只留在对话里。\n- **角色卡出两版（先三视图、再裁正面当单视图）**：每角色先出「三视图」卡（card_variant=three，16:9 横排），再用 **image_crop(image_node=<三视图>, panel=0, panels=3, card_variant=single, paired_node_id=<三视图>) 裁正面格当「单视图」卡**——裁切是纯像素操作，两版同源、身份按构造一致（同 character + cardVariant=single|three 互记 pairedNodeId）。尺寸：三视图 = 图片档位长边 × 16:9（1024×576 / 1344×768 / 2048×1152），单视图 = 正面格（341×576 / 448×768 / 682×1152，比例 ≈0.59，**不要再按旧 2:3 尺寸单独生成单视图**）。三视图不过自检就重出三视图再重裁；单视图边缘带进旁格内容就只调裁切矩形重裁。**视频引用哪一版由 STEP 0 用户选择**（canvas_set_state(characterCardVariant=single|three)）：项目档位 fast 只能选 single；balanced/quality 可选 single 或 three。**工具不按 tier 自动选版**——每镜必须显式传 ref_variant=single|three（fast 镜强制 single）。非 fast 档成片自检发现参考图形态类污染（多角色副本 / 文字或版面被投影 / 环境材质被替换）时，传 ref_variant=single 重渲本镜。\n- **分辨率由画布 settings.aspectRatio × 档位长边推导**（snap32），支持 16:9 / 9:16 / 1:1 等任意比例；显式传 width/height 可覆盖（只传一边时另一边按画布比例补出来）。**图片与视频同一套规则**：图片 fast/balanced/quality 长边 1024/1344/2048，视频 fast/balanced/quality 长边 832/1344/1344（各档实际值以 comfy_list_workflows 为准）。**例外**：若该档解析到的实现**锁定了自己的原生分辨率**，则显式宽高与画布比例都不生效（交付尺寸由该实现决定，通常大于采样尺寸），工具会返回一条 warnings 说明——**照实回报，别声称用了请求的尺寸**。\n- **视频工作流是 AV 模型**：默认带声音，且支持画面内原生字幕——把字幕要求写进 video prompt 末尾即可，无需后期叠加。\n- **失败不要重复提交未改动的同一请求**：先改锚点/缩时长/降档/简化动作再重试。\n\n## 工具契约\n- comfy_list_workflows()：列出**能力 → 档位**（每档的可用性、交付尺寸、实测耗时）。换实现前先调它核对「这个能力有哪些档」。**不要**向用户或流程暴露具体工作流 id——实现是配置面的事（诊断字段仅供排障）。\n- comfy_render(capability, tier?, prompt?, prompt_node?, persist_prompt?, width?, height?, length?, duration?, lyrics?, cfg?, seed?, steps?, guidance?, count?, ref_nodes?, ref_variant?, audio_ref_nodes?, first_frame_node?, last_frame_node?, continuity_from?, title?, group?, nodeId?)：通用渲染入口（模型/实现无关）。capability ∈ image.text2image / image.image2image / video.reference2video / video.image2video / video.upscale / audio.music / ...；audio.music 用 duration（秒）而不是 length（帧）；**实现由配置解析**（设置页的档位选择 / cfg.preferred 家族 / cfg.pins），调用方只传 tier（缺省 quality）。**不接受 workflow=**——传了会报错。\n- comfy_generate_image(prompt, tier?, width?, height?, seed?, steps?, guidance?, count?, character?, card_variant?, paired_node_id?, title?, group?, nodeId?)：文生图别名（= comfy_render capability=image.text2image），写入画布，返回节点 id + 媒体相对路径。角色卡/场景卡/铅笔分镜用它；**抽卡迭代用 tier=fast/balanced，定稿用 quality**。角色卡两版分两次调用：card_variant=single / three，第二张传 paired_node_id=第一张 id 建立配对。\n- comfy_generate_video(prompt?, prompt_node?, type, tier?, persist_prompt?, ref_nodes?, ref_variant?, audio_ref_nodes?, first_frame_node?, last_frame_node?, continuity_from?, width?, height?, length?, seed?, steps?, title?, group?, nodeId?)：单镜头视频别名。**type 必填**（type=形状=条件路径，不再由「传没传首帧」隐式推断）：\n  - prompt 与 prompt_node 二选一：传 prompt_node 时按 tier 从分档提示词库读取（缺该档回退最近档并 warnings）；不传 prompt_node 时传 prompt 即可，工具会自动把本次 prompt 持久化进该镜头的提示词库节点（可用 persist_prompt=false 关闭），返回 promptNodeId。\n  - type=r2v（参考绑定）：用 ref_nodes=[角色卡, 场景卡] 绑定身份/环境；**角色卡版本由 STEP 0 选择驱动**——每镜显式传 ref_variant=single|three（fast 镜强制 single；balanced/quality 按 state.characterCardVariant），不传则原样使用传入的卡。带 character/cardVariant/pairedNodeId 的卡会被换成同角色对应版本。**不许传** first_frame_node/last_frame_node（以前会被静默忽略，现在直接报错）；不传 ref_nodes 仍可跑（纯文本生成）但会给警告。\n  - type=i2v（首/末帧串联）：必须传 first_frame_node（可选 last_frame_node）；**不许传** ref_nodes（身份由首帧继承）。\n  - audio_ref_nodes（参考音频，仅 r2v）：≤3 段，每段 2–15s、总 ≤15s、单文件 ≤15MB；传画布音频节点 / 画布视频节点（取音轨）/ voice:（音频资产）/ clip:（视频资产）。**必须同时传 ref_nodes**（官方要求音频伴随视觉输入）。传了它 prompt 里要写 「<Audio 1> is the voice-timbre reference for <Subject 1> (S1).」+「<Audio 1>: reference - …」，否则会给「参考可能只被当环境音」警告。fast 档是 4 步 turbo，官方说明会削弱参考/音频强度，要稳声线用 balanced/quality。2K/hires 实现暂不支持（显式报 audio-ref-unsupported）。\n  - 形状与「续接」正交：continuity_from=上一镜画布视频节点 id → **链式续接**（消费上一镜的服务端 latent：画面逐帧钉住它的结尾、音频从接缝继续，实测接缝画面差 2.6–7.0 vs 无续接对照 32–68）。**跨形状续接允许**（上一镜 r2v、本镜 i2v + continuity_from），两种形状都有支持续接的实现，用「comfy_list_workflows」查当前哪些可用。注意续接要求**选中的实现支持续接**（不支持时报「上一镜没有链式序号」，意思是上一镜用的实现不支持）。length 是**交付帧数**（续接实现会自己多采、裁掉继承帧，你按交付时长填即可）。mode=quality(成片)/fast(调试快)。**分辨率由画布 aspectRatio 推导（支持 16:9/9:16/1:1 等任意比例），显式传 width/height 可覆盖**。length 为 24fps 帧数（124≈5s）。\n- comfy_generate_music(prompt, duration?, lyrics?, seed?, steps?, cfg?, title?, group?, nodeId?)：用注册表解析的 audio.music 实现生成 BGM（当前 = 本地 MiniMax Music 3）。duration 为秒（1–360，缺省 30）；纯器乐在 prompt 写 instrumental / no vocals 且 lyrics 留空；产物是画布音频节点（44.1kHz 立体声）。触发词：BGM/配乐/背景音乐。\n- extract_frame(video_node, frame_index?, title?, group?, nodeId?)：从画布视频节点抽一帧存为图片节点（frame_index 负数从末尾数，-1=末帧默认，0=首帧）。抽出的图片节点可直接作 first_frame_node / last_frame_node。\n- image_crop(image_node, panel?, panels?, x?, y?, width?, height?, character?, card_variant?, paired_node_id?, title?, group?, nodeId?)：**纯像素裁切**（不重绘、不采样、无提示词），从画布图片节点或图片资产裁出一块，写成新的图片节点。默认按面板均分：panels=3 + panel=0 ⇒ 三视图的左侧正面格（角色卡「单视图」就是这么来的）。裁切矩形自动夹进源图边界；角色卡元数据（character / card_variant / paired_node_id）与 comfy_generate_image 同一套键、双向配对。\n- extract_audio(video_node, title?, group?, nodeId?)：从画布视频节点抽音轨存为音频节点（可作 audio_ref_nodes 的声线参考）。有 ffmpeg 走 ffmpeg，否则走 ComfyUI LoadVideo→GetVideoComponents→SaveAudio。\n- canvas_record_check(nodeId, verdict: pass|fail, frames?, checks?, notes?)：记录某镜头的自检结论（写 params.selfCheck）。**逐镜自检门的放行凭据**：视频产物渲完默认「待自检」，必须 extract_frame 抽帧核对 + canvas_record_check(verdict=\"pass\") 后才允许生成下一镜；pass 必须至少有一张抽帧证据（extract_frame 产物）。**checks 把门 3 六项落成结构化结论**：plan / character / lipsync / subtitle / contamination / audio / style → pass|fail|na（audio 由人工听核写 na；silent 镜 lipsync/subtitle 可 na）；verdict=pass 时任何 fail 会被拒绝。重渲同一 nodeId 不受限；video_concat / video_upscale 是后处理，不受此门约束。\n- canvas_approve(target: assets|shotTable|storyboard|clips, nodeIds?, nodeId?, note?)：记录**用户已人工批准**某阶段产物（写 project.approvals），是创作批准门的放行凭据。assets=角色卡/场景卡/道具卡锁定（每张/每组一次）；shotTable=七列镜头表批准（先跑 STEP 5.5 并在表顶写「shot-table self-check: passed」）；storyboard=分镜批准；clips=门 3 片段批准（per-shot 逐镜 / batch 批量，节点须已 canvas_record_check pass）。未调用时：生成新卡、写七列镜头表、生成 Sxx 视频、video_concat 都会被 pre-execute 门 deny。批准按配置 breakingRev 失效；重出卡/改表/改分镜/重渲片段会失效对应批准。\n- video_interpolate(video_node, target_fps?, multiplier?, tier?)：把画布上一个已生成的片段补帧到更高帧率（48/60fps），时长与音轨不变。整数倍（48/72/96）纯 ComfyUI；非整数倍（60/30）先出整数倍母版再由 ffmpeg 抽取（需本机 ffmpeg）。**逐镜补、不要对成片补**（硬切处会生成两场之间的形变帧）；成片里混不同帧率会被 video_concat 直接拒绝。\n- video_regenerate(video_node, prompt?, target?, handoff?, start_sigma?, steps?, tier?, seed?)：把画布上一个**已生成的 768p 片段**在目标分辨率上**重新生成**（1080p / 2K；**会重画内容，不是超分**）。**handoff=auto|latent|video**（缺省 auto）：源节点有可用 draft latent（balanced 档渲染会自动存一份）就走 latent、无 mp4 往返；没有/不合法就退回视频入口，返回里 handoff / handoffReason 写明实际走了哪条——强制 latent 不满足会直接报错。提示词缺省沿用源节点记录的 prompt（外部导入/拼接成片必须显式传）；源音轨原样接回（不参与重采样）、帧数与源片一致；目标网格由实现声明、竖屏自动翻转。源片护栏：24fps、约 121–362 帧、必须有提示词——不满足直接报错，不要硬跑。**产物必须抽帧核对身份/口型**（start_sigma 0.8 更贴草稿但细节少）；要保内容的放大请用 video_upscale。\n- video_concat(nodes[], title?, group?, nodeId?)：把画布上的多个视频节点按给定顺序拼接成完整成片（含音轨），产物写回画布。后端自动选择：有 ffmpeg 走 ffmpeg（零重编码），否则走 ComfyUI 纯节点链路。拼接本身只做硬切；跨场景过渡应由「转场镜」承担（extract_frame 抽前一镜末帧 + 后一镜首帧 → comfy_generate_video 首末帧生成一个短过渡镜，当普通片段参与拼接）。\n- canvas_list_nodes / canvas_write_node(kind: text|table, title, content, group) / canvas_get_node / canvas_group_nodes / canvas_reorder / canvas_get_state / canvas_set_state：读写画布与项目设置（canvas_set_state 支持 flow / aspectRatio / duration / audioMode / mode / imageTier / delivery / characterCardVariant / voicePlan / subtitles / language / style / bgmMode / reviewMode / shotGate=verdict|frames|off / groupOrder）。所有耐用产物都要落到画布。\n- **项目配置卡（STEP 0 的结构化真相源）**：canvas_set_state 一次写全后，插件自动建/更新画布「项目配置」卡（group=项目配置，含 rev 与来源）。用户可在画布「⚙ 配置」里改；改完后续生成按新配置走。**生成前有配置门**：未建卡时首次生成会被拒一次（先 canvas_set_state 建卡）、显式 width/height 与画幅不一致、fast+三视图、配置=单视图却引用三视图卡都会被 deny。不要用 canvas_write_node 直接改配置卡（会被拒绝）。\n- canvas_write_prompt_bank(title, prompts:{fast?,balanced?,quality?}, group?, promptFor?, note?, nodeId?) / canvas_get_prompt(nodeId, tier?)：读写提示词库（每镜一份，## fast/balanced/quality 分段）。当前 story/brand 策略是三段同文（共用 quality 提示词）；工具仍按 tier 取段、生成后自动回写，换档重渲复用同一节点。\n- **分组是自由字符串**：group 由流程 skill 自行定义，插件不预设任何片型词汇（缺省 ungrouped）。用 canvas_set_state(groupOrder=[...]) 一次性声明分组展示顺序，画布即按此顺序渲染；未列出的分组排在其后、按首次出现顺序。\n- asset_list(type?, query?)：列出跨会话资产库中已入库的素材（角色卡/场景卡/风格锚点/视频片段/文本，返回稳定资产 id：新入库形如 character:<16 位 hex>，老资产可能是 character:luna）。\n- asset_to_canvas(id, title?, group?)：把资产物化为当前会话画布节点（复用卡片也要在画布出现）。返回节点 id。\n- asset_ingest(approvalNodeId, items[], allowOverwrite?)：**系列模式**下，用户批准清单后由 AI 把节点/文件登记进资产库（默认不覆盖同名；覆盖需 allowOverwrite=true 且 version+1）。单项目不要调用。\n\n## 提示词分档持久化（prompt bank）\n- **每个镜头一份提示词库节点**（文本，标题如「S01 提示词（分档）」）：用 canvas_write_prompt_bank 写入 fast / balanced / quality 三段。**当前 story/brand 片型策略：三段写同一份完整 quality 提示词（逐字一致）**，换档只变采样；工具本身仍支持三段不同内容。\n- **生成时优先传 prompt_node**（不传 prompt）：工具按本次实际 tier 取对应段；三段同文时读到的都是同一份 quality 文本。缺该档仍会自动回退到最近档并在 warnings 说明。生成后工具把本次实际 prompt 回写该档段（幂等）。\n- **换档重渲直接复用同一个 prompt_node + 新 tier**（或复用同一个视频 nodeId / 同标题且不传 prompt，工具会读回该镜提示词库）；不要把旧 prompt 手抄到新调用里。\n- 只传 prompt 也能用：视频工具会自动创建/更新该镜头的提示词库节点（persist_prompt:false 可关闭），返回的 promptNodeId 就是后续换档要传的节点 id。\n\n## 参考图硬规则（实测，适用于任何 ref_nodes / first_frame_node 用法）\n- **角色卡双版本（形态按档位选用）**：每个角色都出**两版**——single 单视图正面全身（一图一人、纯底、零文字）与 three 三视图横排（正 / 侧 / 背全身，1×3、纯底、零文字）。两版共享同一份角色设定与风格锁，节点用 character / cardVariant / pairedNodeId 配对。\n  - **视频引用哪一版由 STEP 0 用户选择**（canvas_set_state(characterCardVariant=single|three)）：项目档位 fast 只能单视图（多主体参考图会出角色副本 / 内容被投影成背景 / 环境材质被替换）；balanced / quality 可选单视图或三视图。每镜显式传 ref_variant=single|three（fast 镜强制 single；不传时工具按画布配置注入），工具不按 tier 自动选版。\n  - **非 fast 档的回退规则**：生成后自检若发现「参考图形态类」问题（多出角色副本、参考图的版面 / 文字被印进画面、环境被参考图内容替换），**先传 ref_variant=single 重渲本镜**（或把 ref_nodes 换成同角色单视图卡；同 prompt / 同 seed 优先），再走 prompt 修复；仍不过才走失败梯度。不要用 prompt 声明「只出现一只」来压——实测无效。\n  - **场景卡与道具卡仍只出单视图**（不随档位改形态）。在 prompt 里声明「同一角色多角度、只出现一只」**经实测完全无效**——只能从参考图形态或档位下手。⇒ **「fast」 档对进 「ref_nodes」 的参考图有形态门禁**（单主体 / 单视图 / 零文字 / 无拼图），片型 skill 须按**每次调用实际传入的 tier**（不是开场那一次选择）在渲染前判定；「balanced」 / 「quality」 不受此门禁限制。档位解析到哪个实现由配置决定，改配置后本结论需重新取证。\n- **图内零文字**：参考图上的角色名、「正面/侧面/背面」、FRONT VIEW 之类标注、水印，会被视频模型当成「该出现在画面里的内容」印进成片，标注越清晰烙印越重——「fast」 档尤甚（文档类参考图会以墙面投影的形式把文字烙进画面）。文字信息只写画布节点标题或资产库元数据。\n- **多角度信息来源**：单张正面卡已足以支撑转身/走远等镜头；非「fast」档直接用三视图横排卡即可，需要更多角度时把多张图分别放进不同 ref_nodes 槽位，**绝不临时拼成一张图**（拼图会同时改变形态与档位风险）。\n- **first_frame_node 只用于同场景续接镜**（改善过渡）；跨场景只传角色卡 + 场景卡，不带上一镜末帧。\n- **同场景续接优先用 continuity_from（链式续接）而不是 first_frame_node**：前者把上一镜的 latent 逐帧钉进新镜、音频也接着走，接缝几乎看不出来；后者只是拿一张静帧当首帧，模型仍要重新猜运动与声音。链的硬约束：① **首次续接的上一镜必须也是支持续接的实现渲染的**（否则报「上一镜没有链式序号」）——另起一镜就用普通实现；② 一条链内**采样尺寸必须一致**（＝采样器实际跑的尺寸，**不是交付尺寸**——链上流动的是采样 latent，不能缩放）；普通实现的采样尺寸＝交付尺寸，而两阶段放大类实现两者不同 ⇒ **交付尺寸可以不同**（同档的普通实现与放大实现能互接）；③ 跨场景不要续接，直接换镜。\n- **入库默认由用户人工完成**：单项目/未批准场景，跨会话入库必须由用户在画布点该卡的「入库」按钮（图片/视频/文本节点均可），AI 不代劳。**系列模式例外**：用户先批准一份「入库清单」（画布文本节点，正文含 asset-ingest-approved 与每个 nodeId/srcPath/name），AI 才可调用 asset_ingest 执行登记；未批准条目不得入库。**系列模式资产生成完必须主动出「资产总览卡」让用户审核并询问是否入库；批准后由 AI 调 asset_ingest，禁止提示「AI 不代劳 / 请自己点入库」。**新会话先 asset_list 查库，命中就用 asset_list 返回的资产 id 直接复用（**新入库的 id 形如 character:<16 位 hex>；老资产可能仍是 character:luna 这类可读 id**，一律以返回值为准）；**只有图片类资产能作 ref_nodes**，视频/文本资产只能物化回画布当素材或参考。**资产库对话框里用户还能重命名 / 删除**：重命名只改**显示名**（同类型内唯一；state 是历史字段，界面不再提供编辑），**资产 id 永久不变、所有画布与历史对话里的引用继续有效**——不要因为用户改名就去找新 id，继续用原 id 即可。\n\n## 渠道交付（TUI / 飞书）\n- 「画布」tab 只在 Web 可见；TUI / 飞书看不到画布，产物要主动送达用户，不能只报一句媒体路径。\n- **ask 前自动送达（飞书）**：插件会在每次「ask_user_question」执行前，自动把画布中未送达的产物经「send_file」发到飞书——媒体文件（图片/视频/音频）直接发；文本/表格节点已自动导出为 .pdf 一并送达（puppeteer/Chrome 渲染，飞书可直接预览；本机无 PDF 工具时兜底 .html）。**发送的文件名取自节点标题**（如 主角卡.png、简报.pdf、S01-片段.mp4），不再是内部 id。**不要手动调「send_file」**，避免与自动送达重复。群聊会先弹审批卡、再出选项卡，均由用户在飞书确认，照常调用即可。\n- **文本同时进回复**：简报/大纲/镜头表/分镜等文本节点除 .html 文件外，把要点写进助手回复，飞书回复本身即可读。\n- **没有 send_file（Web / TUI）**：无自动送达，产物已在画布/工作区；TUI 用户按工具返回的 absPath 自行打开。\n- send_file 有单文件上限（默认 20 MiB，可配）：自动送达失败的产物会在画布节点「params.deliveryError」记录原因（可用「canvas_get_node」查看），下次 ask 前会自动重试；若用户反馈未收到，改用 fast 档 / 更短镜头 / 分镜分开发，或提示用户到画布取。\n\n## 生产流程\n**创作批准门（代码强制，story/series）**：project.approvals 是「用户已人工确认」的唯一凭据（由 canvas_approve 写入）。四道校验：① 出新角色卡前，同项目其他角色卡未批准会被拒；② 出场景/道具卡前，角色卡未批准会被拒；③ 写七列镜头表前，资产卡未全部批准会被拒；④ 渲 Sxx 视频前，资产（若已有卡）/镜头表（若已有表，且表顶有 shot-table self-check: passed 戳）/分镜（若已有分镜节点）都必须已批准；⑤ video_concat 前，所有输入镜头必须已在 approvals.clips。**本门没有连续 deny 降级**；批准按 settings.breakingRev 失效，重出卡/改表/改分镜/重渲片段会让对应批准失效，破坏性配置变更清空全部批准。整体关闭：DSH_SVS_APPROVAL_GATE=off。\n**镜头表一致性门（代码强制，先于生成）**：视频生成前，插件按 title 里的 Sxx 在画布七列镜头表里找该行，校验：prompt 里台词 / 字幕与表**逐字一致**、length/24 与表时长一致（±1s）、audio_ref_nodes 与「声线参考」一致、显式 width/height 与画布 aspectRatio 一致、fast 档不得用三视图卡（ref_variant=three 或直接传 three 卡）。不一致会 deny 并列出差异；同一 agent 连续 deny 2 次后降级放行。转场镜（标题含「转场」/「→」）、锚点式重渲（标题含「锚点」）、试镜片段、无 Sxx 标题不参与。⇒ 每镜 title 必须带镜头号（如「S03 片段」），且**新镜 / 拆镜必须先写进镜头表再渲**。\n\n**制片门（代码强制，仅系列项目）**：workspace 里有 \\`series/production-state.json\\` 时，视频生成前会校验 \\`state.episodes[ep]\\` 的 \\`stage\\`（必须在 shotlist/clips/final/delivered）、\\`gate.package.status==='approved'\\`（G-P 方案卡批准留痕）、包与剧本的 \\`packageVersion/scriptVersion\\` 一致（改台词必须重建包）、以及 \\`assetMode=library\\` 时的资产锁定与「参考图必须带 \\`params.assetId\\`」。不满足会 deny 并列出缺哪一项——**先补 state / 重建包再渲**，不要靠连续重试绕过（连续 2 次后降级放行；\\`DSH_SVS_PRODUCTION_GATE=off\\` 可整体关闭）。这一门只验「留痕」，是否真的问过人由 \\`npm run audit:session\\` 从会话记录核对。\n\n**逐镜自检门（代码强制，不是纪律）**：每渲完一镜立即 extract_frame 抽 1–3 帧（首/中/末，含说话窗）→ 看图核对（与计划一致 / 角色一致 / 口型字幕 / 参考图污染 / 音频 / 风格）→ canvas_record_check(verdict=\"pass\"|\"fail\", frames=[…], checks={plan,character,lipsync,subtitle,contamination,audio,style}, notes=…)。未 pass 时 comfy_generate_video 会被 pre-execute 门直接 deny 并给出下一步；重渲该镜本人（复用 nodeId）放行，连续 deny 2 次后降级放行。项目设置 shotGate=off|frames|verdict 控制强度（缺省 verdict）。注意：自检是 AI 逐镜必做，人工确认仍按 reviewMode 决定时机；audio 项 AI 不能听音，写 na 并在确认卡请用户听核。\n\n本段只定义工具契约与硬约束，**不定义任何生产流程**。完整片型流程（简报/大纲/卡片/镜头表/分镜/逐镜生成/交付的顺序、选项卡门控、失败梯度、终检清单）由 skill 定义——本插件会把自带的流程 skill 安装到 ~/.dsh/skills/，用户也可自行放置。触发到某个 skill 就完全按该 skill 执行；未触发任何 skill 时，按用户当下要求直接用上述工具生成，并把耐用产物落到画布。`\n\n// ---------------------------------------------------------------------------\n// apply\n// ---------------------------------------------------------------------------\n\nconst packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')\nlet ctx = null\n\n/** 本插件自带 skill 的安装标记文件（存在 = 该目录由本插件安装过）。 */\nconst STUDIO_SKILL_MARK = '.dsh-studio-manifest'\n/** 刷新策略开关：off=完全不刷新（只做首次安装与冲突提示）；force=连用户改过的副本也覆盖。 */\nconst SKILL_REFRESH = String(process.env.DSH_SVS_SKILL_REFRESH || '').toLowerCase()\n\nlet cachedPluginVersion = null\n/** 读本插件版本（package.json），用于写入 skill 安装标记的版本戳。 */\nfunction readPluginVersion() {\n  if (cachedPluginVersion) return cachedPluginVersion\n  try {\n    cachedPluginVersion = JSON.parse(readFileSync(resolve(packageRoot, 'package.json'), 'utf8')).version || '0.0.0'\n  } catch { cachedPluginVersion = '0.0.0' }\n  return cachedPluginVersion\n}\n\n/** 解析安装标记（`key: value` 纯文本；`#` 开头为注释）。 */\nfunction readSkillStamp(dir) {\n  const file = join(dir, STUDIO_SKILL_MARK)\n  if (!existsSync(file)) return null\n  const out = {}\n  try {\n    for (const line of readFileSync(file, 'utf8').split('\\n')) {\n      const t = line.trim()\n      if (!t || t.startsWith('#')) continue\n      const i = t.indexOf(':')\n      if (i > 0) out[t.slice(0, i).trim()] = t.slice(i + 1).trim()\n    }\n  } catch { return null }\n  return out\n}\n\n/** 写安装标记（含版本戳与内容哈希）。 */\nfunction writeSkillStamp(dir, { name, pluginVersion, contentHash }) {\n  const body = [\n    '# dsh-short-video-studio 安装标记',\n    '# 本目录由插件安装逻辑复制：内容未被修改时会随插件升级自动刷新；',\n    '# 一旦内容哈希与记录不符（= 用户改过），插件不再覆盖，只在日志里提示。',\n    `name: ${name}`,\n    'source: bundled',\n    `pluginVersion: ${pluginVersion}`,\n    `contentHash: ${contentHash}`,\n    `installedAt: ${new Date().toISOString()}`,\n    '',\n  ].join('\\n')\n  writeFileSync(join(dir, STUDIO_SKILL_MARK), body, 'utf8')\n}\n\n/**\n * skill 目录内容哈希（sha256，跳过安装标记本身）：\n * 只按\"排序后的相对路径 + 内容\"计算，所以与 mtime / 复制方式无关，可跨机器比对。\n */\nfunction hashSkillDir(dir) {\n  const files = []\n  const walk = (d, rel) => {\n    for (const e of readdirSync(d, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {\n      if (rel === '' && e.name === STUDIO_SKILL_MARK) continue\n      if (e.name === '.DS_Store') continue\n      const r = rel ? rel + '/' + e.name : e.name\n      if (e.isDirectory()) walk(join(d, e.name), r)\n      else if (e.isFile()) files.push(r)\n    }\n  }\n  walk(dir, '')\n  const h = createHash('sha256')\n  for (const r of files.sort()) {\n    h.update(r)\n    h.update('\\0')\n    h.update(readFileSync(join(dir, ...r.split('/'))))\n    h.update('\\0')\n  }\n  return 'sha256:' + h.digest('hex')\n}\n\n/**\n * 同步自带 skill（版本戳刷新）——本插件 skill 分发的唯一实现，可注入路径以便测试。\n *\n * 策略（目标目录存在的四种情形）：\n *  1. 带标记 + 内容哈希与记录一致（用户没改过）\n *     → 与源不同就**刷新**（删掉重拷 + 更新版本戳）；相同就只更新版本戳（静默）。\n *  2. 带标记 + 内容哈希与记录不符（用户改过）→ **不覆盖**，记入 keptUserEdited 并提示取新版的方法；\n *     `DSH_SVS_SKILL_REFRESH=force` 时才强制覆盖。\n *  3. 带标记但没有内容哈希（旧版安装）→ 内容与源一致就只补戳（stamped）；不一致则按用户改过处理。\n *  4. 不带标记 → 视为用户自建同名 skill，**不覆盖**，记入 conflicts 并给合并指引。\n * `DSH_SVS_SKILL_REFRESH=off` 时只做首次安装 + 冲突提示，完全不碰已有目录。\n */\nfunction syncBundledSkills({ srcRoot, dstRoot, pluginVersion, log = () => {}, refresh = SKILL_REFRESH } = {}) {\n  const report = { installed: [], refreshed: [], adopted: [], stamped: [], upToDate: [], keptUserEdited: [], conflicts: [], reaped: [], keptOrphans: [], errors: [] }\n  if (!existsSync(srcRoot)) return report\n  mkdirSync(dstRoot, { recursive: true })\n  for (const entry of readdirSync(srcRoot, { withFileTypes: true })) {\n    if (!entry.isDirectory()) continue\n    const srcDir = join(srcRoot, entry.name)\n    const target = join(dstRoot, entry.name)\n    const srcHasMark = existsSync(join(srcDir, STUDIO_SKILL_MARK))\n    try {\n      const srcHash = hashSkillDir(srcDir)\n      if (!existsSync(target)) {\n        cpSync(srcDir, target, { recursive: true })\n        writeSkillStamp(target, { name: entry.name, pluginVersion, contentHash: srcHash })\n        report.installed.push(entry.name)\n        continue\n      }\n      const stamp = readSkillStamp(target)\n      if (!stamp) {\n        // 目标没有安装标记。两种情况要分开：\n        //  - 内容与源逐字节一致 → 无法区分「插件早期装的（当时没落戳）」和「全新安装」，\n        //    收编：补写版本戳（只写标记文件，绝不碰 skill 内容），从此纳入刷新管理；\n        //  - 内容与源不同 → 视为用户/第三方同名 skill，不覆盖，仅记冲突（源带标记时才提示）。\n        const curHash = hashSkillDir(target)\n        if (srcHasMark && curHash === srcHash) {\n          writeSkillStamp(target, { name: entry.name, pluginVersion, contentHash: srcHash })\n          report.adopted.push(entry.name)\n          continue\n        }\n        if (srcHasMark) report.conflicts.push(entry.name)\n        continue\n      }\n      if (refresh === 'off') { report.upToDate.push(entry.name); continue }\n      const curHash = hashSkillDir(target)\n      const userEdited = stamp.contentHash ? curHash !== stamp.contentHash : null // null = 旧版无戳，未知\n      if (userEdited === true && refresh !== 'force') {\n        report.keptUserEdited.push(entry.name)\n        continue\n      }\n      if (userEdited === null && curHash !== srcHash) {\n        // 旧版安装且内容与源不一致：无法判断是用户改的还是插件改的 → 保守不覆盖\n        report.keptUserEdited.push(entry.name)\n        continue\n      }\n      if (curHash !== srcHash) {\n        rmSync(target, { recursive: true, force: true })\n        cpSync(srcDir, target, { recursive: true })\n        writeSkillStamp(target, { name: entry.name, pluginVersion, contentHash: srcHash })\n        report.refreshed.push(entry.name)\n        continue\n      }\n      // 内容一致：只在版本戳落后（或旧版无戳）时补戳\n      if (stamp.contentHash !== srcHash || stamp.pluginVersion !== pluginVersion) {\n        writeSkillStamp(target, { name: entry.name, pluginVersion, contentHash: srcHash })\n        report.stamped.push(entry.name)\n      } else {\n        report.upToDate.push(entry.name)\n      }\n    } catch (error) {\n      report.errors.push(`${entry.name}: ${error?.message || String(error)}`)\n    }\n  }\n  // 孤儿回收：目标端带本插件安装戳、但源 bundle 里已不存在同名 skill 的目录。\n  // 改名或下线自带 skill 时必须清掉旧目录——主循环只遍历源目录，从不删目标端多余项，\n  // 不回收的话旧名会永久留在 ~/.dsh/skills/ 并被技能目录同时列出（新旧触发词打架）。\n  // 安全底线：无安装戳 = 非本插件安装，永不删；用户改过的孤儿默认也不删，只提示（force 才删）。\n  if (refresh !== 'off') {\n    const sourceNames = new Set(\n      readdirSync(srcRoot, { withFileTypes: true })\n        .filter((e) => e.isDirectory())\n        .map((e) => e.name),\n    )\n    for (const entry of readdirSync(dstRoot, { withFileTypes: true })) {\n      if (!entry.isDirectory() || sourceNames.has(entry.name)) continue\n      const target = join(dstRoot, entry.name)\n      try {\n        const stamp = readSkillStamp(target)\n        if (!stamp) continue\n        const curHash = hashSkillDir(target)\n        const userEdited = stamp.contentHash ? curHash !== stamp.contentHash : false\n        if (userEdited && refresh !== 'force') {\n          report.keptOrphans.push(entry.name)\n          continue\n        }\n        rmSync(target, { recursive: true, force: true })\n        report.reaped.push(entry.name)\n      } catch (error) {\n        report.errors.push(`${entry.name}: ${error?.message || String(error)}`)\n      }\n    }\n  }\n  return report\n}\n\n/** 安装/刷新自带 skills 到 ~/.dsh/skills（启动时调用；只报告发生了变化的部分，避免刷屏）。 */\nfunction installBundledSkills() {\n  try {\n    const report = syncBundledSkills({\n      srcRoot: resolve(packageRoot, 'skills'),\n      dstRoot: join(homedir(), '.dsh', 'skills'),\n      pluginVersion: readPluginVersion(),\n      log: (m) => console.warn(m),\n    })\n    if (report.installed.length) console.warn(`[dsh-short-video-studio] 已安装自带 skill：${report.installed.join(', ')}`)\n    if (report.refreshed.length) console.warn(`[dsh-short-video-studio] 已刷新自带 skill（插件 v${readPluginVersion()}）：${report.refreshed.join(', ')}`)\n    if (report.adopted.length) console.warn(`[dsh-short-video-studio] 已纳入刷新管理（补写版本戳）：${report.adopted.join(', ')}`)\n    for (const name of report.keptUserEdited) {\n      console.warn(\n        `[dsh-short-video-studio] 自带 skill \"${name}\" 的内容与安装记录不符（你改过），本次未覆盖。` +\n        `要取插件新版：删除 ~/.dsh/skills/${name} 后重启（或手动合并）；` +\n        `要强制覆盖：设 DSH_SVS_SKILL_REFRESH=force 重启。`\n      )\n    }\n    if (report.reaped.length) {\n      console.warn(\n        `[dsh-short-video-studio] 已回收下线/改名的自带 skill：${report.reaped.join(', ')}` +\n        `（源 bundle 里已无同名目录，副本未被你改过）`\n      )\n    }\n    for (const name of report.keptOrphans) {\n      console.warn(\n        `[dsh-short-video-studio] 自带 skill \"${name}\" 已从源 bundle 下线/改名，但你的副本被改过，本次未回收。` +\n        `确认不再需要就手动删除 ~/.dsh/skills/${name}/；要强制回收：设 DSH_SVS_SKILL_REFRESH=force 重启。`\n      )\n    }\n    for (const name of report.conflicts) {\n      console.warn(\n        `[dsh-short-video-studio] 检测到同名 skill \"${name}\" 已存在于 ~/.dsh/skills/（非本插件安装），未覆盖。` +\n        `如需本插件适配版，请删除 ~/.dsh/skills/${name} 后重装插件，或手动合并所需文件。`\n      )\n    }\n    for (const e of report.errors) console.warn('[dsh-short-video-studio] skill 同步失败：' + e)\n  } catch (error) {\n    console.warn('[dsh-short-video-studio] install skills failed:', error?.message || String(error))\n  }\n}\n\nexport function apply(hostCtx) {\n  ctx = hostCtx\n  const runtime = {\n    token: randomBytes(32).toString('base64url'),\n    studioRoot: resolve(packageRoot, 'studio'),\n  }\n\n  // 安装自带 skill（供模型/技能中心发现）\n  installBundledSkills()\n\n  // M1：加载并校验内置工作流清单（纯观察，工具/路由仍走旧 builder，M2 再切换到 registry）\n  const manifestReport = loadBuiltinManifests(resolve(packageRoot, 'workflows'))\n  if (manifestReport.errors.length) {\n    console.warn('[dsh-short-video-studio] 内置工作流清单校验失败:', manifestReport.errors)\n  }\n\n  // 工具\n  const tools = makeTools()\n  const disposeTools = ctx.effect(() => {\n    const disposers = tools.map((t) => ctx.tools.register(t))\n    return () => disposers.forEach((d) => d())\n  }, 'dsh-short-video-studio: tools')\n\n  // pre-ask 自动送达：ask_user_question 执行前，把画布中未送达的产物经\n  // send_file 送达（仅飞书渠道有 send_file；Web/TUI 自动跳过）。\n  // 只拦 ask_user_question，send_file 自身执行不会递归触发。\n  // global:true = 全局监听器不受 agent context filter 限制，所有 scope 的 dispatch 都收到。\n  const disposePreAskDeliver = ctx.effect(() => ctx.on('tools/pre-execute', makePreAskDeliverListener(ctx), { global: true }), 'dsh-short-video-studio: pre-ask deliver')\n\n  // H3 结构化 prompt 质检门：comfy_generate_video / comfy_render 在 H3 系工作流下\n  // 必须携带结构化字段（六段式 / 三段式 + 对齐指令），缺失 deny 引导加载\n  // h3-prompt-writing skill 重写（防死循环上限后降级放行）。\n  const disposeH3Gate = ctx.effect(() => ctx.on('tools/pre-execute', makeH3PromptGateListener(ctx), { global: true }), 'dsh-short-video-studio: h3 prompt gate')\n\n  // 镜头表一致性门：视频生成前按标题 Sxx 对照画布镜头表，校验台词/字幕逐字、\n  // 时长、声线参考、画幅比例与 fast 档参考图形态（不一致 deny；连续 deny 2 次后降级放行）。\n  const disposePlanGate = ctx.effect(() => ctx.on('tools/pre-execute', makePlanGateListener(ctx), { global: true }), 'dsh-short-video-studio: plan gate')\n\n  // 短剧制片门：series/production-state.json 存在时，校验 stage / G-P 批准 / 包版本 / 资产锁定\n  // （封面「跳过阶段 C 直接开渲」这类系列层违规；单片项目不触发）。\n  const disposeProductionGate = ctx.effect(() => ctx.on('tools/pre-execute', makeProductionGateListener(ctx), { global: true }), 'dsh-short-video-studio: production gate')\n\n  // 配置门：生成 / 后处理前读画布配置（未建卡 / 画幅不一致 / 角色卡版本冲突 → deny）\n  const disposeConfigGate = ctx.effect(() => ctx.on('tools/pre-execute', makeConfigGateListener(ctx), { global: true, prepend: true }), 'dsh-short-video-studio: config gate')\n\n  // 逐镜自检门：视频生成 / 拼接前检查镜头是否已抽帧并记录通过\n  // （项目设置 shotGate=off 可整体关闭；重渲同一 nodeId 放行）。\n  const disposeShotGate = ctx.effect(() => ctx.on('tools/pre-execute', makeShotGateListener(ctx), { global: true }), 'dsh-short-video-studio: shot gate')\n\n  // 创作批准门：卡 → 镜头表 → 分镜 → 视频 → 拼接 的人工批准凭据\n  // （project.approvals，由 canvas_approve 写入；无连续 deny 降级）。\n  const disposeApprovalGate = ctx.effect(() => ctx.on('tools/pre-execute', makeApprovalGateListener(ctx), { global: true }), 'dsh-short-video-studio: approval gate')\n\n  // systemPrompt 段\n  const disposeSection = ctx.systemPrompt.section({\n    name: 'plugin:dsh-short-video-studio',\n    order: GUIDANCE_ORDER,\n    text: GUIDANCE,\n  })\n\n  // 归档搬迁：订阅 workspace 域变更，把归档会话的 canvas/<sid> 搬到 archiveRoot（取消归档再搬回）。\n  // archiveRoot 未配置时监听器仍在，但每次搬迁都是纯 no-op。\n  const disposeArchiveMover = ctx.effect(() => startArchiveWatcher(ctx), 'dsh-short-video-studio: archive mover')\n\n  // 路由\n  const { apiPrefix, handleApi, handleMedia, handleStatic } = makeRoutes(runtime)\n  const disposeRoutes = ctx.effect(() => {\n    return ctx.webServer.register({\n      kind: 'prefix',\n      path: ROUTE_ROOT,\n      handler: async (req, res) => {\n        try {\n          const url = new URL(req.url ?? ROUTE_ROOT, 'http://localhost')\n          if (url.pathname.startsWith(apiPrefix)) await handleApi(ctx, req, res, url)\n          else if (url.pathname.startsWith(ROUTE_ROOT + '/media')) await handleMedia(ctx, res, url)\n          else await handleStatic(res, url)\n        } catch (error) {\n          if (res.headersSent) { res.destroy(error instanceof Error ? error : undefined); return }\n          sendJson(res, error?.status || 500, { ok: false, message: error?.message || 'request failed' })\n        }\n      },\n    })\n  }, 'dsh-short-video-studio: routes')\n\n}\n\n// 暴露部分内部供测试\nexport const _internals = {\n  // 工具定义（供 scripts/smoke-tools.mjs 按宿主 register 契约校验：output 缺失、\n  // schema 越界这类错误在真宿主里表现为「插件整个不加载」，必须离线拦住）\n  makeTools,\n  // 归档搬迁：供 scripts/smoke-archive-move.mjs 用假宿主验证「归档→搬出 / 取消归档→搬回」\n  startArchiveWatcher,\n  reconcileArchive,\n  archiveOneSession,\n  restoreOneSession,\n  ensureArchiveRestored,\n  configuredArchiveRoot,\n  // 视频超分（U3）：供 scripts/e2e-upscale.mjs 真机验证整条链路（读画布源节点 → 上传 → 编译图 → 落画布）\n  runUpscale,\n  // 视频重生成（Open-H3）：目标网格规划 / 源片护栏 / 真机链路\n  runRegenerate,\n  planRegenerate,\n  normalizeRegenerateTargets,\n  resolveRegenerateTarget,\n  decideRegenerateHandoff,\n  probeLatentFiles,\n  // 视频补帧（VFI）：工具层后处理（整数倍补帧 + D2 补齐 + 非整数倍 ffmpeg 抽取）\n  runInterpolate,\n  planInterpolate,\n  // 图片裁切（纯像素后处理）：供 scripts/smoke-crop.mjs 校验矩形收敛逻辑与真机链路\n  computeCropRect,\n  runCrop,\n  concatFpsGuard,\n  detectFfmpeg,\n  ffmpegRetimeFps,\n  runExtractAudio,\n  // skill 分发（版本戳刷新）：供 scripts/smoke-skill-install.mjs 注入临时路径测试\n  syncBundledSkills,\n  hashSkillDir,\n  readSkillStamp,\n  readPluginVersion,\n  STUDIO_SKILL_MARK,\n  buildFluxImageWorkflow,\n  buildH3VideoWorkflow,\n  buildH3ImageToVideoWorkflow,\n  comfySubmit,\n  comfyWait,\n  comfyOutputs,\n  comfyDownload,\n  comfyUploadImage,\n  resolveTieredManifest,\n  getCfg,\n  getTierSelection,\n  DEFAULT_GROUP,\n  ROUTE_ROOT,\n  CANVAS_DIR,\n  // 项目配置（settings v2）：供 scripts/smoke-config-*.mjs 覆盖规范化 / 推断 / 写入口 / 门\n  normalizeSettings,\n  inferFlow,\n  applyProjectConfig,\n  renderConfigMarkdown,\n  configCardId,\n  findConfigCard,\n  computeConfigImpact,\n  makeConfigGateListener,\n  configGateOp,\n  configIssuesFor,\n  FLOW_VALUES,\n  GATE_PROFILES,\n  gateOn,\n  CONFIG_GROUP,\n  CONFIG_CARD_TITLE,\n  BREAKING_FIELDS,\n  // M1：工作流契约引擎\n  loadBuiltinManifests,\n  buildGraphFromManifest,\n  VIDEO_SHAPES,\n  validateVideoArgs,\n  validateManifest,\n  resolveAssets,\n  // 档位解析层（契约见 docs/tier-strategy-design.md）\n  TIERS,\n  tierImplementations,\n  sortTierCandidates,\n  groupNameOf,\n  isTieredCapability,\n  getTierSelection,\n  tierFromArgs,\n  legacyModeFromArgs,\n  explicitImplementationOf,\n  probeImageSize,\n  projectCapabilityStrategies,\n  userStrategiesOf,\n  DEFAULT_STRATEGY_ID,\n  describeTierMatrix,\n  describeWorkflowsApi,\n  effectiveAssetsOf,\n  ASSET_OVERRIDE_ALIASES,\n  LEGACY_MODEL_ASSET_MAP,\n  checkAvailability,\n  probeNodeClass,\n  DEFAULT_TIER,\n  CAPABILITIES,\n  // M2：通用渲染\n  runRender,\n  // 分档提示词库（契约见 docs/prompt-bank.md）\n  parsePromptBank,\n  serializePromptBank,\n  resolvePromptForTier,\n  promptBankTitleFor,\n  findPromptBankNode,\n  upsertPromptBankNode,\n  PROMPT_TIERS,\n  PROMPT_BANK_MARK,\n  buildRenderGraph,\n  resolveManifest,\n  resolveMode,\n  computeManifestSize,\n  manifestDeliverySize,\n  resolutionLockWarning,\n  snapLengthToGrid,\n  getAssetOverrides,\n  getRegistry,\n  reloadRegistry,\n  // 短剧制片门（production gate）：离线测试用\n  makeProductionGateListener,\n  // 创作批准门（approval gate）：离线测试用\n  makeApprovalGateListener,\n  APPROVAL_GATE,\n  APPROVAL_TARGETS,\n  approvalSummary,\n  approvalIsCurrent,\n  assetKindOf,\n  isAssetCard,\n  textHash,\n  // 逐镜自检门（shot gate）：离线测试用\n  makeShotGateListener,\n  shotGateLevel,\n  isShotNode,\n  shotGateSatisfied,\n  selfCheckStatus,\n  shotFrames,\n  // 渠道交付：pre-ask 自动送达\n  collectUndelivered,\n  deliverPending,\n  makePreAskDeliverListener,\n  // 手动资产导入（画布上传 / 资产库取用 / 替换）\n  parseDataUrlImage,\n  importManualImage,\n  copyAssetToCanvas,\n  replaceNodeImage,\n  isPromptFreeCapability,\n  UPLOAD_MAX_FILE,\n  UPLOAD_MAX_FILES,\n  // H3 结构化 prompt 质检门\n  makeH3PromptGateListener,\n  h3HasSection,\n  H3_PROMPT_GATE,\n  H3_GATE_MAX_DENIES,\n  // 镜头表一致性门（plan gate）：离线测试用\n  makePlanGateListener,\n  parseShotTableContent,\n  findShotPlan,\n  shotIdFromText,\n  parseAspectRatio,\n  PLAN_GATE,\n  PLAN_GATE_MAX_DENIES,\n  exportTextNode,\n  deliveryFilename,\n  markdownToHtml,\n  renderNodeHtml,\n  AUTO_DELIVER_BEFORE_ASK,\n  TEXT_NODE_EXPORT_PDF,\n}\n"
    },
    {
      "path": "lib/client.js",
      "content": "// dsh-short-video-studio — 浏览器半。\n// 通过 window.__ModuleLoader__.load 注册 client 模块，把「画布」挂到宿主 UI 上。\n// 家由插件级配置项 canvasHome 决定（设置 → ComfyUI → 界面），启动时**只注册一个**：\n//   'tab'（默认）→ conversation.view 会话视图 tab；'sidebar' → 右侧栏 tab 类型。\n// 两种家都复用同一个 CanvasView（iframe 指向宿主伺服的自包含 studio 页）。\nwindow.__ModuleLoader__.load({\n  id: 'dsh-short-video-studio',\n  factory: (require) => {\n    var module = { exports: {} }\n    var exports = module.exports\n    var React = require('react')\n\n    const inject = ['slots']\n\n    const ROUTE_ROOT = '/dsh-short-video-studio'\n\n    // ---- 主题：画布跟随 DSH 的浅色/深色 ----\n    // 宿主把当前配色方案经 ?theme= 写给 iframe（首屏用，避免先闪一下另一种底色），\n    // 运行中主题变化再用 postMessage 下发（studio/app.js 收）。画布页自带两套调色板，\n    // 由 <html data-theme> 选择 —— iframe 读不到宿主文档的 CSS 变量，只能这样传。\n    let hostCtx = null\n    const schemeListeners = new Set()\n    let bootScheme\n\n    /**\n     * 读宿主当前配色方案。\n     * @returns `'light'` / `'dark'`；宿主没装主题服务（或读失败）时返回 `null` ——\n     *   此时**不传** `?theme=`，让画布页按 `prefers-color-scheme` 自行兜底，而不是硬猜一个。\n     */\n    function readScheme() {\n      try {\n        const theme = hostCtx && typeof hostCtx.get === 'function' ? hostCtx.get('theme') : undefined\n        if (!theme || typeof theme.getTheme !== 'function') return null\n        const snap = theme.getTheme()\n        const scheme = snap && snap.active ? snap.active.colorScheme : null\n        if (scheme === 'dark') return 'dark'\n        if (scheme === 'light') return 'light'\n        return null\n      } catch (e) {\n        return null // 主题服务异常不该让画布挂掉\n      }\n    }\n\n    /**\n     * 解析宿主目录选择器的 Remote 命名空间。DSH 把 `directoryPicker` 作为独立服务\n     * `remote.directoryPicker` 安装（cordis 服务名带点），同时 `ctx.remote` 上也能取到同名属性；\n     * 不同宿主版本/加载顺序下两种读法都可能先可用，所以都试一遍，取第一个带 pick 的。\n     * @returns {{pick: Function}|null}\n     */\n    function resolveDirectoryPicker() {\n      const candidates = []\n      const push = (value) => { try { if (value) candidates.push(value) } catch (e) { /* 未注入/未挂载：跳过 */ } }\n      try { if (hostCtx && typeof hostCtx.get === 'function') push(hostCtx.get('remote.directoryPicker')) } catch (e) {}\n      try {\n        const remote = hostCtx && typeof hostCtx.get === 'function' ? hostCtx.get('remote') : null\n        if (remote) push(remote.directoryPicker)\n      } catch (e) {}\n      try { if (hostCtx && hostCtx.remote) push(hostCtx.remote.directoryPicker) } catch (e) {}\n      for (const candidate of candidates) {\n        if (candidate && typeof candidate.pick === 'function') return candidate\n      }\n      return null\n    }\n\n    /**\n     * 调宿主的目录选择器（macOS Finder / Windows 资源管理器 / Linux zenity）。\n     * 走 `ctx.get('remote').directoryPicker.pick()`——与「添加工作区」同一个 Remote 命名空间，\n     * 后端由 @deepseek-ai/dsh-host-directory-picker-auto 在启动时决定：本机回环 + 有显示桌面时是原生对话框，\n     * 远程 / SSH / 纯浏览器环境会退化成 browse（没有 pick），此时返回 unavailable 让调用方提示手输。\n     * @returns {Promise<{path?: string|null, unavailable?: boolean, error?: {code?: string, message?: string}}>}\n     */\n    async function pickDirectoryViaHost() {\n      const picker = resolveDirectoryPicker()\n      if (!picker) return { unavailable: true }\n      const result = await picker.pick()\n      // 正常形态是 RemoteResult `{ ok, value }`；兼容直接返回路径 / null 的宿主版本。\n      if (result === null || typeof result === 'string') return { path: result }\n      if (!result || result.ok !== true) {\n        const error = (result && result.error) || { code: 'unknown', message: '目录选择失败' }\n        return { error }\n      }\n      return { path: result.value === undefined ? null : result.value }\n    }\n\n    /** 首屏主题只取一次并冻结：它进了 iframe 的 src，若跟着变会让 iframe 重载（丢滚动位置）。 */\n    function bootSchemeOnce() {\n      if (bootScheme === undefined) bootScheme = readScheme()\n      return bootScheme\n    }\n\n    /** 把主题下发给画布 iframe。抽成函数是为了离线冒烟能断言（测试里拿不到真 contentWindow）。 */\n    function postThemeToFrame(frame, theme) {\n      if (theme !== 'light' && theme !== 'dark') return false\n      try {\n        const win = frame && frame.contentWindow\n        if (!win || typeof win.postMessage !== 'function') return false\n        win.postMessage({ channel: 'dsh-short-video-studio', type: 'theme', theme }, window.location.origin)\n        return true\n      } catch (e) {\n        return false // 跨源/尚未挂载：下次 theme/change 或 onLoad 会再试\n      }\n    }\n\n    /** 订阅宿主配色方案变化（画布组件用；返回退订函数）。 */\n    function subscribeScheme(fn) {\n      schemeListeners.add(fn)\n      return () => { schemeListeners.delete(fn) }\n    }\n\n    /**\n     * 订阅宿主主题变化（ui-theme 的 `theme/change` 在偏好切换与系统配色变化时都会发）。\n     * 宿主没有事件能力时退化为「只在挂载/iframe load 时读一次」——主题仍然跟随，\n     * 只是运行中切换要等下一次重挂载。宁可降级，也不能让 apply 抛错把整个浏览器半拖垮。\n     */\n    function watchTheme(ctx) {\n      hostCtx = ctx\n      if (!ctx || typeof ctx.on !== 'function') return\n      ctx.on('theme/change', () => {\n        const next = readScheme()\n        for (const fn of schemeListeners) {\n          try { fn(next) } catch (e) { /* 单个订阅者抛错不影响其他 */ }\n        }\n      })\n    }\n\n    // 两个家（会话区视图 tab / 右侧栏 pane body）共用这一层外壳：\n    // 右栏 pane body 是「有确定高度的块级滚动容器」，这里靠 height:100% 撑满；\n    // flex:1 则覆盖父级是 flex 列（会话区视图槽）的情况。两者同时给才在两种家里都铺满。\n    const shellStyle = {\n      display: 'flex',\n      flexDirection: 'column',\n      flex: '1 1 auto',\n      width: '100%',\n      height: '100%',\n      minWidth: 0,\n      minHeight: 0,\n      boxSizing: 'border-box',\n      // 跟随宿主主题的底：这里是「装 iframe 的外壳」，只在 iframe 首帧前可见，\n      // 用宿主变量才不会有「深色应用里闪一下浅色」。\n      background: 'var(--dsw-alias-bg-base, #f6f7f9)',\n    }\n    const frameStyle = {\n      flex: 1,\n      width: '100%',\n      minHeight: 0,\n      border: 0,\n      background: 'var(--dsw-alias-bg-base, #f6f7f9)',\n    }\n    const emptyStyle = {\n      display: 'grid',\n      placeContent: 'center',\n      gap: 8,\n      height: '100%',\n      padding: 32,\n      color: '#70757f',\n      textAlign: 'center',\n    }\n\n    function CanvasView(props) {\n      const sessionId = props.sessionId\n      const useWorkspaces = props.useWorkspaces\n      const inputActions = props.inputActions\n      const iframeRef = React.useRef(null)\n      // 当前宿主配色方案（'light' / 'dark' / null=未知）。宿主切主题时经 schemeListeners 更新。\n      const [scheme, setScheme] = React.useState(readScheme)\n      // 首屏主题冻结一次（进了 src 就不再变，否则 iframe 会重载）\n      const boot = bootSchemeOnce()\n\n      const workspace = useWorkspaces\n        ? useWorkspaces((state) => state.items.find((item) => item.sessionIds.includes(sessionId)))\n        : null\n\n      React.useEffect(() => {\n        const receive = (event) => {\n          if (event.origin !== window.location.origin) return\n          if (event.source !== iframeRef.current?.contentWindow) return\n          const data = event.data\n          if (!data || data.channel !== 'dsh-short-video-studio') return\n          if (data.type === 'ask-ai' && typeof data.text === 'string' && inputActions && typeof inputActions.setDraft === 'function') {\n            inputActions.setDraft(data.text)\n          }\n        }\n        window.addEventListener('message', receive)\n        return () => window.removeEventListener('message', receive)\n      }, [inputActions])\n\n      // 订阅宿主主题变化 → setScheme 触发重渲染 → 下面的 effect 把新主题 postMessage 给 iframe\n      React.useEffect(() => subscribeScheme(setScheme), [])\n\n      // 主题变化时下发给画布（iframe 已挂载才有 contentWindow；未挂载时由 onLoad 兜底）\n      React.useEffect(() => { postThemeToFrame(iframeRef.current, scheme) }, [scheme])\n\n      if (!workspace) {\n        return React.createElement(\n          'div',\n          { style: emptyStyle },\n          React.createElement('strong', null, '画布需要工作区'),\n          React.createElement('span', null, '请从已注册的 DeepSeek Harness 工作区打开本会话。'),\n        )\n      }\n\n      const query = new URLSearchParams({\n        sessionId: String(sessionId),\n        workspaceId: String(workspace.workspaceId),\n      })\n\n      return React.createElement(\n        'section',\n        { style: shellStyle, 'aria-label': '短视频画布' },\n        React.createElement('iframe', {\n          ref: iframeRef,\n          title: '短视频画布',\n          src: ROUTE_ROOT + '/?' + query.toString() + (boot ? '&theme=' + boot : ''),\n          style: frameStyle,\n          // 每次加载都补一次当前主题（首屏可能因时序错过 postMessage）\n          onLoad: () => postThemeToFrame(iframeRef.current, readScheme()),\n          sandbox: 'allow-downloads allow-forms allow-modals allow-popups allow-same-origin allow-scripts',\n        }),\n      )\n    }\n\n    // ComfyUI 设置卡片（DSH 设置页 settings.section）\n    const CONFIG_API = ROUTE_ROOT + '/api/config'\n    const WORKFLOWS_API = ROUTE_ROOT + '/api/workflows'\n    const ARCHIVE_STATUS_API = ROUTE_ROOT + '/api/archive/status'\n    const ARCHIVE_SYNC_API = ROUTE_ROOT + '/api/archive/sync'\n    const CAPABILITY_OPTIONS = [\n      'image.text2image', 'image.image2image', 'video.text2video',\n      'video.image2video', 'video.reference2video', 'audio.tts', 'audio.music',\n    ]\n    // 档位词汇表（受控枚举，与 lib/manifest.js 的 TIERS 一致）\n    const TIER_OPTIONS = ['fast', 'balanced', 'quality']\n\n    function ComfyUISettings() {\n      const [cfg, setCfg] = React.useState(null)\n      const [registry, setRegistry] = React.useState(null)\n      const [selWorkflow, setSelWorkflow] = React.useState('')\n      const [importText, setImportText] = React.useState('')\n      const [importId, setImportId] = React.useState('')\n      const [importCapability, setImportCapability] = React.useState('image.text2image')\n      const [importName, setImportName] = React.useState('')\n      const [importGroup, setImportGroup] = React.useState('')\n      const [importTier, setImportTier] = React.useState('')\n      const [msg, setMsg] = React.useState('加载中…')\n      // 归档搬迁：状态（配置 / 探测 / 索引 / 最近操作）与操作提示\n      const [archiveStatus, setArchiveStatus] = React.useState(null)\n      const [archiveMsg, setArchiveMsg] = React.useState('')\n      const [pickingDir, setPickingDir] = React.useState(false)\n      // 新增策略表单：哪个能力展开着、策略名、逐档选择\n      const [newStratCap, setNewStratCap] = React.useState('')\n      const [newStratName, setNewStratName] = React.useState('')\n      const [newStratTiers, setNewStratTiers] = React.useState({})\n      const [editStratCap, setEditStratCap] = React.useState('')\n      const [editStratId, setEditStratId] = React.useState('')\n      // 内置默认策略的「编辑档位」：内置策略不是用户对象、没有 id，所以用独立开关，\n      // 保存时写的是**逐档显式选择**（cfg.tiers），而不是新增一条自建策略。\n      const [editBuiltinCap, setEditBuiltinCap] = React.useState('')\n      const [renameCap, setRenameCap] = React.useState('')\n      const [renameId, setRenameId] = React.useState('')\n      const [renameText, setRenameText] = React.useState('')\n\n      React.useEffect(() => {\n        Promise.all([\n          fetch(CONFIG_API).then((r) => r.json()),\n          fetch(WORKFLOWS_API).then((r) => r.json()),\n          fetch(ARCHIVE_STATUS_API).then((r) => r.json()).catch(() => null),\n        ]).then(([c, w, a]) => {\n          if (c && c.ok) setCfg(c.config)\n          if (w && w.ok) setRegistry(w)\n          if (a && a.ok) setArchiveStatus(a)\n          setMsg('')\n        }).catch((e) => setMsg('加载失败: ' + e))\n      }, [])\n\n      if (!cfg || !registry) return React.createElement('div', { style: { padding: 16 } }, msg)\n\n      const setTop = (k, v) => setCfg({ ...cfg, [k]: v })\n      // 字段行统一栅格：左标签定宽 + 右控件撑满剩余宽度（minmax(0,1fr) 保证能收缩、不顶破边框）\n      const field = (label, value, onChange, type) =>\n        React.createElement('label', { style: { display: 'grid', gridTemplateColumns: '190px minmax(0, 1fr)', gap: 10, alignItems: 'center', margin: '6px 0', minWidth: 0 } },\n          React.createElement('span', { title: label, style: { fontSize: 12, color: 'var(--dsw-alias-label-secondary, #cfd3d6)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' } }, label),\n          React.createElement('input', {\n            value: value ?? '', type: type || 'text',\n            style: ctrlStyle,\n            onChange: (e) => onChange(e.target.value),\n          }),\n        )\n\n      const post = (url, body, method) =>\n        fetch(url, { method, headers: { 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined })\n          .then((r) => r.json())\n\n      /** 重新拉归档状态（保存配置 / 手动同步 / 打开面板后都刷新一次）。 */\n      const refreshArchiveStatus = () =>\n        fetch(ARCHIVE_STATUS_API).then((r) => r.json())\n          .then((d) => { if (d && d.ok) setArchiveStatus(d); return d })\n          .catch(() => null)\n\n      /** 手动对账：补搬「已归档但画布还在工作区」与会「已取消归档但画布还在归档区」的会话。 */\n      const syncArchive = () => {\n        setArchiveMsg('同步中…')\n        post(ARCHIVE_SYNC_API, {}, 'POST')\n          .then((d) => {\n            if (!d || !d.ok) {\n              setArchiveMsg('同步失败: ' + ((d && (d.error || d.skipped)) || '未知错误'))\n              return\n            }\n            if (d.configured === false) {\n              setArchiveMsg('未配置归档路径：' + (d.skipped || '') )\n              return\n            }\n            setArchiveMsg('同步完成 ✓ 搬出 ' + (d.archivedMoved || 0) + ' 个，回迁 ' + (d.restored || 0) + ' 个' +\n              (d.errors && d.errors.length ? '（' + d.errors.length + ' 个错误：' + d.errors.slice(0, 2).join('；') + '）' : ''))\n            refreshArchiveStatus()\n          })\n          .catch((e) => setArchiveMsg('同步失败: ' + e))\n      }\n\n      /** 「浏览…」：打开系统目录选择器，选中后直接写进 cfg 并保存（用户不必再滚到底部）。 */\n      const pickArchiveDir = () => {\n        if (pickingDir) return\n        setPickingDir(true)\n        setArchiveMsg('等待系统目录选择…')\n        Promise.resolve()\n          .then(() => pickDirectoryViaHost())\n          .then((picked) => {\n            if (picked.unavailable) {\n              setArchiveMsg('当前环境没有可用的系统目录选择器（远程 / SSH / 纯浏览器），请直接输入路径')\n              return null\n            }\n            if (picked.error) {\n              setArchiveMsg('选择失败：' + (picked.error.message || picked.error.code || '未知错误'))\n              return null\n            }\n            if (!picked.path) {\n              setArchiveMsg('已取消选择')\n              return null\n            }\n            const next = { ...cfg, archiveRoot: picked.path }\n            setCfg(next)\n            setArchiveMsg('已选择：' + picked.path + '（自动保存中…）')\n            return post(CONFIG_API, next, 'POST').then((d) => {\n              setArchiveMsg(d && d.ok\n                ? '已选择并保存 ✓ ' + picked.path\n                : '已选择，但保存失败：' + ((d && (d.error || d.errors)) || ''))\n              if (d && d.ok) refreshArchiveStatus()\n            })\n          })\n          .catch((e) => setArchiveMsg('选择失败：' + e))\n          .finally(() => setPickingDir(false))\n      }\n\n      const saveConfig = () => {\n        setMsg('保存中…')\n        post(CONFIG_API, cfg, 'POST')\n          .then((d) => {\n            setMsg(d && d.ok ? '已保存 ✓' : '保存失败: ' + ((d && d.error) || (d && d.errors) || ''))\n            if (d && d.ok) refreshArchiveStatus()\n          })\n          .catch((e) => setMsg('保存失败: ' + e))\n      }\n\n      // 「界面」里的选择型项**改选即保存**（同本页策略单选的做法）。为什么不走底部「保存配置」：\n      // 换家后用户的下一步就是刷新页面，若还要求先滚到底部保存，很容易改完直接刷新 → 改动丢失。\n      const setCanvasHome = (v) => {\n        const next = { ...cfg, canvasHome: v }\n        setCfg(next)\n        setMsg('保存中…')\n        post(CONFIG_API, next, 'POST')\n          .then((d) => setMsg(d && d.ok ? '已保存 ✓ · 刷新页面后生效' : '保存失败: ' + ((d && d.error) || '')))\n          .catch((e) => setMsg('保存失败: ' + e))\n      }\n\n      const setDefault = (cap, wid) => {\n        const next = { ...cfg, preferred: { ...(cfg.preferred || {}), [cap]: [wid] } }\n        setCfg(next)\n        post(CONFIG_API, next, 'POST')\n          .then((d) => {\n            setMsg(d && d.ok ? '默认已更新 ✓' : '更新失败: ' + ((d && d.error) || ''))\n            if (d && d.ok) return refreshRegistry()\n          })\n          .catch((e) => setMsg('更新失败: ' + e))\n      }\n\n      const refreshRegistry = () =>\n        fetch(WORKFLOWS_API).then((r) => r.json()).then((w) => { if (w && w.ok) setRegistry(w) })\n\n      // ---- 档位选择（策略＝整组预设快照；逐档下拉＝自由组合）------------------\n      const saveTiers = (next, okMsg) => {\n        setCfg(next)\n        post(CONFIG_API, next, 'POST')\n          .then((d) => {\n            setMsg(d && d.ok ? okMsg + ' ✓' : '保存失败: ' + ((d && d.error) || (d && d.errors) || ''))\n            if (d && d.ok) return refreshRegistry()\n          })\n          .catch((e) => setMsg('保存失败: ' + e))\n      }\n      // 策略＝**用户自己命名的档位组合**（内置默认那条＝跟随注册表首选）。\n      // 选中内置默认 → 清空该能力的显式选择（跟随注册表首选，不再被快照冻住）；\n      // 选中用户策略 → 写入它的档位快照（点选即快照，不做活引用）。\n      const applyStrategy = (cap, strategy) => {\n        const tiers = { ...(cfg.tiers || {}) }\n        if (strategy.builtin) delete tiers[cap]\n        else tiers[cap] = { ...strategy.tiers }\n        saveTiers({ ...cfg, tiers, strategyOf: { ...(cfg.strategyOf || {}), [cap]: strategy.id } }, `已应用策略「${strategy.label}」`)\n      }\n      // ---- 内置默认策略的编辑（点「编辑档位」才展开多档表单）---------------------\n      // 语义：内置默认 = 跟随注册表首选。编辑它 = 把挑出来的档位写成**显式逐档选择**（cfg.tiers），\n      // 与下面的逐档下拉等价，只是一次配齐；没挑的档位继续跟随注册表首选。\n      const openBuiltinEditor = (cap, c) => {\n        const eff = {}\n        for (const t of c.tiers || []) {\n          const id = ((cfg.tiers || {})[cap] || {})[t] || ((c.effective || {})[t]) || (c.selection || {})[t] || ''\n          if (id) eff[t] = id\n        }\n        setEditBuiltinCap(cap)\n        setEditStratCap(''); setEditStratId('')\n        setNewStratCap(cap); setNewStratName(''); setNewStratTiers(eff)\n      }\n      const closeStrategyForm = () => {\n        setNewStratCap(''); setNewStratName(''); setNewStratTiers({})\n        setEditStratCap(''); setEditStratId(''); setEditBuiltinCap('')\n      }\n      const saveBuiltinTiers = (cap) => {\n        const picked = {}\n        for (const [t, v] of Object.entries(newStratTiers)) if (v) picked[t] = v\n        if (!Object.keys(picked).length) { setMsg('至少挑一个档位（≥1 个即可，只挑一个也行）'); return }\n        const next = {\n          ...cfg,\n          tiers: { ...(cfg.tiers || {}), [cap]: picked },